fn sdHz1(p: vec2f) -> f32 {
  let toBox = vec2f(max(abs(p.x - 1.630) - 0.365, 0.0), max(abs(p.y - 0.467) - 0.333, 0.0));
  let boxD = length(toBox);
  if (boxD > 0.7) { return boxD; }
  var d = 1e5;
  d = min(d, sdSegment(p, vec2f(1.338, 0.771), vec2f(1.870, 0.801)));
  d = min(d, sdSegment(p, vec2f(1.302, 0.574), vec2f(1.417, 0.459)));
  d = min(d, sdSegment(p, vec2f(1.825, 0.673), vec2f(1.845, 0.634)));
  d = min(d, sdSegment(p, vec2f(1.845, 0.634), vec2f(1.698, 0.497)));
  d = min(d, sdSegment(p, vec2f(1.534, 0.750), vec2f(1.597, 0.696)));
  d = min(d, sdSegment(p, vec2f(1.597, 0.696), vec2f(1.538, 0.338)));
  d = min(d, sdSegment(p, vec2f(1.538, 0.338), vec2f(1.431, 0.221)));
  d = min(d, sdSegment(p, vec2f(1.431, 0.221), vec2f(1.265, 0.147)));
  d = min(d, sdSegment(p, vec2f(1.606, 0.447), vec2f(1.820, 0.178)));
  d = min(d, sdSegment(p, vec2f(1.820, 0.178), vec2f(1.995, 0.134)));
  return d;
}

fn sdHz2(p: vec2f) -> f32 {
  let toBox = vec2f(max(abs(p.x - 2.712) - 0.346, 0.0), max(abs(p.y - 0.525) - 0.351, 0.0));
  let boxD = length(toBox);
  if (boxD > 0.7) { return boxD; }
  var d = 1e5;
  d = min(d, sdSegment(p, vec2f(2.673, 0.876), vec2f(2.721, 0.834)));
  d = min(d, sdSegment(p, vec2f(2.721, 0.834), vec2f(2.716, 0.209)));
  d = min(d, sdSegment(p, vec2f(2.716, 0.209), vec2f(2.698, 0.174)));
  d = min(d, sdSegment(p, vec2f(2.698, 0.174), vec2f(2.550, 0.230)));
  d = min(d, sdSegment(p, vec2f(2.473, 0.586), vec2f(2.366, 0.389)));
  d = min(d, sdSegment(p, vec2f(2.892, 0.604), vec2f(3.028, 0.492)));
  d = min(d, sdSegment(p, vec2f(3.028, 0.492), vec2f(3.058, 0.425)));
  return d;
}

fn sdHz3(p: vec2f) -> f32 {
  let toBox = vec2f(max(abs(p.x - 3.809) - 0.404, 0.0), max(abs(p.y - 0.516) - 0.448, 0.0));
  let boxD = length(toBox);
  if (boxD > 0.7) { return boxD; }
  var d = 1e5;
  d = min(d, sdSegment(p, vec2f(3.637, 0.915), vec2f(3.736, 0.827)));
  d = min(d, sdSegment(p, vec2f(3.944, 0.964), vec2f(3.969, 0.924)));
  d = min(d, sdSegment(p, vec2f(3.969, 0.924), vec2f(3.850, 0.812)));
  d = min(d, sdSegment(p, vec2f(3.600, 0.720), vec2f(4.013, 0.763)));
  d = min(d, sdSegment(p, vec2f(3.623, 0.562), vec2f(3.964, 0.600)));
  d = min(d, sdSegment(p, vec2f(3.404, 0.399), vec2f(3.467, 0.381)));
  d = min(d, sdSegment(p, vec2f(3.467, 0.381), vec2f(4.105, 0.452)));
  d = min(d, sdSegment(p, vec2f(4.105, 0.452), vec2f(4.213, 0.421)));
  d = min(d, sdSegment(p, vec2f(3.821, 0.703), vec2f(3.795, 0.068)));
  return d;
}

// The handle row: per-character box rejects keep the segment loops off almost
// every pixel; the min of the boxes still approximates distance for the halo.
fn sdHanzi(p: vec2f) -> f32 {
  return min(min(sdHz0(p), sdHz1(p)), min(sdHz2(p), sdHz3(p)));
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let res = rzResolution();
  let span = res.x / max(res.y, 1.0);
  var p = (uv - 0.5) * vec2f(span, 1.0);
  p.y -= POS_Y;
  // The sign breathes and sways — quiet motion that says "live shader", not GIF.
  let wobble = 0.05 * sin(time * 0.9);
  let breathe = 1.0 + 0.05 * sin(time * 1.7);
  let c = cos(wobble);
  let si = sin(wobble);
  p = mat2x2f(c, -si, si, c) * p;
  // Screen space → title space (centered); the handle row lives below it in the
  // same units, so one hue gradient and one flicker cross both.
  // THE SIGN FITS THE FRAME, whatever shape the frame is.
  //
  // TEXT_SCALE is the size it WANTS. A frame too narrow to hold that gets the
  // size that does fit instead — which is the whole of a 9:16 export, where the
  // visible width is barely a third of what a 16:9 one gives and the sign ran
  // off both ends of it.
  //
  // Never LARGER than TEXT_SCALE, though: a tall frame is not an invitation to
  // blow the lettering up, and a sign that changes size with the export preset
  // is not the same sign.
  let fit = span * (1.0 - SIDE * 2.0) / TEXT_W;
  let scale = min(TEXT_SCALE, fit) * breathe;
  let q = p / scale + vec2f(TEXT_W * 0.5, 0.5);
  let d1 = sdText(q);
  // Handle row: 4.26 hanzi units wide, scaled by HANZI and centered under the
  // title. Distances scale back by HANZI so both rows share one unit.
  let h = (q - vec2f((TEXT_W - 4.26 * HANZI) * 0.5, -(ROW_GAP + HANZI))) / HANZI;
  let d2 = sdHanzi(h) * HANZI;

  // Neon = crisp tube + inner hot line + tight halo. The handle's tubes are
  // thinner — its strokes sit closer than any pair of latin stems, and at the
  // title's radius they would fuse into a blob.
  let aa1 = fwidth(d1) * 1.5;
  let core1 = (1.0 - smoothstep(0.06 - aa1, 0.06 + aa1, d1)) * 0.75 + (1.0 - smoothstep(0.02 - aa1, 0.02 + aa1, d1)) * 0.45;
  let aa2 = fwidth(d2) * 1.5;
  let core2 = (1.0 - smoothstep(0.038 - aa2, 0.038 + aa2, d2)) * 0.75 + (1.0 - smoothstep(0.014 - aa2, 0.014 + aa2, d2)) * 0.45;
  let halo = exp(-d1 * 5.0) * params.GLOW + exp(-d2 * 6.5) * params.GLOW * 0.9;
  // Gentle electrical shimmer (two incommensurate frequencies, shallow depth).
  let flicker = 1.0 - params.FLICKER * (0.5 + 0.5 * sin(time * 7.3) * sin(time * 3.1));
  let core = core1 + core2;
  let s = (core + halo) * flicker;

  // A hue gradient travels along the sign — the "this is a shader" tell.
  let hue = mix(params.NEON_COLOR, params.NEON_COLOR_B, 0.5 + 0.5 * sin(time * 1.1 + q.x * 0.45));
  let color = hue + vec3f(0.35) * core; // core burns toward white
  return vec4f(clamp(color, vec3f(0.0), vec3f(1.0)), clamp(s, 0.0, 1.0));
}

#layer additive

#param color WARM #ffedd1 — the colour of the warm half
#param color COOL #d1e3ff — and the cool half
#param float DENSITY 0.5 0 1 — 0..1 — how crowded the sky is
#param float TWINKLE 0.5 0 1 — 0..1 — flicker speed
#param float INTENSITY 1.15 0 3 — overall brightness

// Shining Stars — a night sky, drawn as points rather than blooms.
//
// The cells, the projection and the hash are the ones this effect has always
// used. What changed is the STAR: it used to reach four times its own radius as
// a soft halo, which at 1080p is a disc 26 pixels across, and it painted that
// whole disc in one flat colour. That is a bloom, not a star.
//
// A field composites in DISPLAY space, after tone mapping, and the engine clamps
// what this returns to [0,1]. Brightness is therefore not available as a dial —
// turning it up only widens the saturated middle. What reads as a bright star is
// a SHARP core that goes white while its halo keeps its colour, and a pair of
// diffraction spikes. That gradient is the whole trick.

// Tunables — edit a value and hit Cmd-Enter to see it live.

const REACH = 0.24;         // a star's whole extent, in cell widths
const HALO = 0.15;          // the glow around it — kept low, it is what discs
const SPIKE = 0.8;          // diffraction flare — what gives a big star structure
const SPIKE_THIN = 0.075;   // how fine its arms are

fn bgHash2(p: vec2f) -> vec2f {
  let q = vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}

/** Compact support: 1 at the centre, exactly 0 at r, smooth between. A glow that
 *  merely gets small has to be cut off somewhere, and the cut is an edge. */
fn bgFall(d: f32, r: f32) -> f32 {
  let x = clamp(d / max(r, 1e-6), 0.0, 1.0);
  let f = 1.0 - x;
  return f * f * f;
}

/** One layer of stars, as (colour * energy, energy). */
fn starLayer(sph: vec2f, scale: f32, thresh: f32, time: f32, speed: f32,
             spikes: f32, latCos: f32) -> vec4f {
  let cell = floor(sph * scale);
  let h = bgHash2(cell);
  let bright = bgHash2(cell + 7.31).x;
  if (bright < thresh) { return vec4f(0.0); }

  // Star sits at a hashed point inside its cell — kills the grid look.
  //
  // Corrected for the projection's stretch: one step of longitude covers cos(lat)
  // as much sky as one of latitude, so an uncorrected star is a circle at the
  // equator and an ellipse overhead.
  let local = (fract(sph * scale) - (0.15 + 0.7 * h)) * vec2f(latCos, 1.0);
  let d = length(local);

  let size = (bright - thresh) / (1.0 - thresh);
  let reach = REACH * (0.62 + 0.38 * size);
  if (d >= reach) { return vec4f(0.0); }

  // Cubed, then cubed again: a ninth-power core is a true point of light with no
  // plateau at all. The old smoothstep held a flat top and then ran on for four
  // times its own radius, which is what drew a disc.
  let f = bgFall(d, reach);
  let core = f * f * f;
  let halo = f * HALO;

  // Diffraction spikes, turned to the star's own angle. What a lens does to a
  // point source, and the thing that says "star" rather than "dot".
  var flare = 0.0;
  if (spikes > 0.0) {
    let rot = h.y * 6.2831853;
    let cr = cos(rot);
    let sr = sin(rot);
    let q = vec2f(local.x * cr - local.y * sr, local.x * sr + local.y * cr) / reach;
    let ax = abs(q);
    let sx = bgFall(ax.x, 1.0) * bgFall(ax.y, SPIKE_THIN);
    let sy = bgFall(ax.y, 1.0) * bgFall(ax.x, SPIKE_THIN);
    // Only the brightest carry a flare, which is what keeps the sky fine.
    flare = (sx + sy) * spikes * size * size;
  }

  // Per-star period from its own hash: some breathe over seconds, some blink.
  let period = 0.25 + 2.75 * bgHash2(cell + 31.7).y;
  let tw = 0.55 + 0.45 * sin(time * speed * period + h.x * 40.0);

  let e = (core + flare + halo) * tw * (0.45 + 0.75 * size);
  // White at the core, its own colour in the halo — the gradient that reads as
  // heat. One flat colour across the whole star is what made it look painted on.
  let tint = mix(params.COOL, params.WARM, h.x);
  let col = mix(tint, vec3f(1.0), clamp(core * 2.2, 0.0, 1.0));
  return vec4f(col * e, e);
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let d = normalize(ray);
  // Latitude/longitude projection
  let sph = vec2f(atan2(d.x, d.z) * 1.2, asin(clamp(d.y, -1.0, 1.0)) * 1.5);
  // How much this latitude squashes longitude, for the correction in starLayer.
  let latCos = max(0.2, sqrt(max(0.0, 1.0 - d.y * d.y)));

  // Denser = MORE stars, not smaller ones (sizes untouched)
  let dens = mix(0.95, 0.82, clamp(params.DENSITY, 0.0, 1.0));
  var acc = starLayer(sph, 30.0, dens, time, params.TWINKLE * 1.6, SPIKE, latCos);
  // Faint dust layer: denser, smaller, slower, and no flare of its own.
  acc += 0.4 * starLayer(sph + 3.7, 70.0, mix(0.985, 0.9, clamp(params.DENSITY, 0.0, 1.0)),
                         time, params.TWINKLE * 0.9, 0.0, latCos);

  let a = clamp(acc.w * params.INTENSITY, 0.0, 1.0);
  if (a <= 0.0) { return vec4f(0.0); }
  // Straight alpha — the engine's over-composite premultiplies. The colour is the
  // energy-weighted average, so two stars overlapping mix instead of the second
  // one winning.
  return vec4f(acc.rgb / max(acc.w, 1e-4), a);
}

#particles 24000
#blend additive
#bloom

#param float GATHER 1.3 0 3 — >1 crowds them toward the cast; 1 is an even spread
#param float RISE 0.055 0 0.3 — metres per second — barely
#param float WANDER 0.11 0 0.5 — sideways drift
#param float SWIRL 0.07 0 0.3 — how tightly that drift curls

// Floating Stars — motes of light drifting around the cast.
//
// The companion to Shining Stars rather than a replacement: that one is the SKY,
// a field with no position, and this one is IN the scene. Particles draw in HDR
// before tone mapping, so these can sit several times brighter than paper and
// bloom, and they are depth-tested — a mote passes behind her shoulder and in
// front of her hand in the same frame.
//
// The volume is THE STAGE, the same box Snow and Rain fall through, and the
// count is in their range: a scattering of motes reads as dirt on the lens, and
// only density reads as weather. It is a cylinder rather than a sphere because a
// skybox-sized sphere puts a few of its stars right against the lens, and a mote
// a metre from the camera is a soft grey smear over everything. Sizes are fixed
// and small for the same reason.
//
// Gathered gently inward, so the figure stands in the thick of it rather than in
// a clearing.
//
// They rise slowly and wander. Nothing about them is fast: the drift is there so
// the field is alive between twinkles, not to read as motion.

// Tunables.
const CENTER = vec3f(0.0, 0.0, 0.0);  // the stage they gather around
const INNER = 1.5;        // clear of the body
const OUTER = 50.0;       // and how far out they reach

const FLOOR = 0.0;
const TOP = 58.0;         // they rise to here, then wrap — well above the frame

const SIZE_MIN = 0.045;
const SIZE_MAX = 0.18;
const WARM = vec3f(1.0, 0.95, 0.86);
const COOL = vec3f(0.87, 0.93, 1.0);
const INTENSITY = 6.5;    // HDR brightness — see the note below
const BRIGHT_VAR = 0.8;   // the faint many against the bright few
const CORE = 0.17;        // core radius, in quad halves
const HALO = 0.16;      // only ever seen at the peak of a flash
const SPIKE = 0.46;     // likewise — the flare IS the shine
const SPIKE_THIN = 0.08;
const TWINKLE = 0.42;   // how often a mote comes round to its flash
const FLASH = 0.7;      // and how much of one it is when it does

// A NOTE ON BRIGHTNESS. Particles draw in HDR before tone mapping, so white here
// is not the white that comes out: vec3f(1.0) goes through AgX and lands as grey.
// INTENSITY is what puts a mote above the paper it is drawn on, and above the
// bloom threshold. It is also why these read on a LIGHT background, where an
// additive glow at 1.0 would simply vanish.

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let a = rzHash13(seed + f32(id) * 0.0193);
  let b = rzHash13(seed * 1.61 + f32(id) * 0.0377);

  // Around the cast, gathered inward. sqrt alone spreads evenly over the disc,
  // which puts most of them at the rim where nobody is looking; the extra power
  // pulls them back toward the figure.
  let ang = a.x * 6.2831853;
  let radial = pow(sqrt(a.y), params.GATHER);
  let radius = mix(INNER, OUTER, radial);
  p.pos = CENTER + vec3f(cos(ang) * radius, mix(FLOOR, TOP, a.z), sin(ang) * radius);

  p.size = mix(SIZE_MIN, SIZE_MAX, b.x * b.x);
  p.vel = vec3f(0.0, params.RISE * mix(0.5, 1.5, b.y), 0.0);
  // Never expires: motes WRAP at the ceiling rather than recycling through the
  // pool, so none of them appears out of nothing in mid-air.
  p.life = 1.0e9;
  p.rot = b.z * 6.2831853;
  p.seed = seed + f32(id) * 0.0193;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Curl noise is divergence-free, so motes wander past each other instead of
  // collecting into the same thread the way a plain sine drift does.
  let w = rzCurlNoise(q.pos * params.SWIRL + vec3f(0.0, rzTime() * 0.07, 0.0));
  q.pos = q.pos + (q.vel + w * params.WANDER) * dt;
  // Over the top and back to the floor, on a freshly drawn ring so the same mote
  // never rises up the same line twice.
  if (q.pos.y > TOP) {
    let h = rzHash13(q.seed + rzTime() * 0.31);
    let ang = h.x * 6.2831853;
    let radius = mix(INNER, OUTER, pow(sqrt(h.y), params.GATHER));
    q.pos = vec3f(CENTER.x + cos(ang) * radius, FLOOR, CENTER.z + sin(ang) * radius);
  }
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let r = length(q);
  let ax = abs(q);

  // Every piece reaches EXACTLY zero at the quad's edge — rzFalloff has compact
  // support. A glow that merely gets small has to be cut off somewhere, and the
  // cut is a square edge that bloom then draws a box around.
  //
  // Squared rather than powed: pow is undefined for a negative base, and x*x
  // says the same thing about a value that reaches zero.
  let cf = rzFalloff(r, CORE);
  let core = cf * cf;
  let halo = rzFalloff(r, 1.0) * HALO;
  let sx = rzFalloff(ax.x, 1.0) * rzFalloff(ax.y, SPIKE_THIN);
  let sy = rzFalloff(ax.y, 1.0) * rzFalloff(ax.x, SPIKE_THIN);
  let flare = (sx + sy) * SPIKE;

  // A sharp pulse, not a swell. Raised to a sixth power the cycle sits near zero
  // for most of its length and flares briefly, which is what makes the shine an
  // EVENT rather than a state — and raising the power makes it RARER without
  // making it faster, which is the difference between a sky and a switchboard.
  let rate = 0.35 + 1.55 * rzHash11(p.seed * 3.41);
  let sw = 0.5 + 0.5 * sin(rzTime() * rate * TWINKLE * 6.2831853 + p.seed * 37.7);
  let sw2 = sw * sw;
  let flash = sw2 * sw2 * sw2 * FLASH;

  // THE POINT IS ALWAYS THERE; THE GLOW ONLY ARRIVES WITH THE FLASH.
  //
  // Halo and flare are gated on the pulse, the core is not. A halo that burns
  // constantly is what turns a field of stars into a field of blooming blobs:
  // every mote wears a permanent soft disc, and the twinkle is lost inside it.
  // Gated, a mote is a fine point until its moment and a burst of light during
  // it — and since bloom keys off brightness, it only blooms then too.
  //
  // SHAPE in alpha, BRIGHTNESS in colour: the fragment is premultiplied
  // (rgb * a), so a profile carried in both would be squared.
  let steady = mix(0.55, 1.0, rzHash11(p.seed * 2.29));
  let e = clamp(core * steady + (halo + flare) * flash, 0.0, 1.0);

  let warmth = rzHash11(p.seed * 5.09);
  let tint = mix(COOL, WARM, warmth);
  let bv = rzHash11(p.seed * 11.71);
  let bright = mix(0.4, 1.0 + BRIGHT_VAR, bv * bv * bv);
  return vec4f(tint * INTENSITY * bright, e);
}

#param float PERIOD 5 1 12 — seconds between a slot's launches
#param float GRAVITY 0.32 0 1
#param float CLIMB_SCALE 1.6 0.5 3 — stretches the climb only — a shell that shoots

// Fireworks — ported to WGSL from "Fireworks" by Gatomoi
// https://www.shadertoy.com/view/73sXWH
// The click-launched shells and the feedback trail are dropped: both needed
// extra buffers, and an effect here is a single pass.

// Tunables — edit and ⌘⏎.
//
// Sized UP for the half-res field pass: the sky holds nearly twice the shells,
// each bigger and hotter, and the arithmetic lands almost exactly on what the
// smaller show used to cost at full resolution. The culls are what let it
// scale — every pixel still rejects whole shells before touching a spark.
const SHELLS = 10;             // shells in the rotation
const PARTICLES = 72;          // sparks per shell — THE cost dial
const SECONDARY = 4;           // crackles each qualifying spark throws

// 0.382 of the period — the golden-ratio conjugate, kept in step with params.PERIOD. A
// rounder fraction resonates: were this an eighth of the period, slots 0 and 8
// would launch in lockstep and the sky would clump instead of filling.
const STAGGER = 1.25;          // seconds between one slot and the next — at
                               // 3.35s of life that is ~2.7 shells in the air
                               // at once, against ~1.75 before

                               // up instantly has no flight to watch
const SEQUENCE = 3.35;         // total life: climb + burst, and no longer — a slot
                               // past it is dead, so ending the window early is
                               // free frames
const BURST_TIME = 1.55;       // the reference's own burst length
// The reference's own value. Raising it was a mistake I made trying to force a
// visible fall — the fall is visible there because the trails DRAW it, not
// because the sparks drop harder, and a heavier one only made the burst hang
// below the point it went off at.

const CHILD_GRAVITY = 0.06;    // the same, for the embers
const CRACKLE_AT = 0.57;       // fraction of the burst before the secondaries go
const EXPOSURE = 1.8;
const SPEED = 0.85;            // clock multiplier — lower is slower, all of it
const BOOM = 1.15;             // how far the sparks throw — smaller sits further back
const WORLD_Z = 46.0;          // how far BEHIND the stage the shells rise
const WORLD_SPAN = 30.0;       // half-width of the firing line, world units
const WORLD_LOW = 17.0;        // burst heights, world units
const WORLD_HIGH = 30.0;
const REF_DIST = 55.0;         // the distance at which a shell wears its tuned size
const CLIMB_TRAIL = 0.045;     // how much of the climb the rocket's streak covers.
                               // Small, because the climb is EASED: at 0.2 the
                               // rocket has already flown half its path, so that
                               // much of "its past" is half the frame.
const HEAD_HALO = 0.022;       // how far the rocket's own glow carries
const CLIMB_GLOW = 2.6;        // brightness of that streak. Brightness IS opacity
                               // here: the layer's alpha is its own energy, so a
                               // dim streak is a see-through one.
const CLIMB_HALO = 0.006;       // and how WIDE it is allowed to be. Brightness and
                               // width are separate dials on purpose — a 1/r glow
                               // spreads as you brighten it, so without a bound
                               // the only legible streak is a fat one.

// The reference kept its streaks in a buffer that decayed 0.955/0.925/0.875 per
// frame, so a streak lived about this long — and PER CHANNEL, blue fastest. Both
// numbers below are that buffer, solved rather than eyeballed: at 60fps the decay
// rates are ln(1/0.955)·60 = 2.76 for red against 8.0 for blue, so a 0.37s-old
// piece of streak keeps 36% of its red and 5% of its blue. That is why the tails
// go orange, and it is a colour we can compute instead of guess at.
const TRAIL_SECONDS = 0.37;
const TRAIL_DECAY = vec3f(2.76, 4.68, 8.0);
const TRAIL_MIX = 0.72;        // what the reference composited that buffer at
const PLAIN_SHELLS = 0.1;      // fraction that burst with no trails at all
const SMALLEST = 0.7;          // the runt of the rotation, as a fraction of BOOM

const TAU = 6.28318530718;
// Every 1/r glow inside the cull is faded to exactly zero at this radius, and the
// cull is this radius past the farthest spark. That makes the boundary a
// definition rather than an estimate: nothing can be truncated, because nothing
// is still alive out there. Estimating it is what drew the ring — a glow reads as
// visible far further than its raw value suggests, since the tone map lifts it
// (alpha = 1 − exp(−1.52·c)) before the frame is quantised.
// Derived, not chosen: a spark's glow is size·0.78/d, so at the size above it
// falls under one code value at 0.32. Every glow inside the cull is faded to
// zero exactly here, which is what makes the boundary safe to cull on.
const GLOW_REACH = 0.52;
// One 8-bit code value, referred back through the tone map (alpha = 1 − exp(−1.52·c)).
// Anything dimmer than this cannot change a pixel, so it need not be drawn.
const VISIBLE = 0.0026;

fn background(ray: vec3f, uv0: vec2f, clock: f32) -> vec4f {
  // One dial for the whole display: shells, climbs, bursts and the sparkle rate
  // all read this clock, so slowing it slows them together instead of drifting
  // out of step with each other.
  let time = clock * SPEED;
  let res = rzResolution();
  // Square units, y in −1..1, x carrying the aspect — the convention this came
  // from, and the one the ballistics constants are tuned in.
  let uv = vec2f((uv0.x * 2.0 - 1.0) * (res.x / max(res.y, 1.0)), uv0.y * 2.0 - 1.0);

  var col = vec3f(0.0);
  for (var s = 0; s < SHELLS; s++) {
    let slot = f32(s);
    let offset = slot * STAGGER;
    if (time < offset) {
      continue;
    }
    // Each slot fires on its own cycle; floor() names the launch, and every
    // random the shell wears is drawn from that name, so it keeps its colour and
    // its scatter for as long as it burns.
    let cycle = floor((time - offset) / params.PERIOD);
    let elapsed = time - (cycle * params.PERIOD + offset);
    if (elapsed <= 0.0 || elapsed >= SEQUENCE) {
      continue;
    }
    let seed = vec2f(slot * 91.7 + cycle * 17.3, cycle * 41.9 + slot * 8.2);
    let wt = fwWorldTarget(slot, cycle);
    let pr = rzProject(wt);
    // Behind the lens, or close enough that the scale would explode: skip.
    if (pr.z < 4.0) { continue; }
    let pad = vec3f(wt.x + (fwHash(seed + vec2f(31.0, 4.0)) - 0.5) * 12.0, 0.0, wt.z);
    let pp = rzProject(pad);
    if (pp.z < 4.0) { continue; }
    let shellScale = clamp(REF_DIST / pr.z, 0.4, 1.6);
    col += fwSequence(uv, pr.xy * res, pp.xy * res, elapsed, seed, res, shellScale) * 0.82;
  }

  let vignette = smoothstep(0.84, 0.2, length(uv0 - 0.5));
  col *= 0.9 + 0.1 * vignette;

  // A soft shoulder rather than a clamp: highlights roll off instead of clipping
  // flat to white, which is what keeps a bright core its own colour.
  let mapped = 1.0 - exp(-max(col, vec3f(0.0)) * EXPOSURE);
  let energy = max(max(mapped.r, mapped.g), mapped.b);
  if (energy <= 0.0) {
    return vec4f(0.0);
  }
  // Hue in rgb, energy in alpha: the composite does rgb·a + background·(1−a),
  // so this reads as additive light while embers still let the sky through.
  return vec4f(mapped / energy, energy);
}

// Climb, then burst. One shell is only ever doing one of the two.
fn fwSequence(uv: vec2f, targetPixel: vec2f, startPixel: vec2f, elapsed: f32, seed: vec2f, res: vec2f, k: f32) -> vec3f {
  let climb = (0.9 + fwHash(seed + vec2f(45.0, 12.0)) * 0.18) * params.CLIMB_SCALE;
  if (elapsed < climb) {
    return fwRocket(uv, startPixel, targetPixel, elapsed / climb, seed, res, k);
  }
  let t = (elapsed - climb) / BURST_TIME;
  if (t < 1.0) {
    return fwBurst(uv, fwToWorld(targetPixel, res), t, seed, k);
  }
  return vec3f(0.0);
}

// ── The climb ──

fn fwRocket(uv: vec2f, startPixel: vec2f, targetPixel: vec2f, t: f32, seed: vec2f, res: vec2f, k: f32) -> vec3f {
  let pos = fwRocketPos(startPixel, targetPixel, t, seed, res);
  // Where it was an instant ago: the streak is the segment between the two, which
  // is the only trail we get in a single pass — the original accumulated one in a
  // feedback buffer.
  let prev = fwRocketPos(startPixel, targetPixel, max(t - CLIMB_TRAIL, 0.0), seed, res);

  let tint = normalize(fwPalette(seed) + vec3f(1.0, 0.72, 0.35));
  // The head needs its own bound for the same reason the streak does: at this
  // amplitude a bare 1/r stays above one code value two whole screen-heights
  // out, so the rocket dragged a frame-sized smudge around with it. Bounded, it
  // is a point with a small halo.
  // Both endpoints are PROJECTED, so the streak's length and slope already
  // carry the perspective; only the widths need the shell's scale.
  let hd = length(uv - pos) / k;
  let head = (0.0022 / (hd + 0.0011) * smoothstep(HEAD_HALO, 0.0, hd) +
              exp(-hd * hd * 55000.0) * 1.7);

  // The streak gets a hard core as well as a glow, for the same reason the
  // sparks do: a glow alone is a smudge, and it is the core that reads as a
  // line. `age` is 0 at the far end, so the streak thins and dims backwards
  // instead of ending square.
  var arc = fwArc(uv, prev, pos);
  arc.x = arc.x / k;
  // Holds full strength for the first third of the climb rather than starting to
  // go immediately, so the streak is still legible when the shell is high.
  let fadeIn = smoothstep(1.3, 0.35, t);
  let taper = mix(0.55, 1.0, arc.y);
  // The halo is faded to nothing at CLIMB_HALO, so the streak has an actual
  // edge; the core carries the light. Roughly three pixels wide at 1080p, which
  // is a wire rather than a band.
  let glow = 0.0014 / (arc.x + 0.0016) * smoothstep(CLIMB_HALO, 0.0, arc.x) *
             fadeIn * taper * CLIMB_GLOW;
  // 260000 against the head's 55000: the streak's falloff is a bit over half the
  // head's width, so the rocket reads as a point DRAGGING a wire rather than a
  // wire with a bulge in it. They were within 10% of each other before.
  let core = exp(-arc.x * arc.x * 260000.0) * 2.2 * fadeIn * taper * CLIMB_GLOW;

  return tint * head + mix(tint, vec3f(1.0, 0.38, 0.12), 0.35) * (glow + core);
}

fn fwRocketPos(startPixel: vec2f, targetPixel: vec2f, t: f32, seed: vec2f, res: vec2f) -> vec2f {
  // Eased so it leaves fast and arrives slow, the way a shell running out of
  // thrust does. A FOURTH power, not a cube: it puts the rocket within a fraction
  // of a percent of its apex by four-fifths of the climb, so the last stretch is
  // a hang rather than an arrival. Without that pause the burst reads as going
  // off mid-flight — there is no moment of being at the top to go off AT.
  let x = clamp(t, 0.0, 1.0);
  let inv = 1.0 - x;
  let inv2 = inv * inv;
  var p = mix(fwToWorld(startPixel, res), fwToWorld(targetPixel, res), 1.0 - inv2 * inv2);
  // A little lateral bow, biggest mid-flight.
  p.x += sin(t * 3.14159265359) * (fwHash(seed + vec2f(17.0, 91.0)) - 0.5) * 0.055;
  return p;
}

// ── The burst ──

fn fwBurst(uvIn: vec2f, center: vec2f, t: f32, seed: vec2f, k: f32) -> vec3f {
  // The shell's whole private frame, scaled about its own centre: every tuned
  // distance below — velocities, reaches, glow radii — lands k times larger on
  // screen, which is all "nearer" means to a billboard burst.
  let uv = center + (uvIn - center) / k;
  // Nothing in this shell reaches farther than its fastest spark, plus the
  // crackles it throws, plus the distance a glow stays visible. Outside that
  // circle the loop below cannot contribute, so it is skipped whole — and a young
  // shell is nearly a point, which is when the saving is largest.
  let rel = uv - center;
  // Not every shell is the same shell: the small ones read as further away and
  // give the big ones something to be big against.
  let boom = BOOM * mix(SMALLEST, 1.0, fwHash(seed + vec2f(5.5, 2.2)));

  // The opening flash is a 1/r glow, so it reaches much further than the sparks
  // early on and nothing at all once it has decayed — its radius is derived
  // rather than guessed: the distance at which it falls under one code value.
  let flashAmp = exp(-t * 18.0) * 0.010;
  let flashReach = max(flashAmp / VISIBLE, 1e-4);

  // ONE test for the whole shell, against whichever of the two is currently
  // larger. Returning here costs a pixel nothing at all — not even the palette,
  // which is four hashes and two normalises that most pixels have no use for.
  let reach = max(flashReach,
                  (1.02 * t + 0.16 + 0.5 * params.GRAVITY * t * t + CHILD_GRAVITY) * boom + GLOW_REACH);
  if (dot(rel, rel) > reach * reach) {
    return vec3f(0.0);
  }

  let tint = fwPalette(seed);
  let flashDistance = length(rel);
  var col = normalize(tint + vec3f(1.0)) * flashAmp / (flashDistance + 0.0025) *
            smoothstep(flashReach, 0.0, flashDistance);

  let emberTint = normalize(tint + vec3f(0.9, 0.55, 0.25));
  let hotTint = normalize(tint + vec3f(1.0, 0.62, 0.22));
  // A tenth of shells burst with no streaks at all, which is what keeps the sky
  // from reading as one firework repeated.
  let trails = fwHash(seed + vec2f(101.7, 53.3)) >= PLAIN_SHELLS;
  // The streak's span in burst-time: one unit of t is BURST_TIME/SPEED seconds.
  let trailLen = select(0.0, TRAIL_SECONDS * SPEED / BURST_TIME, trails);
  let hSeed = fwHash(seed);

  let fade = smoothstep(0.82, 0.08, t);
  // The streaked layer outlives the sharp one and ramps in over the first frames
  // rather than arriving whole — both straight from the reference's second pass.
  let trailFade = smoothstep(0.95, 0.08, t) * smoothstep(0.0, 0.06, t);
  let crackleT = clamp((t - CRACKLE_AT) / (1.0 - CRACKLE_AT), 0.0, 1.0);

  // Radii for the rejects in the loop, hoisted — the same for every spark in the
  // shell. A spark's arc is no longer than its top speed plus gravity over the
  // streak's span; its embers stay within their own scatter.
  let sparkReach = (1.02 + params.GRAVITY) * boom * trailLen + GLOW_REACH;
  let emberReach = (0.16 + CHILD_GRAVITY) * boom + GLOW_REACH;

  for (var particle = 0; particle < PARTICLES; particle++) {
    let i = f32(particle);
    // An even fan, jittered, so the shell is round without being a stencil.
    let angle = i * (TAU / f32(PARTICLES)) + (fwHash(seed + vec2f(i, 13.1)) - 0.5) * 0.22;
    let velocity = vec2f(cos(angle), sin(angle)) * ((0.3 + 0.72 * fwHash(vec2f(i, hSeed))) * boom);

    let pos = fwBallistic(center, velocity, t, boom);

    // A pixel further from the spark than its whole arc plus a glow's reach
    // cannot be lit by any part of it. Skipping here skips the second ballistic,
    // the segment solve and all the shading — and a shell's sparks fan out over
    // ten times a glow's radius, so nearly all of them miss any given pixel.
    let toSpark = uv - pos;
    if (dot(toSpark, toSpark) <= sparkReach * sparkReach) {
      let sparkle = sin(t * 58.0 + i + hSeed * 12.0) * 0.5 + 0.5;

      // ── The sharp spark. Every one of them, drawn at where it IS. Gated on its
      // OWN radius, which is tighter than the reject above: that one has to cover
      // the streak's whole length, so between the two radii this maths would run
      // only to be multiplied by a window of zero.
      let d = length(toSpark);
      if (d < GLOW_REACH) {
        let size = 0.00125 * fade * (0.55 + 0.45 * sparkle);
        let glow = size / (d + 0.00062) * smoothstep(GLOW_REACH, 0.0, d);
        let core = exp(-d * d * 120000.0) * 1.35 * fade * (0.75 + 0.25 * sparkle);
        col += tint * (glow * 0.78 + core);
      }

      // ── The streak. EVERY OTHER spark, exactly as the reference's second pass
      // stepped its particle index by two: half the shell streaks and half stays
      // sharp, and it is the mixture that reads as fireworks rather than as a
      // net. Drawing it on all of them was what made the sky look woven.
      if (trails && (particle & 1) == 0) {
        let prev = fwBallistic(center, velocity, max(t - trailLen, 0.0), boom);
        // .x = distance to the arc, .y = where along it — 0 at the tail, 1 at
        // the spark. The second is the streak's own age, in seconds.
        let arc = fwArc(uv, prev, pos);
        let td = arc.x;
        if (td < GLOW_REACH) {
          // The decay the buffer applied over frames, applied over LENGTH
          // instead. Per channel, so the tail goes orange on its own rather than
          // being tinted orange by hand.
          let held = exp(-TRAIL_DECAY * ((1.0 - arc.y) * TRAIL_SECONDS));
          let tSize = 0.00105 * trailFade * (0.6 + 0.4 * sparkle);
          let tGlow = tSize / (td + 0.00072) * smoothstep(GLOW_REACH, 0.0, td);
          let tCore = exp(-td * td * 95000.0) * trailFade * (0.65 + 0.35 * sparkle);
          col += mix(tint, hotTint, 0.28 + sparkle * 0.2) * held *
                 (tGlow * 0.52 + tCore * 0.46) * TRAIL_MIX;
        }
      }
    }

    // Roughly two in five sparks crackle into a handful of embers. Tested
    // separately from the spark above, and NOT skipped with it: a crackle goes
    // off where the spark was at CRACKLE_AT, which by now is somewhere else
    // entirely.
    if (crackleT > 0.0 && fwHash(seed + vec2f(i, 71.7)) >= 0.58) {
      let origin = fwBallistic(center, velocity, CRACKLE_AT, boom);
      let toOrigin = uv - origin;
      if (dot(toOrigin, toOrigin) > emberReach * emberReach) {
        continue;
      }
      let flashDist = length(toOrigin);
      col += emberTint * exp(-crackleT * 20.0) * 0.0032 / (flashDist + 0.0018) *
             smoothstep(GLOW_REACH, 0.0, flashDist);

      for (var child = 0; child < SECONDARY; child++) {
        let j = f32(child);
        let cSeed = fwHash(seed + vec2f(i * 17.0, j * 23.0));
        let cAngle = TAU * (j / f32(SECONDARY) + cSeed * 0.35);
        let cVel = vec2f(cos(cAngle), sin(cAngle)) *
                   ((0.06 + 0.10 * fwHash(seed + vec2f(j * 9.0, i * 5.0))) * boom);

        var cPos = origin + cVel * crackleT;
        cPos.y -= CHILD_GRAVITY * boom * crackleT * crackleT;

        let cd = length(uv - cPos);
        let cFade = smoothstep(1.0, 0.05, crackleT);
        col += mix(emberTint, vec3f(1.0, 0.82, 0.42), cSeed * 0.45) *
               ((0.00088 * cFade) / (cd + 0.00062) * 0.75 * smoothstep(GLOW_REACH, 0.0, cd) +
                exp(-cd * cd * 150000.0) * 0.85 * cFade);
      }
    }
  }

  return col;
}

fn fwBallistic(center: vec2f, velocity: vec2f, t: f32, boom: f32) -> vec2f {
  // Gravity scales with the shell alongside the velocity it fights. Throwing the
  // sparks half again as far while they still drop the same 0.15 flattens every
  // arc into a straight fan — the trajectory has to grow with the shell, or the
  // shell stops falling.
  return center + velocity * t - vec2f(0.0, 0.5 * params.GRAVITY * boom * t * t);
}

// ── Toolbox ──

/**
 * Where shell (slot, cycle) bursts — a WORLD point behind the stage.
 *
 * The display used to be composed in screen space, which is why it moved with
 * the camera: it was wallpaper. Anchored in the world and projected each frame
 * (rzProject), the shells stay put while you orbit, sit behind the character
 * because the background mount composites behind the scene, and gain parallax
 * for free — a shell farther down the line is smaller because it IS farther.
 */
fn fwWorldTarget(slot: f32, cycle: f32) -> vec3f {
  let seed = vec2f(slot * 37.17 + cycle * 11.31, cycle * 23.73 + slot * 5.91);
  return vec3f(
    mix(-WORLD_SPAN, WORLD_SPAN, fwHash(seed + vec2f(1.0, 0.0))),
    mix(WORLD_LOW, WORLD_HIGH, fwHash(seed + vec2f(0.0, 1.0))),
    WORLD_Z + (fwHash(seed + vec2f(2.0, 7.0)) - 0.5) * 14.0,
  );
}

/** Pixels → the square, y-normalised space everything above is tuned in. */
fn fwToWorld(pixel: vec2f, res: vec2f) -> vec2f {
  return (pixel * 2.0 - res) / max(res.y, 1.0);
}

fn fwPalette(seed: vec2f) -> vec3f {
  // A pyrotechnician's palette, not noise. Random RGB pulled toward warm or
  // cool and normalised always averaged out to pastel — every shell the same
  // washed grey-gold. Real shows read as NAMED colours: strontium red, sodium
  // gold, barium green, copper blue... eight of them, picked per shell, with a
  // small wobble so two reds are sisters rather than twins.
  let pick = i32(fwHash(seed + vec2f(11.3, 0.7)) * 7.99);
  var c = vec3f(1.0, 0.92, 0.80);                  // 7: white-gold
  if (pick == 0) { c = vec3f(1.0, 0.22, 0.20); }   // strontium red
  if (pick == 1) { c = vec3f(1.0, 0.62, 0.16); }   // sodium gold
  if (pick == 2) { c = vec3f(1.0, 0.92, 0.35); }   // champagne
  if (pick == 3) { c = vec3f(0.30, 1.0, 0.42); }   // barium green
  if (pick == 4) { c = vec3f(0.25, 0.85, 1.0); }   // cyan
  if (pick == 5) { c = vec3f(0.35, 0.45, 1.0); }   // copper blue
  if (pick == 6) { c = vec3f(1.0, 0.35, 0.75); }   // magenta
  let wob = (fwHash(seed + vec2f(2.1, 19.8)) - 0.5) * 0.18;
  return normalize(c + vec3f(wob, -wob * 0.5, wob * 0.3));
}

/** Distance to the segment ab — the rocket's streak. */
fn fwSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  return fwArc(p, a, b).x;
}

/** Distance to segment ab, and how far along it the nearest point sits (0 at a,
 *  1 at b). A spark's streak needs both: the distance draws it, the position
 *  along it ages it. */
fn fwArc(p: vec2f, a: vec2f, b: vec2f) -> vec2f {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 0.00001), 0.0, 1.0);
  return vec2f(length(pa - ba * h), h);
}

fn fwHash(p0: vec2f) -> f32 {
  var p = fract(p0 * vec2f(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

// ── The light a burst throws ─────────────────────────────────────────────────
//
// This is the case the lightEmit mount was built for. A shell's burst position
// is already a closed form in this file — fwWorldTarget(slot, cycle) — so the
// light re-evaluates the SAME expression the picture is drawn from. Nothing is
// mirrored on the CPU, so there is no second derivation to drift, and an
// offline export stepped at another rate gets the same answer as playback.
//
// Four lights against ten shells, because a slot only qualifies while it is
// BURSTING: 1.55s of a 5s period, so four slots average a bit over one lit at
// a time and peak at four. Ten lights would be ten slots of budget for the
// same picture.
//
// The climb throws nothing. A rocket is a spark against the sky; it is the
// burst that lights a field, and spending a slot on the climb would keep a
// light alive for the two-thirds of the sequence when it is doing nothing.
#lights 4
const FLASH_PEAK = 2.2;    // brightness at the burst itself
const FLASH_REACH = 90.0;  // world units. The shells sit WORLD_Z behind the
                           // stage and WORLD_LOW..HIGH up, so the stage is ~50
                           // units away — a reach under that lights nothing
const FLASH_DECAY = 4.0;   // how fast the flash falls off across the burst

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  // Dark by default, and every early return leaves it that way: a slot between
  // bursts is not a light at zero brightness sitting somewhere, it is no light.
  l.pos = vec3f(0.0, WORLD_LOW, WORLD_Z);
  l.color = vec3f(1.0);
  l.intensity = 0.0;
  l.radius = 1.0;

  // The same clock the picture runs on, including SPEED — slowing the display
  // has to slow the light with it or they come apart.
  let t = time * SPEED;
  let slot = f32(i);
  let offset = slot * STAGGER;
  if (t < offset) { return l; }

  // floor() names the launch, exactly as background() does, so this light is
  // reading the same shell the same way — same cycle, same seed, same colour.
  let cycle = floor((t - offset) / params.PERIOD);
  let elapsed = t - (cycle * params.PERIOD + offset);
  let climb = SEQUENCE - BURST_TIME;
  if (elapsed < climb || elapsed >= SEQUENCE) { return l; }

  let seed = vec2f(slot * 91.7 + cycle * 17.3, cycle * 41.9 + slot * 8.2);
  l.pos = fwWorldTarget(slot, cycle);
  l.color = fwPalette(seed);
  l.radius = FLASH_REACH;

  // A burst is a FLASH: almost all of the light in the first fraction, then a
  // fall. exp() alone never reaches zero, so the tail is faded out over the
  // last of the burst — a light still lit when its sparks have gone is a lamp
  // hanging in the sky.
  let bt = (elapsed - climb) / BURST_TIME;
  l.intensity = FLASH_PEAK * exp(-bt * FLASH_DECAY) * (1.0 - smoothstep(0.8, 1.0, bt));
  return l;
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#anchor 左手首 trail
#anchor 右手首 trail
#particles 320
#blend additive
#bloom

#param color CORE_COLOR #dbf7ff — white-hot, faintly blue
#param color BODY_COLOR #1f6bff — electric blue
#param color HAZE_COLOR #571afa — violet, in the outer light
#param color SPARK_COLOR #5c3dff — the sparks' halo
#param color SPARK_HOT #b899ff — and the pinpoint inside it
#param float LIFETIME 0.8 0.1 2 — seconds of path drawn behind the hand
#param float WIDTH 0.6 0.1 2 — half-width of the GLOW in world units

// A neon ribbon along the path each hand actually took — with the sparks it
// sheds living as real GPU particles.
//
// The fullscreen original walked up to 128 trail samples PER PIXEL and drew its
// sparks by looping over every path sample at every pixel; it looked right and
// cost the frame rate. This version draws the same recorded history as
// geometry: 127 spline-smoothed segments per hand, and the sparks are the first
// use of both mounts in one file — particleInit spawns them ON the trail, from
// the same buffer the ribbon reads.
//
// The ribbon renders into its OWN layer, max-blended — the original's
// core-takes-the-max rule as a blend mode — then composites over the frame
// AFTER tone mapping, exactly where the fullscreen version ran. Max is why the
// parallel strands of a circling hand cannot double into bright dashes, and
// post-tonemap is why these colours reach the screen verbatim, never bleached
// by AgX. (The @blend/@bloom pragmas below apply to the SPARKS, which are
// particles in the scene pass; the ribbon's blending is fixed by the layer.)
//
// Tunables — edit and ⌘⏎.

// WORLD UNITS — the ribbon is a thing in the scene, so its width lives in the
// model's units and foreshortens with distance like everything else. (It was
// pixels once, faithful to the fullscreen original; the engine converts world
// width to the screen-space extrusion per vertex now, so the original's
// artefact-free 2D geometry is unchanged.) 0.7 is the old 32px at the editor's
// usual framing of a ~20-unit character, then tuned down by eye.

const CORE_FRAC = 0.21;  // the hot core inside it — the original's 7px in 34
const TAIL_WIDTH = 0.40; // core width at the far end, as a fraction
const TAIL_EASE = 0.22;  // last stretch of life spent fading to nothing
// Rebalanced toward the saber grammar: the white-hot part is a THIN line and
// the saturated colour is most of the visible width. CORE high makes white
// spread; HALO carries the neon.
const CORE = 2.6;        // weight of the core — what makes it read as light
// 0.55 in the original — times the overlap its `+=` accumulated. There every
// pixel SUMMED every segment within the glow radius (about 1.5 segments' worth
// on a straight path); here the quads tile, so each pixel samples the profile
// once and the weight carries the difference.
// The wide soft skirt. It is what BLOOM has to catch: the pyramid works on
// what is already on screen, so a thin hot filament with nothing around it
// blooms into a thin hot filament. Widening the skirt is what makes the
// light spread rather than just brighten.
const HALO = 0.85;
const LIGHT = 1.35;      // final gain on the ribbon's alpha
// Ribbons draw INSIDE the scene pass now — HDR, before tone mapping — so this
// colour is no longer what reaches the screen. vec3f(1.0) goes through AgX and
// lands as grey, which is why the ribbon dimmed the moment it stopped being
// pasted over the finished frame. Same constant Snow carries, for the same
// reason: anything meant to read as LIGHT has to out-shine the paper.
const INTENSITY = 3.2;

// Sparks. World units; a model stands ~20 units tall, judge against that.
//
// THEIR TWO COLOURS ARE DIALS, and the pair is deliberate: a spark is a hard
// pinpoint inside a soft halo, and picking one colour for both gives a smudge
// in that colour rather than a spark. SPARK_COLOR is the halo, SPARK_HOT the
// centre — ordinarily the same hue carried up toward white.
//
// KEEP THE HALO DEEP. Sparks are PARTICLES, so unlike the ribbon they render in
// the scene pass and pass through AgX, which bleaches any bright tint toward
// white: a pale halo arrives on screen as a grey dot with no hue left in it.
// The lightness belongs in the pinpoint, where it is small enough to survive as
// a highlight rather than wash the whole spark out.
const SPARK_LIFE = 0.80;  // seconds a spark lives, when the trail lasts at least that long
const SPARK_EMERGE = 0.30;// spent fading in, while it swings clear of the ribbon

/** A spark dies with the ribbon it came off, so shortening the trail does not
 *  leave dots hanging where the path used to be. */
fn sparkLife() -> f32 { return min(SPARK_LIFE, params.LIFETIME); }
const SPARK_SIZE = 0.07;
const ORBIT_SPEED = 2.5;  // how hard the path curls sideways as it flies
const DRIFT = 2.6;        // outward speed at birth — clear the ribbon fast
const RISE = 2.4;         // upward drift
const TWINKLE = 9.0;
const SPARK_INTENSITY = 1.7;   // low, or AgX's shoulder eats the hue

// ── The ribbon ──────────────────────────────────────────────────────────────

fn trailWidth(u: f32, age: f32) -> f32 {
  // The quad IS the glow, and the glow keeps a constant radius — only the core
  // narrows down the tail (in trailShade). The width itself just closes the very
  // end so the oldest sample is not a hard edge, and it deliberately ignores how
  // fast the hand moves: pinching where the hand slows breaks the ribbon at
  // every turn, because a turn is where a hand decelerates.
  let a = clamp(1.0 - age / params.LIFETIME, 0.0, 1.0);
  // rzViewportHeight()/1080 is the original's pxK: the same effect at a 4K
  // export and in the editor, instead of a different-looking one per resolution.
  return params.WIDTH * smoothstep(0.0, TAIL_EASE, a);
}

fn trailShade(u: f32, v: f32, age: f32, weight: f32, slot: i32) -> vec4f {
  // `a` runs 1 at the hand to 0 at the end of params.LIFETIME, exactly as the original.
  let a = clamp(1.0 - age / params.LIFETIME, 0.0, 1.0);
  let ease = smoothstep(0.0, TAIL_EASE, a);
  let bright = a * a * ease;
  let d = abs(v);

  // A GAUSSIAN core inside a compact-support halo — the original's two shapes.
  // `weight` is the engine's segment length over a full contribution: the line
  // integral, so a pausing hand goes dim and blue instead of white.
  let frac = CORE_FRAC * mix(TAIL_WIDTH, 1.0, pow(a, 0.7));
  let core = exp(-(d * d) / max(frac * frac, 1e-6)) * bright * weight;
  let halo = rzFalloff(d, 1.0) * bright * weight;
  let heat = core * CORE + halo * HALO;

  // Colour FROM intensity: white only where it is genuinely hot, azure through
  // the body, deep blue in the outer light.
  var rgb = mix(params.HAZE_COLOR, params.BODY_COLOR, smoothstep(0.03, 0.40, heat));
  rgb = mix(rgb, params.CORE_COLOR, smoothstep(0.45, 1.30, heat));
  // No gain, no tone-map compensation: the layer composites after AgX, so what
  // is written here is what appears — the original's own contract.
  return vec4f(rgb * INTENSITY, clamp(heat * LIGHT, 0.0, 1.0));
}

// ── The sparks ──────────────────────────────────────────────────────────────

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let h = rzHash13(seed + f32(id) * 0.0193);
  let h2 = rzHash13(seed * 3.1 + f32(id) * 0.0711);
  // A hand, a character, a recent point on that hand's path.
  let slot = i32(h.x * f32(RZ_TRAIL_SLOTS));
  var subject = i32(h.y * 4.0) % 4;
  if (rzTrailCount(subject, slot) < 6) { subject = 0; }
  let n = rzTrailCount(subject, slot);
  // Half a second of real history before the FIRST spark — a catch-all for
  // every first-frame path shape (bind pose, load pop-in, first-pose snap):
  // whatever those look like, a freshly started trail sits out the grace and a
  // burst at scene start is impossible by construction, not by enumeration.
  if (n < 6 || rzTrail(subject, slot, n - 1).w < 0.5) {
    p.life = 0.0;
    return p;
  }
  // Spread along the recent path, not piled at the live end — 512 sparks all
  // born at the newest five samples was a permanent starburst welded to the
  // hand, and its bloom spikes read as burrs on the ribbon.
  let k = 1 + i32(h.z * 24.0);
  let sampleA = rzTrail(subject, slot, k);
  let sampleB = rzTrail(subject, slot, min(k + 2, n - 1));
  // Sparks are shed by MOTION, so a still path sheds none. A resting hand keeps
  // a trail — a cluster of near-identical samples — and unguarded spawns
  // fountained from it while the ribbon itself rightly drew nothing. The same
  // guard kills the burst at the world origin while a model loads: its bones
  // sit at (0,0,0) then, which is just another perfectly still path.
  if (distance(sampleA.xyz, sampleB.xyz) < 0.06) {
    p.life = 0.0;
    return p;
  }
  p.pos = sampleA.xyz;
  // Thrown outward and upward; the swirl in the step curls the path.
  let phase = h2.x * 6.2831853;
  p.vel = vec3f(cos(phase) * DRIFT, RISE * 0.5, sin(phase) * DRIFT);
  p.size = SPARK_SIZE * (0.6 + 0.9 * h2.y);
  p.life = sparkLife() * (0.7 + 0.5 * h2.z);
  p.seed = h2.x * 39.0 + h.z * 17.0;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Curl the horizontal velocity, so a spark orbits away from the path rather
  // than flying a straight line off it.
  let c = cos(ORBIT_SPEED * dt);
  let s = sin(ORBIT_SPEED * dt);
  q.vel = vec3f(q.vel.x * c - q.vel.z * s, q.vel.y + RISE * 0.6 * dt, q.vel.x * s + q.vel.z * c);
  q.pos = q.pos + q.vel * dt;
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let dd = length(q);
  let t = clamp(p.age / max(p.life, 1e-3), 0.0, 1.0);
  // Fade IN first: a spark born at full brightness is a bright dot sitting on
  // the ribbon. By the time it is visible it has swung clear.
  let emerge = smoothstep(0.0, SPARK_EMERGE / sparkLife(), t);
  let fall = (1.0 - t) * (1.0 - t);
  let twinkle = 0.4 + 0.6 * sin(rzTime() * TWINKLE + p.seed);
  // A hard pinpoint inside a soft bloom — a spark, not a smudge.
  let soft = exp(-(dd * dd) / 0.5);
  let hot = exp(-(dd * dd) / 0.08);
  let alpha = clamp((soft * 0.55 + hot) * fall * twinkle * emerge, 0.0, 1.0);
  // Two-tone: violet halo, lavender heart — colour from intensity, the ribbon's
  // own rule at spark scale.
  let rgb = mix(params.SPARK_COLOR, params.SPARK_HOT, clamp(hot, 0.0, 1.0));
  return vec4f(rgb * SPARK_INTENSITY, alpha);
}

// ── The light the ribbons throw ──────────────────────────────────────────────
//
// The ribbons already GLOW: they draw inside the scene pass, so the bloom
// pyramid catches them. What they never did is LIGHT anything — a neon band
// whipping past a dress left it exactly as the sun had it, which is the same
// tell the fire and the follow-spots had before they declared lights.
//
// One light per wrist, at the anchors the ribbons are already drawn from, so
// the light is where the band is by construction rather than by a second guess
// at where her hands are.
#lights 2
const RIBBON_LIGHT_I = 1.4;   // brightness at the wrist
const RIBBON_LIGHT_R = 7.0;   // world units — a band lights what it passes,
                              // not the room; this is about an arm's length

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  // params.BODY_COLOR, not params.CORE_COLOR: the core is white-hot and would wash whatever
  // it touched, and the colour a viewer reads off the ribbon is the body.
  l.color = params.BODY_COLOR;
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0, 0.0, 0.0);

  // Slot 0 is the left wrist, 1 the right — the same order the anchors are
  // declared in at the top of this file, which is what rzAnchor's slots mean.
  //
  // SUBJECT 0, deliberately. The ribbons themselves are drawn for every
  // character in the scene, but a light is a declared cost: covering four
  // dancers would spend eight of the sixteen slots on one effect, and leave a
  // composer no room for the stage. One dancer is what this is for.
  let a = rzAnchor(0, i32(i));
  if (!a.valid) { return l; }
  l.pos = a.pos;
  l.radius = RIBBON_LIGHT_R;

  // Brighter the faster the hand moves, because that is when the ribbon is
  // longest and brightest — a still hand trails almost nothing, and a light
  // blazing off a motionless wrist reads as a lamp she is holding.
  let speed = length(a.vel);
  l.intensity = RIBBON_LIGHT_I * clamp(speed / 12.0, 0.0, 1.0);
  return l;
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#anchor 左手首 trail
#anchor 右手首 trail
#particles 3584
#blend additive
#bloom
#lights 2

#param color GOLD_COLOR #ffbd47 — the body
#param color HOLY_COLOR #fff7e0 — the pinpoint — warm white
#param float INTENSITY 1.6 0 4 — low, or AgX's shoulder eats the gold
#param float TRAIL_LIFE 0.85 0.2 2 — seconds of path the swarm covers

// A trail with nothing drawing the trail.
//
// Hand Ribbon extrudes the recorded path into geometry and sheds a few sparks
// off it for garnish. Here the sparks ARE the path: no trailWidth, no
// trailShade, no band — a swarm of motes dropped onto the hand's own history,
// dense enough that the eye joins them into a stroke.
//
// The rule that makes it a trail rather than a fog: rzTrail hands back HOW MANY
// SECONDS AGO each sample was recorded, so a spark is given exactly the time
// that sample has left before it ages out. The swarm covers the path by
// construction, and it retracts as the path does, without a second constant
// deciding how long a trail looks like it should be.
//
// GOLD IS THE HARD PART. Particles draw inside the scene pass, in HDR, and go
// through AgX — which pulls anything bright toward white. A gold that is bright
// at source arrives as cream. So the halo is a DEEP amber that has somewhere to
// go, and the whiteness is confined to the pinpoint at the centre where it
// reads as heat rather than as a wash.
//
// Tunables — edit and ⌘⏎.

// The palette, darkest outward. Colour comes FROM intensity: a mote is amber at
// its edge, gold through its body, and near-white only in the very centre.
const HALO_COLOR = vec3f(0.52, 0.26, 0.02);  // deep amber, the outer light

const MIN_LIFE = 0.28;    // floor, so a mote placed at the very oldest sample
                          // still gets long enough to be seen fading. Also what
                          // keeps the old end from churning: a mote given
                          // almost no life is respawned almost at once, and a
                          // swarm doing that flickers
// World units — a model stands ~20 units tall, judge sizes against that.
const SPARK_SIZE = 0.082;
const SIZE_FALL = 0.55;   // how much smaller a mote is at the old end
const MOVE_MIN = 0.05;    // a still hand sheds nothing. A resting hand keeps a
                          // trail — a cluster of near-identical samples — and
                          // unguarded that fountains motes from a hand that is
                          // not moving. It is also what kills the burst at the
                          // world origin while a model loads, since bones sit
                          // at (0,0,0) then and that is just another still path
const THREAD = 0.07;      // how thick the stroke is AT THE HAND. The swarm was
                          // a wire there and only opened out behind, so the
                          // live end read as a line and the tail as smoke —
                          // two different materials in one stroke
const FRAY = 0.78;        // and how far it has spread by the old end. 0 is a
                          // wire the whole way; this is what makes the stroke
                          // dissolve into motes behind the hand instead of
                          // ending
const DRIFT = 0.35;       // outward speed. Still small — the swarm has to hold
                          // the shape of the path, and anything that flies off
                          // it is a spark effect rather than a trail
const RISE = 0.55;        // upward drift. Nothing falls: this is light
const SWIRL = 0.9;        // how the path curls as it rises
const TWINKLE = 5.5;      // slow, and shallow — see particleShade. A mote that
                          // swings between a fifth and full brightness nine
                          // times a second is not twinkling, it is strobing

// ── The swarm ───────────────────────────────────────────────────────────────

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let h = rzHash13(seed + f32(id) * 0.0193);
  let h2 = rzHash13(seed * 3.1 + f32(id) * 0.0711);

  // A hand, a character.
  let slot = i32(h.x * f32(RZ_TRAIL_SLOTS));
  var subject = i32(h.y * 4.0) % 4;
  if (rzTrailCount(subject, slot) < 6) { subject = 0; }
  let n = rzTrailCount(subject, slot);
  // Half a second of real history before the first mote — a catch-all for every
  // first-frame path shape (bind pose, load pop-in, first-pose snap): whatever
  // those look like, a freshly started trail sits out the grace, so a burst at
  // scene start is impossible by construction rather than by enumeration.
  if (n < 6 || rzTrail(subject, slot, n - 1).w < 0.5) {
    p.life = 0.0;
    return p;
  }

  // WHERE ON THE PATH, as a fractional index, so motes land BETWEEN recorded
  // samples as well as on them. Landing only on samples beads the stroke at
  // whatever rate the path happens to be recorded at.
  //
  // Squared, so the live end is written densely and the tail is only patched:
  // the newest stretch is the part being read as a stroke, and it is also the
  // part a spark has the longest to live on.
  let along = h.z * h.z;
  let fi = along * f32(n - 2);
  let ki = i32(fi);
  let fr = fi - f32(ki);
  let s0 = rzTrail(subject, slot, ki);
  let s1 = rzTrail(subject, slot, ki + 1);

  // Motion, measured across a couple of samples rather than one — a single gap
  // is short enough that a slow hand reads as a still one.
  if (distance(s0.xyz, rzTrail(subject, slot, min(ki + 2, n - 1)).xyz) < MOVE_MIN) {
    p.life = 0.0;
    return p;
  }

  let at = mix(s0.xyz, s1.xyz, fr);
  let age = mix(s0.w, s1.w, fr);
  let old = clamp(age / params.TRAIL_LIFE, 0.0, 1.0);

  // A direction on the sphere, used for both the spread and the drift — so a
  // mote continues the way it was placed instead of scattering from a point it
  // has already left.
  let phase = h2.x * 6.2831853;
  let zt = h2.y * 2.0 - 1.0;
  let rr = sqrt(max(1.0 - zt * zt, 0.0));
  let dir = vec3f(rr * cos(phase), zt, rr * sin(phase));

  // THE FRAY GROWS WITH AGE. At the hand the motes sit on the path and the
  // stroke is tight; further back they have wandered, and the stroke opens into
  // a veil. Applied at birth as well as through the drift, so a mote placed
  // straight onto an old part of the path matches the ones that drifted there.
  p.pos = at + dir * ((THREAD + (FRAY - THREAD) * old) * h2.z);
  p.vel = dir * DRIFT + vec3f(0.0, RISE, 0.0);
  p.size = max(SPARK_SIZE * (1.0 - SIZE_FALL * old) * (0.6 + 0.8 * h2.y), 0.015);
  // EXACTLY WHAT THE SAMPLE HAS LEFT. This is the whole trick: the swarm ends
  // where the path ends because every mote is on the same clock as the point it
  // is marking.
  p.life = max(params.TRAIL_LIFE - age, MIN_LIFE) * (0.8 + 0.4 * h2.z);
  p.seed = h2.x * 39.0 + h.z * 17.0;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Rising and turning. Embers of light, so there is no gravity term at all —
  // a mote that falls reads as debris off a firework, which is a different
  // thing entirely from a trail of holy light.
  let c = cos(SWIRL * dt);
  let s = sin(SWIRL * dt);
  q.vel = vec3f(q.vel.x * c - q.vel.z * s, q.vel.y + RISE * 0.5 * dt, q.vel.x * s + q.vel.z * c);
  q.pos = q.pos + q.vel * dt;
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let dd = length(q);
  let t = clamp(p.age / max(p.life, 1e-3), 0.0, 1.0);
  // Short fade in, long fade out — a mote arrives on the path rather than
  // popping onto it, and leaves slowly enough that the tail dissolves.
  let emerge = smoothstep(0.0, 0.18, t);
  let fall = (1.0 - t) * (1.0 - t);
  let twinkle = 0.80 + 0.20 * sin(rzTime() * TWINKLE + p.seed);

  // Three shapes: a soft bloom for the bloom pyramid to catch, a hard pinpoint
  // for the heat, and a screen-aligned cross. The cross is what separates HOLY
  // from merely bright — it is the flare a light source picks up through a lens,
  // and at these sizes it reads as a twinkle rather than as a drawn star.
  let soft = exp(-(dd * dd) / 0.55);
  let hot = exp(-(dd * dd) / 0.06);
  let bar = exp(-abs(q.x) * 9.0) * exp(-(q.y * q.y) / 0.02);
  let col = exp(-abs(q.y) * 9.0) * exp(-(q.x * q.x) / 0.02);
  let heat = soft * 0.42 + (bar + col) * 0.30 + hot;

  var rgb = mix(HALO_COLOR, params.GOLD_COLOR, smoothstep(0.05, 0.55, heat));
  rgb = mix(rgb, params.HOLY_COLOR, smoothstep(0.75, 1.25, heat));
  let alpha = clamp(heat * fall * twinkle * emerge, 0.0, 1.0);
  return vec4f(rgb * params.INTENSITY, alpha);
}

// ── The light the swarm throws ──────────────────────────────────────────────
//
// One light per wrist, at the anchors the motes are already dropped from, so
// the light is where the stroke is by construction rather than by a second
// guess at where her hands are.
const LIGHT_COLOR = vec3f(1.00, 0.70, 0.28);  // warm gold. Not the pinpoint's
                                              // near-white, which would wash
                                              // whatever it touched
const LIGHT_I = 1.05;
const LIGHT_R = 7.5;   // world units — an arm's length, not the room
const LIGHT_REST = 0.45;  // what a still hand keeps. Hand Ribbon's light goes
                          // out entirely when the hand stops, because a neon
                          // band with no trail behind it is nothing. A halo is
                          // not: it belongs to the hand, not to the motion
const LIGHT_FULL = 9.0;   // hand speed, world units per second, at which the
                          // light is all the way up

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  l.color = LIGHT_COLOR;
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0, 0.0, 0.0);

  // Slot 0 is the left wrist, 1 the right — the order the anchors are declared
  // in at the top of this file, which is what rzAnchor's slots mean.
  //
  // SUBJECT 0, deliberately. The motes are dropped for every character in the
  // scene, but a light is a declared cost: covering four dancers would spend
  // eight of the sixteen slots on one effect and leave a composer no room for
  // the stage.
  let a = rzAnchor(0, i32(i));
  if (!a.valid) { return l; }
  l.pos = a.pos;
  l.radius = LIGHT_R;

  // HOW FAST SHE IS MOVING, AVERAGED OVER THE WHOLE RECORDED PATH.
  //
  // This read length(a.vel), which is one frame's velocity — a number that
  // jumps between frames because a pose track is sampled, not smooth. A light
  // driven by it flickers on the model, and no amount of tuning the curve
  // fixes that: the input is the noise.
  //
  // The path is its own low-pass. Walking it and dividing the distance covered
  // by how long it took is an average over the trail's whole span, so the light
  // can only change as fast as a hand can change its mind. Path LENGTH, not the
  // distance between the ends — a circling hand comes back to where it started
  // and would otherwise read as standing still.
  let n = rzTrailCount(0, i32(i));
  var travelled = 0.0;
  if (n >= 2) {
    var prev = rzTrail(0, i32(i), 0).xyz;
    for (var s = 1; s < n; s = s + 1) {
      let cur = rzTrail(0, i32(i), s).xyz;
      travelled = travelled + distance(prev, cur);
      prev = cur;
    }
  }
  let span = max(rzTrail(0, i32(i), max(n - 1, 0)).w, 1e-3);
  l.intensity = LIGHT_I * mix(LIGHT_REST, 1.0, clamp((travelled / span) / LIGHT_FULL, 0.0, 1.0));
  return l;
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#particles 7000
#blend additive
#bloom
#duration 11.15
#dissolve
#anchor 頭
#anchor 首
#anchor 上半身2
#anchor 下半身
#anchor 左肩
#anchor 右肩
#anchor 左ひじ
#anchor 右ひじ
#anchor 左手首
#anchor 右手首
#anchor 左ひざ
#anchor 右ひざ
#anchor 左足首
#anchor 右足首

#param float SIZE 0.0055 0.001 0.02 — mote radius, in HIP HEIGHTS — about 0.05 world
#param float FALL 0.72 0 3 — gravity, in hip heights per second squared. THEY
#param float SWIRL 0.75 0 2 — and how tightly it curls

// Divine Teleportation — she comes apart into gold, and it RISES.
//
// Teleportation's machinery, three things changed. The motes are Divine
// Ribbon's, to the constant, so the gold family reads as one light. The params.FALL is
// the original's, unchanged — what leaves her keeps falling and is never called
// back. And the WAITING is long: the departure itself takes
// about as long as the neon version's, but she stands there nine seconds between
// them rather than three. An ascension that happens as often as a teleport is a
// nervous tic; one that is slow to WATCH is a different mistake, so the length
// went into DISSOLVE_WHOLE and nowhere else.
//
// FOURTEEN ANCHORS, not eight. The cap is sixteen, and the neon version spent
// eight of them, so the cloud came off a stick figure — limb-shaped, and it
// showed. Shoulders, neck, hips and ankles fill in the parts a shed body should
// have: the trail is the whole of her, which is what was asked for.
//
// THIS FILE DOES NOT DRAW THE BODY, which is the one thing to know before
// reading it. `@dissolve` asks the engine to take the model apart in the
// MATERIAL — every flake whose object-space threshold has passed is thrown
// away, in the colour pass, the depth prepass and the shadow map alike — and
// what is written here is only what LEAVES her. Covering her with a cloud
// instead was the first attempt, and it looked like what it was.
//
// ONE CLOCK, the engine's. It samples the four durations below — on the scene
// clock, or on a clip's own clock wherever this effect is placed on the
// timeline — and writes the result into every material and into the cast, so a
// mote asks rzSubject(0).dissolve where the body is up to rather than keeping
// time of its own. That is also why an export reproduces a take exactly.
//
// THEY params.FALL, they are not thrown, and they are never called back. Release is
// nearly velocity-free; everything after is gravity against a heavy drag with
// curl noise for the wander. Pulling them home as she reassembled read as
// rewind — the same dust running backwards up the same path — so what has left
// her simply keeps falling.
//
// THEY ARE SMALL, and they light what they pass. A mote is about Footprints'
// ember, well under a hundredth of her height; fineness comes from COUNT, not
// from size. Seven thousand lamps is not something an engine will give you, so
// three declared lights stand in for the cloud at chest, hips and shins,
// sinking as it falls.
//
// WHERE THEY COME FROM is an approximation worth knowing about: a particle pass
// sees the cast and the bones it declared, not the mesh, so a mote spawns on a
// random limb segment between two anchors. The cloud is limb-shaped rather than
// silhouette-shaped, and it shows if you look for it.

// Tunables — edit and ⌘⏎.
//
// ── The four phases, in seconds ──
// The whole of the timing, and what this gets retuned on most, so they are
// DIALS: drag one and she retimes on the next frame. No line below reads them —
// `#dissolve` above is the declaration, and the engine performs them.
//
// PLACED ON THE TIMELINE, a clip opens on the departure: someone dropping one
// on a beat means the teleport lands there, not WHOLE seconds later. WHOLE is
// then the tail the motes finish falling in. Unscheduled, the cycle repeats.
//
// BACK IS QUICKER THAN APART on purpose — coming apart happens TO a body and
// wants watching, arriving is a decision. Matched, the return read as the
// dissolve running backwards.
//
// The floor under WHOLE is the params.FALL, not the dissolve: a mote shed as she goes
// is still going out nearly two seconds later. To teleport more often than
// that, shorten LIFE rather than WHOLE.
#param float DISSOLVE_APART 0.60 0.05 3 — seconds she takes to come apart
#param float DISSOLVE_GONE 1.10 0 5 — seconds there is nothing of her
#param float DISSOLVE_BACK 0.45 0.05 3 — seconds she takes to arrive again
#param float DISSOLVE_WHOLE 9.00 0 30 — seconds she stands whole, between turns

                          // units on a normal model, i.e. Footprints' ember
const SIZE_VARY = 0.65;   // how much that differs mote to mote

                          // params.FALL, as the original's do. Rising was tried and it
                          // is a different effect: what leaves her stops reading
                          // as shed and starts reading as summoned, and the
                          // cloud drifts up out of frame instead of hanging
                          // under her where the shot is
const DRAG = 2.0;         // and what fights it; the two together are the
                          // terminal speed — params.FALL × hip ÷ DRAG. Half again as
                          // quick as the first pass, which drifted
const SWAY = 0.14;        // curl wander, in hip heights per second

const PUFF = 0.06;        // the whisper of movement at release. Near zero on
                          // purpose: a mote that leaves fast has been thrown
const SPIN = 1.9;         // how fast a petal turns as it falls
#param float LIFE 1.8 0.3 6 — seconds before a mote is spent. Deliberately SHORT
                          // of the floor: a mote that lands has stopped being
                          // light and started being litter, and the fall wants
                          // to end in the air. It also has to be gone before
                          // she leaves again, or the second cycle opens over
                          // the leftovers of the first
const LIFE_VARY = 0.40;   // how much that differs mote to mote. NOT a detail:
                          // they are all shed inside one short window, so a
                          // single lifetime ages the whole cloud in lockstep
                          // and puts it out in one frame — a fall that ends
                          // like a switch. Spread, they go out the way they
                          // left, a few at a time
const JITTER = 0.30;      // how far off the bone a mote starts, in hip heights
// NEON, and Hand Ribbon's exactly — electric blue through violet, with a
// lavender heart. Taken rather than invented: the two effects are the same
// light seen twice, one whipping off a wrist and one falling off a whole body,
// and a scene wearing both should not have to explain why they disagree about
// what neon is.
//
// Each mote keeps one hue for its whole fall, and the fall is all three at once
// — a single hue reads as a colour wash, three read as lights. Saturated well
// past what survives AgX alone, which is what the white core and the halo are
// for.
const HALO_COLOR = vec3f(0.52, 0.26, 0.02);  // deep amber, the outer light
const GOLD_COLOR = vec3f(1.00, 0.74, 0.28);  // the body of a mote
const HOLY_COLOR = vec3f(1.00, 0.97, 0.88);  // the pinpoint — warm white
                                         // filament still reads as this colour
                                         // rather than as a hole in it
                          // is the neon: a lamp is a filament you cannot look
                          // at, sitting inside a colour you can
// 6, not Divine Ribbon's 1.6. That number is right for a mote you can SEE —
// its sparks are dense along one hand's path and overlap additively. These are
// seven thousand specks spread over a whole body at a twentieth of a hip
// height, sparse enough that each one carries itself, and at 1.6 they were
// there and invisible. The gold has headroom to spend before AgX turns it
// cream; the neon it replaced needed all of this just to read as blue.
const INTENSITY = 6.0;    // HDR: particles draw before the tone map, so white
                          // here lands as grey without it — see Snow's note
                          // off. A dot this small that ramps from its centre
                          // reaches full brightness at one pixel and reads as
                          // dirt on the lens
// ── The light the fall throws ───────────────────────────────────────────────
//
// The motes already GLOW — they draw inside the scene pass, so the bloom
// pyramid catches them. What they did not do is LIGHT anything: a body coming
// apart into seven thousand lamps left the floor under her, the stage behind
// her and her own remaining half exactly as the sun had them, which is the tell
// Hand Ribbon, the fire and the follow-spots each had before they declared
// lights of their own.
//
// THREE, not seven thousand. A light is a declared cost and the engine's slots
// are few, so what these stand in for is the CLOUD rather than any mote in it:
// one at the chest where the shedding is thickest, one at the hips, one at the
// shins where what has already fallen collects. They sink as she empties, which
// is what keeps the lit patch travelling down with the fall instead of hanging
// where she was.
#lights 3
const LIGHT_I = 3.2;      // brightness at the source
const LIGHT_R = 2.4;      // reach, in hip heights — past her own width, so the
                          // floor and whatever she is standing near take it too
const LIGHT_SINK = 0.45;  // how far the three drop as the cloud falls, in hip
                          // heights

const TAU = 6.2831853;

/** The joints this file knows, in declaration order, plus two the cast already
 *  carries. Fourteen anchors of the sixteen the cap allows; 14 is her middle and
 *  15 the floor under her. */
fn jointAt(i: i32, s: RzSubject) -> vec3f {
  if (i == 14) { return s.center; }
  if (i == 15) { return s.root; }
  let a = rzAnchor(0, i);
  // A rig that spells a bone differently reports .valid false — that limb then
  // collapses onto the torso rather than shedding motes from the world origin.
  return select(s.center, a.pos, a.valid);
}

/**
 * Where on the body this mote belongs, THIS frame.
 *
 * Recomputed rather than stored: a particle has no field to keep it in, and
 * asking the live skeleton means a waiting mote rides the dance — she can walk
 * across the stage between departures and every mote is still on her.
 *
 * SIXTEEN SEGMENTS over fourteen joints. The neon version had ten over eight,
 * and the cloud came off a stick figure: no shoulders, so the arms grew out of
 * the chest, and no ankles, so the shins ran straight to the floor. What a shed
 * body looks like is decided here and nowhere else.
 */
fn bodyPoint(seed: f32, s: RzSubject) -> vec3f {
  let h = rzHash13(seed * 3.117);
  let k = i32(floor(h.x * 16.0));
  var a = 2;
  var b = 1;
  switch k {
    case 0:  { a = 1;  b = 0;  }   // neck → head
    case 1:  { a = 2;  b = 1;  }   // chest → neck
    case 2:  { a = 3;  b = 2;  }   // hips → chest
    case 3:  { a = 2;  b = 4;  }   // chest → left shoulder
    case 4:  { a = 4;  b = 6;  }   // left shoulder → elbow
    case 5:  { a = 6;  b = 8;  }   // left elbow → wrist
    case 6:  { a = 2;  b = 5;  }   // chest → right shoulder
    case 7:  { a = 5;  b = 7;  }   // right shoulder → elbow
    case 8:  { a = 7;  b = 9;  }   // right elbow → wrist
    case 9:  { a = 3;  b = 10; }   // hips → left knee
    case 10: { a = 10; b = 12; }   // left knee → ankle
    case 11: { a = 12; b = 15; }   // left ankle → the floor under her
    case 12: { a = 3;  b = 11; }   // hips → right knee
    case 13: { a = 11; b = 13; }   // right knee → ankle
    case 14: { a = 13; b = 15; }   // right ankle → the floor
    default: { a = 14; b = 3;  }   // her middle → hips
  }
  let hip = max(s.center.y - s.root.y, 0.05);
  let j = (rzHash13(seed * 7.31 + 1.7) - vec3f(0.5)) * hip * JITTER;
  return mix(jointAt(a, s), jointAt(b, s), h.y) + j;
}

/**
 * The dissolve value at which this mote's flake goes.
 *
 * The SAME shape the material's threshold has — noise alone, no sweep — so a
 * mote appears at the moment the surface it came from stops being drawn, and
 * the whole body sheds at once. It cannot be the same NUMBER (that one is per
 * fragment, in object space; this is per particle, in world space), but matching
 * the shape is what keeps the two reading as one event rather than as a cloud
 * that happens to be near a vanishing woman.
 */
/** This mote's own span, in seconds. Derived from the seed rather than stored:
 *  a particle has no field to keep it in, and the seed is stable per slot. */
fn moteLife(seed: f32) -> f32 {
  return params.LIFE * mix(1.0 - LIFE_VARY, 1.0 + LIFE_VARY, rzHash13(seed * 17.9 + 3.1).y);
}

fn releaseAt(seed: f32) -> f32 {
  return rzHash13(seed * 11.3 + 4.2).x;
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let sd = seed + f32(id) * 0.0173;
  let s = rzSubject(0);
  p.seed = sd;
  p.pos = bodyPoint(sd, s);
  p.vel = vec3f(0.0);
  // Waiting. It is ON her, invisible, until the front reaches it — a mote that
  // spawns already falling has come from nowhere.
  p.size = 0.0;
  p.rot = rzHash13(sd * 2.9).z * TAU;
  // Never stretched: these drift, and the velocity-as-orientation path would
  // turn a petal into a streak the moment it picked up any speed at all.
  p.stretch = 1.0;
  // Never retires: the pool IS the body, and a slot that recycled would move a
  // mote to another limb mid-fall.
  p.life = 1.0e9;
  p.age = 0.0;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  let s = rzSubject(0);
  if (!s.valid) {
    q.size = 0.0;
    return q;
  }
  let hip = max(s.center.y - s.root.y, 0.05);
  let home = bodyPoint(q.seed, s);
  let gate = releaseAt(q.seed);
  let h = rzHash13(q.seed * 13.7 + 2.3);

  // A mote ALREADY FALLING is left alone, whatever the body is doing. She can
  // be whole again by now — near the end of a fall she usually is — and that is
  // the point: what has left her goes on falling, and she arrives again without
  // collecting it. The only thing the dissolve decides is whether a WAITING
  // mote may leave.
  if (q.size <= 0.0) {
    if (s.dissolve >= gate) {
      q.pos = home;
      q.vel = vec3f(0.0);
      // Held at zero, so the first frame of the fall is the first frame of the
      // mote's life however long it has been waiting. The pass adds dt after
      // this returns, which is what -dt is for.
      q.age = -dt;
      return q;
    }
    // RELEASED. Barely a push: enough that two motes leaving the same square
    // centimetre do not fall down the same line, and no more.
    q.vel = (rzHash13(q.seed * 5.5 + 0.9) - vec3f(0.5)) * PUFF * hip;
    q.size = params.SIZE * hip * mix(1.0 - SIZE_VARY, 1.0 + SIZE_VARY, h.x);
    q.age = 0.0;
  }

  // Gravity against a heavy drag is a slow terminal fall; the curl is the
  // wander on the way down. Divergence-free, so motes pass each other instead
  // of collecting into the same thread the way a plain sine drift does.
  let w = rzCurlNoise(q.pos * (params.SWIRL / max(hip, 1e-3)) + vec3f(0.0, rzTime() * 0.2, 0.0));
  let fall = vec3f(0.0, -params.FALL * hip, 0.0);
  q.vel = q.vel + (fall + w * SWAY * hip - q.vel * DRAG) * dt;
  q.pos = q.pos + q.vel * dt;
  // Each turns at its own rate, and the slow ones read as the heavy petals.
  q.rot = q.rot + dt * SPIN * mix(0.35, 1.5, h.z);
  if (q.age > moteLife(q.seed)) {
    q.size = 0.0;
    q.pos = home;
    q.vel = vec3f(0.0);
    q.age = -dt;
  }
  return q;
}

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  // The cloud's own gold, never the pinpoint's near-white: a warm-white light
  // washes whatever it lands on, and the colour a viewer reads off the cloud is
  // its body, not its filaments.
  l.color = GOLD_COLOR;
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0, 0.0, 0.0);

  // SUBJECT 0, as the sparks are. Lighting a whole cast would spend nine slots
  // on one effect and leave a composer no room for the stage.
  let s = rzSubject(0);
  if (!s.valid) { return l; }
  // How much of her has left. The same number the motes gate on and the
  // material dissolves by, so the light cannot be bright while she is whole or
  // dark while she is gone.
  let gone = clamp(1.0 - s.dissolve, 0.0, 1.0);
  if (gone <= 0.002) { return l; }

  let hip = max(s.center.y - s.root.y, 0.05);
  // Chest, hips, shins — and all three sink as the cloud does.
  var band = 1.55;
  if (i == 1u) { band = 0.95; }
  if (i == 2u) { band = 0.30; }
  l.pos = vec3f(s.root.x, s.root.y + hip * (band - LIGHT_SINK * gone), s.root.z);
  l.radius = hip * LIGHT_R;
  // Squared, so the light arrives with the fall rather than switching on with
  // the first flake: at a tenth gone she is a body with a few sparks leaving
  // it, and lighting the room for that reads as a lamp somebody threw.
  //
  // The lowest one holds up longest — what has already fallen is still down
  // there glowing after the shedding above it has stopped.
  let hold = select(1.0, 0.75 + 0.25 * gone, i == 2u);
  l.intensity = LIGHT_I * gone * gone * hold;
  return l;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let dd = length(q);

  // DIVINE RIBBON'S SPARK, to the constant. Three shapes: a soft bloom for the
  // bloom pyramid to catch, a hard pinpoint for the heat, and a screen-aligned
  // cross — the flare a light source picks up through a lens, which at this size
  // reads as a twinkle rather than a drawn star. It is what separates HOLY from
  // merely bright, and it is why the petals and stars the neon version drew are
  // gone: a shape that reads as a petal reads as something shed.
  let soft = exp(-(dd * dd) / 0.55);
  let hot = exp(-(dd * dd) / 0.06);
  let bar = exp(-abs(q.x) * 9.0) * exp(-(q.y * q.y) / 0.02);
  let cross = exp(-abs(q.y) * 9.0) * exp(-(q.x * q.x) / 0.02);
  let heat = soft * 0.42 + (bar + cross) * 0.30 + hot;

  // Colour FROM intensity: amber at the edge, gold through the body, near-white
  // only in the very centre. Particles draw in HDR and go through AgX, which
  // pulls anything bright toward white, so a gold that is bright at source
  // arrives as cream — the halo is a deep amber that has somewhere to go.
  var rgb = mix(HALO_COLOR, GOLD_COLOR, smoothstep(0.05, 0.55, heat));
  rgb = mix(rgb, HOLY_COLOR, smoothstep(0.75, 1.25, heat));

  // In, then out ON ITS OWN CLOCK — the mote's age against its own span, which
  // has nothing to do with where the body is in the dissolve. A mote released
  // late still gets a whole life.
  let t = clamp(p.age / max(moteLife(p.seed), 1e-3), 0.0, 1.0);
  let emerge = smoothstep(0.0, 0.12, t);
  let leave = (1.0 - t) * (1.0 - t);
  let twinkle = 0.80 + 0.20 * sin(rzTime() * 7.0 + p.seed);
  let a = clamp(heat * emerge * leave * twinkle, 0.0, 1.0);
  if (a < 0.004) { return vec4f(0.0); }
  return vec4f(rgb * INTENSITY, a);
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#halfres
#param color HOT_COLOR #e0fcff — white-cyan, centre of a fresh print
#param color GLOW_COLOR #24c2ff — cyan, the body of it
#param float RADIUS 1.25 0.3 4 — world units — a mark a foot sits INSIDE, not one it
#param float FADE 2 0.3 6 — seconds a print takes to burn out

// Measured at 1.2ms here against 4.5ms at full, and the marks are soft
// stains with no edge to lose — the one effect this was measured on.
#layer additive
#anchor 左足ＩＫ trail
#anchor 右足ＩＫ trail
#anchor 左足首 trail
#anchor 右足首 trail

// Tunables — edit and ⌘⏎.
// Colour comes from INTENSITY, not from a single tint. A disc filled with one
// saturated colour and then alpha-blended over a dark floor lands somewhere in
// the middle and reads muddy — which is how a red print came out dark orange.
// Light goes WHITE where it is strong and keeps its colour only as it falls off.

const RIM_COLOR = vec3f(0.05, 0.30, 0.95);   // deep blue, at the edge

                         // covers, or the print reads as a dot under the shoe.
                         // Sized against THIS cast: an 18-unit model has a foot
                         // a bit over a unit long, and the 2.4 this started at
                         // drew a pool wider than her stride, so both prints
                         // merged into one puddle she stood in the middle of.
const EDGE = 0.5;        // soft rim as a fraction of the radius
// How much the foot must have dropped for a sample to read as a landing. A
// RELATIVE test, never an absolute height: 足ＩＫ sits at the ANKLE, already a
// hand's width up on a bare foot and higher in heels, so any constant measured
// from the floor is wrong on some rig.
const TOUCH_EPS = 0.03;

const STANCE_HOLD = 0.85;// how bright a print stays while the foot is STILL on
                         // it, regardless of that timer — see the use site
// How much the score brightens the floor. The prints and the falling notes are
// the same music seen twice, and having the ground answer the same beat is what
// makes them one scene instead of two effects that happen to share a frame.
// ADDED, never multiplied: with no score loaded this is zero and the prints are
// exactly what they always were, rather than going dark.
const PULSE = 0.55;
// What rises off a print as it burns out. Motes, not a column: a column is one
// solid shape and it reads as a shape — two rims, a lit tube between them. A
// print going out like a candle is a disc that dims while sparks leave it, and
// sparks are what carry that. They are placed in SCREEN space around the
// projected print, so seven of them cost two projections rather than seven.
// The plume scales with the mark, or a half-size print throws a full-size
// spray and the sparks read as belonging to something else.
const EMBERS = 80;        // motes rising off each print
const EMBER_LIFE = 1.60;  // seconds one lives
const EMBER_RISE = 2.4;   // world units per second it climbs
const EMBER_VARY = 0.70;  // how much that speed differs mote to mote
const EMBER_SPREAD = 0.10;// how much further OUT it drifts as it climbs. Small
                          // on purpose: anything generous here and the sparks
                          // leave from outside the mark they belong to
const EMBER_R = 0.075;    // its radius, the same
const EMBER_CORE = 0.72;  // fraction of that which is SOLID before it falls off
const EMBER_SIZES = 0.6;  // how much THAT differs mote to mote
const EMBER_I = 1.7;      // how bright, against the mark on the floor
const FLOOR_BIAS = 0.35; // world units of slack before the scene is treated as
                         // standing in FRONT of a mark. A drawn ground sits on
                         // the same plane as the marks, so without this it
                         // occludes them by a rounding error and they flicker.
const ELONGATE = 1.0;    // 1 = round; above 1 stretches along the step
const STRENGTH = 2.3;
const FAR_CLAMP = 400.0;

// Marks where the feet met the ground, left behind as the character walks away.
//
// The worked example for rzSubject().root and for reading a trail in WORLD space
// rather than on screen. It was called Footfalls and only lit the foot's current
// position, which followed the foot around like a spotlight — a foot's location,
// not a footprint.
//
// A print is a place and a TIME: born where the foot met the floor, then burning
// down while the foot walks on. rzTrail carries exactly that — every sample is a
// position plus how many seconds ago it was there — so the samples whose height
// is near the floor ARE the contacts, and their age is how long ago each one
// happened. That is a real print that stays behind, out of data the engine keeps
// for a hand ribbon.
//
// It is still an approximation of contact rather than the thing itself: engine
// contact events would give the exact frame a foot landed, its facing and how
// hard, where this infers it from height. Good enough to look right, and the
// comment is here so the next person knows which part is the stand-in.
//
// The height test is also why the band has to be tight: a shoe's toe is a few
// centimetres off the ground, so a generous band marks the toe as readily as the
// floor under it. Position alone cannot tell them apart — they are in the same
// place. Knowing which pixels are the CHARACTER would, and that needs the subject
// mask the engine does not expose yet.
/** Returns the mark on the FLOOR in x, and the light standing on it in y. */
/** Two uncorrelated 0..1 values from a 2D key, WITHOUT a transcendental.
 *
 *  This was `fract(sin(q) * 43758.5453)`, the Shadertoy standard — two sines
 *  per call, two calls per mote, eighty motes per print. Measured at 1.7ms of
 *  the effect's 3.6, which is a lot of frame to spend on randomness nobody can
 *  see the shape of. Dave Hoskins' hash22 is the same job in multiplies and
 *  fracts, and a spark that lands a pixel elsewhere is not a spark anyone can
 *  tell was moved. */
fn fpHash(p: vec2f) -> vec2f {
  var q = fract(vec3f(p.x, p.y, p.x) * vec3f(0.1031, 0.1030, 0.0973));
  q += dot(q, q.yzx + 33.33);
  return fract(vec2f((q.x + q.y) * q.z, (q.x + q.z) * q.y));
}

/** Returns the mark on the FLOOR in x, and what rises off it in y. */
fn markFor(subject: i32, slot: i32, alt: i32, p: vec3f, sp: vec2f, aspect: f32,
           ro: vec3f, ray: vec3f, depth: f32) -> vec2f {
  var n = rzTrailCount(subject, slot);
  var pick = slot;
  if (n < 2) {
    n = rzTrailCount(subject, alt);
    pick = alt;
  }
  if (n < 4) { return vec2f(0.0); }

  // Cull in world space: the whole walk fits in a circle, and most of the floor
  // is nowhere near it.
  var mid = vec2f(0.0);
  for (var k = 0; k < 4; k++) {
    mid += rzTrail(subject, pick, min(k * n / 3, n - 1)).xz;
  }
  mid *= 0.25;
  var reach = 0.0;
  for (var k = 0; k < 4; k++) {
    reach = max(reach, distance(rzTrail(subject, pick, min(k * n / 3, n - 1)).xz, mid));
  }
  // Cull on the RAY, not on the surface point.
  //
  // The floor test alone was right while this only drew on the floor: the pixel
  // was the mark. A pillar stands in the air, so a ray that passes straight
  // through one on its way to a wall fifty metres behind has a surface point
  // nowhere near the walk, and culling on it would erase the very pixels the
  // pillar lives in. Closest approach to a vertical axis through the middle of
  // the walk covers both — it is exactly the surface test when the ray ends on
  // the floor there, and looser everywhere the pillar needs it to be.
  let denom = max(1.0 - ray.y * ray.y, 1e-4);
  let w0 = ro - vec3f(mid.x, 0.0, mid.y);
  let near = ro + ray * max((ray.y * w0.y - dot(ray, w0)) / denom, 0.0);
  if (distance(near.xz, mid) > reach * 1.5 + params.RADIUS) { return vec2f(0.0); }

  var acc = 0.0;
  var col = 0.0;
  // EVERY sample. The ring shifts by one each frame, so a given moment of the
  // path sits on an even index one frame and an odd one the next — striding
  // over it means a landing is detected every OTHER frame, and the print
  // strobes at half the framerate.
  //
  // The three reads per step look redundant — consecutive iterations overlap by
  // two — and carrying them across the loop in registers instead was MEASURED
  // SLOWER, 1.9ms to 3.6ms. They land in cache and cost almost nothing; two
  // vec4f held live across the body cost occupancy, which is the scarcer thing.
  // Left alone deliberately.
  for (var i = 1; i + 1 < n; i = i + 1) {
    let s = rzTrail(subject, pick, i);
    if (s.w > params.FADE) { break; }               // older than a print lasts

    // TOUCHDOWN, not "low". Index 0 is now and rising indices run backwards in
    // time, so `older` is where the foot was before this sample and `newer` is
    // where it went after. A landing is the moment it STOPS descending: it was
    // higher a moment ago, and it did not keep dropping.
    //
    // Marking every low sample instead — which is what this did — puts a print
    // every 20ms through the whole stance, forty overlapping discs that merge
    // into one blob and flicker as each new one is born a few centimetres from
    // the last. A step should leave ONE print, and the path already says
    // exactly when it happened.
    let older = rzTrail(subject, pick, i + 1);
    let newer = rzTrail(subject, pick, i - 1).y;
    if (older.y - s.y < TOUCH_EPS) { continue; }   // was not descending
    if (s.y - newer > TOUCH_EPS) { continue; }     // still descending

    // Elongate along the direction of travel: a footprint is longer than it is
    // wide, and the step direction is the only orientation trail data carries.
    // (The foot's actual facing would need per-contact data — see the note above.)
    let travel = s.xz - older.xz;
    var axis = vec2f(0.0, 1.0);
    if (length(travel) > 1e-4) { axis = normalize(travel); }
    let perp = vec2f(-axis.y, axis.x);
    // STILL STANDING ON IT? A print fades on a timer, which is right for one
    // she has walked away from and wrong for the one under her weight: a
    // planted foot ended up sitting on a mark two seconds into dying, so the
    // moment she was most obviously in contact with the floor was the moment
    // the floor said least about it. On a dark stage — where a shadow has
    // nothing to fall on — that print is the only thing tying her to the
    // ground, so it holds while the foot is on it and fades once she lifts off.
    //
    // The height test is against the TOUCHDOWN's own height, never a constant:
    // 足ＩＫ sits at the ankle, a hand's width up on a bare foot and higher in
    // heels, so anything measured from the floor is wrong on some rig. Compared
    // against where this same foot actually landed, it is right on all of them.
    let cur = rzTrail(subject, pick, 0);
    let onIt = select(0.0, 1.0, distance(cur.xz, s.xz) < params.RADIUS * 0.5 && cur.y - s.y < TOUCH_EPS * 6.0);
    let age = 1.0 - clamp(s.w / params.FADE, 0.0, 1.0);
    let fade = max(age * age, onIt * STANCE_HOLD);

    // The mark on the floor, BURNING DOWN: it dims and it also draws in, the
    // way a candle's pool of light does. Fading alone leaves a disc of the same
    // size going grey, which reads as a light being turned down rather than as
    // something being used up.
    let burn = params.RADIUS * (0.60 + 0.40 * age);
    let rel = p.xz - s.xz;
    let local = vec2f(dot(rel, axis) / ELONGATE, dot(rel, perp));
    let dist = length(local);
    if (dist <= burn) {
      // Compact support: zero at the rim, so the cull leaves no hard edge.
      acc = max(acc, (1.0 - smoothstep(burn * (1.0 - EDGE), burn, dist)) * fade);
    }

    // The light standing on it, INTEGRATED through the slab of air it occupies.
    //
    // Closest approach to the axis is the right primitive for a filled
    // cylinder, where the nearest point is also the brightest and carries the
    // whole shape. It is the wrong one for a WALL: a ray that goes straight
    // through a pillar crosses the wall twice and should come out bright, yet
    // its closest approach lands in the hollow middle and reports nothing at
    // all. Only rays that happened to graze a wall tangentially survived, which
    // is why the light arrived as a few thin streaks sitting nowhere near the
    // prints they belonged to.
    //
    // Six samples between where the ray enters the pillar's height band and
    // where it leaves — or where the scene stops it, so a leg in front cuts the
    // light rather than glowing through it.
    // The embers. Placed in SCREEN space off the projected print: one
    // projection puts the print on the frame, a second puts a world-up metre on
    // it, and from those two every mote's rise, drift and size follow without a
    // projection of its own. Rising along a projected world up rather than the
    // frame's own +y is what keeps them going up when the camera is tilted.
    // From the FLOOR, not from the sample. A trail sample is a bone, and 足ＩＫ
    // sits at the ankle — already a hand's width up on a bare foot and higher in
    // heels — so sparks launched from it start in mid-air above the mark they
    // are supposed to be leaving. The subject's root is where the ground is.
    let gy = rzSubject(subject).root.y;
    let g0 = vec3f(s.x, gy, s.z);
    let pc = rzProject(g0);
    if (pc.z > 0.0) {
      // The GROUND PLANE, as two screen vectors. Screen up alone can only place
      // a mote along a line, and the disc is a disc: to leave from anywhere on
      // it, a mote needs the print's own two ground axes projected as well.
      // Four projections per print, and every one of the hundred-odd motes
      // below is then plain arithmetic.
      let pu = rzProject(g0 + vec3f(0.0, 1.0, 0.0));
      let pa = rzProject(g0 + vec3f(axis.x, 0.0, axis.y));
      let pp = rzProject(g0 + vec3f(-axis.y, 0.0, axis.x));
      let base = vec2f(pc.x * aspect, pc.y);
      let upv = vec2f(pu.x * aspect, pu.y) - base;
      let ax2 = vec2f(pa.x * aspect, pa.y) - base;
      let pz2 = vec2f(pp.x * aspect, pp.y) - base;

      // One circle around the whole plume, before any of it is worked out.
      // At this count the motes are the entire cost of the effect, and all of
      // them are inside a patch of frame a hand's breadth across — so the
      // pixels that are not in that patch must never touch the loop at all.
      let climbMax = EMBER_RISE * (1.0 + EMBER_VARY * 0.5) * EMBER_LIFE;
      let wide = burn * (1.0 + EMBER_SPREAD) * max(length(ax2), length(pz2))
               + EMBER_R * (1.0 + EMBER_SIZES) * length(upv);
      let plumeC = base + upv * (climbMax * 0.5);
      let plumeR = length(upv) * climbMax * 0.5 + wide;
      // Hidden where the scene is NEARER than the print — a leg in front cuts
      // the sparks rather than letting them glow through it.
      let occ = 1.0 - smoothstep(pc.z - 0.4, pc.z + 0.4, depth);
      if (occ < 0.999 && dot(sp - plumeC, sp - plumeC) <= plumeR * plumeR) {
        for (var k = 0; k < EMBERS; k++) {
          let key = floor(s.x * 13.0 + s.z * 7.0);
          let h = fpHash(vec2f(f32(k) + 1.0, key));
          let g = fpHash(vec2f(key + 3.7, f32(k) * 2.3 + 5.1));
          // Staggered births across the print's life, so they leave in a
          // stream rather than all at once.
          let el = s.w - (f32(k) + h.x) / f32(EMBERS) * params.FADE;
          if (el < 0.0 || el > EMBER_LIFE) { continue; }
          let t = el / EMBER_LIFE;
          // WHERE ON THE DISC it left from — uniform over the area, which is
          // what the square root does. Without it they crowd the centre, and
          // the print looks like it is venting through a hole.
          let ang = h.y * 6.2831853;
          // Against the disc's LIT radius, not its geometric one. The mark
          // fades out across EDGE of itself, so the circle anyone can actually
          // see ends well inside `burn` — spawning against `burn` put the whole
          // spray out in the invisible skirt, reading as sparks leaving from a
          // ring around the print rather than from the print. Derived from EDGE
          // so it follows if the rim is ever made softer or harder.
          let lit = burn * (1.0 - EDGE * 0.65);
          let rad = sqrt(g.y) * lit * (1.0 + EMBER_SPREAD * t);
          let out = ax2 * cos(ang) + pz2 * sin(ang);
          // Its own climb rate and its own size. Without these a crowd this
          // large rises as a rank of identical dots — the variation is what
          // turns a hundred motes into a spray rather than a row.
          let climb = EMBER_RISE * (1.0 - EMBER_VARY * 0.5 + EMBER_VARY * g.x);
          let q = base + out * rad + upv * (climb * el);
          let r = EMBER_R * (1.0 - EMBER_SIZES * 0.5 + EMBER_SIZES * fract(g.x * 7.3))
                * (1.0 - t * 0.55) * max(length(upv), 1e-5);
          // Solid to EMBER_CORE, then falling off. Ramping from the very
          // centre puts half the brightness in the outer skirt, so a mote this
          // small only ever reaches full at a single point and the field pass
          // runs at half resolution — between them, the dot upsamples into
          // nothing. A flat core survives that; a peak does not.
          let mote = 1.0 - smoothstep(r * EMBER_CORE, r, length(sp - q));
          col = max(col, mote * (1.0 - t) * (1.0 - t) * fade * EMBER_I * (1.0 - occ));
        }
      }
    }
  }
  return vec2f(acc, col);
}

/** Loudest key sounding right now, 0..1 — the floor's share of the music.
 *  Twelve samples across the score's own range rather than all 128: this is a
 *  brightness nudge, not a readout, and it runs per pixel. Zero when no score
 *  is installed, which is what keeps this effect standing on its own. */
fn midiPulse() -> f32 {
  if (rzNoteCount() == 0) { return 0.0; }
  let lo = rzPitchLow();
  let hi = rzPitchHigh();
  var e = 0.0;
  for (var k = 0; k < 12; k++) {
    e = max(e, rzKeyEnergy(round(mix(lo, hi, f32(k) / 11.0))));
  }
  return e;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let ro = rzCameraPos();
  // Where the scene put a surface. Meaningless past the far clamp, and the
  // floor test below rejects it there — but the pass no longer returns early on
  // it, because a pillar over open sky is drawn on a pixel that has no surface
  // at all.
  let p = rzWorldPos(ray, min(depth, FAR_CLAMP));
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // The pixel itself, in a square space — where the embers are measured.
  let sp = vec2f(uv.x * aspect, uv.y);

  // How far along this ray the scene actually put something, for occlusion.
  let surfT = select(1.0e9, length(p - ro), depth < FAR_CLAMP);

  var acc = 0.0;
  for (var i = 0; i < rzSubjectCount(); i++) {
    let s = rzSubject(i);
    if (!s.valid) { continue; }

    // THE FLOOR IS A PLANE, not whatever the depth buffer happens to hold.
    //
    // This read the drawn surface point and asked whether it was at floor
    // height, which works only where the floor is actually drawn. On a dark
    // stage it often is not — a scene with ground opacity 0 renders nothing
    // there and writes no depth — so every mark failed the test and vanished,
    // leaving only the embers, which are placed in SCREEN space and so hung in
    // the air near the feet instead of under them. It read as the prints being
    // offset; they were absent.
    //
    // Intersecting the ray with the subject's own ground height puts the mark
    // where the floor IS, drawn or not. Depth is still used, but only for what
    // it can answer: whether something stands in front of the mark.
    var pf = p;
    var flat = 0.0;
    if (abs(ray.y) > 1.0e-5) {
      let tf = (s.root.y - ro.y) / ray.y;
      if (tf > 0.0) {
        pf = ro + ray * tf;
        // Hidden behind a leg, but never behind the floor it lies on: the
        // tolerance is what stops a drawn ground from occluding its own marks.
        flat = select(1.0, 0.0, surfT < length(pf - ro) - FLOOR_BIAS);
      }
    }
    let a = markFor(i, 0, 2, pf, sp, aspect, ro, ray, depth);
    let b = markFor(i, 1, 3, pf, sp, aspect, ro, ray, depth);
    acc = max(acc, max(a.x, b.x) * flat);
    acc = max(acc, max(a.y, b.y));
  }
  let heat = acc * STRENGTH * (1.0 + PULSE * midiPulse());
  if (heat <= 0.004) { return vec4f(0.0); }
  // Deep blue at the rim, cyan through the body, white-hot in the middle of a
  // fresh print — and the whole thing cools as it ages, because `acc` carries
  // the age fade into the intensity this reads.
  var rgb = mix(RIM_COLOR, params.GLOW_COLOR, smoothstep(0.04, 0.45, heat));
  rgb = mix(rgb, params.HOT_COLOR, smoothstep(0.55, 1.25, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}

#halfres
#param color COLOR_L #3b82f6 — stage left — blue-500 #3b82f6
#param color COLOR_T #ffffff — overhead — white, the key
#param color COLOR_R #ef4444 — stage right — red-500 #ef4444
#param float DENSITY 1.15 0 3 — how much haze the beam lights up — carries the

// A volumetric march: twenty steps a pixel, per beam, per subject. Haze has
// no edge worth four times the pixels.
#layer additive
#anchor センター trail

// Tunables — edit and ⌘⏎.

const HEIGHT = 42.0;     // world units above the floor the lamps hang
const SPREAD = 25.0;     // how far left and right of centre they sit — this
                         // against HEIGHT is the rake angle of the outer beams
const FRONT = 7.0;       // ...and how far toward the audience
const TOP_R = 2.4;       // beam radius at the lamp
const BOT_R = 4.8;       // ...and where it lands — close to TOP_R keeps the
                         // shaft near parallel instead of a wide fan
const EDGE = 0.09;       // softness of the shaft's rim, as a fraction of BOT_R

                         // shaft's brightness, since coverage IS its intensity
const POOL_R = 3.6;      // bright pool on the floor — inside the beam's landing
const POOL = 0.26;
const FLATNESS = 0.35;   // world units of ground the pool may lie on
const LAG = 0.30;        // seconds the aim trails the dancer
const AIM_STRIDE = 4;    // trail samples skipped when averaging the aim
const STEPS = 20;        // march steps. Twenty against the beam's own cylinder
                         // samples DENSER than thirty-four did against the old
                         // bounding sphere, which was mostly empty air
const FAR_CLAMP = 400.0;
const LIGHT_VIVID = 1.5;  // saturation of the CAST light vs the shaft's own
                          // colour — see vivid(). 1.0 casts exactly what the
                          // beam looks like, which reads white on a lit surface

// Follow-spots that track the cast.
//
// The worked example for rzSubject().root: the beams aim at the FLOOR under each
// character, so they follow a dancer across the stage the way an operator would,
// and land where the feet are rather than around the waist.
//
// The lamps are placed relative to the CAMERA — left, overhead, right, all in
// front of the character — so they read as stage lighting from wherever you
// orbit. Pinned to world axes they end up behind the subject half the time,
// which is backlight, not a follow-spot.
//
// The beam is volumetric, marched through the air, which is why it is occluded
// correctly: the march ends at the scene's own depth, so a shaft passes in front
// of a character and stops behind her.
fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}

/**
 * Where lamp i hangs: side is -1, 0, +1 for left, overhead, right.
 *
 * WORLD-FIXED, fully: rigged to the stage's own axes, no camera term and no
 * sway. Earlier versions placed the rig around the camera's side of the stage
 * so it always read left/overhead/right — but that swings the lamp heads on
 * every orbit and every camera cut, and a fixture that moves is no fixture.
 * Only the AIM follows anything now; orbit behind the stage and you are simply
 * seeing the rig from behind, which is what a rig does.
 */
fn lampPos(side: f32, floorY: f32) -> vec3f {
  return vec3f(side * SPREAD, floorY + HEIGHT, FRONT);
}

/**
 * Where the beams point: the dancer, but lagged.
 *
 * An operator does not snap a follow-spot onto a moving target and neither
 * should this — an aim locked exactly to the hips twitches on every step and
 * makes the beam feel weightless. This is the same damping the follow camera
 * uses, done differently because a shader keeps nothing between frames: an
 * exponentially weighted average over the センター trail IS a low-pass filter,
 * and the trail is a position history we already have.
 *
 * LAG is the time constant. Larger drifts more lazily behind her; zero would be
 * the twitchy lock this exists to avoid.
 */
fn aimPoint(subject: i32, root: vec3f) -> vec3f {
  let n = rzTrailCount(subject, 0);
  if (n < 2) { return root; }
  var sum = vec3f(0.0);
  var wsum = 0.0;
  for (var i = 0; i < n; i = i + AIM_STRIDE) {
    let s = rzTrail(subject, 0, i);
    // Past two time constants the weight is already under a seventh — the rest
    // of the trail cannot move the average enough to be worth walking.
    if (s.w > LAG * 2.0) { break; }
    let we = exp(-s.w / LAG);
    sum += s.xyz * we;
    wsum += we;
  }
  if (wsum < 1e-4) { return root; }
  let p = sum / wsum;
  // Horizontal only: the aim follows where she IS on the stage, and the beam
  // still lands on the floor rather than chasing her hips up and down.
  return vec3f(p.x, root.y, p.z);
}

fn beamFor(side: f32, aim: vec3f, origin: vec3f, ray: vec3f, tMax: f32, time: f32, jitter: f32) -> f32 {
  let apex = lampPos(side, aim.y);
  let toFloor = aim - apex;
  let len = length(toFloor);
  if (len < 1e-3) { return 0.0; }
  let dir = toFloor / len;

  // March the BEAM's true envelope: its cylinder, cut by the lamp and floor
  // planes. Stepping uniformly from the lens to the scene gives every pixel a
  // different interval; and the earlier fix — a bounding SPHERE around the whole
  // beam — was still five times fatter than the beam it contained (radius
  // len/2 + BOT_R against a shaft at most BOT_R wide), so most of a fixed step
  // budget landed in empty air and failed the d < r test below. Against the
  // tight envelope, twenty steps hold the sampling density thirty-four needed
  // inside the sphere, and the jitter hides the rest.
  let w0 = origin - apex;
  let rd = dot(ray, dir);
  let wd = dot(w0, dir);
  var t0 = 0.0;
  var t1 = tMax;
  if (abs(rd) > 1e-4) {
    let ta = (0.0 - wd) / rd;
    let tb = (len - wd) / rd;
    t0 = max(t0, min(ta, tb));
    t1 = min(t1, max(ta, tb));
  } else if (wd < 0.0 || wd > len) {
    return 0.0;
  }
  let aq = 1.0 - rd * rd;
  let bq = dot(w0, ray) - wd * rd;
  let cq = dot(w0, w0) - wd * wd - BOT_R * BOT_R;
  if (aq > 1e-5) {
    let disc = bq * bq - aq * cq;
    if (disc < 0.0) { return 0.0; }
    let sq = sqrt(disc);
    t0 = max(t0, (-bq - sq) / aq);
    t1 = min(t1, (-bq + sq) / aq);
  } else if (cq > 0.0) {
    return 0.0;
  }
  if (t1 <= t0) { return 0.0; }

  var acc = 0.0;
  let dt = (t1 - t0) / f32(STEPS);
  for (var s = 0; s < STEPS; s++) {
    // JITTERED start. Every pixel sampling at the same offsets makes each step
    // deposit a visible disc, and a marched cone comes out as a stack of
    // spheres — worse the harder the beam's edge is, which is exactly when you
    // want it. Offsetting each pixel by a hash turns that banding into fine
    // noise, which is what haze looks like anyway.
    let p = origin + ray * (t0 + dt * (f32(s) + jitter));
    let along = clamp(dot(p - apex, dir) / len, 0.0, 1.0);
    let r = mix(TOP_R, BOT_R, along);
    let d = distance(p, apex + dir * (along * len));
    if (d < r) {
      // A searchlight has a defined SHAFT: flat across its width, falling off
      // only at the rim. The rim is a WORLD width, not a fraction of the local
      // radius — as a fraction it widens with the cone, leaving the beam sharp
      // at the lamp and smeared where it lands, which is the end you look at.
      let soft = max(EDGE * BOT_R, 1e-3);
      acc += smoothstep(r, r - soft, d) * mix(0.55, 1.0, along) * dt;
    }
  }
  return acc;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let origin = rzCameraPos();
  let dir = normalize(ray);
  // A beam is light in the air BETWEEN the lens and whatever was drawn, so
  // stopping at depth is what occludes it.
  let tMax = min(depth, FAR_CLAMP);
  if (tMax <= 0.01) { return vec4f(0.0); }
  let jitter = hash21(uv * rzResolution());

  // Composited OVER one another, not summed.
  //
  // Three beams converge on the dancer by design, and summing their coverage
  // put the total past 1 exactly where they meet — so the most interesting part
  // of the shot clipped to flat white and lost both the shafts and her legs.
  // Over-compositing is how overlapping lights actually behave: each adds what
  // is left rather than its whole self, so the total approaches 1 and never
  // slams into it.
  var rgbPm = vec3f(0.0);   // premultiplied
  var alpha = 0.0;
  for (var c = 0; c < rzSubjectCount(); c++) {
    let subj = rzSubject(c);
    if (!subj.valid) { continue; }
    let aim = aimPoint(c, subj.root);

    for (var i = 0; i < 3; i++) {
      let side = f32(i) - 1.0;   // -1 left, 0 overhead, +1 right
      var col = params.COLOR_T;
      if (i == 0) { col = params.COLOR_L; }
      if (i == 2) { col = params.COLOR_R; }
      let beam = clamp(beamFor(side, aim, origin, dir, tMax, time, jitter) * params.DENSITY * 0.06, 0.0, 1.0);
      if (beam > 0.001) {
        rgbPm += col * beam * (1.0 - alpha);
        alpha += beam * (1.0 - alpha);
      }
      // Saturated is saturated: with alpha this close to 1, a third beam's whole
      // march could not move the pixel a code value.
      if (alpha > 0.985) { break; }
    }

    // The pool where the light lands. Read off the pixel's own world position,
    // so it lies on whatever the floor actually is and bends over it.
    if (depth < FAR_CLAMP) {
      let p = rzWorldPos(dir, depth);
      if (abs(p.y - subj.root.y) < FLATNESS) {
        let d = distance(p.xz, aim.xz);
        if (d < POOL_R) {
          let x = 1.0 - d / POOL_R;
          let pool = clamp(x * x * POOL, 0.0, 1.0);
          rgbPm += params.COLOR_T * pool * (1.0 - alpha);
          alpha += pool * (1.0 - alpha);
        }
      }
    }
  }

  let a = clamp(alpha, 0.0, 1.0);
  if (a <= 0.002) { return vec4f(0.0); }
  // Un-premultiply for the straight alpha the mount wants.
  //
  // The tint is HELD now. This used to lerp toward white from alpha 0.8, which
  // whitened the core of every shaft — the exact place a coloured beam should
  // read most strongly, and most of why three lamps looked like one. Neon is
  // saturated where it is brightest; only the last sliver before full coverage
  // blooms out, and at alpha 1 that is a couple of per cent rather than a fifth.
  let lit = rgbPm / max(alpha, 1e-4);
  return vec4f(mix(lit, vec3f(1.0), smoothstep(0.96, 1.7, alpha)), a);
}

/** Saturation about the colour's own luminance. k = 1 is unchanged; above it
 *  pushes away from grey while holding hue and rough brightness. Clamped at
 *  zero because k > 1 drives the weakest channel negative, and a negative
 *  channel in an ADDITIVE light darkens what it lands on. */
fn vivid(c: vec3f, k: f32) -> vec3f {
  let luma = dot(c, vec3f(0.2126, 0.7152, 0.0722));
  return max(mix(vec3f(luma), c, k), vec3f(0.0));
}

// ── The light the beams actually cast ────────────────────────────────────────
//
// Until this mount existed a beam could only PAINT light: the shaft was drawn
// over the finished frame, so the pool on the floor was a bright patch that lit
// nothing, and the dancer standing in it was shaded by the sun alone. Three
// obvious follow-spots converging on someone who does not react to them is the
// tell that the whole effect is a decal.
//
// One light per beam, placed where that beam LANDS rather than where the
// fixture hangs. The lamp is 42 units up and its pool is on the floor; putting
// the light at the head would wash the whole stage evenly from above, which is
// the one thing a follow-spot does not do. At the landing point the falloff
// does the work the beam's cone is already doing visually.
//
// The aim is the same lagged aim the shafts use — literally the same function,
// so the light cannot drift away from the shaft supposed to be delivering it.
#lights 3
fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  // The SAME palette as the shafts, pushed. Haze reads pale because it is
  // scattered light seen edge-on; the same lamp landing on a dress has to read
  // by its hue or three spots converging look like one white one — which is
  // what they did. Deriving it rather than keeping a second set of constants
  // means editing a beam's colour moves the light it casts with it.
  //
  // AgX is the other half of why this is needed: it desaturates as it
  // compresses, so a colour that survives the tone map has to start further out
  // than it would in a linear render.
  l.color = vivid(select(select(params.COLOR_L, params.COLOR_T, i == 1u), params.COLOR_R, i == 2u), LIGHT_VIVID);
  // Sides match beamFor's: -1 stage left, 0 overhead, +1 stage right.
  let side = f32(i32(i) - 1);

  // The first subject is who the rig follows, exactly as the beams do.
  let subj = rzSubject(0);
  if (!subj.valid) {
    // Nobody on stage. The fixtures still hang, but there is no pool to light,
    // so this slot goes dark rather than parking a lamp at the world origin.
    l.pos = lampPos(side, 0.0);
    l.intensity = 0.0;
    l.radius = 1.0;
    return l;
  }
  let aim = aimPoint(0, subj.root);
  // Lifted off the floor by the pool's own radius. A light exactly ON the plane
  // it lights grazes it — the floor's normal is perpendicular to the direction
  // to the light, N·L is zero, and the pool would be invisible from directly
  // above. Standing it off makes the brightest point the middle of the pool,
  // which is where the beam is brightest too.
  l.pos = vec3f(aim.x + side * POOL_R * 0.5, aim.y + POOL_R, aim.z);
  // The overhead lamp is the key of the three and the rakes are fill — the same
  // relationship the drawn beams have, where the white one reads as strongest.
  l.intensity = select(1.6, 2.4, i == 1u);
  // Reaches a little past the pool it paints, so someone standing in it is lit
  // to about the waist rather than only at the ankles.
  l.radius = POOL_R * 4.5;
  return l;
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#particles 8000

#param float FALL 2.2 0 8 — metres per second, before size weighting
#param float DRIFT 0.55 0 2 — sideways wander
#param float SWIRL 0.18 0 1 — how tightly the wander curls
#param float SIZE_MAX 0.17 0.02 0.5 — a few big ones near the lens, most of them small

// Snow — the first effect drawn as geometry rather than marched per pixel.
//
// Every flake is one instanced quad, so the cost is the flakes and not the
// screen: eight thousand of these cost less than one fullscreen effect that
// touches every pixel to decide most of them are empty. The old path could not
// have afforded a tenth as many, and the count is the whole difference between
// "it is snowing" and a few dots drifting past.
//
// The volume is FIXED TO THE STAGE, not to the camera.
//
// Following the eye seemed right — weather is everywhere, so keep it where you
// are looking — but it makes the weather a property of the camera rather than of
// the scene, and a camera VMD is the case that proves it wrong: a VMD dollies and
// cuts, and the whole field would lurch after it on every cut. A stage that snows
// is a stage that snows regardless of where you stand to watch it.
//
// The cost is honest: fly the camera outside CENTER ± AREA and the weather is
// behind you. MMD scenes are staged around the origin, so that is a corner rather
// than the common case, and AREA is the dial if a scene needs a bigger stage.

// Tunables.

const CENTER = vec3f(0.0, 0.0, 0.0);   // the stage the weather falls on
const AREA = 34.0;       // half-width of the volume
const TOP = 46.0;        // ceiling they fall from — well above the frame
const SIZE_MIN = 0.035;

const TWINKLE = 0.35;     // how much a flake catches the light as it turns
const SOFT = 0.5;        // softness of the flake's halo, 0..1
const INTENSITY = 3.0;   // HDR brightness — see the note below
const ARMS = 0.55;       // how far the arms reach, 0..1 of the quad
const CORE = 0.16;       // the hub at the centre

// A NOTE ON BRIGHTNESS, because it is the one thing that surprises everyone.
//
// Particles draw INSIDE the scene pass, in HDR, before tone mapping — unlike a
// background or foreground, which composites over the finished frame. So white
// here is not the white you get out: vec3f(1.0) goes through AgX and lands as
// grey. Snow has to be brighter than the paper it is drawn on, which is what
// INTENSITY is for. The upside of the same fact is that the scene's grade and
// exposure apply to the snow, so it belongs to the shot instead of sitting on
// top of it.

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let r = rzHash13(seed + f32(id) * 0.0173);
  let r2 = rzHash13(seed * 1.77 + f32(id) * 0.0411);
  p.pos = vec3f(CENTER.x + (r.x - 0.5) * AREA * 2.0, r.y * TOP, CENTER.z + (r.z - 0.5) * AREA * 2.0);
  p.size = mix(SIZE_MIN, params.SIZE_MAX, r2.x);
  // Bigger flakes fall faster, which is what stops the field looking like one
  // sheet sliding down the screen.
  p.vel = vec3f(0.0, -params.FALL * mix(0.6, 1.4, r2.x), 0.0);
  // Never expires: flakes WRAP at the floor (see step) rather than recycling
  // through the pool, so none of them appears out of nothing in mid-air.
  p.life = 1.0e9;
  p.rot = r2.z * 6.2831853;
  p.seed = seed + f32(id) * 0.0173;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Curl noise is divergence-free, so flakes wander past each other instead of
  // piling into the same line the way a plain sine drift does.
  let w = rzCurlNoise(q.pos * params.SWIRL + vec3f(0.0, rzTime() * 0.15, 0.0));
  q.pos = q.pos + (q.vel + w * params.DRIFT) * dt;
  q.rot = q.rot + dt * 0.6;
  // TOROIDAL in x/z as well as y.
  //
  // Wrapping only at the floor meant the volume moved with the camera but its
  // contents did not: orbiting left the old field draining where it was while a
  // new one filled in slowly, a fall-time behind. Folding x and z about the
  // centre too means a flake that leaves one side re-enters on the other in the
  // SAME frame, so the field is always centred and never has to refill. The
  // seam sits AREA away, off to the side and far from what you are looking at.
  let span = AREA * 2.0;
  let rx = q.pos.x - CENTER.x;
  let rz = q.pos.z - CENTER.z;
  q.pos.x = CENTER.x + rx - span * floor(rx / span + 0.5);
  q.pos.z = CENTER.z + rz - span * floor(rz / span + 0.5);
  // And over the top when it reaches the floor, in a freshly chosen column so the
  // same flake never falls down the same line twice.
  if (q.pos.y < 0.0) {
    let h = rzHash13(q.seed + rzTime() * 0.29);
    q.pos = vec3f(CENTER.x + (h.x - 0.5) * span, TOP, CENTER.z + (h.z - 0.5) * span);
  }
  return q;
}

fn sdSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

/**
 * A six-armed flake, folded rather than repeated.
 *
 * The obvious way to build one is to loop six times and rotate — which is what
 * the hand-written fullscreen version had to do. Folding the angle into a single
 * 60-degree wedge gets the same six-fold symmetry from ONE arm, so this is three
 * segment tests instead of thirty. That trade is worth spelling out: a particle
 * shader runs on the handful of pixels its own quad covers, not on the screen,
 * so detail here is cheap in a way it never was in a fullscreen march.
 */
fn flake(q: vec2f) -> f32 {
  let k = 1.0471975;                     // 60 degrees
  let a = atan2(q.y, q.x);
  let folded = abs(a - k * floor(a / k + 0.5));
  let r = length(q);
  let p = vec2f(cos(folded), sin(folded)) * r;
  var d = sdSegment(p, vec2f(0.0), vec2f(ARMS, 0.0)) - 0.035;
  d = min(d, sdSegment(p, vec2f(ARMS * 0.45, 0.0), vec2f(ARMS * 0.72, ARMS * 0.30)) - 0.022);
  d = min(d, sdSegment(p, vec2f(ARMS * 0.75, 0.0), vec2f(ARMS * 0.95, ARMS * 0.22)) - 0.018);
  return min(d, r - CORE);
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let d = flake(q);
  // The crystal itself, plus a soft bloom of light around it — near flakes read
  // as a shape, distant ones collapse to the halo, which is what snow does.
  let solid = smoothstep(0.04, -0.02, d);
  let halo = rzFalloff(length(q), 1.0) * SOFT * 0.5;
  // No lifetime fade — a wrapped flake never dies, and fading a share of them at
  // any moment is what makes a field look like it is flickering.
  let a = clamp(solid + halo, 0.0, 1.0);
  // Each flake catches the light at its own rate as it tumbles. Snow that all
  // brightens together reads as a flicker; snow that does not sparkle at all
  // reads as paper.
  let twinkle = 1.0 + TWINKLE * sin(rzTime() * (1.3 + p.seed * 2.7) + p.seed * 39.1);
  return vec4f(vec3f(INTENSITY * twinkle), a);
}

#layer additive
#param color COLOR1 #4d8cff — the wave's tint at screen left
#param color COLOR2 #ff5980 — ...and at screen right
#param float BOUNCE 0.5 0 2 — how far the music bends the wave. THE size dial:
#param float BRIGHT 1 0 3 — how much light the curve adds, overall

// this effect is LIGHT, not matter. The layer ADDS to what
// the scene already drew, so a backdrop image, a flat colour, a skybox or
// another effect behind it all stay visible and nothing here covers them.
//
// Waveform — mafik's Shadertoy visualiser, ported onto the rzAudio* interface.
// Original: https://www.shadertoy.com/view/XsjGz3 — the structure below follows
// it line for line; the adaptations are named where they happen.
//
// The idea that makes it beautiful: twenty spectrum bands each bend a
// TRAVELLING COSINE into the same coordinate, faster per band, amplitude from
// the band's PEAKINESS (its value against its neighbours' — a second
// difference, so flat noise moves nothing and a beat kicks). The glow is the
// classic 1/|y| falloff around whatever curve all that bending composed.
// Shadertoy feeds a live analyser; here rzAudioBand reads the precomputed
// analysis, which is why an export shows the same picture.
//
// WHAT THE PORT LEAVES BEHIND. A Shadertoy owns its whole canvas, so mafik
// opens by painting one: a blue-to-red gradient, the bass eighth of the
// spectrum as vertical columns, grain standing in for his noise texture, the
// lot pulled down by 0.7. A scene here already HAS a backdrop, and painting
// over it is the one thing a visualiser must not do — the gradient survives
// as the wave's own tint across the frame, which is where its colour was
// doing the work anyway, and the columns and grain go, because a full-frame
// wash of added light is opacity by another name.

// Tunables — edit and ⌘⏎.

const BANDS_N = 20;      // cosines composed — the original's n

                         // 1.0 is mafik's full swing, which reaches the frame's
                         // edges on big drops; 0.5 keeps the dance in the middle
                         // of the frame. Scales GEOMETRY only — brightness and
                         // the crisp 1/|y| lines are untouched, which is what
                         // the earlier limiter experiments got wrong.
const GLOW = 200.0;      // the 1/|y| glow's tightness — original's constant
const WAVE_TINT = vec3f(1.9, 1.0, 1.5); // pink-white, r > b > g as mafik had it

const CALM = 0.10;       // amplitude left when paused, or with no track at all

/** The original's audio texture row, as our bands: x 0..1 across the spectrum.
 *  Read raw — the AnalyserNode smoothing already lives in the analysis. */
fn wvSpectrum(x: f32) -> f32 {
  return rzAudioBand(i32(clamp(x, 0.0, 1.0) * f32(rzAudioBandCount() - 1)));
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  // Paused or trackless goes CALM: the maths below would happily oscillate
  // over a frozen spectrum forever — and with no track at all, the 0.6 seed in
  // the walk fabricates waves out of silence.
  let drive = mix(CALM, 1.0, rzAudioPlaying());

  // The wave. uv into [-1,1], the original's offsets verbatim.
  var p = vec2f(-1.0 + 2.0 * uv.x, -1.0 + 2.0 * uv.y);
  p.y += 0.1;
  p.x *= 2.0;

  var prev = 0.0;
  var curr = 0.6;
  var next = wvSpectrum(0.0);
  var wave = 0.0;
  for (var i = 0; i < BANDS_N; i++) {
    prev = curr;
    curr = next;
    next = wvSpectrum(f32(i + 1) / f32(BANDS_N));
    // Mafik's amplitude, undamped — including the i = 0 line, whose cos(0) is
    // constant: a straight bar displaced by the first band's peakiness squared,
    // the thick centre line that BUMPS with the music. The tempering happens in
    // the analysis instead: bands arrive smoothed with the AnalyserNode's own
    // 0.8, exactly the sluggishness Shadertoy fed him.
    let amp = max(0.0, curr * 2.0 - prev - next) * drive;
    p.y += cos((p.x * 2.0 * f32(i) / f32(BANDS_N) * 10.0 + time * f32(i)) % 6.2831853) * amp * amp * params.BOUNCE;
    p.x += 0.1;
    // Scalar now: the tint is applied once at the end, so the gradient can
    // colour the curve without being mixed into the falloff twenty times.
    wave += abs(1.0 / (GLOW * p.y)) * (5.0 / f32(BANDS_N));
  }

  // Straight alpha over a layer that adds: the COLOUR is what the light is,
  // the ALPHA is how much of it lands, and where the curve is far away that
  // alpha is zero — which is the whole point, since zero is what lets the
  // backdrop through.
  //
  // The field layer composites after tone mapping, so anything past 1 would
  // simply clip. The overshoot is spent on the tint going white instead: an
  // overexposed core reads as heat rather than as a flat clamped stripe.
  let lit = wave * params.BRIGHT;
  let tint = clamp(WAVE_TINT * mix(params.COLOR1, params.COLOR2, uv.x), vec3f(0.0), vec3f(1.0));
  let color = mix(tint, vec3f(1.0), clamp(lit - 1.0, 0.0, 1.0));
  return vec4f(color, clamp(lit, 0.0, 1.0));
}

#layer additive
#anchor 頭
#anchor 上半身2
#anchor 左ひじ
#anchor 右ひじ
#anchor 左手首
#anchor 右手首
#anchor 左ひざ
#anchor 右ひざ

#param color CORE_COLOR #ffc7ad — the filament — hot, still red
#param color BODY_COLOR #ff1c0a — the body of the arc
#param float STRIKE_HZ 5 0.5 15 — new channels per second
#param float SIZZLE 9 0 20 — flickers per life

// Vyke's Dragonbolt — the red fire-lightning of Elden Ring, clinging to a body.
//
// These are ARCS, not lightning. Lightning is a path from somewhere to
// somewhere else and it looks it: straight, spanning, purposeful. An electric
// arc has nowhere to go, so it curves — it crawls around what it is clinging
// to. That is the whole difference between this and a bolt effect, and it is
// built into the geometry rather than tuned in afterwards:
//
//   CRACKLES orbit a joint, on a tilted ring, through less than a third of a
//   turn. CONNECTORS are short bowed pieces of the way between two joints,
//   never the whole span — electricity crawling over a body, not a cable strung
//   between its corners.
//
// Both ORBIT IN DEPTH as well as across the screen, which is what makes them
// look wrapped rather than painted on. Every point of every path carries its
// own distance from the camera, and the half of a ring that swings behind a
// shoulder is hidden by that shoulder. rzProject hands back z in metres on the
// same axis as the depth the mount is given, so the test costs one comparison
// per path — no marching, no 3D distance field.
//
// The depth is derived rather than projected point by point: the ring's screen
// radius is converted to metres once per arc (one extra projection, after the
// bound rejects), and the swing is that radius through the tilt. A tilted ring
// projects to an ellipse and this draws a circle, which is a lie no one can see
// in a jagged filament, and it keeps the whole path in 2D where it is cheap.
//
// Both FORK, off the tangent wherever the branch tears. Eight anchors (head,
// chest, elbows, wrists, knees) plus the hips and the floor point, free from
// rzSubject, cover the whole silhouette. Channels RESTRIKE on a timer rather
// than animating — a path lives for a blink, then a new seed tears a new one
// somewhere else. That flicker is what reads as electricity.
//
// The halo is drawn in two tiers rather than one. A foreground mount composites
// after tone mapping and is clamped to display range, so it never reaches the
// bloom pyramid: every bit of the glow around these arcs has to be in the
// falloff here, and a single radius reads as a flat disc.
//
// Tunables — edit and ⌘⏎.

const HAZE_COLOR = vec3f(0.52, 0.03, 0.01);  // deep ember, the outer light

const ATTACK = 0.05;      // of a life spent snapping on
const HOLD = 0.55;        // and how much of it is spent at full before dying

const BOLTS = 20;         // channels alive at once — most of them crackles
const CONNECTORS = 6;     // how many of those crawl between two joints
const SEGS = 7;           // jags per arc — enough that the curve stays a curve
const FORK_SEGS = 3;      // and per branch
const CRACKLE_R = 0.024;  // how wide a crackle orbits its joint
const SWEEP_MIN = 0.7;    // and through how much of a turn, in radians
const SWEEP_MAX = 1.9;
const TILT_MIN = 0.45;    // how far the ring leans into the screen: 0 is flat
const TILT_MAX = 1.0;     // on to the frame, 1 is swinging fully through it
const SPAN_MIN = 0.20;    // a connector's length, as a fraction of the joint gap
const SPAN_MAX = 0.38;
const HUG = 0.85;         // how far along its bone a connector may slide
const BOW = 0.5;          // how far a connector bows, relative to JAG
const JAG = 0.016;        // sideways wander — small, or it eats the curve
const CORE_W = 0.0018;    // filament half-width — a hairline, and it stays one
const GLOW_W = 0.0090;    // the tight halo hugging it
const HAZE_W = 0.0500;    // and the wide, faint aura it sits in
const CORE_I = 1.9;
const GLOW_I = 0.90;
const HAZE_I = 0.30;
const FLICKER = 0.40;     // depth of the per-channel brightness flicker
const WOBBLE = 0.35;      // how much the filament writhes while it is alive
const WOBBLE_HZ = 7.0;    // and how fast
const Z_BIAS = 0.02;      // metres of slack, so an arc lying on the skin shows
const Z_FADE = 0.03;      // and how sharply it goes as it passes behind

const TAU = 6.2831853;

fn arcHash(p: vec2f) -> f32 {
  var q = fract(vec3f(p.x, p.y, p.x) * 0.1031);
  q = q + dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

/**
 * The aura around the filament, falling off cubically.
 *
 * The shape is the whole difference between neon and a blob. A linear ramp
 * across the radius fills its disc almost evenly, so a wide one reads as a lit
 * tube; cubed, the same radius stays concentrated on the line and trails away
 * to nothing at its edge — which is what a glass tube full of gas actually does
 * to the air around it. That is what lets the aura be WIDE and faint at once,
 * and a wide faint aura next to a hairline core is the neon look.
 *
 * Bounded, not a 1/r tail: the reject below is derived from HAZE_W, and a glow
 * that never quite reaches zero has no radius to derive one from.
 */
fn arcHalo(dist: f32) -> f32 {
  let t = 1.0 - smoothstep(0.0, HAZE_W, dist);
  return t * t * t;
}

fn arcSeg(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

/** Ten points on the body: eight declared anchors, then the hips and the floor.
 *  World space — the caller projects, because it also wants the world position
 *  to work out how big a metre is on screen there. w is 0 on a rig without it. */
fn arcWorld(subject: i32, idx: i32) -> vec4f {
  if (idx >= 8) {
    let s = rzSubject(subject);
    if (!s.valid) { return vec4f(0.0); }
    return vec4f(select(s.center, s.root, idx == 9), 1.0);
  }
  let a = rzAnchor(subject, idx);
  return vec4f(a.pos, select(0.0, 1.0, a.valid));
}

const BONE_COUNT = 10;

/**
 * The body as SEGMENTS, not points — which pairs of the ten are joined by limb.
 *
 * Anchors are capped at eight and all eight are spent, but the coverage problem
 * was never the count: ten discrete points leave the forearms, the thighs and
 * the torso bare no matter how many channels orbit the joints, because there is
 * nothing between them to orbit. Naming the segments instead lets a channel sit
 * ANYWHERE along a limb, so eight anchors cover a whole body continuously and
 * more anchors would buy nothing.
 *
 * It also fixes what the connectors were doing. Picking two joints at random
 * drew head-to-knee lines through open air; along a bone, every one of them
 * lies on the body by construction, and the end-hugging that used to paper over
 * that is now just where along the limb it sits.
 *
 * The two lower legs run knee to the FLOOR POINT rather than to an ankle: at
 * eight slots the wrists earn their place more than the ankles do, and knee to
 * floor tracks a shin closely enough while she is standing on it. A lifted leg
 * is the case it approximates worst.
 */
fn arcBone(i: i32) -> vec2<i32> {
  switch i {
    case 0: { return vec2<i32>(1, 0); }   // neck
    case 1: { return vec2<i32>(8, 1); }   // torso
    case 2: { return vec2<i32>(1, 2); }   // upper arm, left
    case 3: { return vec2<i32>(1, 3); }   //            right
    case 4: { return vec2<i32>(2, 4); }   // forearm, left
    case 5: { return vec2<i32>(3, 5); }   //          right
    case 6: { return vec2<i32>(8, 6); }   // thigh, left
    case 7: { return vec2<i32>(8, 7); }   //        right
    case 8: { return vec2<i32>(6, 9); }   // lower leg, left
    default: { return vec2<i32>(7, 9); }  //            right
  }
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // Measure in a square space, or every arc is stretched into an ellipse.
  let p = vec2f(uv.x * aspect, uv.y);

  var core = 0.0;
  var glow = 0.0;
  var haze = 0.0;

  for (var c = 0; c < rzSubjectCount(); c++) {
    let s = rzSubject(c);
    if (!s.valid) { continue; }

    // ── Reject the whole character before touching a single channel ──
    //
    // The two-tier cull below is tight, but every channel had to be SET UP
    // before it could be reached: a hash for its phase, four more for its
    // shape, ten trig calls to sketch it and a projection or two to place it.
    // Twenty-odd of those ran on every pixel of the frame, including the empty
    // corners — which is most of any frame, and was most of the cost.
    //
    // One circle around the character answers all of them at once. Two
    // projections, and a pixel that is nowhere near her is done.
    let bc = rzProject(s.bounds.xyz);
    if (bc.z <= 0.0) { continue; }
    let be = rzProject(s.bounds.xyz + rzCameraUp() * s.bounds.w);
    let br = max(abs(be.y - bc.y), 1e-4);
    let bc2 = vec2f(bc.x * aspect, bc.y);
    // Her silhouette, plus how far past it a channel can stray: a branch may
    // leave a bone by half its length, and an orbit and its aura add their own.
    let bound = br * 1.5 + CRACKLE_R + JAG + HAZE_W;
    if (dot(p - bc2, p - bc2) > bound * bound) { continue; }

    // ── The body, projected once for every channel that will ask ──
    //
    // Each channel used to project the bone it sits on for itself, which is one
    // or two projections apiece and the same joints over and over. Ten points
    // cover every bone, so ten projections cover every channel.
    var pts: array<vec2f, 10>;
    var zs: array<f32, 10>;
    var ok: array<bool, 10>;
    for (var i = 0; i < 10; i++) {
      let wp = arcWorld(c, i);
      let pr = rzProject(wp.xyz);
      pts[i] = vec2f(pr.x * aspect, pr.y);
      zs[i] = pr.z;
      ok[i] = wp.w > 0.5 && pr.z > 0.0;
    }

    // ── How near is this pixel to each LIMB ──
    //
    // The reject above answers "is this pixel anywhere near her" and no more,
    // and it cannot do better: bounds.w is the generous cull sphere, so the
    // circle it gives covers most of the frame whenever she is framed at all.
    // Inside it every channel was still being set up — a hash for its phase,
    // four for its shape, ten trig calls to sketch it — and twenty of those on
    // most of the frame is the whole cost of this effect.
    //
    // Ten segment distances answer it properly. A channel can only reach so far
    // from the bone it lives on, so a pixel beside one arm can throw out every
    // channel on the other arm and both legs for the price of ONE array lookup
    // in the loop below, before any of that setup runs. Ten cheap tests replace
    // most of twenty expensive ones.
    var bd: array<f32, 10>;
    var near = false;
    for (var i = 0; i < BONE_COUNT; i++) {
      let bn = arcBone(i);
      if (!ok[bn.x] || !ok[bn.y]) {
        bd[i] = 1e9;
        continue;
      }
      // Its own longest branch scales with its own length, so a torso claims
      // more room than a forearm and neither is given the other's slack.
      let len = length(pts[bn.y] - pts[bn.x]);
      let reach = CRACKLE_R * 1.25 + JAG + HAZE_W + 0.55 * SPAN_MAX * len;
      bd[i] = arcSeg(p, pts[bn.x], pts[bn.y]) - reach;
      near = near || bd[i] <= 0.0;
    }
    if (!near) { continue; }

    for (var b = 0; b < BOLTS; b++) {
      // Each channel restrikes on its own phase, so they never blink together.
      let phase = time * params.STRIKE_HZ + f32(b) * 0.317;
      let strike = floor(phase);
      let life = fract(phase);
      let seed = vec2f(strike * 1.7 + f32(b) * 31.7, f32(c) * 11.3 + f32(b) * 5.1);

      // WHICH LIMB this channel lives on — asked FIRST, because the answer is
      // also the cheapest possible rejection. Both shapes below sit on it: a
      // crackle rings some point along it, a connector runs a slice of it.
      let bi = i32(arcHash(seed) * f32(BONE_COUNT) * 0.9999);
      if (bd[bi] > 0.0) { continue; }   // one lookup, and the channel is gone
      let bone = arcBone(bi);
      let e2 = pts[bone.x];
      let f2 = pts[bone.y];
      let ez = zs[bone.x];
      let fz = zs[bone.y];

      // Snap on, HOLD, then die. A plain decay across a life this long reads
      // as a slow fade rather than as an arc that struck and stayed lit; the
      // hold is what lets a channel linger without going sluggish.
      let env = smoothstep(0.0, ATTACK, life) * (1.0 - smoothstep(HOLD, 1.0, life));
      let flick = 1.0 - FLICKER * arcHash(seed + vec2f(life * params.SIZZLE, 0.0));
      let amp = env * flick;
      if (amp < 0.02) { continue; }

      // The two shapes share one walk below; these are the parameters it needs.
      let curved = b >= CONNECTORS;
      var rad = 0.0;              // curved: orbit radius, on screen
      var a0 = 0.0;               //         from what angle
      var sweep = 0.0;            //         through how much of a turn
      var p0 = vec2f(0.0);        // straight: from here
      var p1 = vec2f(0.0);        //           to here
      var bow = 0.0;              //           bowing this far off the chord
      var z0 = 0.0;               // depth at the head of the run
      var z1 = 0.0;               //           and at its tail
      var anchor = vec2f(0.0);    // what a ring is centred on, on screen
      var anchorZ = 0.0;
      var boneLen = 1.0;          // its bone's length on screen, for the scale

      if (curved) {
        // A crackle: a ring around a point ANYWHERE ALONG the limb. Small
        // radius, partial turn, either handedness — it clings, it does not
        // radiate. Projected from the interpolated world point rather than
        // interpolated between two projections, which is the same thing only
        // for a bone pointed across the frame.
        // Interpolated between the bone's two PROJECTED ends rather than
        // projected from the interpolated world point. Those differ only by
        // what perspective does across the length of one limb, which at the
        // scale of a hairline arc is nothing, and it saves a projection on
        // every channel.
        let tb = arcHash(seed + vec2f(0.9, 3.4));
        anchor = mix(e2, f2, tb);
        anchorZ = mix(ez, fz, tb);
        boneLen = length(f2 - e2);
        z0 = anchorZ;
        z1 = anchorZ;
        rad = CRACKLE_R * (0.55 + 0.7 * arcHash(seed + vec2f(1.1, 8.8)));
        a0 = arcHash(seed + vec2f(5.1, 2.9)) * TAU;
        let turn = SWEEP_MIN + (SWEEP_MAX - SWEEP_MIN) * arcHash(seed + vec2f(2.4, 6.3));
        sweep = select(-turn, turn, arcHash(seed + vec2f(9.2, 0.4)) > 0.5);
      } else {
        // A connector: a SHORT bowed slice OF the limb, not the whole of it.
        let frac = SPAN_MIN + (SPAN_MAX - SPAN_MIN) * arcHash(seed + vec2f(1.1, 8.8));
        // Where along the bone it sits, measured from one end or the other.
        let slide = arcHash(seed + vec2f(4.9, 3.1)) * (1.0 - frac) * HUG;
        let t0 = select(slide, 1.0 - frac - slide, arcHash(seed + vec2f(2.2, 9.6)) > 0.5);
        p0 = mix(e2, f2, t0);
        p1 = mix(e2, f2, t0 + frac);
        // The slice runs along the limb in depth as well as across screen.
        z0 = mix(ez, fz, t0);
        z1 = mix(ez, fz, t0 + frac);
        anchorZ = z0;
        // Signed, so it curves one way instead of wobbling around the chord.
        bow = select(-BOW, BOW, arcHash(seed + vec2f(9.2, 0.4)) > 0.5) * JAG;
      }

      // ── Culling, in two tiers ──
      //
      // Walking the real path costs ten segment tests and ten sines, and a
      // circular bound is a bad fit for something long and thin — worse, it
      // admits every pixel out to the AURA radius, where the wander is far
      // smaller than the distance and nothing about the exact path can be seen.
      // Widening the aura for the neon look therefore cost roughly the square
      // of the widening in walked pixels, which is where the frame rate went.
      //
      // So measure once against a three-piece SKETCH of the shape — both ends,
      // the bulge between them, and the branch as one straight run — and decide
      // from that. Beyond the aura, skip. Inside the aura but outside the
      // filament, shade the aura straight off the sketch: at that distance a
      // wander of JAG is a rounding error on a cubic falloff, and the walk buys
      // nothing. Only pixels near enough to resolve the filament pay for it.
      //
      // The sketch is a capsule rather than a disc, which is the second saving:
      // for a connector it admits about half the pixels the old bound did.
      let run = select(length(p1 - p0), abs(sweep) * rad, curved);
      let fi = 1 + i32(arcHash(seed + vec2f(6.6, 1.3)) * f32(SEGS - 2));
      let tf = f32(fi + 1) / f32(SEGS);
      var mid = (p0 + p1) * 0.5;
      var head = p0;
      var tail = p1;
      var fo = mix(p0, p1, tf);   // where the branch tears, near enough for a cull
      var tang = vec2f(1.0, 0.0);
      if (curved) {
        let am = a0 + sweep * 0.5;
        let af = a0 + sweep * tf;
        head = anchor + vec2f(cos(a0), sin(a0)) * rad;
        tail = anchor + vec2f(cos(a0 + sweep), sin(a0 + sweep)) * rad;
        mid = anchor + vec2f(cos(am), sin(am)) * rad;
        fo = anchor + vec2f(cos(af), sin(af)) * rad;
        tang = vec2f(-sin(af), cos(af)) * sign(sweep);
      } else {
        let dirn = normalize(p1 - p0 + vec2f(1e-5));
        let perp = vec2f(-dirn.y, dirn.x);
        mid = mid + perp * bow;
        fo = fo + perp * (bow * sin(tf * 3.14159265));
        tang = dirn;
      }
      // Same handedness hash the branch itself uses, and its longest reach.
      let fangC = select(-1.1, 1.1, arcHash(seed + vec2f(0.3, 4.4)) > 0.5);
      let fdirC = vec2f(
        tang.x * cos(fangC) - tang.y * sin(fangC),
        tang.x * sin(fangC) + tang.y * cos(fangC)
      );
      let dc = min(
        min(arcSeg(p, head, mid), arcSeg(p, mid, tail)),
        arcSeg(p, fo, fo + fdirC * run * 0.55)
      );
      if (dc > HAZE_W + JAG) { continue; }
      if (dc > GLOW_W + JAG) {
        // Aura only. One depth for the whole shape is enough for something this
        // soft, and it saves working out the metre scale at all.
        let zc = select(mix(z0, z1, 0.5), anchorZ, curved);
        let visC = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, zc);
        haze = max(haze, arcHalo(dc) * amp * visC);
        continue;
      }

      // How far this ring swings toward and away from the camera. The radius is
      // on screen; the bone below says how much of the frame a metre is; the tilt is
      // how much of the ring is pointed through the frame rather than across
      // it. A flat ring never hides, a steep one spends half its sweep behind.
      var zAmp = 0.0;
      var zAxis = 0.0;
      if (curved) {
        let tilt = TILT_MIN + (TILT_MAX - TILT_MIN) * arcHash(seed + vec2f(3.7, 5.5));
        // How many metres a frame-height is HERE, read off the bone the arc
        // is sitting on: its length on screen against its length in the world.
        // That was a second projection per channel when it went through
        // a helper of its own, and the bone already answers it.
        let wl = length(arcWorld(c, bone.y).xyz - arcWorld(c, bone.x).xyz);
        let perFrame = max(boneLen, 1e-5) / max(wl, 1e-4);
        // Capped at the bounding sphere: a camera looking down the up axis
        // makes the metre-to-frame conversion degenerate, and an uncapped
        // swing would then bury or float every arc at once.
        zAmp = min(rad / perFrame * tilt, s.bounds.w);
        zAxis = arcHash(seed + vec2f(8.1, 1.9)) * TAU;
      }

      // fi — where the branch tears off — was chosen by the cull above. Never
      // the first or last jag: a fork at the root reads as two arcs, and one at
      // the tip reads as a fray.
      var forkAt = mid;
      var forkDir = vec2f(1.0, 0.0);
      var forkZ = anchorZ;
      var prev = head;
      var zPrev = select(z0, anchorZ + zAmp * cos(a0 - zAxis), curved);
      // Nearest point on the path, and — the reason this is tracked at all —
      // how far away that point is. One shade, one depth test, per path.
      var d = 1e9;
      var dz = zPrev;

      for (var i = 0; i < SEGS; i++) {
        let t = f32(i + 1) / f32(SEGS);
        // Wander biggest mid-run, so both ends stay where they belong.
        let bulge = sin(t * 3.14159265);
        // The wander is fixed for the life of the channel, so a longer life
        // would sit there as a still picture. This is the one term that moves
        // while it is lit: each jag breathes on its own phase, which is what an
        // arc does when it is hunting for a path.
        let wob = sin(time * WOBBLE_HZ * TAU + arcHash(seed + vec2f(f32(i) * 3.1, 5.5)) * TAU);
        let jit = ((arcHash(seed + vec2f(f32(i) * 9.1, 2.2)) - 0.5) * 2.0 + wob * WOBBLE) * JAG * bulge;
        var next: vec2f;
        var zNext: f32;
        if (curved) {
          // Radially, so the jag roughens the orbit instead of flattening it.
          let ang = a0 + sweep * t;
          next = anchor + vec2f(cos(ang), sin(ang)) * (rad + jit);
          zNext = anchorZ + zAmp * cos(ang - zAxis);
        } else {
          let dirn = normalize(p1 - p0 + vec2f(1e-5));
          next = mix(p0, p1, t) + vec2f(-dirn.y, dirn.x) * (jit + bow * bulge);
          zNext = mix(z0, z1, t);
        }
        let ds = arcSeg(p, prev, next);
        if (ds < d) {
          d = ds;
          dz = (zPrev + zNext) * 0.5;
        }
        if (i == fi) {
          forkAt = next;
          forkDir = normalize(next - prev + vec2f(1e-5));
          forkZ = zNext;
        }
        prev = next;
        zPrev = zNext;
      }

      // The branch: off the tangent, short, thinner, bowed one way so it curls
      // rather than zigzags. Short enough that it takes its depth from where it
      // tore off and does not need one of its own.
      let fang = select(-1.1, 1.1, arcHash(seed + vec2f(0.3, 4.4)) > 0.5);
      let fdir = vec2f(
        forkDir.x * cos(fang) - forkDir.y * sin(fang),
        forkDir.x * sin(fang) + forkDir.y * cos(fang)
      );
      let fperp = vec2f(-fdir.y, fdir.x);
      let fbow = select(-1.0, 1.0, arcHash(seed + vec2f(7.7, 2.1)) > 0.5) * JAG * 0.7;
      let fend = forkAt + fdir * run * (0.25 + 0.30 * arcHash(seed + vec2f(0.7, 6.1)));
      var fa = forkAt;
      var df = 1e9;
      for (var i = 0; i < FORK_SEGS; i++) {
        let t = f32(i + 1) / f32(FORK_SEGS);
        let e = sin(t * 3.14159265);
        let wob = sin(time * WOBBLE_HZ * TAU + arcHash(seed + vec2f(f32(i) * 6.3, 1.4)) * TAU);
        let jit = ((arcHash(seed + vec2f(f32(i) * 4.7, 8.3)) - 0.5) + wob * WOBBLE) * JAG * 0.5 * e;
        let next = mix(forkAt, fend, t) + fperp * (fbow * e + jit);
        df = min(df, arcSeg(p, fa, next));
        fa = next;
      }

      // Hidden where the body is nearer than the arc. Soft, over a few
      // centimetres: a hard test crawls along the silhouette as she turns.
      let visM = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, dz);
      let visF = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, forkZ);
      if (visM + visF <= 0.001) { continue; }

      // BRIGHTEST WINS, rather than summing. Twenty-two channels over ten
      // joints means two or three of them share a limb at any moment, and added
      // light compounds there: the halos merge into one blob and the filament
      // saturates past white in the middle of it. Under a max, an arc crossing
      // another stays as bright as the brighter of the two and no brighter, so
      // each one keeps its own edge and the discharge reads as many thin arcs
      // instead of one lit tube.
      //
      // The branch carries a thinner filament but the same light, so it reads
      // as part of the same discharge rather than as a second, dimmer one.
      core = max(core, (1.0 - smoothstep(0.0, CORE_W, d)) * amp * visM);
      core = max(core, (1.0 - smoothstep(0.0, CORE_W * 0.6, df)) * amp * 0.8 * visF);
      glow = max(glow, (1.0 - smoothstep(0.0, GLOW_W, d)) * amp * visM);
      glow = max(glow, (1.0 - smoothstep(0.0, GLOW_W, df)) * amp * visF);
      haze = max(haze, arcHalo(d) * amp * visM);
      haze = max(haze, arcHalo(df) * amp * visF);
    }
  }

  let heat = core * CORE_I + glow * GLOW_I + haze * HAZE_I;
  if (heat <= 0.004) { return vec4f(0.0); }
  // Colour from intensity: ember in the outer light, red through the body of
  // the arc, and the pale core only where it is genuinely hot — a high
  // threshold, because a red bolt that whites out along its length is an
  // orange one.
  var rgb = mix(HAZE_COLOR, params.BODY_COLOR, smoothstep(0.03, 0.50, heat));
  rgb = mix(rgb, params.CORE_COLOR, smoothstep(1.3, 2.4, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}

#layer additive

#param color RING_COLOR #a357ff — the lines — violet
#param color HOT_COLOR #ebd6ff — where they are brightest
#param float SIZE 1.6 0.5 4 — sigil radius, in hip heights
#param float SPIN 0.05 -0.5 0.5 — turns per second

// Summoning Circle — a sigil under the cast, and the light standing on it.
//
// WHERE IT STANDS is rzSubject().root by default: the floor under the character,
// which tracks her across the stage and stays on the ground when she jumps.
//
// It used to default to "@anchor 全ての親" on the reasoning that this is the
// model's own floor bone. It is — in the REST pose. Almost no MMD motion keys
// 全ての親; a dance moves センター and leaves the master bone at the model origin,
// so the sigil sat where she STARTED and she walked out of it. rzSubject().root
// is the pair no single bone can give: センター's horizontal position, at the
// placement height rather than the animated one.
//
// To move it, add an @anchor line and it re-centres on that bone, lying in the
// horizontal plane through it: 左手首 follows her palm, 頭 makes it a halo, 右足首
// burns it under one foot. A rig that spells the bone differently reports
// .valid false and it falls back to the floor point above.
//
// The sigil is a port of nayk's summoningCircle():
//   https://www.shadertoy.com/view/M3KGD3          (nayk, 2024-06-14)
// which itself credits
//   https://glslsandbox.com/e#109235.1
//   https://www.shadertoy.com/view/43V3zG
// The construction below is transcribed rather than reinterpreted — the same
// helpers (lPoly, mPoly, strokeStar, wtrz), the same figures in the same order,
// the same constants. Its shape is three chords struck across a triangle, a
// rimmed ring whose outer stroke breathes on a trapezoidal wave, nested
// triangles and a hexagon, and a hexagram set into a disc at each vertex.
//
// What is NOT the original is where it lives. This draws on the HORIZONTAL
// PLANE through the anchor, found by intersecting the view ray with it, so the
// figure lies flat in the world under the bone instead of across the frame.
//
// Level, deliberately, even when the anchor is a wrist. A bone carries a
// forward axis and the disc could be turned onto it, but a summoning circle
// reads as one BECAUSE it lies flat and lights what stands over it — tumble it
// with the hand and it reads as a decal stuck to the palm.
//
// It is a FOREGROUND mount even though it draws on the ground, and that is
// deliberate. A background mount only survives where the scene did not cover
// the pixel, so a scene with a ground plane would hide the sigil completely.
// Drawn forward and depth-tested by hand, it lies on the floor whether or not
// there is a floor, and her legs cut into it correctly either way.
//
// The one place the port had to change: the original's line widths and feathers
// are constants in a space where the figure fills the frame, so a pixel is
// always far smaller than the thinnest of them. On a ground plane raking away
// toward the horizon a pixel covers a great deal of sigil, and those strokes
// fall below it and break into dashes. So every width and every feather has a
// floor of one measured pixel — metres-per-pixel converted at the point being
// drawn, which holds at any distance, any field of view and any grazing angle.
// Up close nothing is touched and the figure is the original's exactly.
//
// Tunables — edit and ⌘⏎.

const COL_COLOR = vec3f(0.40, 0.07, 0.90);   // deep purple, in the faint light

const EXTENT = 1.30;      // how far past that radius the FIGURE actually goes.
                          // The rim is at 1.0, but mPoly centres the three
                          // vertex discs ON it and they are 0.2 across, so the
                          // drawing reaches 1.2 — gate any tighter and the
                          // discs come back sliced off, which is exactly what
                          // a rim-radius gate did to them.

const LINE_W = 1.3;       // the one-pixel floor, in pixels
const RING_I = 1.35;      // how hot a line is
const COL_R = 1.05;       // column radius, in hip heights — wide enough to
                          // stand the whole body inside it
const COL_H = 3.0;        // and height, the same
const COL_I = 0.50;
const PULSE = 0.18;       // depth of the breathing brightness
const PULSE_HZ = 0.5;
const Z_BIAS = 0.03;      // metres of slack before the scene occludes it
const Z_FADE = 0.04;

const PI = 3.14159265;
const TAU = 6.2831853;

fn sat(x: f32) -> f32 { return clamp(x, 0.0, 1.0); }

/** p turned by a. GLSL's `p * rot(a)` is a row vector times a column-major
 *  matrix, which comes out as the ordinary counter-clockwise turn. */
fn rot2(p: vec2f, a: f32) -> vec2f {
  let c = cos(a);
  let s = sin(a);
  return vec2f(p.x * c - p.y * s, p.x * s + p.y * c);
}

// The original's signed-distance shorthand: inside is positive.
fn sdR(d: f32, r: f32) -> f32 { return r - d; }
fn sd1(d: f32) -> f32 { return 1.0 - d; }

fn fillA(d: f32, aa: f32) -> f32 { return smoothstep(0.0, aa, d); }

/** Both the width and the feather take a floor of one pixel. Without it the
 *  0.005-wide strokes below vanish wherever the plane rakes away. */
fn strokeA(d: f32, w: f32, aa: f32) -> f32 {
  let ww = max(w, aa * 0.5);
  return 1.0 - smoothstep(ww, ww + aa, abs(d));
}
fn strokeInnerA(d: f32, w: f32, aa: f32) -> f32 { return strokeA(d - w, w, aa); }
fn strokeOuterA(d: f32, w: f32, aa: f32) -> f32 { return strokeA(d + w, w, aa); }

fn lSquare(p: vec2f) -> f32 { let q = abs(p); return max(q.x, q.y); }

/** Distance to a regular n-gon, by folding the angle onto its nearest edge. */
fn lPoly(p: vec2f, n: f32) -> f32 {
  let a = atan2(p.x, p.y) + PI;
  let r = TAU / n;
  return cos(floor(0.5 + a / r) * r - a) * length(p) / cos(r * 0.5);
}

/** Fold the plane into n wedges, each measured from a point s out along its
 *  own axis — how the vertex discs get drawn once and appear three times. */
fn mPoly(p: vec2f, n: f32, s: f32) -> vec2f {
  let r = TAU / n;
  let a = floor(atan2(p.y, p.x) / r) * r + r * 0.5;
  return rot2(vec2f(cos(a), sin(a)) * s - p, -a - PI * 0.5);
}

fn wtri(x: f32) -> f32 { return abs(2.0 * fract(x * 0.5 - 0.25) - 1.0) * 2.0 - 1.0; }
/** Trapezoidal wave — the outer ring's width steps between two values on it. */
fn wtrz(x: f32, w: f32) -> f32 { return clamp(wtri(x * 2.0) * w, -1.0, 1.0); }

/** Two n/2-gons, the second turned or mirrored: for n = 6, a hexagram. */
fn strokeStar(p: vec2f, n: f32, w: f32, aa: f32) -> f32 {
  var l = strokeInnerA(sd1(lPoly(p, n * 0.5)), w, aa);
  let odd = (n - 2.0 * floor(n * 0.5)) != 0.0;
  let p2 = select(rot2(p, TAU / n), vec2f(-p.x, p.y), odd);
  l = l + strokeInnerA(sd1(lPoly(p2, n * 0.5)), w, aa);
  return l;
}

/** nayk's figure, transcribed. p is in sigil radii; 1.0 is the rim. */
fn summoningCircle(p: vec2f, aa: f32) -> f32 {
  var l = 0.0;
  // Three chords struck across the figure — thin bands through the centre,
  // squashed a hundred to one so lSquare reads them as lines.
  l = l + fillA(sdR(lSquare(rot2(p, PI / 3.0 * 1.5) * vec2f(100.0, 1.0)), 1.0), aa);
  l = l + fillA(sdR(lSquare(rot2(p, PI / 3.0 * 2.5) * vec2f(100.0, 1.0)), 1.0), aa);
  l = l + fillA(sdR(lSquare(rot2(p, PI / 3.0 * 3.5) * vec2f(100.0, 1.0)), 1.0), aa);
  l = sat(l);
  // and cut back out of the triangle, so they read as spokes from its edges.
  l = l - fillA(sd1(lPoly(p, 3.0)), aa);
  l = sat(l);

  let r = atan2(p.y, p.x);
  // The rim: outer stroke breathing between two widths three times around.
  l = l + strokeOuterA(sdR(length(p), 0.98), 0.008 + wtrz(r / TAU * 3.0, 12.0) * 0.005, aa);
  l = l + strokeInnerA(sdR(length(p), 0.95), 0.005, aa);
  // Nested triangles, and the hexagon between them.
  l = l + strokeInnerA(sd1(lPoly(p, 3.0)), 0.01, aa);
  l = l + strokeInnerA(sdR(lPoly(p, 3.0), 0.88), 0.02, aa);
  l = l + strokeInnerA(sdR(lPoly(p, 6.0), 0.53), 0.01, aa);
  let q = mPoly(rot2(p, PI * 0.5), 3.0, 0.5);
  l = l + fillA(sdR(lPoly(q, 3.0), 0.3), aa);
  let q2 = mPoly(rot2(p, PI / 3.0 + PI * 0.5), 3.0, 0.7);
  l = l + fillA(sdR(lPoly(q2, 3.0), 0.1), aa);
  l = l + strokeInnerA(sdR(lPoly(rot2(p, PI), 3.0), 0.5), 0.02, aa);
  l = l + fillA(sdR(length(p), 0.05), aa);

  // A disc at each triangle vertex: punched out of everything above, ringed
  // twice, with a hexagram set into it.
  let q3 = mPoly(rot2(p, PI * 0.5), 3.0, 1.0);
  l = sat(l);
  l = l - fillA(sdR(length(q3), 0.2), aa);
  l = sat(l);
  l = l + strokeInnerA(sdR(length(q3), 0.18), 0.005, aa);
  l = l + strokeInnerA(sdR(length(q3), 0.15), 0.005, aa);
  l = l + strokeStar(rot2(q3, PI) * 7.0, 6.0, 0.1, aa);
  return l;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let ro = rzCameraPos();
  var lines = 0.0;
  var beam = 0.0;

  for (var c = 0; c < rzSubjectCount(); c++) {
    let s = rzSubject(c);
    if (!s.valid) { continue; }
    // Sized off the HIP HEIGHT. bounds.w is a deliberately generous cull
    // sphere, not a fit — sizing off it put the sigil several body heights
    // across, so only ever a fragment of it was on screen. Root to hips is a
    // dependable fraction of any rig's height, and it costs nothing to read.
    let H = max(s.center.y - s.root.y, 0.05);
    let R = H * params.SIZE;
    // WHERE this character's figure stands. Read per subject, so two dancers
    // each get their own wrist rather than sharing the first one's, and checked
    // rather than trusted — an unchecked .valid is how a bone effect draws at
    // the world origin on every model that spells the name differently.
    let anchor = rzAnchor(c, 0);
    let base = select(s.root, anchor.pos, anchor.valid);
    // Breathing, per character and out of phase, so a duo does not pulse as one.
    let pulse = 1.0 + PULSE * sin((time * PULSE_HZ + f32(c) * 0.37) * TAU);

    // ── The sigil, on the plane through the anchor ──
    if (abs(ray.y) > 1e-4) {
      let t = (base.y - ro.y) / ray.y;
      if (t > 0.0) {
        let hit = ro + ray * t;
        let rel = hit.xz - base.xz;
        if (dot(rel, rel) < R * R * EXTENT * EXTENT) {
          let at = rzProject(hit);
          // Hidden by anything nearer — her legs, a prop, the lip of a stage.
          // Soft, or the boundary crawls as she moves over it.
          let vis = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, at.z);
          if (vis > 0.001) {
            // One pixel, in sigil radii, HERE — measured rather than assumed,
            // which is what keeps the strokes whole as the plane rakes away and
            // one pixel starts covering a great deal of ground.
            let up = rzProject(hit + rzCameraUp() * 0.25);
            let uvPerM = max(abs(up.y - at.y) * 4.0, 1e-5);
            let aa = max(0.01, LINE_W / (uvPerM * max(res.y, 1.0) * R));
            let sig = summoningCircle(rot2(rel / R, time * params.SPIN * TAU), aa);
            lines = max(lines, sat(sig) * vis * pulse);
          }
        }
      }
    }

    // ── The column standing on it ──
    //
    // A vertical cylinder, shaded from the ray's CLOSEST APPROACH to its axis
    // rather than marched: for a shape this soft the nearest point carries the
    // whole look, and a march would cost thirty samples to say the same thing.
    //
    // It rises FROM THE SIGIL, not from the floor — anchor to a wrist and the
    // shaft climbs out of her palm, which is the point of anchoring at all.
    let denom = 1.0 - ray.y * ray.y;
    if (denom > 1e-4) {
      let w0 = ro - base;
      let tc = (ray.y * w0.y - dot(ray, w0)) / denom;
      if (tc > 0.0) {
        let q = ro + ray * tc;
        let h = (q.y - base.y) / (H * COL_H);
        let rad = length(q.xz - base.xz) / (H * COL_R);
        if (h > 0.0 && h < 1.0 && rad < 1.0) {
          let qat = rzProject(q);
          let vis = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, qat.z);
          // Squared across the radius rather than cubed: a shaft of light
          // still, but one that carries out to its edge instead of collapsing
          // onto its axis — a cubic falloff is down to an eighth at the halfway
          // mark, which leaves the body standing outside its own light. Fading
          // out at the top, and in off the ground so it does not end in a hard
          // disc where it meets the sigil.
          let radial = 1.0 - smoothstep(0.0, 1.0, rad);
          let vert = (1.0 - h) * smoothstep(0.0, 0.12, h);
          beam = max(beam, radial * radial * vert * vis * pulse);
        }
      }
    }
  }

  let heat = lines * RING_I + beam * COL_I;
  if (heat <= 0.004) { return vec4f(0.0); }
  // Deep purple in the faint light, violet through the strokes, and a pale
  // lilac only where they are hottest.
  var rgb = mix(COL_COLOR, params.RING_COLOR, smoothstep(0.05, 0.6, heat));
  rgb = mix(rgb, params.HOT_COLOR, smoothstep(1.0, 1.9, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}

// ── The light the sigil throws ───────────────────────────────────────────────
//
// A magic circle that lights nothing is a decal on the floor. This one is drawn
// as a violet figure on the plane through its anchor with a column standing in
// it, so the light belongs just above that plane, at the middle of the ring —
// lighting her from BELOW, which is the whole reason a summoning circle reads as
// one. It rides the anchor for the same reason the figure does: a light left at
// her feet while the sigil follows her palm is two effects, not one.
//
// One light, following the first subject, because that is the character the
// sigil is drawn under. A scene with two summoners is two instances of this
// effect, not one light budget split.
#lights 1
const LIGHT_UP = 0.35;     // how far above the sigil's own plane the source
                           // sits, in hip heights — a light lying IN that plane
                           // grazes the floor it lands on and lights nothing,
                           // since a floor normal is perpendicular to it
const LIGHT_I = 1.5;       // brightness at the source
const LIGHT_REACH = 2.6;   // in hip heights: past the sigil's own extent, so
                           // she is lit to the waist rather than the ankles

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  l.color = params.RING_COLOR;
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0, 0.0, 0.0);

  let s = rzSubject(0);
  if (!s.valid) { return l; }
  // Hip height is this effect's unit for everything else it draws; the light
  // measures in the same one, so it scales with the model like the sigil does.
  let H = max(s.center.y - s.root.y, 0.05);
  // The same anchor and the same fallback the figure uses — one bone read in
  // two mounts, so the light cannot end up somewhere the sigil is not.
  let anchor = rzAnchor(0, 0);
  let base = select(s.root, anchor.pos, anchor.valid);
  l.pos = vec3f(base.x, base.y + H * LIGHT_UP, base.z);
  l.radius = H * LIGHT_REACH;
  // The SAME breathing the figure has, so the glow on her and the glow on the
  // floor are one thing pulsing rather than two that happen to overlap.
  let pulse = 1.0 - PULSE * 0.5 + PULSE * 0.5 * sin(time * TAU * PULSE_HZ);
  l.intensity = LIGHT_I * pulse;
  return l;
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#particles 7000
#blend additive
#bloom
#duration 4.5 — one turn of the DISSOLVE_ cycle at its default dials
#dissolve
#anchor 頭
#anchor 上半身2
#anchor 左ひじ
#anchor 右ひじ
#anchor 左手首
#anchor 右手首
#anchor 左ひざ
#anchor 右ひざ

#param float SIZE 0.0055 0.001 0.02 — mote radius, in HIP HEIGHTS — about 0.05 world
#param float FALL 0.72 0 3 — gravity, in hip heights per second squared
#param float SWIRL 0.75 0 2 — and how tightly it curls

// Teleportation — she comes apart into falling neon motes, is gone for a beat,
// and reforms while what left her is still on its way down.
//
// THIS FILE DOES NOT DRAW THE BODY, which is the one thing to know before
// reading it. `@dissolve` asks the engine to take the model apart in the
// MATERIAL — every flake whose object-space threshold has passed is thrown
// away, in the colour pass, the depth prepass and the shadow map alike — and
// what is written here is only what LEAVES her. Covering her with a cloud
// instead was the first attempt, and it looked like what it was.
//
// ONE CLOCK, the engine's. It samples the four durations below — on the scene
// clock, or on a clip's own clock wherever this effect is placed on the
// timeline — and writes the result into every material and into the cast, so a
// mote asks rzSubject(0).dissolve where the body is up to rather than keeping
// time of its own. That is also why an export reproduces a take exactly.
//
// THEY params.FALL, they are not thrown, and they are never called back. Release is
// nearly velocity-free; everything after is gravity against a heavy drag with
// curl noise for the wander. Pulling them home as she reassembled read as
// rewind — the same dust running backwards up the same path — so what has left
// her simply keeps falling.
//
// THEY ARE SMALL, and they light what they pass. A mote is about Footprints'
// ember, well under a hundredth of her height; fineness comes from COUNT, not
// from size. Seven thousand lamps is not something an engine will give you, so
// three declared lights stand in for the cloud at chest, hips and shins,
// sinking as it falls.
//
// WHERE THEY COME FROM is an approximation worth knowing about: a particle pass
// sees the cast and the bones it declared, not the mesh, so a mote spawns on a
// random limb segment between two anchors. The cloud is limb-shaped rather than
// silhouette-shaped, and it shows if you look for it.

// Tunables — edit and ⌘⏎.
//
// ── The four phases, in seconds ──
// The whole of the timing, and what this gets retuned on most, so they are
// DIALS: drag one and she retimes on the next frame. No line below reads them —
// `#dissolve` above is the declaration, and the engine performs them.
//
// PLACED ON THE TIMELINE, a clip opens on the departure: someone dropping one
// on a beat means the teleport lands there, not WHOLE seconds later. WHOLE is
// then the tail the motes finish falling in. Unscheduled, the cycle repeats.
//
// BACK IS QUICKER THAN APART on purpose — coming apart happens TO a body and
// wants watching, arriving is a decision. Matched, the return read as the
// dissolve running backwards.
//
// The floor under WHOLE is the params.FALL, not the dissolve: a mote shed as she goes
// is still going out nearly two seconds later. To teleport more often than
// that, shorten LIFE rather than WHOLE.
#param float DISSOLVE_APART 0.50 0.05 3 — seconds she takes to come apart
#param float DISSOLVE_GONE 0.65 0 5 — seconds there is nothing of her
#param float DISSOLVE_BACK 0.35 0.05 3 — seconds she takes to arrive again
#param float DISSOLVE_WHOLE 3.00 0 20 — seconds she stands whole, between turns

                          // units on a normal model, i.e. Footprints' ember
const SIZE_VARY = 0.65;   // how much that differs mote to mote

const DRAG = 2.0;         // and what fights it; the two together are the
                          // terminal speed — params.FALL × hip ÷ DRAG. Half again as
                          // quick as the first pass, which drifted
const SWAY = 0.14;        // curl wander, in hip heights per second

const PUFF = 0.06;        // the whisper of movement at release. Near zero on
                          // purpose: a mote that leaves fast has been thrown
const SPIN = 1.9;         // how fast a petal turns as it falls
#param float LIFE 1.8 0.3 6 — seconds before a mote is spent. Deliberately SHORT
                          // of the floor: a mote that lands has stopped being
                          // light and started being litter, and the fall wants
                          // to end in the air. It also has to be gone before
                          // she leaves again, or the second cycle opens over
                          // the leftovers of the first
const LIFE_VARY = 0.40;   // how much that differs mote to mote. NOT a detail:
                          // they are all shed inside one short window, so a
                          // single lifetime ages the whole cloud in lockstep
                          // and puts it out in one frame — a fall that ends
                          // like a switch. Spread, they go out the way they
                          // left, a few at a time
const JITTER = 0.30;      // how far off the bone a mote starts, in hip heights
const PETALS = 0.45;      // fraction of them that are petals; the rest stars
// NEON, and Hand Ribbon's exactly — electric blue through violet, with a
// lavender heart. Taken rather than invented: the two effects are the same
// light seen twice, one whipping off a wrist and one falling off a whole body,
// and a scene wearing both should not have to explain why they disagree about
// what neon is.
//
// Each mote keeps one hue for its whole fall, and the fall is all three at once
// — a single hue reads as a colour wash, three read as lights. Saturated well
// past what survives AgX alone, which is what the white core and the halo are
// for.
const NEON_A = vec3f(0.12, 0.42, 1.00);  // electric blue — the ribbon's body
const NEON_B = vec3f(0.34, 0.10, 0.98);  // violet — its outer haze
const NEON_C = vec3f(0.36, 0.24, 1.00);  // deep violet-blue — its spark halo
const HOT = vec3f(0.80, 0.74, 1.00);     // the core: lavender, not white, so a
                                         // filament still reads as this colour
                                         // rather than as a hole in it
const GLOW = 0.55;        // the halo around each mote, against its core. This
                          // is the neon: a lamp is a filament you cannot look
                          // at, sitting inside a colour you can
const GLOW_R = 2.4;       // how tightly that halo falls off — smaller spreads
const INTENSITY = 6.0;    // HDR: particles draw before the tone map, so white
                          // here lands as grey without it — see Snow's note
const CORE = 0.42;        // fraction of the mote that is SOLID before it falls
                          // off. A dot this small that ramps from its centre
                          // reaches full brightness at one pixel and reads as
                          // dirt on the lens
// ── The light the fall throws ───────────────────────────────────────────────
//
// The motes already GLOW — they draw inside the scene pass, so the bloom
// pyramid catches them. What they did not do is LIGHT anything: a body coming
// apart into seven thousand lamps left the floor under her, the stage behind
// her and her own remaining half exactly as the sun had them, which is the tell
// Hand Ribbon, the fire and the follow-spots each had before they declared
// lights of their own.
//
// THREE, not seven thousand. A light is a declared cost and the engine's slots
// are few, so what these stand in for is the CLOUD rather than any mote in it:
// one at the chest where the shedding is thickest, one at the hips, one at the
// shins where what has already fallen collects. They sink as she empties, which
// is what keeps the lit patch travelling down with the fall instead of hanging
// where she was.
#lights 3
const LIGHT_I = 3.2;      // brightness at the source
const LIGHT_R = 2.4;      // reach, in hip heights — past her own width, so the
                          // floor and whatever she is standing near take it too
const LIGHT_SINK = 0.45;  // how far the three drop as the cloud falls, in hip
                          // heights

const TAU = 6.2831853;

/** The joints this file knows, in declaration order, plus two the cast already
 *  carries. 8 is the anchor cap, so the feet are the subject's own root. */
fn jointAt(i: i32, s: RzSubject) -> vec3f {
  if (i == 8) { return s.center; }
  if (i == 9) { return s.root; }
  let a = rzAnchor(0, i);
  // A rig that spells a bone differently reports .valid false — that limb then
  // collapses onto the torso rather than shedding motes from the world origin.
  return select(s.center, a.pos, a.valid);
}

/**
 * Where on the body this mote belongs, THIS frame.
 *
 * Recomputed rather than stored: a particle has no field to keep it in, and
 * asking the live skeleton means a waiting mote rides the dance — she can walk
 * across the stage between teleports and every mote is still on her.
 */
fn bodyPoint(seed: f32, s: RzSubject) -> vec3f {
  let h = rzHash13(seed * 3.117);
  let k = i32(floor(h.x * 10.0));
  var a = 8;
  var b = 0;
  switch k {
    case 0: { a = 8; b = 0; }   // torso → head
    case 1: { a = 8; b = 1; }   // hips → chest
    case 2: { a = 1; b = 2; }   // chest → left elbow
    case 3: { a = 2; b = 4; }   // left elbow → wrist
    case 4: { a = 1; b = 3; }   // chest → right elbow
    case 5: { a = 3; b = 5; }   // right elbow → wrist
    case 6: { a = 8; b = 6; }   // hips → left knee
    case 7: { a = 6; b = 9; }   // left knee → the floor under her
    case 8: { a = 8; b = 7; }   // hips → right knee
    default: { a = 7; b = 9; }  // right knee → the floor
  }
  let hip = max(s.center.y - s.root.y, 0.05);
  let j = (rzHash13(seed * 7.31 + 1.7) - vec3f(0.5)) * hip * JITTER;
  return mix(jointAt(a, s), jointAt(b, s), h.y) + j;
}

/**
 * The dissolve value at which this mote's flake goes.
 *
 * The SAME shape the material's threshold has — noise alone, no sweep — so a
 * mote appears at the moment the surface it came from stops being drawn, and
 * the whole body sheds at once. It cannot be the same NUMBER (that one is per
 * fragment, in object space; this is per particle, in world space), but matching
 * the shape is what keeps the two reading as one event rather than as a cloud
 * that happens to be near a vanishing woman.
 */
/** This mote's own span, in seconds. Derived from the seed rather than stored:
 *  a particle has no field to keep it in, and the seed is stable per slot. */
fn moteLife(seed: f32) -> f32 {
  return params.LIFE * mix(1.0 - LIFE_VARY, 1.0 + LIFE_VARY, rzHash13(seed * 17.9 + 3.1).y);
}

fn releaseAt(seed: f32) -> f32 {
  return rzHash13(seed * 11.3 + 4.2).x;
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let sd = seed + f32(id) * 0.0173;
  let s = rzSubject(0);
  p.seed = sd;
  p.pos = bodyPoint(sd, s);
  p.vel = vec3f(0.0);
  // Waiting. It is ON her, invisible, until the front reaches it — a mote that
  // spawns already falling has come from nowhere.
  p.size = 0.0;
  p.rot = rzHash13(sd * 2.9).z * TAU;
  // Never stretched: these drift, and the velocity-as-orientation path would
  // turn a petal into a streak the moment it picked up any speed at all.
  p.stretch = 1.0;
  // Never retires: the pool IS the body, and a slot that recycled would move a
  // mote to another limb mid-fall.
  p.life = 1.0e9;
  p.age = 0.0;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  let s = rzSubject(0);
  if (!s.valid) {
    q.size = 0.0;
    return q;
  }
  let hip = max(s.center.y - s.root.y, 0.05);
  let home = bodyPoint(q.seed, s);
  let gate = releaseAt(q.seed);
  let h = rzHash13(q.seed * 13.7 + 2.3);

  // A mote ALREADY FALLING is left alone, whatever the body is doing. She can
  // be whole again by now — near the end of a fall she usually is — and that is
  // the point: what has left her goes on falling, and she arrives again without
  // collecting it. The only thing the dissolve decides is whether a WAITING
  // mote may leave.
  if (q.size <= 0.0) {
    if (s.dissolve >= gate) {
      q.pos = home;
      q.vel = vec3f(0.0);
      // Held at zero, so the first frame of the fall is the first frame of the
      // mote's life however long it has been waiting. The pass adds dt after
      // this returns, which is what -dt is for.
      q.age = -dt;
      return q;
    }
    // RELEASED. Barely a push: enough that two motes leaving the same square
    // centimetre do not fall down the same line, and no more.
    q.vel = (rzHash13(q.seed * 5.5 + 0.9) - vec3f(0.5)) * PUFF * hip;
    q.size = params.SIZE * hip * mix(1.0 - SIZE_VARY, 1.0 + SIZE_VARY, h.x);
    q.age = 0.0;
  }

  // Gravity against a heavy drag is a slow terminal fall; the curl is the
  // wander on the way down. Divergence-free, so motes pass each other instead
  // of collecting into the same thread the way a plain sine drift does.
  let w = rzCurlNoise(q.pos * (params.SWIRL / max(hip, 1e-3)) + vec3f(0.0, rzTime() * 0.2, 0.0));
  let fall = vec3f(0.0, -params.FALL * hip, 0.0);
  q.vel = q.vel + (fall + w * SWAY * hip - q.vel * DRAG) * dt;
  q.pos = q.pos + q.vel * dt;
  // Each turns at its own rate, and the slow ones read as the heavy petals.
  q.rot = q.rot + dt * SPIN * mix(0.35, 1.5, h.z);
  if (q.age > moteLife(q.seed)) {
    q.size = 0.0;
    q.pos = home;
    q.vel = vec3f(0.0);
    q.age = -dt;
  }
  return q;
}

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  // Blue at the top, violet at the bottom — the same order the fall cools in,
  // and the same two colours the motes are drawn with. Never the core colour:
  // a lavender-white light washes whatever it lands on, and the colour a viewer
  // reads off the cloud is its body, not its filaments.
  l.color = select(select(NEON_A, NEON_C, i == 1u), NEON_B, i == 2u);
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0, 0.0, 0.0);

  // SUBJECT 0, as the sparks are. Lighting a whole cast would spend nine slots
  // on one effect and leave a composer no room for the stage.
  let s = rzSubject(0);
  if (!s.valid) { return l; }
  // How much of her has left. The same number the motes gate on and the
  // material dissolves by, so the light cannot be bright while she is whole or
  // dark while she is gone.
  let gone = clamp(1.0 - s.dissolve, 0.0, 1.0);
  if (gone <= 0.002) { return l; }

  let hip = max(s.center.y - s.root.y, 0.05);
  // Chest, hips, shins — and all three sink as the cloud does.
  var band = 1.55;
  if (i == 1u) { band = 0.95; }
  if (i == 2u) { band = 0.30; }
  l.pos = vec3f(s.root.x, s.root.y + hip * (band - LIGHT_SINK * gone), s.root.z);
  l.radius = hip * LIGHT_R;
  // Squared, so the light arrives with the fall rather than switching on with
  // the first flake: at a tenth gone she is a body with a few sparks leaving
  // it, and lighting the room for that reads as a lamp somebody threw.
  //
  // The lowest one holds up longest — what has already fallen is still down
  // there glowing after the shedding above it has stopped.
  let hold = select(1.0, 0.75 + 0.25 * gone, i == 2u);
  l.intensity = LIGHT_I * gone * gone * hold;
  return l;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  // The billboard is already turned by p.rot, so a shape drawn here spins with
  // the mote — which is the whole difference between a falling petal and a
  // sprite that happens to be moving downward.
  let c = uv * 2.0 - 1.0;
  let kind = rzHash13(p.seed * 21.1).y;
  var mask = 0.0;
  if (kind < PETALS) {
    // A petal: a rounded wedge, wider than it is deep, with the notch a sakura
    // has at its tip. Cheap — one squashed distance and one cosine.
    let q = vec2f(c.x, c.y * 1.35);
    let d = length(q);
    let notch = 0.16 * max(0.0, cos(atan2(q.y, q.x) * 1.0));
    mask = 1.0 - smoothstep(CORE, 1.0 - notch, d);
  } else {
    // A star: a solid core with two thin arms. Kept fine — an arm any thicker
    // and seven thousand of them read as snow.
    let d = length(c);
    let core = 1.0 - smoothstep(CORE * 0.7, 0.95, d);
    let arms = (1.0 - smoothstep(0.0, 0.16, abs(c.x))) + (1.0 - smoothstep(0.0, 0.16, abs(c.y)));
    mask = clamp(core + arms * (1.0 - smoothstep(0.2, 1.0, d)) * 0.55, 0.0, 1.0);
  }
  // The HALO is the neon. At this size the shape itself is two pixels, so all
  // of the light is in what surrounds it — and additive particles write their
  // alpha into the bloom mask, so the halo is also what makes them bloom.
  let halo = exp(-dot(c, c) * GLOW_R) * GLOW;
  let a = clamp(mask + halo, 0.0, 1.0);
  if (a < 0.004) { return vec4f(0.0); }

  // Its own colour for the whole fall, white only at the core. Mixed toward
  // white by the SHAPE rather than by radius, which is what makes the core read
  // as a filament: the solid part goes white and the glow around it keeps
  // the hue.
  let pick = rzHash13(p.seed * 31.7).z;
  var neon = NEON_A;
  if (pick > 0.66) { neon = NEON_C; } else if (pick > 0.33) { neon = NEON_B; }
  let rgb = mix(neon, HOT, mask * 0.85);

  // In, then out ON ITS OWN CLOCK — the mote's age against the mote's own span,
  // which has nothing to do with where the body is up to. It matters because
  // the two used to coincide: every mote is shed inside one short window, so
  // with one shared lifetime the whole cloud dimmed at the same instant, and
  // that instant landed near her return. The fall looked like it was being
  // switched off BY her coming back.
  //
  // Fading from a QUARTER of the way in and finished at nine tenths, so a mote
  // spends most of its fall going out and the last of it is dark before its
  // span even ends. Dropping at full brightness and then vanishing is what
  // makes a fall end like a switch.
  let life = clamp(p.age / moteLife(p.seed), 0.0, 1.0);
  let born = smoothstep(0.0, 0.05, life);
  let spent = 1.0 - smoothstep(0.22, 0.9, life);
  let twinkle = 0.74 + 0.26 * sin(rzTime() * 19.0 + p.seed * 40.0 + p.rot * 2.0);
  let heat = mix(1.35, 1.0, smoothstep(0.0, 0.35, life));
  let fade = born * spent * twinkle;
  return vec4f(rgb * INTENSITY * heat * fade, a * fade);
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#grid 768

#anchor 左足首
#anchor 右足首

#param float ADVECT 0.95 0 2 — `dissipation` — the backtrace falls 5% short on purpose
#param float KICK_R 2.6 0 8
#param float PUFF_V 1.25 0 4 — 0.1 px added per frame

// Dry Ice — David Gallardo (xjorma)'s heightfield fog, ported whole.
// CC BY-NC-SA 3.0. Common + Buffer A + B/C/D + Image, all four.
//
// The earlier port took Buffer A and the Image pass and rewrote the rest from
// memory of what a fluid needs. This one is the arithmetic, converted rather
// than reinterpreted — and the conversion is the interesting part, because the
// original is written entirely in PIXELS AND FRAMES:
//
//   velocity is pixels per frame; it backtraces by `dissipation * velocity`
//   pixels; density decays by a factor per frame; the noise is sampled in a uv
//   normalised by the viewport HEIGHT.
//
// None of those units exist here. A grid is a fixed number of texels whatever
// the window is, and dt is whatever the machine managed. So every constant
// below is the original's number times the conversion that makes it mean the
// same thing:
//
//   per frame   → per second, × 60
//   per pixel   → per FIELD (0..1 across the grid), ÷ 288
//
// 288 because that is the short side of the picture this was matched against.
// The original's look genuinely depends on its resolution — at 1080p the same
// source runs a slower, finer fluid, because a velocity of "one pixel" is a
// smaller fraction of the screen. Pinning the conversion to one resolution is
// what makes the port resolution-INDEPENDENT: raising @grid below now buys
// sharpness and changes nothing else, which is the property you want and the
// original does not have.

// Tunables — every const below is one, grouped by what it shapes. Edit and ⌘⏎.
// ── Where it lies, and how big ────────────────────────────────────────────────
//
// The original ties every length to one: fog 0.24 deep across a field 2 wide,
// emitters reaching 0.12, the light at 1.0. Held to exactly, on a stage, that
// gives a cloud sea — because the thing it is scaled around is a ball 3% of the
// field across, and a dancer is 12% of it and has to stay visible standing in
// the stuff. So the pool's WIDTH and the fog's DEPTH are set apart here, and
// what stays tied to the depth is everything that decides how the fog LOOKS:
// the light's height above it, and the size of the noise that shapes it.
//
// Read the three together. Widening the pool without moving the other two is
// what turns billows into hills.
const SIM_AT = vec2f(0.0, 0.0);   // the pool's centre, in world x/z
const SIM_SPAN = 160.0;           // and its width — the default ground, covered
const FLOOR_Y = 0.0;
// Thigh-deep on a model that stands ~20, which is where dry ice sits. Not a
// share of the span: at the original's 12% this would be 19 and she would be in
// it to the chest.
const HEIGHT = 7.0;
// The lamp, at the original's 4.17 fog-heights up (its 1.0 over a fog 0.24
// deep). Tied to HEIGHT and NOT to the span, and that is the whole difference
// between a lit pool and a white sheet: hung at half the span instead — 80 units
// for this pool — it lights everything from so far above that the 1/d² is flat
// across the whole floor and every billow shadow is too short to see.
const LIGHT_Y = FLOOR_Y + HEIGHT * 4.17;
// A foot. Absolute, because a foot does not get bigger when the stage does —
// this is the one length the original scales that has a real size here.

// ── The fluid (Buffer A) ─────────────────────────────────────────────────────
//
// Velocity is in FIELDS PER SECOND: 1.0 crosses the pool in a second. Density is
// 0..1, the fraction of HEIGHT the fog reaches here.

// The two noise fields, in cycles across the pool. The original samples them at
// uv*40 and uv*1.5 over a uv spanning 2, so: 80 and 3.
//
// The coarse one is the workhorse, which reads as the wrong way round until you
// count texels. At 3 cycles its cells are a third of the pool, and seven octaves
// carry it down to about four of them — so it alone spans everything from a bank
// drifting through to the fray on a single billow. The fine one is grain: its
// base cell is a hundredth of the pool and its finest is well under a texel, and
// its job is to give advection something to stretch, not to be seen.
// The two stirring rates are the one place the conversion bites twice, and
// getting it wrong is invisible in the arithmetic and obvious on screen. The
// original ADDS 0.2·noise to a velocity already measured per frame, so it is an
// acceleration: fields per second, per second. Both 60s apply — one for the
// velocity's own unit and one for the rate at which it is handed out. Convert it
// as a velocity, the way it reads, and the fluid comes out sixty times too
// slack; it still churns, because the noise fields keep moving underneath it,
// which is exactly what makes the mistake survive a look.
// Sized against the FOG'S DEPTH, not the pool's width. The original's coarse
// cells are a third of its field, which is 2.8 times its fog depth — hold that
// ratio and the billows stay billow-shaped at any pool size. Held to a share of
// the span instead, this pool's cells would be 53 units across against a fog 7
// deep, and a lump eight times wider than it is tall does not read as a billow,
// it reads as a hill.
const PUFF = SIM_SPAN / (HEIGHT * 2.8);   // ≈ 8 cycles across the pool
const PUFF_HZ = 0.05;

const PUFF_D = 2.40;      // 0.04 /frame
const PUFF_OCT = 7;
// The fine field is GRAIN, and its octaves stop at the texel on purpose.
//
// The original runs seven here too, and at its resolution the bottom four are
// sub-pixel and read as film grain. On this grid they are sub-TEXEL, which is a
// different thing entirely: a sub-texel octave cannot be advected, because every
// frame re-randomises it rather than carrying it, so it is not grain that flows
// — it is fresh white noise stirred into density sixty times a second, and it
// lands on screen as wet sand poured over the fog. Three octaves puts the
// finest at about a texel and stops.
const WISP = PUFF * 26.7;   // the original's 40-to-1.5 ratio
const WISP_HZ = 0.25;
const WISP_V = 2.50;      // 0.2 px added per frame → fields/s per second
const WISP_D = 0.60;      // 0.01 /frame — a density, so only one 60
const WISP_OCT = 3;
// How hard the whole thing is stirred, against the original's own figures above.
//
// Theirs is a shadertoy: a field two units wide that the eye takes in at once,
// where fog crossing it in six seconds reads as lively. The same number over a
// stage is the pool sliding past at 26 units a second, which is faster than the
// dancer can run. Dry ice creeps.
const FLOW = 0.20;
const DECAY = 0.60;       // ×0.99 a frame is exp(-0.6·t)
// The rim, and it is the original's screen vignette rather than an invention:
// density and velocity are multiplied by 0.98 at the border of the buffer and by
// 1.0 at its centre, every frame. Two percent is nothing per frame and
// everything in the steady state — it is what makes the fog a POOL with a soft
// edge instead of a square that stops. Measured radially here, because a square
// grid faded on a square profile announces its own corners.
const EDGE = 1.2;         // ×0.98 a frame
// And then an actual END, which the original has no need of: its buffer edge IS
// its floor slab's edge, so the straight cut where its fog stops is hidden by
// the scenery. This pool lies on a floor of the user's own size, so it has to
// run out on its own — inside the grid, and before any corner of it can show.
// A radius in field widths, frayed so the boundary is not a circle somebody
// drew. The fray stays SMALL on purpose: the coarse field has three cycles
// across the pool, so a large one would not fray the rim, it would give the pool
// three lobes and turn it into a shape.
const EDGE_FRAY = 0.05;
const EDGE_FADE = 0.16;
// ── Her feet ──
//
// The original's spheres do three things, and only the first is obvious: they
// SUBTRACT density (a hole is a hole, not fog pushed aside), they hand the fluid
// a little of their own motion, and they do it whether they are moving or not.
const KICK_CLEAR = 9.0;   // 0.15 /frame at the centre of the reach
// How fast fog under a sole is brought up to the sole's own speed — a rate, so
// half a second of contact gets it most of the way there. The original writes
// this as `velocity -= ballVelocity * 5` per frame, which reads like a hard
// shove and converts to 2.1 a second, because the 5 multiplies a PER-FRAME
// displacement before landing in a per-frame velocity.
const KICK_DRAG = 2.1;
// How far below 足首 the sole is. The bone sits at the ankle, and the height that
// decides whether a foot is in the fog is the sole's.
const FOOT_DROP = 1.3;
const FOOT_SOFT = 1.5;    // and over what height the reach fades out

// ── The picture (Image) ──────────────────────────────────────────────────────
//
// A volume march, and at every step of it a second march toward the light. What
// this accumulates is scattered light and transmittance; there is no surface and
// no normal anywhere in it. That is the whole reason the original's fog has
// depth — you are seeing INTO it, and the dark is fog standing in the lee of
// fog, which is a fact about the neighbourhood and not about the slope underfoot.
const SLICES = 24;            // the original's nbSlice, exactly
const SHADOW_SLICES = 12;     // half of it, at twice the stride — same path
// Optical depth through the FULL height: fogDensity 20 and shadowDensity 25 over
// a fog 0.24 deep. Stated as the product so they survive a change to HEIGHT.
const FOG_DENSITY = 4.8;
const SHADOW_DENSITY = 6.0;
// ONE POINT LIGHT, hanging over the cast, and this is the composition of the
// original: a lamp above the emitter, everything falling off as 1/d² around it.
// The pool is bright where she is and sinks toward black at its edges, billows
// throw shadows that lengthen outward, and none of that is available to a
// directional light — which is what the previous version used, and why its fog
// read as one flat grey sheet however much relief was in the field.
//
// Bounded by construction: the lamp hangs half a pool-width above the floor, so
// d² never approaches zero and the 1/d² never blows up.
const AMBIENT = 0.0;          // the original gives shadowed fog nothing at all
const MAX_FOG = 1.0;          // and lets it close over the emitters completely
const MIN_SLOPE = 0.12;       // flattest ray the march will step along; the
                              // original refuses anything flatter outright, and
                              // a dance camera is flatter than that most of the
                              // time, so it is clamped rather than rejected

/**
 * SINE-FREE, and it has to be.
 *
 * The usual sine hash works beautifully near the origin and falls apart away
 * from it: a float32 sine of a six-figure argument has no meaningful fractional
 * part left, and the hash stops being random and becomes an interference
 * pattern — concentric rings and oil-slick swirls sliding under everything. The
 * original has exactly that (its `fract(sin(h)*43758.5)` at seven octaves), and
 * at its resolution the artefact is sub-pixel and reads as grain.
 */
fn dfHash(p: vec3f) -> f32 {
  var q = fract(p * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

fn dfNoise(p: vec3f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(mix(dfHash(i), dfHash(i + vec3f(1.0, 0.0, 0.0)), u.x),
              mix(dfHash(i + vec3f(0.0, 1.0, 0.0)), dfHash(i + vec3f(1.0, 1.0, 0.0)), u.x), u.y);
  let b = mix(mix(dfHash(i + vec3f(0.0, 0.0, 1.0)), dfHash(i + vec3f(1.0, 0.0, 1.0)), u.x),
              mix(dfHash(i + vec3f(0.0, 1.0, 1.0)), dfHash(i + vec3f(1.0, 1.0, 1.0)), u.x), u.y);
  return mix(a, b, u.z);
}

/**
 * TWO channels out of one walk, which is the original's `fbm` and is not a
 * saving. A vec2 of noise is a DIRECTION to push in; a scalar could only ever
 * have been a strength, and a field stirred by a scalar has no curl in it.
 *
 * Time doubles with space, octave by octave, exactly as the original's
 * `p = p*2.0 + shift` does to all three components — so every octave drifts at
 * the same rate measured in its own cells, and the field boils self-similarly
 * instead of having one scale crawl while another flickers. Capped at 8× so the
 * argument stays inside float32's useful range over a long take; past that the
 * octaves are well under a texel and their rate cannot be seen anyway.
 */
fn dfFbm2(p: vec2f, t: f32, octaves: i32) -> vec2f {
  var acc = vec2f(0.0);
  var amp = 0.5;
  var total = 0.0;
  var q = p;
  var tz = t;
  for (var i = 0; i < octaves; i++) {
    acc += vec2f(dfNoise(vec3f(q, tz)), dfNoise(vec3f(q, tz + 10.0))) * amp;
    total += amp;
    q = q * 2.0 + vec2f(100.0);
    tz = select(tz, tz * 2.0, i < 3) + 100.0;
    amp *= 0.5;
  }
  // Centred on its OWN mean, where the original subtracts a flat 0.5.
  //
  // An fbm of k octaves averages 0.5·(1 - 2⁻ᵏ), not 0.5, so subtracting 0.5
  // leaves every sample biased low by the same amount everywhere — and a
  // constant added to a VELOCITY field every frame is a wind. Nothing removes
  // it either: the pressure solve only takes out what has divergence, and a
  // uniform flow has none. At seven octaves the bias is 0.4% and the original
  // rides it (it is a good half of where its steady drift comes from); at the
  // four this file wants for the grain it would be 3%, and the pool would simply
  // sail off downwind. Centring it properly makes the octave count free, and
  // leaves the drift to FLOW, where it can be read.
  return acc - vec2f(0.5 * total);
}

/** Grid uv to world x/z, and back. The engine imposes no mapping — this is it. */
fn dfWorld(uv: vec2f) -> vec2f { return SIM_AT + (uv - vec2f(0.5)) * SIM_SPAN; }
fn dfUV(xz: vec2f) -> vec2f { return (xz - SIM_AT) / SIM_SPAN + vec2f(0.5); }

/**
 * The field with the pressure gradient already taken out of it — the original's
 * `sampleMinusGradient`, and the one line the previous port dropped.
 *
 * It matters where it is CALLED, not just that it exists. Advection reads
 * through this at the point the parcel came FROM, so what gets carried forward
 * and stored is the corrected velocity. Reading the raw field there instead —
 * and correcting only the direction of the backtrace, which is the natural
 * mistake — leaves the divergent half of the flow in the grid permanently. The
 * solve then spends every frame fighting a component that never leaves, the
 * pressure climbs without bound, and the fluid never circulates.
 */
fn dfMinusGrad(uv: vec2f, te: f32) -> vec3f {
  let c = rzGridPrev(uv);
  let l = rzGridPrev(uv - vec2f(te, 0.0)).w;
  let r = rzGridPrev(uv + vec2f(te, 0.0)).w;
  let d = rzGridPrev(uv - vec2f(0.0, te)).w;
  let u = rzGridPrev(uv + vec2f(0.0, te)).w;
  return vec3f(c.xy - vec2f(r - l, u - d) * 0.5, c.z);
}

fn gridStep(uv: vec2f, prev: vec4f, dt: f32) -> vec4f {
  // Starts EMPTY. There is nothing to seed: injection fills the pool within a
  // couple of seconds and then never stops, and what you look at is the balance
  // between that and the decay, not a bank that was placed there.
  if (rzGridFrame() == 0) { return vec4f(0.0); }

  let te = rzGridTexel();
  let t = rzTime();
  let sL = rzGridPrev(uv - vec2f(te, 0.0));
  let sR = rzGridPrev(uv + vec2f(te, 0.0));
  let sD = rzGridPrev(uv - vec2f(0.0, te));
  let sU = rzGridPrev(uv + vec2f(0.0, te));

  // ── Project, then advect backwards, both through dfMinusGrad ──
  let here = prev.xy - vec2f(sR.w - sL.w, sU.w - sD.w) * 0.5;
  let carried = dfMinusGrad(uv - here * (dt * params.ADVECT), te);
  var vel = carried.xy;
  var density = carried.z;

  // ── Injection, two scales, into velocity AND density ──
  //
  // Raw fbm, not its curl. Curl noise is divergence-free by construction and
  // looks like the obvious improvement — it is how the previous port avoided
  // needing a real solve — but it also means every eddy is one the noise
  // function decided on. Half of what goes in here is divergent, and the
  // pressure solve is what turns that half into circulation that answers to the
  // fog already present: fluid piling into a bank has to go somewhere, and where
  // it goes is around.
  let wispN = dfFbm2(uv * WISP, t * WISP_HZ, WISP_OCT);
  let puffN = dfFbm2(uv * PUFF, t * PUFF_HZ, PUFF_OCT);
  vel += (wispN * WISP_V + puffN * params.PUFF_V) * (FLOW * dt);

  // WHERE fog is made — the end of the pool, applied to the INJECTION and not as
  // one more decay. A mask multiplied into density every frame compounds: it
  // lands in the steady state as inject/(1 - keep·mask), so halving it does not
  // halve the fog, it divides it by fifty. Injecting nothing past the brink just
  // means no fog is made there, which is the thing that was meant.
  // Written as 1 - smoothstep and not as smoothstep with its edges swapped:
  // WGSL leaves smoothstep undefined when low >= high, and it is the kind of
  // undefined that works on the machine you wrote it on.
  let brink = 0.5 + EDGE_FRAY * puffN.x;
  let made = 1.0 - smoothstep(brink - EDGE_FADE, brink, length(uv - vec2f(0.5)));
  density += (length(wispN) * WISP_D + length(puffN) * PUFF_D) * (dt * made);

  // ── Her feet ──
  let world = dfWorld(uv);
  for (var c = 0; c < rzSubjectCount(); c++) {
    for (var slot = 0; slot < 2; slot++) {
      let foot = rzAnchor(c, slot);
      if (!foot.valid) { continue; }
      let dist = distance(world, foot.pos.xz);
      if (dist > params.KICK_R) { continue; }
      // IS THE SOLE IN THE FOG. The original never asks, because its emitters
      // roll on the floor and cannot be anywhere else; a dancer's foot spends
      // half its time in the air, and without this a kick thrown at head height
      // carves the floor as readily as a step does. Measured against the LOCAL
      // fog top, so a sole clears deep bank and passes over a thin patch
      // untouched.
      let immersion = clamp(
        ((FLOOR_Y + density * HEIGHT) - (foot.pos.y - FOOT_DROP)) / FOOT_SOFT, 0.0, 1.0);
      if (immersion <= 0.0) { continue; }
      let f = (params.KICK_R - dist) / params.KICK_R * immersion;
      density -= f * (KICK_CLEAR * dt);
      vel = mix(vel, foot.vel.xz / SIM_SPAN, clamp(f * KICK_DRAG * dt, 0.0, 1.0));
    }
  }

  density = clamp(density, 0.0, 1.0);

  // ── Decay, and the rim ──
  //
  // The decay is DENSITY'S ALONE. Velocity is damped by nothing here and nothing
  // anywhere else — the original never damps it either, and what bounds it is
  // the projection above plus the 5% the backtrace falls short. Handing velocity
  // the density's decay as well is the quiet way to kill this effect: the fluid
  // then loses in half a second whatever circulation it built, everything reads
  // as blobs drifting, and the field looks noise-driven because effectively it is.
  let off = uv - vec2f(0.5);
  let bowl = clamp(1.0 - dot(off, off) * 4.0, 0.0, 1.0);  // 1 at the centre, 0 at the rim
  let rim = exp(-EDGE * (1.0 - bowl) * dt);
  density *= exp(-DECAY * dt) * rim;
  vel *= rim;

  // ── One Jacobi sweep toward incompressible ──
  //
  // The original spends about twenty of these a frame, spread over three buffers
  // and a pair of hand-generated 121-tap kernels that are ten sweeps each. One
  // sweep here, over a grid that keeps its pressure between frames, is sixty a
  // second chasing a field that turns over in one — the same destination,
  // several frames behind.
  //
  // Full step, not the half step the previous version took. Under-relaxation was
  // put in to damp a texel-scale checkerboard, which it does by damping
  // everything; the checkerboard was the pressure field growing without bound
  // against divergence that advection was quietly putting back every frame, and
  // that is fixed above, at its cause.
  let divergence = ((sR.x - sL.x) + (sU.y - sD.y)) * 0.5;
  let pressure = (sL.w + sR.w + sD.w + sU.w - divergence) * 0.25;

  return vec4f(vel, density, pressure);
}

/** The top of the fog over a point of floor, in world units. Flat off the pool. */
fn dfFogTop(xz: vec2f) -> f32 {
  let g = dfUV(xz);
  if (g.x < 0.0 || g.x > 1.0 || g.y < 0.0 || g.y > 1.0) { return FLOOR_Y; }
  return FLOOR_Y + rzGrid(g).z * HEIGHT;
}

/**
 * How much of the lamp reaches a point inside the fog — the original's inner
 * loop, and the entire reason the picture has shape in it.
 *
 * Steps rise by one shadow slice each, so the march clears the full depth in
 * SHADOW_SLICES of them however shallow the light lies. Sizing the step by the
 * VIEW slice instead and then taking fewer of them, which is what the previous
 * version did, marches a third of the way up and stops: everything comes back
 * barely shadowed, and the fog renders flat.
 */
fn dfShadow(pos: vec3f, lamp: vec3f, jitter: f32) -> f32 {
  let toLamp = lamp - pos;
  let dist2 = dot(toLamp, toLamp);
  let L = toLamp / sqrt(dist2);
  let rise = HEIGHT / f32(SHADOW_SLICES);
  let step = L * (rise / max(L.y, 0.15));
  let per = length(step) / rise;
  var p = pos + step * jitter;
  var through = 0.0;
  for (var i = 0; i < SHADOW_SLICES; i++) {
    p += step;
    if (p.y > FLOOR_Y + HEIGHT) { break; }
    through += clamp(dfFogTop(p.xz) - p.y, 0.0, rise) * per;
  }
  // 1/d², normalised so the floor directly under the lamp reads exactly 1 — the
  // original's `/lightDist2` with its light one unit up over a field of two.
  return exp(-through * (SHADOW_DENSITY / HEIGHT)) * (LIGHT_Y * LIGHT_Y / dist2);
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let ro = rzCameraPos();
  let tScene = depth / max(dot(ray, rzCameraForward()), 1e-3);
  let top = FLOOR_Y + HEIGHT;

  // Enter at the top of the slab, or at the lens when it is already inside.
  var t0 = 0.0;
  if (ro.y > top) {
    if (ray.y > -1e-4) { return vec4f(0.0); }
    t0 = (top - ro.y) / ray.y;
  }
  if (t0 >= tScene) { return vec4f(0.0); }

  // The lamp rides over the cast, as the original's rides over its white ball.
  var lamp = vec3f(SIM_AT.x, LIGHT_Y, SIM_AT.y);
  if (rzSubjectCount() > 0) {
    let hip = rzSubjectHip(0);
    lamp = vec3f(hip.x, LIGHT_Y, hip.z);
  }

  let slice = HEIGHT / f32(SLICES);
  // One slice of RISE per step, so the march covers the depth in SLICES samples
  // however steep the ray is.
  let stepV = slice / max(abs(ray.y), MIN_SLOPE);
  // Jittered, as the original's `fudge` is — a march this coarse lays down
  // visible contour rings without it. Seeded on the PIXEL, which is what
  // `hash12(fragCoord + iTime)` is: seeding on uv scaled by a round number
  // instead leaves neighbouring pixels a fraction apart in the hash's input,
  // which is where a dither stops being a dither. fract keeps it bounded over a
  // long take.
  //
  // HALF a step of it, not the original's whole one. It has more slices and
  // fewer pixels to spread the noise across; at full resolution a whole step of
  // white noise, feeding the shadow march as well as this one, is a speckle over
  // the entire fog rather than a dither along its contours. Half still breaks
  // the rings.
  let jitter = 0.25 + 0.5 * dfHash(vec3f(uv * rzResolution(), fract(time * 7.0)));

  var trans = 1.0;
  var lit = 0.0;
  for (var i = 0; i < SLICES; i++) {
    let t = t0 + (f32(i) + jitter) * stepV;
    if (t > tScene) { break; }
    let p = ro + ray * t;
    if (p.y < FLOOR_Y - slice) { break; }
    let below = dfFogTop(p.xz) - p.y;
    if (below <= 0.0) { continue; }
    // Clamped at one slice, as the original clamps: a sample stands for the fog
    // in ITS slice, not for everything underneath it.
    let dens = min(below, slice) * (stepV / slice) * (FOG_DENSITY / HEIGHT);
    if (dens <= 0.001) { continue; }
    // Beer–Lambert, where the original writes `transmittance *= 1 - density`.
    // That linear form is this one's small-step approximation and is fine at its
    // step sizes; a grazing ray here carries a density past 1 in a single step,
    // and the linear form then returns a NEGATIVE transmittance and the
    // accumulation comes apart.
    let a = 1.0 - exp(-dens);
    lit += (AMBIENT + dfShadow(p, lamp, jitter)) * a * trans;
    trans *= 1.0 - a;
    if (trans < 0.02) { break; }
  }

  let alpha = clamp(1.0 - trans, 0.0, MAX_FOG);
  if (alpha <= 0.004) { return vec4f(0.0); }
  // The colour IS the scattered light, greyscale, with no tint anywhere: dry ice
  // is water vapour, it has no colour of its own, and the only hue it can show
  // is the lamp's. Divided by coverage because this returns a straight-alpha
  // layer — the original folds the two together and its thin fog comes out
  // darker than it should for it.
  //
  // sqrt is the original's own `sqrt(tot)`: the march accumulates a linear
  // radiance and this mount hands back display-space sRGB. Without it the fog
  // arrives about half as bright as the picture it came from.
  let energy = clamp(lit / alpha, 0.0, 1.0);
  return vec4f(vec3f(sqrt(energy)), alpha);
}

#layer additive

#param float FALL 2.2 0.3 8 — seconds of music visible above the line
#param float DUR_MAX 4 0.5 12

// Note Fall — the score falling onto a keyboard, behind the cast.
//
// Reads the installed MIDI through rzNote*. With no score loaded it draws the
// line alone and nothing falls, which is a scene waiting for a file rather than
// an error.
//
// A BACKGROUND, not particles. An early version put quads in the scene pass in
// front of the character and they cut across her legs; a background sits behind
// everything by construction, so the cast reads clean and the notes are light
// behind her rather than debris in front. Additive for the same reason — this is
// light, so it adds to whatever backdrop the scene already has.
//
// AND FULL RESOLUTION, which is not the default. The field layer runs at half
// res and upsamples, because field effects are fog and shafts and gradients —
// low-frequency things a bilinear stretch cannot hurt. This is the exception
// the flag exists for: crisp bar edges, key seams and single-pixel glints are
// exactly the detail an upsample destroys.
//
// THE ROLL IS A TIME AXIS DRAWN VERTICALLY. That is the one idea the geometry
// hangs from: height above the line IS time ahead of now, at (uv.y - LINE_Y) /
// speed. So a bar's length is its DURATION times the fall speed — not a
// separate size dial — and the bar covers a pixel exactly when its note is
// sounding at the moment that pixel stands for. An earlier version scaled
// length by an unrelated constant, which made every bar 3.5x too short and then
// clipped 13% of the piece flat on top of that.
//
// The same idea decides what happens at the line: the bar is EATEN by it. The
// bottom edge arrives at note-on and the top edge at note-off, so what is left
// above the line is exactly what is left to sound. No separate collapse
// animation, and a held note stays visible for as long as you hear it.
//
// HOW A FULLSCREEN PASS AFFORDS THIS. Notes are sorted by onset, so a pixel
// binary-searches for its own band instead of scanning. An earlier version
// walked a fixed 28 notes from t - TAIL, which is fine for the average of six
// notes a second and badly wrong for a piano, where a chord puts six notes on
// ONE instant: the 28 were used up by the oldest and the newest were never
// reached, so falling notes vanished and popped back as the window slid. It
// read as bad sync; it was dropped geometry. The band below is derived, and
// WINDOW is sized from the real file — see it.
//
// The glow is mafik's trick from the Waveform effect: brightness as 1/distance
// rather than a smoothstep. A soft edge gives a flat sticker; a reciprocal
// gives a thin hot core inside a wide falloff, which is what reads as emissive
// once bloom picks it up.

// Tunables — every const below is one, grouped by what it shapes. Edit and ⌘⏎.
// ── Layout ──────────────────────────────────────────────────────────────────
const LINE_Y: f32 = 0.20;      // the strike line, 0 = bottom of frame

const KEYS_LO: f32 = 0.06;     // keyboard margins across the frame
const KEYS_HI: f32 = 0.94;

/**
 * Longest and shortest a note may DRAW as, in seconds.
 *
 * params.DUR_MAX is a cost bound, not a look: the per-pixel search band is exactly
 * this wide (a pixel must reach back far enough to find any note still
 * sounding), so it sets WINDOW. Measured against the Reze arc transcription:
 * durations run p50 0.26s, p90 0.41s, p99 3.97s, max 8.61s — the shape of a
 * piece that is fast runs over long pedalled bass. Four seconds clips 16 of
 * 1562 notes, one percent, and those keep their key lit for the true length
 * anyway. DUR_MIN keeps a staccato note from drawing as nothing.
 */

const DUR_MIN: f32 = 0.06;

/** Notes considered per pixel. The band is params.DUR_MAX + SPARK_LIFE + 2*PAD/speed,
 *  about 4.9s, and the densest 5.0s of the real file holds 72 onsets. 80 is
 *  that with headroom; past it a note is simply not drawn, which is a ceiling
 *  on cost rather than an error. */
const WINDOW: i32 = 80;

// ── The keyboard ────────────────────────────────────────────────────────────
// Laid out as a piano actually is — whites of equal width, blacks narrower and
// sitting ON the seam between two of them — rather than a slot per semitone.
// Both mappings put a note somewhere sensible; only this one lets you read WHICH
// note, because the eye finds a pitch by counting the black-key groups of two
// and three, and a uniform semitone grid destroys that grouping. keyX below is
// the single mapping for notes AND keys, so the two cannot disagree.
const KEY_TOP: f32 = LINE_Y - 0.004;   // the keys start where the line is, so a
                                       // note lands ON the keyboard rather than
                                       // stopping short of it
const KEY_H: f32 = 0.115;              // white key length
const BLACK_H: f32 = 0.072;
const KEY_GAP: f32 = 0.0013;           // the seam, in screen widths. Additive light
                                       // cannot draw a dark line, so the seam is
                                       // simply where no key is drawn.
// The keyboard is ALWAYS there and reads as a keyboard: bright whites, dark
// blacks. A press then shifts the key to blue rather than lighting it up.
//
// That direction is the point. The first version drew every key dim and lit the
// struck one, which is backwards from every piano and every roll app: on a real
// keyboard the white keys are the bright thing, so a bright key reads as the
// DEFAULT and a dark one as pressed. This layer is additive and cannot subtract
// light, so "darker" has to be spent on hue — blue is both unmistakably
// different and lower in luminance than ivory, which is exactly the read wanted.
// A press DIMS the key, as a real one falls into its own shadow. Additive light
// cannot darken what is behind it, but a key's colour IS what this layer emits,
// so emitting less is a real dim rather than a trick — and it costs no hue,
// which is what the coloured version spent and did not need.
//
// Black keys go the other way by necessity: dimming something already at 0.05
// is invisible. They lift to the same dark grey the whites fall to, so a
// pressed key of either kind reads as the same state.
const KEY_IVORY = vec3f(0.72, 0.78, 0.88);    // an unpressed white key
const KEY_EBONY = vec3f(0.045, 0.055, 0.080); // and an unpressed black one
const KEY_PRESS = vec3f(0.20, 0.23, 0.30);    // a pressed white, in shadow
const KEY_PRESS_B = vec3f(0.14, 0.16, 0.21);  // a pressed black, just readable
const KEY_SHADE: f32 = 0.82;           // how much the back of a key falls off,
                                       // so the keys have a face and not just
                                       // a fill

/**
 * A key shows a STRIKE, not a hold.
 *
 * rzKeyEnergy holds at a flat 1.0 for as long as a note sounds, which is right
 * for the fog and glow effects it was built for and wrong here: this piece
 * holds notes for 4.6 and 8.6 seconds, so a key lit from it simply stays
 * glaring after the music has moved on. So the bright part is a short flash
 * from the note list, and rzKeyEnergy only contributes a low sustain — which is
 * also what a struck piano string actually does.
 */
const KEY_FLASH: f32 = 0.45;      // seconds the strike takes to fade
const KEY_FLASH_GAIN: f32 = 1.6;
const KEY_SUSTAIN: f32 = 0.34;    // how much a merely-held key keeps

// ── Bars ────────────────────────────────────────────────────────────────────
// Lengths are in units of screen HEIGHT on BOTH axes — x is divided by aspect
// before use. Mixing raw uv.x with uv.y was why bars read as slabs: on a 16:9
// frame the same number is 1.8x wider than it is tall, and the round glow came
// out an ellipse.
//
// WIDTH is the exception: a fraction of a white key rather than a fixed number,
// so a two-octave piece and a seven-octave one both get bars that sit on their
// keys instead of swamping them or vanishing between them.
const BAR_FILL: f32 = 0.17;    // half-width, as a fraction of a white slot
const BAR_FILL_B: f32 = 0.12;  // black-key notes are narrower, as their keys are
// The GLOW is what made neighbouring notes touch, not the box. At forty white
// keys a slot is about 42px, and the old halo reached 11px past a 26px box —
// 48px of ink in a 42px slot, so adjacent notes overlapped however narrow the
// box got. Both falloffs are now tight enough that the ink stays inside its key.
const BAR_SHARP: f32 = 220000.0; // core falloff — half brightness ~2.4px out
const BAR_HALO: f32 = 340.0;   // and the wider one, ~3px
const BAR_HALO_W: f32 = 0.12;  // how much of the halo to mix in
const PAD: f32 = 0.035;        // how far a bar's glow reaches past its edge.
                               // The search band is derived from this, so
                               // widening the glow without widening PAD clips it.

const CORE = vec3f(0.86, 0.95, 1.00);   // white, faintly cold
const GLOW = vec3f(0.14, 0.42, 1.00);   // the blue that carries the falloff

// ── The line ────────────────────────────────────────────────────────────────
// Matched to Waveform's weight deliberately. Waveform composes twenty copies of
// 1/(200*p.y) over [-1,1] at a 1.9 tint, which works out near 1/(400*dy) at
// several times this gain; an earlier version used 1/(620*dy) at 0.5, about
// thirty times dimmer, and read as a hairline.
const LINE_TINT = vec3f(0.50, 0.80, 1.00);
const LINE_SHARP: f32 = 800.0; // the CORE: higher is thinner
const LINE_GAIN: f32 = 1.5;
const LINE_CAP: f32 = 4.0;     // the reciprocal is unbounded at dy = 0
// …and a second, much wider falloff around it. One reciprocal cannot be both
// thin and glowing — its width and its reach are the same number — so thinning
// the core kept costing the glow. Two terms separate the questions: SHARP is
// how thin the filament is, HALO is how far the light carries.
const LINE_HALO: f32 = 55.0;
const LINE_HALO_W: f32 = 0.42;
/** Past this far from the line, in screen heights, it contributes nothing worth
 *  a twenty-four-key sample — so pixels beyond it skip lineY entirely. At the
 *  edge the wide falloff is under 0.03, below what bloom can lift. */
const LINE_REACH: f32 = 0.30;

// The line is the surface notes land ON, so it has to read as level. It bends
// where keys sound, but only just: the bend is per-key and SUMS across the
// sampled pitches, so a chord with a wide voicing stacked several of them and
// swung the whole line into a wave taller than the bars falling onto it.
// RIPPLE_MAX caps the total, which keeps a dense passage a disturbed surface
// rather than a different shape.
// Barely anything. The line is the surface notes land ON, so it has to read as
// level — a visible swell on every hit made it the loudest thing in the frame
// and turned the strike into an event the line was having rather than one the
// note was. What is left is a flicker of life at the point of contact.
const RIPPLE: f32 = 0.0015;    // how far one struck key bends the line
const RIPPLE_MAX: f32 = 0.003; // ceiling on the total bend, however many sound
const RIPPLE_W: f32 = 0.085;   // how wide that bend reaches, in screen widths
const FLOW: f32 = 0.55;        // idle drift, so the line breathes when silent

// ── Impact ──────────────────────────────────────────────────────────────────
// A burst, not a puff: twelve glints fanned across the half-circle rather than
// five thrown at random angles, each its own size and speed. Uniform dots at
// random angles read as a handful of copies of one sprite; a fan with varied
// size reads as something breaking apart.
const SPARK_LIFE: f32 = 0.7;
const SPARK_N: i32 = 24;
const SPARK_REACH: f32 = 0.22;  // how far a glint travels. This is the size dial
                                // for the whole burst; SPARK_TOP below is
                                // derived from it and has to follow it up.
const SPARK_RISE: f32 = 1.3;    // how much of that goes upward
const SPARK_GRAV: f32 = 0.12;   // and what pulls it back
const SPARK_SHARP: f32 = 600000.0; // per-glint tightness — ~1.4px, which only
                                   // resolves at all because of @fullres
const SPARK_GAIN: f32 = 0.95;
/** The highest a glint gets, and how far below the line one may dip. Bounds the
 *  block so a pixel outside it does not pay twenty-four iterations to learn
 *  that, so it must stay at or above the arc's real apex: with the constants
 *  above the peak works out near 0.26. */
const SPARK_TOP: f32 = 0.30;
const SPARK_DIP: f32 = 0.03;

// ── Piano geometry ──────────────────────────────────────────────────────────
// Closed forms rather than lookup tables: WGSL cannot index a const array with
// a runtime value, and a var<private> table would be state this needs none of.

/** White keys below this semitone class, within its octave. The 7-in-12 pattern
 *  C D E F G A B, as arithmetic — verified for all twelve classes. */
fn whiteInOctave(c: i32) -> i32 { return (c * 7 + 6) / 12; }

/** Is this semitone class one of the five black keys? Below E the black ones
 *  are odd, from F up they are even — which is exactly the seam in the pattern
 *  that makes the groups of two and three. */
fn isBlackClass(c: i32) -> bool { return select(c % 2 == 1, c % 2 == 0, c >= 5); }

/** How many white keys sit below this pitch on a full keyboard. A black key
 *  shares the ordinal of the white ABOVE it, which is what places it on the
 *  seam between two whites instead of in a slot of its own. */
fn whiteOrd(p: i32) -> i32 { return 7 * (p / 12) + whiteInOctave(p % 12); }

/** The pitch of the nth white key — whiteOrd inverted over the whites. */
fn pitchOfWhiteOrd(n: i32) -> i32 { return 12 * (n / 7) + (12 * (n % 7) + 5) / 7; }

/** White ordinal of the score's lowest pitch: the keyboard's left edge.
 *
 *  One white LOWER when that lowest note is itself black. A black key sits on
 *  the seam below the white it shares an ordinal with, so without this it lands
 *  at seam index 0 — the frame's left edge, where there is no white beneath it
 *  and the drawing code skips it. Its bars would then fall on a key that was
 *  never drawn. */
fn kbLowOrd() -> i32 {
  let lo = i32(round(rzPitchLow()));
  return whiteOrd(lo) - select(0, 1, isBlackClass(lo % 12));
}

/** White keys the score spans. The keyboard is the PIECE's range, not 0..127 —
 *  a piece that never leaves two octaves fills the width instead of huddling in
 *  the middle of an 88-key drawing that is mostly empty. */
fn kbWhites() -> i32 {
  return max(whiteOrd(i32(round(rzPitchHigh()))) - kbLowOrd() + 1, 1);
}

/** Width of one white key, in screen widths. */
fn kbKeyW() -> f32 { return (KEYS_HI - KEYS_LO) / f32(kbWhites()); }

/**
 * x of a pitch: the centre of its white key, or the seam its black key sits on.
 * The one mapping a falling note and its key both go through.
 *
 * ord0 and kw are passed IN, not looked up. They used to be read here through
 * kbLowOrd()/kbKeyW(), which is correct and was costing the whole effect: each
 * of those does integer division and reads the score header, and this function
 * is called about a hundred times per pixel — twenty-four by the line and up to
 * eighty by the note loop. Integer division is among the slowest things a GPU
 * does, so that worked out at several hundred divides on every pixel of a
 * full-resolution frame, and the field pass measured 23.8ms. They are loop
 * invariants; hoisting them to the caller is the whole fix.
 */
fn keyX(pitch: f32, ord0: i32, kw: f32) -> f32 {
  let p = i32(round(pitch));
  let n = f32(whiteOrd(p) - ord0);
  let off = select(0.5, 0.0, isBlackClass(p % 12));
  return KEYS_LO + (n + off) * kw;
}

/** Signed distance to a rounded box — the bar's shape before it becomes light. */
fn boxSdf(p: vec2f, half: vec2f, r: f32) -> f32 {
  let q = abs(p) - half + vec2f(r);
  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - r;
}

/** First note whose onset is at or after t, by binary search over the sorted
 *  score. Returns the count when every note is earlier. */
fn firstAfter(t: f32) -> i32 {
  var lo = 0;
  var hi = rzNoteCount();
  // 16 halvings covers 65536 notes. WGSL cannot see that hi - lo shrinks, so
  // the bound has to be written out; too FEW iterations does not fail loudly,
  // it returns a wrong index and puts notes at wrong times.
  for (var k = 0; k < 16; k = k + 1) {
    if (lo >= hi) { break; }
    let mid = (lo + hi) / 2;
    if (rzNoteStart(mid) < t) { lo = mid + 1; } else { hi = mid; }
  }
  return lo;
}

/** How hard this key was struck in the last KEY_FLASH seconds — see KEY_FLASH.
 *  A narrow scan: only onsets in that window can matter, and the keyboard is a
 *  thin strip of the frame, so this is far cheaper than it looks. */
fn strikeAt(pitch: i32, t: f32) -> f32 {
  let count = rzNoteCount();
  // Not named 'from': that is a WGSL reserved keyword, and the compiler reports
  // it as a syntax error at the USE site rather than as a bad declaration.
  let head = firstAfter(t - KEY_FLASH);
  var v = 0.0;
  // 32, not 24: this walks EVERY onset in the flash window, not just the ones
  // on this key, so a chord-heavy passage exhausts it quickly — and running out
  // does not fail, it silently leaves a key dark while its note falls past.
  for (var k = 0; k < 32; k = k + 1) {
    let i = head + k;
    if (i >= count) { break; }
    let age = t - rzNoteStart(i);
    if (age < 0.0) { break; }     // sorted, so nothing after this has sounded
    if (i32(round(rzNotePitch(i))) == pitch) { v = max(v, 1.0 - age / KEY_FLASH); }
  }
  return v;
}

/** How pressed a key looks, 0..1 — a strike that fades, plus a low sustain
 *  while the note is still held. Saturated, so a struck key goes fully over to
 *  the pressed colour and then returns. */
fn pressAt(pitch: i32, t: f32) -> f32 {
  return clamp(KEY_SUSTAIN * rzKeyEnergy(f32(pitch)) + KEY_FLASH_GAIN * strikeAt(pitch, t), 0.0, 1.0);
}

/** The keyboard under the line: which note is which, and which were just hit. */
/**
 * A key, and whether this pixel is ON one.
 *
 * The w is COVERAGE, not brightness. An ebony key is nearly black and entirely
 * opaque, and those two facts have to travel separately: derive one from the
 * other and the black keys ask to be see-through, which is exactly what they do
 * over a backdrop.
 */
fn keyboard(uv: vec2f, t: f32) -> vec4f {
  if (uv.y > KEY_TOP || uv.y < KEY_TOP - KEY_H) { return vec4f(0.0); }
  let nW = kbWhites();
  let ord0 = kbLowOrd();
  let kw = kbKeyW();
  let wf = (uv.x - KEYS_LO) / kw;
  if (wf < 0.0 || wf >= f32(nW)) { return vec4f(0.0); }

  // A black key first, since it sits on top of the two whites it divides. It
  // exists only where those two are a whole tone apart — which is what leaves
  // the gaps at E-F and B-C that make the groups readable.
  let bIdx = i32(round(wf));
  if (bIdx > 0 && bIdx < nW) {
    let below = pitchOfWhiteOrd(ord0 + bIdx - 1);
    let above = pitchOfWhiteOrd(ord0 + bIdx);
    if (above - below == 2 && abs(uv.x - (KEYS_LO + f32(bIdx) * kw)) < kw * 0.30 && uv.y > KEY_TOP - BLACK_H) {
      let p = below + 1;
      let press = pressAt(p, t);
      let v = (uv.y - (KEY_TOP - BLACK_H)) / BLACK_H;
      return vec4f(mix(KEY_EBONY, KEY_PRESS_B, press) * mix(1.0, KEY_SHADE * 0.85, v), 1.0);
    }
  }

  // Otherwise the white key whose slot this is, inset so the seams read.
  let wi = i32(floor(wf));
  let frac = wf - f32(wi);
  let inset = KEY_GAP / kw;
  if (frac < inset || frac > 1.0 - inset) { return vec4f(0.0); }
  let p = pitchOfWhiteOrd(ord0 + wi);
  let press = pressAt(p, t);
  let v = (uv.y - (KEY_TOP - KEY_H)) / KEY_H;
  return vec4f(mix(KEY_IVORY, KEY_PRESS, press) * mix(1.0, KEY_SHADE, v), 1.0);
}

/** The line's height at x: a flowing baseline, nudged where a key sounds.
 *  ord0/kw/lo/hi are hoisted for the reason keyX explains. */
fn lineY(x: f32, t: f32, ord0: i32, kw: f32, lo: f32, hi: f32) -> f32 {
  // Idle motion, so the line is fluid rather than a rule drawn across the frame.
  let base = LINE_Y
           + sin(x * 9.0 + t * FLOW) * 0.0022
           + sin(x * 19.0 - t * FLOW * 1.6) * 0.0011
           + sin(x * 37.0 + t * FLOW * 2.3) * 0.0005;
  // Every sounding key pushes it up near its own x. Sampling the key map rather
  // than the note list is the whole reason that map exists: this is a per-pixel
  // question about NOW, which a list of onsets cannot answer cheaply.
  var bend = 0.0;
  for (var k = 0; k < 24; k = k + 1) {
    let pitch = round(mix(lo, hi, f32(k) / 23.0));
    let d = (x - keyX(pitch, ord0, kw)) / RIPPLE_W;
    // Distance first: past three widths the gaussian is nothing, and this is
    // the innermost loop of a full-resolution fullscreen pass.
    if (abs(d) > 3.0) { continue; }
    bend += RIPPLE * rzKeyEnergy(pitch) * exp(-d * d);
  }
  return base + min(bend, RIPPLE_MAX);
}

/**
 * What this pixel is worth as COVERAGE.
 *
 * Brightness alone was the whole rule, and on black it was invisibly wrong: an
 * opaque background forces the canvas opaque whatever an effect asks, so only
 * colour was ever read and the stage looked right. Put a backdrop behind it and
 * the canvas carries THIS number instead — so the keys, dark and solid, asked
 * to be see-through and the video came through the piano.
 *
 * Two sources, whichever is greater. Light adds by how bright it is, which is
 * what makes a glow a glow. An OBJECT covers by its own shape, however dark it
 * happens to be.
 */
/**
 * How much of the backdrop the stage holds back. 0 disables the scrim.
 *
 * The effect is composed as a full-screen scene against black, so over footage
 * its empty stage is a hole and the piano competes with whatever is playing.
 * This lays a dark wash under the whole composition instead of asking the
 * backdrop to be graded down for it.
 */
const SCRIM: f32 = 0.40;
/** The wash's own colour. Near-black, so it reads as depth rather than as a
 *  blue filter laid over the picture — the piano and the bars are what should
 *  carry colour. Set to vec3f(0.0) for a neutral scrim. */
const SCRIM_TINT: vec3f = vec3f(0.055, 0.095, 0.205);

fn nfOut(col: vec3f, solid: f32) -> vec4f {
  let lum = clamp(max(col.r, max(col.g, col.b)), 0.0, 1.0);
  // What the effect covers ON ITS OWN — light by its brightness, objects by
  // their shape.
  let own = clamp(max(lum, solid), 0.0, 1.0);
  let a = max(own, SCRIM);
  // What the scrim itself covers: the coverage this pixel gained BEYOND what the
  // effect draws, which is the part that would otherwise have been a hole.
  let wash = max(a - own, 0.0);
  // The layer blend multiplies rgb by alpha, so lifting alpha for the scrim
  // would lift the whole picture with it and every faint glow would bloom.
  // Dividing by a is what cancels that: the effect's own light lands at exactly
  // the strength it always did, and the wash colours only the share it added.
  return vec4f((col * own + SCRIM_TINT * wash) / max(a, 1e-6), a);
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  let t = rzMidiTime();
  var col = vec3f(0.0);
  // Coverage of whatever SOLID sits under this pixel — the keys, and the bodies
  // of the bars. Kept apart from col so a dark object still hides the backdrop.
  var solid = 0.0;

  // The keyboard's shape, read ONCE. Every one of these costs an integer divide
  // or a score-header read, and everything below wants them — see keyX.
  let ord0 = kbLowOrd();
  let nW = kbWhites();
  let kw = (KEYS_HI - KEYS_LO) / f32(nW);
  let pLo = rzPitchLow();
  let pHi = rzPitchHigh();

  // ── The line ──────────────────────────────────────────────────────────────
  // 1/|distance| — a hot filament inside a wide glow, which is what a soft edge
  // cannot give and what bloom needs something to catch.
  //
  // Skipped outright where it cannot be seen. lineY samples twenty-four keys,
  // and it was doing that for every pixel of the frame including the empty sky
  // — most of a full-resolution pass spent computing a line that contributes
  // nothing that far from it. LINE_REACH is past where the wide falloff has
  // anything left to add.
  if (abs(uv.y - LINE_Y) < LINE_REACH) {
    let dy = uv.y - lineY(uv.x, time, ord0, kw, pLo, pHi);
    col += LINE_TINT * (min(abs(1.0 / (LINE_SHARP * dy)), LINE_CAP) * LINE_GAIN
                      + LINE_HALO_W / (1.0 + LINE_HALO * abs(dy)));
  }

  let count = rzNoteCount();
  if (count == 0) {
    // No score: the line alone, and no keyboard — the pitch range it would be
    // drawn against is zero, and one key stretched across the frame is worse
    // than nothing while a file is on its way.
    return nfOut(col, solid);
  }
  let kb = keyboard(uv, t);
  col += kb.rgb;
  solid = max(solid, kb.a);

  let speed = (1.0 - LINE_Y) / params.FALL;
  let above = uv.y - LINE_Y;
  if (above < -SPARK_DIP) {
    // Below the line: the keyboard and the line's own glow live here.
    return nfOut(col, solid);
  }

  // ── Which notes can reach THIS pixel ──────────────────────────────────────
  // The height IS a time — see the header — so a bar covers this pixel exactly
  // when its note is sounding at tau. That inverts into a band of onsets: a
  // note must have started by tau, and cannot have started more than params.DUR_MAX
  // before it or it would already be over.
  let tau = t + above / speed;
  let sTo = tau + PAD / speed;
  let sFrom = min(tau, t) - PAD / speed - params.DUR_MAX - SPARK_LIFE;

  let start = firstAfter(sFrom);
  for (var k = 0; k < WINDOW; k = k + 1) {
    let i = start + k;
    if (i >= count) { break; }
    let s = rzNoteStart(i);
    if (s > sTo) { break; }        // sorted, so everything after is later still

    let dur = clamp(rzNoteLength(i), DUR_MIN, params.DUR_MAX);
    // The bar is eaten by the line: bottom edge at note-on, top edge at
    // note-off, so its length is what is left to sound.
    let bot = max((s - t) * speed, 0.0);
    let top = max((s + dur - t) * speed, 0.0);
    let age = t - s;
    // Emission runs the length of the note, and the last glint still has a
    // life to live after that — which is why the band below reaches back
    // params.DUR_MAX + SPARK_LIFE rather than params.DUR_MAX.
    let sparking = age > 0.0 && age < dur + SPARK_LIFE;

    // Vertical reject BEFORE touching pitch: keyX costs integer divides, and
    // most of a 4-second band is notes this pixel is nowhere near in time.
    if (top <= bot && !sparking) { continue; }
    if ((above < bot - PAD || above > top + PAD) && !sparking) { continue; }

    let pitch = rzNotePitch(i);
    let black = isBlackClass(i32(round(pitch)) % 12);
    // Height units on both axes, so the glow is round in pixels.
    let dx = (uv.x - keyX(pitch, ord0, kw)) * aspect;
    let halfW = kw * aspect * select(BAR_FILL, BAR_FILL_B, black);
    // 2.3x SPARK_REACH, not 1.0: a glint's reach is scaled by its own hash to
    // 1.25, by its note's energy to 1.35, and then travelled at up to 1.25
    // speed — every one of those multiplies the spread. Raise this whenever any
    // of them is raised: an unraised bound does not fail, it silently clips the
    // outermost glints of exactly the biggest hits.
    if (abs(dx) > halfW + PAD + SPARK_REACH * 2.3) { continue; }

    if (top > bot) {
      let len = top - bot;
      let cy = LINE_Y + (bot + top) * 0.5;
      let d = max(boxSdf(vec2f(dx, uv.y - cy), vec2f(halfW, len * 0.5), min(halfW * 0.5, len * 0.4)), 0.0);
      // Velocity is normalised against the score's own range inside rzNote*,
      // but a quiet transcription still tops out low — so lift it rather than
      // trust it.
      let hit = 0.55 + 0.45 * clamp(rzNoteVelocity(i) * 2.2, 0.0, 1.0);
      // A brief overshoot as it arrives — what sells the note LANDING rather
      // than merely crossing.
      let flash = 1.0 + 1.6 * exp(-max(age, 0.0) * 12.0) * step(0.0, age);
      let core = 1.0 / (1.0 + BAR_SHARP * d * d);
      let halo = 1.0 / (1.0 + BAR_HALO * d);
      col += mix(GLOW, CORE, clamp(core, 0.0, 1.0)) * (core * 1.5 + halo * BAR_HALO_W) * hit * flash;
      // core is 1 down the bar's spine and falls away with it, so the coverage
      // has the same profile as the light — solid where the bar reads solid,
      // gone where it was only ever a glow.
      solid = max(solid, clamp(core, 0.0, 1.0));
    }

    // ── The burst. It KEEPS EMITTING for as long as the note sounds instead of
    //    firing once: contact with the line lasts the whole note, and a single
    //    puff at the start read as the bar bouncing off rather than grinding
    //    against it. Each glint is born on its own staggered cycle, so the
    //    stream is continuous, and the cycle index seeds the hash so no two
    //    waves repeat. Still closed-form in age, so a scrub replays it exactly.
    if (sparking && uv.y < LINE_Y + SPARK_TOP) {
      // Short notes pack their glints into the time they have; long ones spread
      // over a full life and then recycle. Without the floor, a staccato note
      // emitted only the first two or three of them.
      // THIS NOTE'S OWN CHARACTER, drawn once and shared by every glint it
      // throws. Without it every burst was the same fan at a different place —
      // same width, same count, same energy — so a run of notes read as one
      // animation repeating rather than as a piece being played. The pitch is
      // in the seed as well as the index, so the same key struck twice differs
      // and two different keys differ more.
      let nh = rzHash11(f32(i) * 1.37 + pitch * 0.29 + 0.11);
      let nh2 = rzHash11(f32(i) * 2.71 + pitch * 0.73 + 7.3);
      let nh3 = rzHash11(f32(i) * 5.11 + pitch * 1.13 + 3.7);
      // How hard this one went: velocity, plus a draw of its own so two notes
      // at the same velocity are still not the same burst.
      let energy = mix(0.65, 1.35, nh2) * (0.6 + 0.4 * clamp(rzNoteVelocity(i) * 2.2, 0.0, 1.0));
      let spread = mix(0.5, 1.0, nh);        // how wide the fan opens
      let tilt = (nh3 - 0.5) * 0.85;         // and which way it leans
      // Not every hit throws the same number. A light one is a few glints.
      let live = max(i32(mix(f32(SPARK_N) * 0.4, f32(SPARK_N), nh2 * energy)), 3);

      let step = min(SPARK_LIFE, max(dur, 0.12)) / f32(live);
      for (var j = 0; j < live; j = j + 1) {
        let tj = age - f32(j) * step;
        if (tj < 0.0) { continue; }
        let cyc = floor(tj / SPARK_LIFE);
        if (f32(j) * step + cyc * SPARK_LIFE > dur) { continue; }  // it stopped sounding
        let sp = (tj - cyc * SPARK_LIFE) / SPARK_LIFE;             // 0..1 through its life
        let h = rzHash11(f32(i) * 3.17 + f32(j) * 0.71 + cyc * 5.13);
        let h2 = rzHash11(f32(i) * 7.31 + f32(j) * 2.13 + cyc * 1.77 + 11.0);
        // Fanned by j and only JITTERED by the hash. Pure hash angles clump —
        // random draws leave gaps and pairs, which reads as a handful rather
        // than as a burst. The fan is centred on straight up and then leaned,
        // so the SHAPE varies per note while the spacing stays even.
        let ang = 1.5707963 + tilt
                + ((f32(j) + 0.5) / f32(live) - 0.5) * 3.14159265 * spread
                + (h - 0.5) * 0.42;
        let reach = SPARK_REACH * energy * (0.35 + 0.9 * h2);
        let sp2 = sp * (0.75 + 0.5 * h);   // and not all at one speed
        let px = cos(ang) * reach * sp2;
        let py = LINE_Y + sin(ang) * reach * SPARK_RISE * sp2 - SPARK_GRAV * sp2 * sp2;
        let sd = length(vec2f(dx - px, uv.y - py));
        // Each glint its own size. One size for all is the other half of what
        // reads as copies of a sprite.
        let sharp = SPARK_SHARP * (0.5 + h2 * 1.6);
        let fade = (1.0 - sp) * (1.0 - sp);
        col += CORE * (1.0 / (1.0 + sharp * sd * sd)) * fade * SPARK_GAIN;
      }
    }
  }

  // Alpha is the light's own strength: additive means it is never asked to
  // cover anything, but the composite still wants to know how present it is.
  return nfOut(col, solid);
}

#param color FILL #ffffff — unsung glyphs
#param color SUNG #6bc7ff — what the sweep leaves behind
#param float LINE_H 0.05 0.02 0.12 — line box height, fraction of frame height
#param float SHADOW 0.45 0 1 — drop shadow strength, 0 for none

// Lyrics — the words of the track, one line at a time, lettered the way
// Subtitles letters them: white glyphs in a thin dark rim over a soft shadow,
// cut in and out on the timing, the sung part wiping to colour as the clock
// crosses the line. The same renderer as Subtitles, row for row — this file
// differs only in drawing ONE line, and in where it puts it.
//
// The TEXT arrives from the host — pair an .lrc with the track (X.mp3 beside
// X.lrc) and each line is rasterised once into the lyric atlas. What this file
// owns is where the words go, when they land, and how they look.
//
//   rzLyricIndex(t)      which line is live at time t (-1 between lines)
//   rzLyricText(i, uv)   glyph coverage of line i; uv is 0..1 across its box
//   rzLyricAspect(i)     the line's width over its height, as rasterised
//   rzLyricProgress(i,t) 0..1 through the line — the karaoke sweep

// Tunables — edit and ⌘⏎.
const LEAD = 0.0;                       // seconds EARLY — the knob to turn when the
                                        // words feel late against this particular rip
const SIDE = 0.06;                      // frame edge a line never crosses, per side,
                                        // as a fraction of frame width
const RIM = vec3f(0.05, 0.05, 0.08);    // the outline around the glyphs
const RIM_R = 0.055;                    // outline reach, fraction of row height —
                                        // a caption's stroke
const SHADOW_DROP = 0.6;                // how far BELOW the words it sits, in rim radii
const SHARP = 0.35;                     // edge contrast; 0.5 is raw coverage,
                                        // lower is harder — under ~0.2 it steps
const FADE_IN = 0.16;                   // seconds; a caption cuts, an MV line breathes
const FADE_OUT = 0.22;

/**
 * WHERE the line goes: xy is the box's anchor in screen fractions (x is its
 * centre, y its bottom edge, both from the bottom-left), z scales its height.
 * This is the function to edit when the words should move — it gets the
 * line's index and the clock, so placement can follow the song.
 *
 * Some ideas, each one line:
 *   alternate high and low   vec3f(0.5, select(0.075, 0.60, (i % 2) == 1), 1.0)
 *   the chorus, bigger       vec3f(0.5, 0.075, select(1.0, 1.6, i >= 18))
 *   drift with the music     vec3f(0.5 + 0.04 * sin(t * 0.7), 0.075, 1.0)
 *   step up the screen       vec3f(0.5, 0.075 + 0.03 * f32(i % 4), 1.0)
 */
fn linePlace(i: i32, t: f32) -> vec3f {
  return vec3f(0.5, 0.075, 1.0);
}

/**
 * Glyph coverage over ONE SCREEN PIXEL, not at one point. The atlas holds a
 * row at whatever size it was rasterised and the box is drawn at whatever size
 * the canvas asks for, so a single bilinear tap misses texels where the atlas
 * is denser than the screen — the stair-stepped edge. Four taps on a rotated
 * grid estimate the area instead, which is what an antialiased edge is.
 */
fn lyricCoverage(i: i32, lu: vec2f, px: vec2f) -> f32 {
  var s = rzLyricText(i, lu + vec2f(0.125, 0.375) * px);
  s = s + rzLyricText(i, lu + vec2f(-0.375, 0.125) * px);
  s = s + rzLyricText(i, lu + vec2f(-0.125, -0.375) * px);
  s = s + rzLyricText(i, lu + vec2f(0.375, -0.125) * px);
  return s * 0.25;
}

/**
 * One row: line i in a box centred on x = 0.5 whose bottom edge sits at y0
 * and whose height is h, both in screen fractions; `sung` is how far across
 * the box the sweep has reached. Straight-alpha colour at uv; zero outside
 * the box and its rim.
 */
fn rowInk(i: i32, uv: vec2f, x0: f32, y0: f32, h: f32, fill: vec3f, sung: f32, res: vec2f) -> vec4f {
  let w = h * rzLyricAspect(i) * (res.y / max(res.x, 1.0));
  let lu = vec2f((uv.x - x0) / w + 0.5, (uv.y - y0) / h);
  // Reject early and generously — the rim and shadow reach past the box.
  if (lu.x < -0.2 || lu.x > 1.2 || lu.y < -0.4 || lu.y > 1.4) { return vec4f(0.0); }

  // One screen pixel, in the box's own units. Everything below measures in it.
  let px = vec2f(1.0 / max(w * res.x, 1.0), 1.0 / max(h * res.y, 1.0));
  let glyph = smoothstep(0.5 - SHARP, 0.5 + SHARP, lyricCoverage(i, lu, px));

  // The rim is the glyph dilated over two rings, each tap nudged a quarter
  // pixel off its spoke so the dilated edge is sampled at more than one phase.
  let r = vec2f(RIM_R * h * (res.y / res.x) / w, RIM_R);
  var raw = 0.0;
  for (var k = 0; k < 8; k = k + 1) {
    let a = 6.2831853 * f32(k) / 8.0;
    let d = vec2f(cos(a), sin(a));
    raw = max(raw, rzLyricText(i, lu + d * r + d.yx * px * 0.25));
    let b = a + 6.2831853 / 16.0;
    let e = vec2f(cos(b), sin(b));
    raw = max(raw, rzLyricText(i, lu + e * r * 0.55 - e.yx * px * 0.25));
  }
  let rim = max(glyph, smoothstep(0.5 - SHARP, 0.5 + SHARP, raw));

  // A soft shadow UNDER the words. A tap reads the line at lu + off and draws
  // what it finds at lu, so reaching ABOVE the glyphs hangs the ink below them;
  // averaged over a disc rather than maxed, or it is the line drawn twice.
  var shade = 0.0;
  if (params.SHADOW > 0.0) {
    let drop = vec2f(0.0, r.y * SHADOW_DROP);
    var wsum = 1.0;
    shade = rzLyricText(i, lu + drop);
    for (var k = 0; k < 6; k = k + 1) {
      let a = 6.2831853 * f32(k) / 6.0;
      let d = vec2f(cos(a), sin(a));
      let e = vec2f(cos(a + 0.5235988), sin(a + 0.5235988));
      shade = shade + 0.70 * rzLyricText(i, lu + drop + d * r * 0.60);
      shade = shade + 0.40 * rzLyricText(i, lu + drop + e * r * 1.10);
      wsum = wsum + 1.10;
    }
    shade = shade / wsum;
  }

  // The sweep: everything left of the stack's progress has been sung. Its
  // edge is one pixel wide, like every other edge here.
  let swept = smoothstep(-px.x, px.x, sung - lu.x);
  let ink = mix(fill, params.SUNG, swept);

  // Shadow under rim under fill. Each coverage is >= the one above it, so the
  // mixes stack in that order and the rim never darkens the glyph it surrounds.
  let color = mix(mix(vec3f(0.0), RIM, rim), ink, glyph);
  let a = max(max(shade * params.SHADOW, rim), glyph);
  return vec4f(color, clamp(a, 0.0, 1.0));
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let t = rzAudioTime() + LEAD;
  let i = rzLyricIndex(t);
  if (i < 0 || !rzLyricHasText(i)) { return vec4f(0.0); }

  let start = rzLyricStart(i);
  let end = rzLyricEnd(i);
  let inT = clamp((t - start) / FADE_IN, 0.0, 1.0);
  let fade = inT * clamp((end - t) / FADE_OUT, 0.0, 1.0);
  if (fade <= 0.0) { return vec4f(0.0); }

  // The box: height from linePlace, width from the rasterised proportions, so
  // a two-word interjection and a full verse both sit unstretched — and a line
  // that would cross the frame edge is set smaller, which is what every
  // subtitle renderer does. Per line: only the verse that needs it comes down.
  let res = rzResolution();
  let place = linePlace(i, t);
  let k = res.y / max(res.x, 1.0);
  let wantH = params.LINE_H * place.z;
  let h = wantH * min(1.0, (1.0 - SIDE * 2.0) / max(wantH * rzLyricAspect(i) * k, 1e-4));

  let ink = rowInk(i, uv, place.x, place.y, h, params.FILL, rzLyricProgress(i, t), res);
  return vec4f(ink.rgb, ink.a * fade);
}

#param color FILL #ffffff — unsung glyphs, the first line on the stamp
#param color SUNG #6bc7ff — what the sweep leaves behind
#param float LINE_H 0.046 0.02 0.1 — every row's height, fraction of frame height —
#param float GAP 0.22 0 1 — between rows, in row heights

// Subtitles — the words the way a film captions them and a Japanese MV letters
// them: the line low and centred, its translation beneath it in the same size
// of type, white glyphs in a thin dark rim over a soft shadow, cut in and out
// on the timing, and the sung part wiping to colour down both rows at once.
//
// A BILINGUAL .lrc puts an original and its translation on one stamp —
//
//   [00:14.42]まるでこの世界で二人だけみたいだね
//   [00:14.42]仿佛这世上唯余你我二人
//
// — and the host keeps them consecutive on the same window. The stack drawn
// here is every line that shares the live line's start, in file order, top to
// bottom. A one-language file draws one row.
//
//   rzLyricIndex(t)      a line live at time t (-1 between lines)
//   rzLyricStart(i)      when line i lands — equal across a stack
//   rzLyricText(i, uv)   glyph coverage of line i; uv is 0..1 across its box
//   rzLyricAspect(i)     the line's width over its height, as rasterised
//   rzLyricPixels(i)     the line's box in atlas texels

// Tunables — edit and ⌘⏎.
const LEAD = 0.0;                       // seconds EARLY — the knob to turn when the
                                        // words feel late against this particular rip
const BASE_Y = 0.075;                   // bottom edge of the stack, fraction of frame height

                                        // one type size for the whole stack

const SIDE = 0.06;                      // frame edge a row never crosses, per side,
                                        // as a fraction of frame width

const SECOND_FILL = vec3f(1.0, 1.0, 1.0); // unsung glyphs, every line under it

const RIM = vec3f(0.05, 0.05, 0.08);    // the outline around both
const RIM_R = 0.055;                    // outline reach, fraction of row height —
                                        // a caption's stroke, thinner than a
                                        // broadcast karaoke rim
const SHADOW = 0.45;                    // drop shadow strength, 0 for none
const SHADOW_DROP = 0.6;                // how far BELOW the words it sits, in rim radii
const SHARP = 0.35;                     // edge contrast; 0.5 is raw coverage,
                                        // lower is harder — under ~0.2 it steps
const FADE_IN = 0.16;                   // seconds; a caption cuts, an MV line breathes
const FADE_OUT = 0.22;
const MAX_ROWS = 3;                     // original, romanisation, translation

/** The first line of the stack the given line belongs to. */
fn stackFirst(i: i32) -> i32 {
  var j = i;
  for (var k = 1; k < MAX_ROWS; k = k + 1) {
    if (j <= 0 || rzLyricStart(j - 1) != rzLyricStart(j)) { break; }
    j = j - 1;
  }
  return j;
}

/** How many lines share the stamp of line `first`, capped at MAX_ROWS. */
fn stackRows(first: i32) -> i32 {
  var n = 1;
  for (var k = 1; k < MAX_ROWS; k = k + 1) {
    if (first + k >= rzLyricCount() || rzLyricStart(first + k) != rzLyricStart(first)) { break; }
    n = n + 1;
  }
  return n;
}

/**
 * Glyph coverage over ONE SCREEN PIXEL, not at one point. The atlas holds a
 * row at whatever size it was rasterised and the box is drawn at whatever size
 * the canvas asks for, so a single bilinear tap misses texels where the atlas
 * is denser than the screen — the stair-stepped edge. Four taps on a rotated
 * grid estimate the area instead, which is what an antialiased edge is.
 */
fn lyricCoverage(i: i32, lu: vec2f, px: vec2f) -> f32 {
  var s = rzLyricText(i, lu + vec2f(0.125, 0.375) * px);
  s = s + rzLyricText(i, lu + vec2f(-0.375, 0.125) * px);
  s = s + rzLyricText(i, lu + vec2f(-0.125, -0.375) * px);
  s = s + rzLyricText(i, lu + vec2f(0.375, -0.125) * px);
  return s * 0.25;
}

/**
 * One row: line i in a box centred on x = 0.5 whose bottom edge sits at y0
 * and whose height is h, both in screen fractions; `sung` is how far across
 * the box the sweep has reached. Straight-alpha colour at uv; zero outside
 * the box and its rim.
 */
fn rowInk(i: i32, uv: vec2f, y0: f32, h: f32, fill: vec3f, sung: f32, res: vec2f) -> vec4f {
  let w = h * rzLyricAspect(i) * (res.y / max(res.x, 1.0));
  let lu = vec2f((uv.x - 0.5) / w + 0.5, (uv.y - y0) / h);
  // Reject early and generously — the rim and shadow reach past the box.
  if (lu.x < -0.2 || lu.x > 1.2 || lu.y < -0.4 || lu.y > 1.4) { return vec4f(0.0); }

  // One screen pixel, in the box's own units. Everything below measures in it.
  let px = vec2f(1.0 / max(w * res.x, 1.0), 1.0 / max(h * res.y, 1.0));
  let glyph = smoothstep(0.5 - SHARP, 0.5 + SHARP, lyricCoverage(i, lu, px));

  // The rim is the glyph dilated over two rings, each tap nudged a quarter
  // pixel off its spoke so the dilated edge is sampled at more than one phase.
  let r = vec2f(RIM_R * h * (res.y / res.x) / w, RIM_R);
  var raw = 0.0;
  for (var k = 0; k < 8; k = k + 1) {
    let a = 6.2831853 * f32(k) / 8.0;
    let d = vec2f(cos(a), sin(a));
    raw = max(raw, rzLyricText(i, lu + d * r + d.yx * px * 0.25));
    let b = a + 6.2831853 / 16.0;
    let e = vec2f(cos(b), sin(b));
    raw = max(raw, rzLyricText(i, lu + e * r * 0.55 - e.yx * px * 0.25));
  }
  let rim = max(glyph, smoothstep(0.5 - SHARP, 0.5 + SHARP, raw));

  // A soft shadow UNDER the words. A tap reads the line at lu + off and draws
  // what it finds at lu, so reaching ABOVE the glyphs hangs the ink below them;
  // averaged over a disc rather than maxed, or it is the line drawn twice.
  var shade = 0.0;
  if (SHADOW > 0.0) {
    let drop = vec2f(0.0, r.y * SHADOW_DROP);
    var wsum = 1.0;
    shade = rzLyricText(i, lu + drop);
    for (var k = 0; k < 6; k = k + 1) {
      let a = 6.2831853 * f32(k) / 6.0;
      let d = vec2f(cos(a), sin(a));
      let e = vec2f(cos(a + 0.5235988), sin(a + 0.5235988));
      shade = shade + 0.70 * rzLyricText(i, lu + drop + d * r * 0.60);
      shade = shade + 0.40 * rzLyricText(i, lu + drop + e * r * 1.10);
      wsum = wsum + 1.10;
    }
    shade = shade / wsum;
  }

  // The sweep: everything left of the stack's progress has been sung. Its
  // edge is one pixel wide, like every other edge here.
  let swept = smoothstep(-px.x, px.x, sung - lu.x);
  let ink = mix(fill, params.SUNG, swept);

  // Shadow under rim under fill. Each coverage is >= the one above it, so the
  // mixes stack in that order and the rim never darkens the glyph it surrounds.
  let color = mix(mix(vec3f(0.0), RIM, rim), ink, glyph);
  let a = max(max(shade * SHADOW, rim), glyph);
  return vec4f(color, clamp(a, 0.0, 1.0));
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let t = rzAudioTime() + LEAD;
  let live = rzLyricIndex(t);
  if (live < 0) { return vec4f(0.0); }
  let first = stackFirst(live);
  let rows = stackRows(first);

  let res = rzResolution();
  let k = res.y / max(res.x, 1.0);
  // ONE TYPE SIZE FOR THE STACK. Every row is params.LINE_H tall, and if the widest
  // row would cross the frame edge the whole stack comes down together — a
  // verse and its translation are always the same size of character, and the
  // shorter of them is simply the narrower row. The window is the stack's:
  // its start is shared, its end is the widest of the rows'.
  var widest = 0.0;
  var end = 0.0;
  for (var r = 0; r < rows; r = r + 1) {
    let i = first + r;
    widest = max(widest, rzLyricAspect(i));
    end = max(end, rzLyricEnd(i));
  }
  let h = params.LINE_H * min(1.0, (1.0 - SIDE * 2.0) / max(params.LINE_H * widest * k, 1e-4));
  let start = rzLyricStart(first);
  let inT = clamp((t - start) / FADE_IN, 0.0, 1.0);
  let fade = inT * clamp((end - t) / FADE_OUT, 0.0, 1.0);
  if (fade <= 0.0) { return vec4f(0.0); }
  // One clock for the stack, so the sweep crosses both rows together.
  let sung = clamp((t - start) / max(end - start, 1e-4), 0.0, 1.0);

  // Rows stack upward from BASE_Y in reverse file order, so the first line on
  // the stamp ends up on top. They never overlap: the row whose ink covers
  // this pixel is the one that keeps it.
  let gap = params.GAP * h;
  var y = BASE_Y;
  var out = vec4f(0.0);
  for (var r = rows - 1; r >= 0; r = r - 1) {
    let i = first + r;
    if (rzLyricHasText(i)) {
      let ink = rowInk(i, uv, y, h, select(SECOND_FILL, params.FILL, r == 0), sung, res);
      if (ink.a > out.a) { out = ink; }
    }
    y = y + h + gap;
  }
  return vec4f(out.rgb, out.a * fade);
}

#param color COLOR #ffffff
#param float WIDTH 12 1 60 — border thickness, in pixels of a 1440-line frame
#param float FEATHER 1.4 0 6 — softness at the outer edge, in real pixels
#param float OPACITY 1 0 1 — 0..1

// Sticker Outline — a die-cut border around the cast.
//
// A TEMPLATE more than an effect: it is the shortest thing that shows what
// rzCastDistance is for. Every silhouette look is these same three lines with a
// different curve on the end — swap the smoothstep for exp(-d/k) and it is an
// aura, for sin(d*k - t) and it is a shield, for a second read at uv + offset
// and it is a drop shadow. Start here and change the last line.
//
// The engine answers the hard part. Distance to the nearest cast pixel is not a
// property of the pixel — it depends on every pixel around it — so a shader with
// one pass can only go looking, and searching a disc costs O(radius^2). This
// effect used to do exactly that: 64 id samples on every background pixel for a
// 9 pixel border, and over 96 for a 16 pixel one. rzCastDistance is built once
// per frame by a jump flood, costs the same whatever width anyone asks for, and
// is shared by every effect that reads it.
//
// It borders the CAST and what they hold. The ground, a stage and a media plane
// all draw into the id buffer exactly as she does, but only the subjects and
// their props seed the field, so the floor gets no white rectangle around it.

// Tunables — edit a value and hit Cmd-Enter to see it live.

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  // THE params.WIDTH IS A FRACTION OF THE PICTURE, not a count of device pixels.
  //
  // rzCastDistance answers in screen pixels, so a bare 12 is twelve pixels of
  // whatever frame is being drawn — the border tuned in the preview comes out
  // half as thick in a 4K export, which is the copy anyone keeps. Measured
  // against 1440 lines — about what the editor's preview is — it is the same
  // border at every resolution, and the export is the preview enlarged.
  //
  // params.FEATHER stays in real pixels: it is the anti-aliasing of the cut, and a cut
  // wants the same pixel and a half however many the frame has.
  let width = params.WIDTH * rzResolution().y / 1440.0;
  let d = rzCastDistance(uv);
  if (d >= width) { return vec4f(0.0); }
  // WHERE IT MEETS HER, faded across the one pixel her edge actually lives in.
  //
  // The distance is signed and its zero crossing is sub-pixel — it comes from the
  // MSAA coverage she is drawn with, not from a single sample — so fading over
  // that crossing lands the border against the same edge the eye sees. Stopping
  // dead at d > 0 instead puts a hard binary step next to an anti-aliased figure,
  // which is what makes a border look stuck on rather than attached.
  let inner = clamp(d + 0.5, 0.0, 1.0);
  // And the outer edge is a cut, not a glow: solid to the feather, then off.
  // 1 - smoothstep(lo, hi), never smoothstep(hi, lo): WGSL leaves it undefined
  // when low >= high, and it is the kind of undefined that works locally.
  let outer = 1.0 - smoothstep(width - params.FEATHER, width, d);
  return vec4f(params.COLOR, inner * outer * params.OPACITY);
}

