#param color GOLD #ffde54 — the body of the glow, and its hottest point
#param color LIGHT_COLOR #ffd973
#param float LIGHT_POWER 1.5 0 4 — how hard she is lit
#param float RIM_GAIN 0.9 0 3

#param float REACH 110 20 400 — how far the light carries, in pixels of a 1440-line frame
#param float LIGHT_R 9 1 30 — reach of each lamp, in world units

