  p.age = select(0.0, r1.y * p.life, rzTime() < p.life);
  let rc = rzHash13(p.seed * 11.7 + 0.5);
  let t = 0.0;
  p.size = 0.5 * max(mix(0.03, 0.06, rs.x) * (1.0), mix(0.02, 0.05, rs.y) * (1.0)) * e.unit;

