  q.size = 0.5 * max(mix(0.03, 0.06, rs.x) * (1.0), mix(0.02, 0.05, rs.y) * (1.0)) * unit;

  return q;
}

fn mainLayer(q: vec2f, n: f32, c1: vec4f) -> vec4f {
