#particles 768
#blend additive
#lights 3

#param color CORE_COLOR #fff2f8 — white-hot, a breath of pink
#param color BODY_COLOR #ff2e93 — the neon
#param color HAZE_COLOR #8f1dff — violet, in the outer light
#param float WIDTH 0.18 0.05 0.8 — half-width of the glow, in finger lengths

// Finger Shapes — neon round both hands, and round the shape the fingers make
// whenever they close around one.
//
// TWO OUTLINES. Half the dots trace the outline OUTSIDE both hands — the hull,
// banding them together when they are apart — and it is always there. The
// other half trace the space the fingers ENCLOSE — a frame of two L's, a heart,
// a diamond — faded in by how enclosed that space is, so a shape forming draws
// itself in inside the hull and a hand opening lets it go. Nothing here knows
// what a heart is.
//
// Everything happens on one plane facing the camera, just in front of the
// nearest finger, where each joint lands along its ray from the camera — the
// hands as they are seen, and every dot the same distance away, which is what
// keeps the width even.
//
// THE HULL. Gift wrapping gives the convex hull of every finger joint and tip;
// one concave pass pulls each long edge toward the points just inside it, by a
// smooth max and a softmax so a dent slides rather than pops; a disc offset
// rounds it, so a point arriving on a straight run changes nothing.
//
// THE ENCLOSED SHAPE. Fingers and palms become capsules — fingers thin, each
// palm a fan of thick ones so it has no inside.
//   1. A few starting points (both hands' thumbs and index fingers, each hand's,
//      all ten fingertips) climb clearance to the widest point of their space.
//      Clearance falls in a gap, so nothing leaks out of a hole.
//   2. Rays from each, against capsules THICKENED to seal a narrow gap — never
//      thicker than the point's own clearance — say how enclosed it is. The best
//      point wins; w is its enclosure, size and clearance, measured smoothly.
//   3. The outline is the REAL finger edge along every ray that meets one, and
//      a straight bridge across a gap, so an open corner closes as a corner.
//
// THE SAME WIDTH OVER THE DRESS AS OVER THE SKY: only the core is hot and there
// is no bloom — a hot halo added to a lit body, and bloom spread over it, read
// as a wider line there than against the sky.

const POOL: u32 = 768u;        // = #particles; per dancer, half the hull and half the enclosed shape
const NC: i32 = 46;            // capsules: per hand the thumb's 2, four fingers' 3, the palm fan's 5, the knuckle row's 4
const NR: i32 = 48;            // rays round the enclosed shape
const NS: i32 = 16;            // rays for scoring a starting point
const NP: i32 = 38;            // hull points: per hand the thumb's two joints and tip, four fingers' three and tip
const TIP: f32 = 0.8;          // a fingertip, this much of the segment before it past the last joint
const RADIUS: f32 = 0.13;      // a finger's half-thickness, in finger lengths — and the hull's rounding
const PALM_R: f32 = 0.3;       // the palm fan's
const GAP: f32 = 0.35;         // gaps narrower than about twice this are sealed for the enclosure test
const REACH: f32 = 4.0;        // a ray that meets nothing within this many finger lengths has escaped
const HOLE_MIN: f32 = 0.26;    // an enclosed space starts to take over from the hull at this mean radius, in finger lengths…
const HOLE_FULL: f32 = 0.4;    // …and has taken over by this one — a frame is 0.44, a heart 0.64, a pocket 0.2-0.3
const DIG_MIN: f32 = 0.6;      // hull edges shorter than this many finger lengths are left straight
const DIG_LO: f32 = 0.25;      // a hull dent shallower than this fraction of its edge is pulled all the way…
const DIG_HI: f32 = 0.45;      // …and one deeper than this not at all
const ABS_LO: f32 = 0.3;       // and the same in finger lengths, so a band held between two hands
const ABS_HI: f32 = 0.6;       // keeps straight sides instead of reaching in to either hand
const TAU: f32 = 0.05;         // how hard the dent's smooth max leans toward the best candidate
const LIFT: f32 = 0.1;         // the plane sits this many finger lengths in front of the nearest finger
const CORE_W: f32 = 0.16;      // the white-hot core, as a fraction of the glow
const CORE: f32 = 2.4;
const HALO: f32 = 1.4;         // the soft skirt — the glow, since there is no bloom to make one
const DOT_GAIN: f32 = 1.1;     // the line's brightness once the dots along it are summed
const INTENSITY: f32 = 4.2;    // the core's HDR headroom
const HALO_I: f32 = 1.1;       // the halo's: near 1, where adding it and covering with it look alike
const PULSES: f32 = 3.0;       // bright pulses round each outline at once
const FLOW: f32 = 0.33;        // turns a second each pulse makes round it
const LIGHT_I: f32 = 3.0;
const LIGHT_R: f32 = 7.0;      // finger lengths

struct NsCaps {
  a: array<vec2f, 46>,
  b: array<vec2f, 46>,
  r: array<f32, 46>,
}

/** One dancer's hands on the plane, this frame. */
struct NsFrame {
  /** Per hand: wrist, thumb joints and tip, each finger's three joints and tip. */
  q: array<vec2f, 40>,
  /** The plane: its origin (straight ahead of the hands' middle) and axes. */
  o: vec3f,
  ax: vec3f,
  ay: vec3f,
  /** One finger length on the plane, and in the world. */
  finger: f32,
  finger3: f32,
  ok: bool,
}

/** Where the enclosed space is, and how much of one there is. */
struct NsFind {
  seed: vec2f,
  grow: f32,
  w: f32,
}

struct NsHole {
  /** Distance along each ray from the seed to the edge. */
  h: array<f32, 48>,
  /** Length round the outline to each ray's point; c[48] is the whole outline. */
  c: array<f32, 49>,
  seed: vec2f,
}

struct NsHull {
  /** The corners, counter-clockwise as seen. */
  g: array<vec2f, 76>,
  /** Each corner's outward normals, from the edge arriving and the edge leaving. */
  nin: array<vec2f, 76>,
  nout: array<vec2f, 76>,
  /** Length round to the start of each piece: corner i's arc is piece 2i, the
   *  straight run to the next corner piece 2i + 1. */
  cum: array<f32, 153>,
  n: i32,
  r: f32,
}

fn nsDir(v: vec3f, fallback: vec3f) -> vec3f {
  let l = length(v);
  return select(fallback, v / max(l, 1e-6), l > 1e-6);
}

/** A finger joint, or the wrist when the rig has no such bone. */
fn nsBone(s: i32, slot: i32, wrist: vec3f) -> vec3f {
  let a = rzAnchor(s, slot);
  return select(wrist, a.pos, a.valid);
}

fn nsClosest(p: vec2f, a: vec2f, b: vec2f) -> vec2f {
  let ab = b - a;
  let t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-12), 0.0, 1.0);
  return a + ab * t;
}

/** How far p is from the nearest surface; negative inside one. */
fn nsClear(caps: ptr<function, NsCaps>, p: vec2f) -> f32 {
  var m = 1.0e9;
  for (var i = 0; i < NC; i++) {
    m = min(m, distance(p, nsClosest(p, (*caps).a[i], (*caps).b[i])) - (*caps).r[i]);
  }
  return m;
}

/** Step away from the nearest surface, the step shrinking: the widest point of
 *  the space p began in. */
fn nsClimb(caps: ptr<function, NsCaps>, p0: vec2f, finger: f32) -> vec2f {
  var p = p0;
  var step = 0.2 * finger;
  for (var it = 0; it < 16; it++) {
    var m = 1.0e9;
    var away = vec2f(0.0);
    for (var i = 0; i < NC; i++) {
      let v = p - nsClosest(p, (*caps).a[i], (*caps).b[i]);
      let l = length(v);
      if (l - (*caps).r[i] < m) {
        m = l - (*caps).r[i];
        away = select(vec2f(0.0), v / max(l, 1e-6), l > 1e-6);
      }
    }
    p += away * step;
    step *= 0.82;
  }
  return p;
}

/** How far along a ray from o the capsule's surface is; 0 if o is inside it. */
fn nsRayCap(o: vec2f, d: vec2f, a: vec2f, b: vec2f, r: f32) -> f32 {
  if (distance(o, nsClosest(o, a, b)) <= r) { return 0.0; }
  var best = 1.0e9;
  for (var e = 0; e < 2; e++) {
    let c = select(a, b, e == 1);
    let oc = c - o;
    let t = dot(oc, d);
    let h2 = dot(oc, oc) - t * t;
    if (h2 <= r * r) {
      let t0 = t - sqrt(r * r - h2);
      if (t0 >= 0.0) { best = min(best, t0); }
    }
  }
  let ab = b - a;
  let L = length(ab);
  let den = d.x * ab.y - d.y * ab.x;
  if (L > 1e-6 && abs(den) > 1e-9) {
    let n = vec2f(-ab.y, ab.x) / L;
    for (var k = 0; k < 2; k++) {
      let w = a + n * r * select(-1.0, 1.0, k == 1) - o;
      let t = (w.x * ab.y - w.y * ab.x) / den;
      let u = (w.x * d.y - w.y * d.x) / den;
      if (t >= 0.0 && u >= 0.0 && u <= 1.0) { best = min(best, t); }
    }
  }
  return best;
}

/** The nearest surface along one ray, capsules thickened by grow, capped at reach. */
fn nsRay(caps: ptr<function, NsCaps>, o: vec2f, angle: f32, grow: f32, reach: f32) -> f32 {
  let d = vec2f(cos(angle), sin(angle));
  var m = reach;
  for (var i = 0; i < NC; i++) {
    m = min(m, nsRayCap(o, d, (*caps).a[i], (*caps).b[i], (*caps).r[i] + grow));
  }
  return m;
}

/** A ray's share of being enclosed: 1 when it meets something well within reach. */
fn nsHit(h: f32, reach: f32) -> f32 {
  return 1.0 - smoothstep(0.75 * reach, reach, h);
}


fn nsDir2(v: vec2f) -> vec2f {
  let l = length(v);
  return select(vec2f(0.0), v / max(l, 1e-6), l > 1e-6);
}

/** Twice the signed area of o, a, b: positive when b is left of o→a. */
fn nsTurn(o: vec2f, a: vec2f, b: vec2f) -> f32 {
  return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}

/** Ray k's direction. */
fn nsRayDir(k: i32) -> vec2f {
  let angle = f32(k) * 6.2831853 / f32(NR);
  return vec2f(cos(angle), sin(angle));
}

/** One dancer's hands on the plane this frame. */
fn nsFrame(s: i32) -> NsFrame {
  var fr: NsFrame;
  let lw = rzAnchor(s, 0);
  let rw = rzAnchor(s, 15);
  // No wrists, no hands. A model still loading has every bone at the origin,
  // which is the same answer: both wrists in one place.
  fr.ok = lw.valid && rw.valid && distance(lw.pos, rw.pos) > 1e-4;
  if (!fr.ok) { return fr; }
  var B: array<vec3f, 40>;
  var fingers = 0.0;
  for (var hand = 0; hand < 2; hand++) {
    let b = hand * 15;
    let k = hand * 20;
    let w = select(lw.pos, rw.pos, hand == 1);
    let t1 = nsBone(s, b + 1, w);
    let t2 = nsBone(s, b + 2, w);
    B[k] = w;
    B[k + 1] = t1;
    B[k + 2] = t2;
    B[k + 3] = t2 + (t2 - t1) * TIP;
    for (var f = 0; f < 4; f++) {
      let j1 = nsBone(s, b + 3 + f * 3, w);
      let j2 = nsBone(s, b + 4 + f * 3, w);
      let j3 = nsBone(s, b + 5 + f * 3, w);
      B[k + 4 + f * 4] = j1;
      B[k + 5 + f * 4] = j2;
      B[k + 6 + f * 4] = j3;
      B[k + 7 + f * 4] = j3 + (j3 - j2) * TIP;
      if (f == 0) { fingers += distance(j1, j2) + distance(j2, j3); }
    }
  }
  fr.finger3 = max(0.5 * fingers, 1e-3);
  var sum = vec3f(0.0);
  for (var i = 0; i < 40; i++) {
    sum += B[i];
  }
  let mid = sum / 40.0;
  let eye = rzCameraPos();
  let fwd = nsDir(mid - eye, rzCameraForward());
  let ax = nsDir(rzCameraRight() - fwd * dot(rzCameraRight(), fwd), rzCameraRight());
  let ay = nsDir(rzCameraUp() - fwd * dot(rzCameraUp(), fwd) - ax * dot(rzCameraUp(), ax), rzCameraUp());
  var near = 1.0e9;
  for (var i = 0; i < 40; i++) {
    near = min(near, dot(B[i] - eye, fwd));
  }
  let zMid = max(dot(mid - eye, fwd), 1e-3);
  let z = max(near - LIFT * fr.finger3, 1e-3);
  fr.o = eye + fwd * z;
  fr.ax = ax;
  fr.ay = ay;
  fr.finger = fr.finger3 * z / zMid;
  for (var i = 0; i < 40; i++) {
    let x = eye + (B[i] - eye) * (z / max(dot(B[i] - eye, fwd), 1e-3));
    fr.q[i] = vec2f(dot(x - fr.o, ax), dot(x - fr.o, ay));
  }
  return fr;
}

/** The capsules: fingers thin, each palm a fan of thick ones so it has no inside. */
fn nsCapsOf(fr: ptr<function, NsFrame>) -> NsCaps {
  var caps: NsCaps;
  let f = (*fr).finger;
  var n = 0;
  for (var hand = 0; hand < 2; hand++) {
    let k = hand * 20;
    let w = (*fr).q[k];
    caps.a[n] = (*fr).q[k + 1]; caps.b[n] = (*fr).q[k + 2]; caps.r[n] = RADIUS * f; n += 1;
    caps.a[n] = (*fr).q[k + 2]; caps.b[n] = (*fr).q[k + 3]; caps.r[n] = RADIUS * f; n += 1;
    caps.a[n] = w; caps.b[n] = (*fr).q[k + 1]; caps.r[n] = PALM_R * f; n += 1;
    for (var g = 0; g < 4; g++) {
      let j = k + 4 + g * 4;
      caps.a[n] = (*fr).q[j]; caps.b[n] = (*fr).q[j + 1]; caps.r[n] = RADIUS * f; n += 1;
      caps.a[n] = (*fr).q[j + 1]; caps.b[n] = (*fr).q[j + 2]; caps.r[n] = RADIUS * f; n += 1;
      caps.a[n] = (*fr).q[j + 2]; caps.b[n] = (*fr).q[j + 3]; caps.r[n] = RADIUS * f; n += 1;
      caps.a[n] = w; caps.b[n] = (*fr).q[j]; caps.r[n] = PALM_R * f; n += 1;
    }
    // The web to the index knuckle, and the knuckle row.
    caps.a[n] = (*fr).q[k + 1]; caps.b[n] = (*fr).q[k + 4]; caps.r[n] = RADIUS * f; n += 1;
    caps.a[n] = (*fr).q[k + 4]; caps.b[n] = (*fr).q[k + 8]; caps.r[n] = RADIUS * f; n += 1;
    caps.a[n] = (*fr).q[k + 8]; caps.b[n] = (*fr).q[k + 12]; caps.r[n] = RADIUS * f; n += 1;
    caps.a[n] = (*fr).q[k + 12]; caps.b[n] = (*fr).q[k + 16]; caps.r[n] = RADIUS * f; n += 1;
  }
  return caps;
}

/** Where the enclosed space is and how much of one there is — the one number
 *  both outlines are faded by, so it is worked out the same way for every dot. */
fn nsFind(fr: ptr<function, NsFrame>, caps: ptr<function, NsCaps>) -> NsFind {
  var fd: NsFind;
  let f = (*fr).finger;
  let reach = REACH * f;
  var starts: array<vec2f, 4>;
  var both = vec2f(0.0);
  var one = array<vec2f, 2>(vec2f(0.0), vec2f(0.0));
  var tips = vec2f(0.0);
  for (var hand = 0; hand < 2; hand++) {
    let k = hand * 20;
    // The thumb's two joints and the index finger's three.
    let ti = (*fr).q[k + 1] + (*fr).q[k + 2] + (*fr).q[k + 4] + (*fr).q[k + 5] + (*fr).q[k + 6];
    both += ti;
    one[hand] = ti / 5.0;
    tips += (*fr).q[k + 3] + (*fr).q[k + 7] + (*fr).q[k + 11] + (*fr).q[k + 15] + (*fr).q[k + 19];
  }
  starts[0] = both / 10.0;
  starts[1] = one[0];
  starts[2] = one[1];
  starts[3] = tips / 10.0;
  // The best-enclosed start wins; starts in the same hole settle on one spot.
  var seed = starts[0];
  var best = -1.0;
  for (var c = 0; c < 4; c++) {
    let p = nsClimb(caps, starts[c], f);
    let cl = nsClear(caps, p);
    let grow = min(GAP * f, 0.8 * max(cl, 0.0));
    var enc = 0.0;
    for (var k = 0; k < NS; k++) {
      enc += nsHit(nsRay(caps, p, f32(k) * 6.2831853 / f32(NS), grow, reach), reach);
    }
    let score = enc / f32(NS) * smoothstep(0.0, 0.3 * f, cl);
    if (score > best) {
      best = score;
      seed = p;
    }
  }
  let cl = nsClear(caps, seed);
  fd.seed = seed;
  fd.grow = min(GAP * f, 0.8 * max(cl, 0.0));
  var enc = 0.0;
  var size = 0.0;
  for (var k = 0; k < NR; k++) {
    let sealed = nsRay(caps, seed, f32(k) * 6.2831853 / f32(NR), fd.grow, reach);
    enc += nsHit(sealed, reach);
    size += min(sealed + fd.grow, reach);
  }
  // A space only takes over from the hull if it is big enough to carry the
  // line. A pocket between curled fingers, or between two palms pressed
  // together, is fully enclosed too — at the old threshold it took the hull
  // away and put a speck in its place, and the neon seemed to vanish.
  fd.w = smoothstep(0.88, 0.97, enc / f32(NR)) * smoothstep(HOLE_MIN, HOLE_FULL, size / f32(NR) / f) *
    smoothstep(0.0, 0.1 * f, cl);
  return fd;
}

/** The enclosed shape: the real edge wherever a finger is, a straight bridge across a gap. */
fn nsHole(fr: ptr<function, NsFrame>, caps: ptr<function, NsCaps>, fd: ptr<function, NsFind>) -> NsHole {
  var ho: NsHole;
  let f = (*fr).finger;
  let reach = REACH * f;
  let seed = (*fd).seed;
  ho.seed = seed;
  var sealed: array<f32, 48>;
  var edge: array<f32, 48>;
  var gap: array<bool, 48>;
  for (var k = 0; k < NR; k++) {
    let angle = f32(k) * 6.2831853 / f32(NR);
    sealed[k] = nsRay(caps, seed, angle, (*fd).grow, reach);
    edge[k] = nsRay(caps, seed, angle, 0.0, reach);
    // Escaped, or ran far past where the sealed capsules stopped it: a gap.
    gap[k] = edge[k] >= 0.9 * reach || edge[k] - sealed[k] > 1.5 * f;
  }
  for (var k = 0; k < NR; k++) {
    var hk = edge[k];
    if (gap[k]) {
      hk = min(edge[k], sealed[k] + (*fd).grow);
      // The nearest finger rays either side, and where this ray crosses the
      // line between their edge points.
      var before = -1;
      var after = -1;
      for (var j = 1; j < NR; j++) {
        let i = (k - j + NR) % NR;
        if (!gap[i]) {
          before = i;
          break;
        }
      }
      for (var j = 1; j < NR; j++) {
        let i = (k + j) % NR;
        if (!gap[i]) {
          after = i;
          break;
        }
      }
      if (before >= 0 && after >= 0) {
        let edgeA = seed + nsRayDir(before) * edge[before];
        let span = seed + nsRayDir(after) * edge[after] - edgeA;
        let d = nsRayDir(k);
        let den = d.x * span.y - d.y * span.x;
        if (abs(den) > 1e-9) {
          let w0 = edgeA - seed;
          let t = (w0.x * span.y - w0.y * span.x) / den;
          if (t > 0.0) { hk = min(t, reach); }
        }
      }
    }
    ho.h[k] = hk;
  }
  ho.c[0] = 0.0;
  for (var k = 0; k < NR; k++) {
    ho.c[k + 1] = ho.c[k] + distance(nsHolePoint(&ho, k), nsHolePoint(&ho, (k + 1) % NR));
  }
  return ho;
}

/** Ray k's point on the enclosed shape. */
fn nsHolePoint(ho: ptr<function, NsHole>, k: i32) -> vec2f {
  return (*ho).seed + nsRayDir(k) * (*ho).h[k];
}

fn nsHoleAt(ho: ptr<function, NsHole>, at: f32) -> vec2f {
  var k = 0;
  for (var j = 1; j < NR; j++) {
    if ((*ho).c[j] <= at) { k = j; }
  }
  let u = clamp((at - (*ho).c[k]) / max((*ho).c[k + 1] - (*ho).c[k], 1e-6), 0.0, 1.0);
  return nsSpline(
    nsHolePoint(ho, (k + NR - 1) % NR),
    nsHolePoint(ho, k),
    nsHolePoint(ho, (k + 1) % NR),
    nsHolePoint(ho, (k + 2) % NR),
    u,
  );
}

/** The hull round both hands: gift wrapped, dented where the fingers leave a
 *  gap by a smooth max and a softmax, and rounded by a disc. */
fn nsHull(fr: ptr<function, NsFrame>) -> NsHull {
  var hu: NsHull;
  let f = (*fr).finger;
  hu.r = RADIUS * f;
  // Every joint and tip, without the wrists.
  var Q: array<vec2f, 38>;
  for (var i = 0; i < 19; i++) {
    Q[i] = (*fr).q[i + 1];
    Q[i + 19] = (*fr).q[i + 21];
  }
  var start = 0;
  for (var i = 1; i < NP; i++) {
    if (Q[i].x < Q[start].x || (Q[i].x == Q[start].x && Q[i].y < Q[start].y)) { start = i; }
  }
  var hull: array<i32, 38>;
  var h = 0;
  var cur = start;
  loop {
    hull[h] = cur;
    h += 1;
    var next = (cur + 1) % NP;
    for (var j = 0; j < NP; j++) {
      let turn = nsTurn(Q[cur], Q[next], Q[j]);
      let farther = dot(Q[j] - Q[cur], Q[j] - Q[cur]) > dot(Q[next] - Q[cur], Q[next] - Q[cur]);
      if (turn < 0.0 || (turn == 0.0 && farther)) { next = j; }
    }
    cur = next;
    if (cur == start || h >= NP) { break; }
  }
  var n = 0;
  for (var e = 0; e < h; e++) {
    let a = hull[e];
    let b = hull[(e + 1) % h];
    hu.g[n] = Q[a];
    n += 1;
    let ab = Q[b] - Q[a];
    let L = length(ab);
    let gate = smoothstep(DIG_MIN * 0.6 * f, DIG_MIN * f, L);
    if (gate <= 0.0) { continue; }
    var z0 = 0.0;
    var tm = 0.0;
    var qm = vec2f(0.0);
    var lse = 0.0;
    for (var j = 0; j < NP; j++) {
      let t = dot(Q[j] - Q[a], ab) / (L * L);
      let wt = smoothstep(0.1, 0.2, t) * (1.0 - smoothstep(0.8, 0.9, t));
      if (wt <= 0.0) { continue; }
      let d = abs(nsTurn(Q[a], Q[b], Q[j])) / L;
      let score = gate * wt * (1.0 - smoothstep(DIG_LO * L, DIG_HI * L, d)) *
        (1.0 - smoothstep(ABS_LO * f, ABS_HI * f, d));
      let ex = exp(score / TAU);
      z0 += ex;
      tm += ex * t;
      qm += ex * Q[j];
      // exp(0) - 1 is exactly nothing, so a candidate scoring zero adds no pull.
      lse += ex - 1.0;
    }
    if (z0 <= 0.0) { continue; }
    let pull = min(1.0, TAU * log(1.0 + lse));
    if (pull < 1e-3) { continue; }
    hu.g[n] = mix(Q[a] + ab * (tm / z0), qm / z0, pull);
    n += 1;
  }
  hu.n = n;
  for (var i = 0; i < n; i++) {
    let e1 = hu.g[i] - hu.g[(i + n - 1) % n];
    let e2 = hu.g[(i + 1) % n] - hu.g[i];
    hu.nin[i] = nsDir2(vec2f(e1.y, -e1.x));
    hu.nout[i] = nsDir2(vec2f(e2.y, -e2.x));
  }
  hu.cum[0] = 0.0;
  for (var i = 0; i < n; i++) {
    hu.cum[2 * i + 1] = hu.cum[2 * i] + hu.r * nsSweep(&hu, i);
    hu.cum[2 * i + 2] = hu.cum[2 * i + 1] + distance(nsLeave(&hu, i), nsArrive(&hu, (i + 1) % n));
  }
  return hu;
}

/** Where corner i's inward mitre lands: the two edges' offsets meeting. */
fn nsMitre(hu: ptr<function, NsHull>, i: i32) -> vec2f {
  let a = (*hu).nin[i];
  let b = (*hu).nout[i];
  return (*hu).g[i] + (a + b) * (*hu).r / max(1.0 + dot(a, b), 0.2);
}

fn nsConvex(hu: ptr<function, NsHull>, i: i32) -> bool {
  let n = (*hu).n;
  let e1 = (*hu).g[i] - (*hu).g[(i + n - 1) % n];
  let e2 = (*hu).g[(i + 1) % n] - (*hu).g[i];
  return e1.x * e2.y - e1.y * e2.x >= 0.0;
}

/** Where the straight run leaving corner i starts, and where the one arriving
 *  at it ends: off the arc for an outward corner, at the mitre for an inward one. */
fn nsLeave(hu: ptr<function, NsHull>, i: i32) -> vec2f {
  return select(nsMitre(hu, i), (*hu).g[i] + (*hu).nout[i] * (*hu).r, nsConvex(hu, i));
}

fn nsArrive(hu: ptr<function, NsHull>, i: i32) -> vec2f {
  return select(nsMitre(hu, i), (*hu).g[i] + (*hu).nin[i] * (*hu).r, nsConvex(hu, i));
}

/** How far an outward corner's arc turns, in radians; nothing for an inward one. */
fn nsSweep(hu: ptr<function, NsHull>, i: i32) -> f32 {
  let a = (*hu).nin[i];
  let b = (*hu).nout[i];
  return select(0.0, max(atan2(a.x * b.y - a.y * b.x, dot(a, b)), 0.0), nsConvex(hu, i));
}

fn nsHullAt(hu: ptr<function, NsHull>, at: f32) -> vec2f {
  let n = (*hu).n;
  var k = 0;
  for (var j = 1; j < 2 * n; j++) {
    if ((*hu).cum[j] <= at) { k = j; }
  }
  let u = clamp((at - (*hu).cum[k]) / max((*hu).cum[k + 1] - (*hu).cum[k], 1e-6), 0.0, 1.0);
  let i = k / 2;
  if (k % 2 == 0) {
    let a0 = atan2((*hu).nin[i].y, (*hu).nin[i].x) + nsSweep(hu, i) * u;
    return (*hu).g[i] + vec2f(cos(a0), sin(a0)) * (*hu).r;
  }
  return mix(nsLeave(hu, i), nsArrive(hu, (i + 1) % n), u);
}

/** Place one dot: on the hull or on the enclosed shape, from this frame's bones alone. */
fn nsPlace(p: Particle) -> Particle {
  var q = p;
  // Hidden unless everything below says otherwise.
  q.size = 0.0;
  let live = rzSubjectCount();
  if (live <= 0) { return q; }
  let idx = u32(q.seed);
  let per = max(2u, POOL / u32(live));
  let s = idx / per;
  if (s >= u32(live)) { return q; }
  let half = per / 2u;
  let k = idx % per;
  let onHull = k < half;

  var fr = nsFrame(i32(s));
  if (!fr.ok) { return q; }

  var at2 = vec2f(0.0);
  var total = 0.0;
  var count = 0u;
  var share = 1.0;
  if (onHull) {
    // Always there. The hull's dots never search for a hole, which is most of
    // what this effect costs.
    var hu = nsHull(&fr);
    if (hu.n < 2) { return q; }
    count = half;
    total = hu.cum[2 * hu.n];
    at2 = nsHullAt(&hu, (f32(k) + 0.5) / f32(count) * total);
    // Pulses turn about the hands' middle, which is the plane's origin.
    q.rot = atan2(at2.y, at2.x) / 6.2831853 + 0.5;
  } else {
    var caps = nsCapsOf(&fr);
    var fd = nsFind(&fr, &caps);
    share = fd.w;
    // No shape, nothing to draw — and a hidden dot costs nothing past the vertex stage.
    if (share <= 0.0) { return q; }
    var ho = nsHole(&fr, &caps, &fd);
    count = per - half;
    total = ho.c[NR];
    at2 = nsHoleAt(&ho, (f32(k - half) + 0.5) / f32(count) * total);
    let v = at2 - ho.seed;
    q.rot = atan2(v.y, v.x) / 6.2831853 + 0.5;
  }
  q.pos = fr.o + fr.ax * at2.x + fr.ay * at2.y;
  q.size = params.WIDTH * fr.finger;
  // This half's brightness, and each dot's share of the spacing, so a line is
  // as bright round a small circle as along a long band.
  q.vel = vec3f(share, 0.0, (total / f32(max(count, 1u))) / max(q.size, 1e-6));
  return q;
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  // Which dot this is, for good: the pool is never recycled.
  p.seed = f32(id);
  p.life = 1.0e9;
  return nsPlace(p);
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  return nsPlace(p);
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let d2 = dot(q, q);
  if (d2 >= 1.0) { return vec4f(0.0); }

  // Pulses running round each outline, always.
  let band = pow(0.5 + 0.5 * cos(6.2831853 * PULSES * (p.rot - rzTime() * FLOW)), 6.0);
  let bright = 0.8 + 0.7 * band;

  let core = exp(-d2 / (CORE_W * CORE_W));
  let halo = (1.0 - d2) * (1.0 - d2);
  let heat = core * CORE + halo * HALO;
  var rgb = mix(params.HAZE_COLOR, params.BODY_COLOR, smoothstep(0.05, 0.5, heat));
  rgb = mix(rgb, params.CORE_COLOR, smoothstep(0.9, 2.0, heat));
  let a = clamp(heat * bright * p.vel.z * DOT_GAIN, 0.0, 1.0) * p.vel.x;
  let hot = core * CORE / max(heat, 1e-6);
  return vec4f(rgb * mix(HALO_I, INTENSITY, hot), a);
}

// ── The light the hands throw ────────────────────────────────────────────────
//
// A lamp in each palm, always, and one inside the shape while there is one —
// the neon's own colour. Dancer 0 only: a lamp is a declared cost.

fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  l.color = params.BODY_COLOR;
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0);
  var fr = nsFrame(0);
  if (!fr.ok) { return l; }
  l.radius = LIGHT_R * fr.finger3;
  if (i == 2u) {
    var caps = nsCapsOf(&fr);
    var fd = nsFind(&fr, &caps);
    l.pos = fr.o + fr.ax * fd.seed.x + fr.ay * fd.seed.y;
    l.intensity = LIGHT_I * fd.w;
    return l;
  }
  // The palm: the wrist and the four knuckles.
  let b = i32(i) * 15;
  let w = rzAnchor(0, b).pos;
  l.pos = (w + nsBone(0, b + 3, w) + nsBone(0, b + 6, w) + nsBone(0, b + 9, w) + nsBone(0, b + 12, w)) * 0.2;
  l.intensity = LIGHT_I;
  return l;
}

/**
 * Centripetal Catmull-Rom, p1 to p2.
 *
 * Centripetal because a ray meeting a fingertip and the next one sliding past
 * it put two neighbours very different distances out, and the uniform spline
 * loops back on itself at exactly that spot.
 */
fn nsSpline(p0: vec2f, p1: vec2f, p2: vec2f, p3: vec2f, u: f32) -> vec2f {
  let t0 = 0.0;
  let t1 = t0 + sqrt(max(distance(p0, p1), 1e-4));
  let t2 = t1 + sqrt(max(distance(p1, p2), 1e-4));
  let t3 = t2 + sqrt(max(distance(p2, p3), 1e-4));
  let t = mix(t1, t2, u);
  let a1 = (t1 - t) / (t1 - t0) * p0 + (t - t0) / (t1 - t0) * p1;
  let a2 = (t2 - t) / (t2 - t1) * p1 + (t - t1) / (t2 - t1) * p2;
  let a3 = (t3 - t) / (t3 - t2) * p2 + (t - t2) / (t3 - t2) * p3;
  let b1 = (t2 - t) / (t2 - t0) * a1 + (t - t0) / (t2 - t0) * a2;
  let b2 = (t3 - t) / (t3 - t1) * a2 + (t - t1) / (t3 - t1) * a3;
  return (t2 - t) / (t2 - t1) * b1 + (t - t1) / (t2 - t1) * b2;
}

// Its lights as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// the same brightness half-way out, brighter nearer, dimmer beyond, in
// Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

#particles 512
#points flame
#blend additive
#bloom

#param float SIZE 1 0.3 3 — every flame against the length its wick's bone gives it
#param float WIDTH 0.35 0.1 0.8 — a flame's width, as a share of its height
#param color COLOR #ff8a2a — the flame's body; its core burns toward white
#param float INTENSITY 4 0 12 — HDR: well above 1, so the core blooms white-hot
#param float FLICKER 0.5 0 1 — how hard it trembles, many times a second
#param float SWAY 0.5 0 1 — how far the tip leans in the draught
#param float GLOW 0.6 0 2 — the halo of light round it
#param float BREATH 0.25 0 1 — a slow dimming and return, every two or three seconds

// Candle Flames (wick bones) — a flame standing on every wick the scene names.
//
// A WICK IS A BONE whose name starts with "flame", on any model: the Unity
// stage converter writes one per candle, and a hand-made stage needs only a
// bone on each wick with its tail pointing up the flame. The bone's head is
// the flame's foot and its tail is its length, so a tall candle and a tea
// light each get their own flame with no dial per candle.
//
// A FLAME IS NEVER STILL, and a still one reads as an LED candle. Three
// motions, each on its own clock per wick: a tremble many times a second that
// stretches and narrows it, a slow lean that carries the tip while the foot
// stays on the wick, and a waver running up the edge. Two particles a wick:
// the flame, and a halo of light round it that breathes with it.
//
// IT IS LIGHT: drawn additively, a hot core burning toward white inside an
// orange body, cooling to red at the tip over a faint blue foot where the wax
// vapour burns. Bloom does the rest. The light the candles cast on the room is
// the stage's own lamps, one over each cluster.

const TALL = 1.3;     // the card's height over the flame's: room to flicker taller
const ROOM = 1.8;     // the card's width over the flame's: room to lean
const HALO = 0.9;     // the halo's radius, in flame heights
const HALO_AT = 0.4;  // where up the flame the halo centres

// Smooth 1D noise in -1..1.
fn flameNoise(x: f32) -> f32 {
  let i = floor(x);
  let f = fract(x);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(rzHash11(i), rzHash11(i + 1.0), u) * 2.0 - 1.0;
}

// Slot 2w is wick w's flame, 2w + 1 its halo. Pinned to the wick every frame,
// so a candle a character carries moves with her hand.
fn onWick(p: Particle, wick: u32, halo: bool) -> Particle {
  var q = p;
  let pt = rzPoint(wick);
  let axis = pt.tip - pt.pos;
  let len = length(axis);
  let up = select(vec3f(0.0, 1.0, 0.0), axis / max(len, 1e-6), len > 1e-6);
  let h = max(len, 0.05) * params.SIZE;
  q.vel = up;
  if (halo) {
    q.pos = pt.pos + up * (h * HALO_AT);
    q.size = h * HALO;
    q.stretch = 0.0;
    q.rot = 0.0;
  } else {
    // The engine stretches a card along its velocity on screen, so the
    // velocity is the wick's direction and nothing moves.
    let tall = h * TALL;
    let wide = h * params.WIDTH * ROOM;
    q.pos = pt.pos + up * (tall * 0.5);
    q.size = wide * 0.5;
    q.stretch = tall / wide;
  }
  return q;
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  // A slot past the wicks stays dead, and is asked again next frame — which is
  // how flames appear when the stage loads after the effect.
  if (id / 2u >= rzPointCount()) { return p; }
  p.life = 1.0e9;
  // The slot's own index, exactly: step and shade read it back.
  p.seed = f32(id);
  return onWick(p, id / 2u, (id & 1u) == 1u);
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  let id = u32(p.seed);
  // The wick is gone — the stage was removed. Dead, and back to init.
  if (id / 2u >= rzPointCount()) {
    var dead: Particle;
    return dead;
  }
  return onWick(p, id / 2u, (id & 1u) == 1u);
}

// A wick's motion at time t: (tremble, lean, breath). Shared by the flame and
// its halo, so the light round a flame moves with it.
fn flameLife(wick: f32, t: f32) -> vec3f {
  let k = rzHash11(wick * 1.7 + 0.3);
  let tremble = flameNoise(t * 9.0 + k * 31.0) * 0.6 + flameNoise(t * 23.0 + k * 7.0) * 0.4;
  let lean = flameNoise(t * 1.1 + k * 13.0) * 0.7 + flameNoise(t * 3.3 + k * 5.0) * 0.3;
  let period = mix(2.0, 3.0, k);
  let breath = 1.0 - params.BREATH * (0.5 - 0.5 * cos(6.2831853 * (t / period + k)));
  return vec3f(tremble, lean, breath);
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let id = u32(p.seed);
  let wick = f32(id / 2u);
  let life = flameLife(wick, p.age);
  if ((id & 1u) == 1u) {
    // The halo: bounded, exactly zero at the card's edge.
    let r2 = dot(uv - vec2f(0.5), uv - vec2f(0.5)) * 4.0;
    let fall = max(1.0 - r2, 0.0);
    let glow = fall * fall * exp(-r2 * 4.0);
    let a = glow * params.GLOW * life.z * (1.0 + 0.15 * params.FLICKER * life.x);
    return vec4f(params.COLOR * params.INTENSITY * 0.12, clamp(a, 0.0, 1.0));
  }
  // In the flame's own units: y from the wick (0) to its tip (1), x in
  // half-widths from its axis.
  let y = uv.y * TALL / (1.0 + 0.12 * params.FLICKER * life.x);
  if (y >= 1.0) { return vec4f(0.0); }
  var x = (uv.x - 0.5) * 2.0 * ROOM;
  // The tip leans and the foot stays put; a finer waver runs up the edge.
  x = x - params.SWAY * 0.9 * life.y * y * y;
  x = x - 0.12 * params.FLICKER * flameNoise(p.age * 14.0 + y * 3.0 + wick) * y;
  // A teardrop: round at the foot, widest a quarter of the way up, drawn to a
  // point — narrowing a little as it stretches.
  let edge = sqrt(y) * pow(1.0 - y, 1.5) / 0.325 * (1.0 - 0.06 * params.FLICKER * life.x);
  let ax = abs(x);
  let body = 1.0 - smoothstep(edge * 0.35, edge, ax);
  let core = (1.0 - smoothstep(edge * 0.05, edge * 0.6, ax)) * smoothstep(0.02, 0.2, y) * (1.0 - smoothstep(0.35, 0.8, y));
  var c = mix(params.COLOR, mix(params.COLOR, vec3f(1.0, 0.92, 0.75), 0.75), core);
  c = mix(c, params.COLOR * vec3f(0.9, 0.45, 0.3), smoothstep(0.55, 1.0, y) * 0.6);
  c = mix(c, vec3f(0.15, 0.24, 0.6), (1.0 - smoothstep(0.0, 0.14, y)) * 0.7);
  return vec4f(c * params.INTENSITY * (1.0 + 0.2 * core), clamp(body * life.z, 0.0, 1.0));
}

#param color NEBULA #1a3c9c — the galaxy's colour
#param float TURN 20 0 360 — which way the band runs, in degrees
#param float STARS 0.6 0 1 — how crowded the stars are
#param float TWINKLE 0.6 0 1 — how fast they shimmer
#param float BRIGHTNESS 1 0 2 — the whole sky

// Galaxy Sky — a night sky with a galaxy across it, for any scene.
//
// Made after the night over X309's beach: a band of blue nebula, swirled and
// mottled, with teal filaments and dark dust lanes through it; a sky from near
// black overhead to deep blue at the horizon with a violet glow along it; and a
// dense field of stars — a few bright ones with spikes, many faint pinpoints —
// crowding along the band. It is the sky: it covers the backdrop, fixed to the
// world, so turning the camera turns across it.
//
// SHINING, IN DISPLAY SPACE. A field composites after tone mapping, where the
// engine clamps what this returns and nothing blooms, so a star's shine is
// drawn: a sharp core that goes white, a halo that keeps its colour, and
// diffraction spikes on the brightest — the construction Shining Stars uses —
// with each star on its own twinkle.
//
// SIX NOISE LOOKUPS A PIXEL: a swirl, three octaves of cloud, a ridged one for
// the filaments and their grain, one for the dust. Tuned on a numpy port of this
// file, looked at before it was written here.

const ZENITH = vec3f(0.004, 0.012, 0.047); // the sky overhead, #01030c
const LOW = vec3f(0.024, 0.082, 0.255);    // the sky toward the horizon, #061541
const WISP = vec3f(0.235, 0.71, 0.678);    // the bright filaments, #3cb5ad
const GLOW = vec3f(0.435, 0.227, 0.902);   // the glow along the horizon, #6f3ae6
const TILT = 30.0;        // how steeply the band climbs from the horizon, in degrees
const REACH = 0.24;       // a star's whole extent, in cell widths
const HALO = 0.18;        // the glow round a star
const SPIKE_THIN = 0.075; // how fine a star's spikes are

fn gxHash2(p: vec2f) -> vec2f {
  let q = vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}

// One layer of stars on a latitude-longitude grid, as (colour × energy, energy).
fn gxStars(sph: vec2f, scale: f32, thresh: f32, time: f32, speed: f32, spikes: f32, latCos: f32) -> vec4f {
  let cell = floor(sph * scale);
  let h = gxHash2(cell);
  let bright = gxHash2(cell + 7.31).x;
  if (bright < thresh) { return vec4f(0.0); }
  // At a hashed point in its cell, corrected for the projection's stretch.
  let local = (fract(sph * scale) - (0.15 + 0.7 * h)) * vec2f(latCos, 1.0);
  let d = length(local);
  let size = (bright - thresh) / (1.0 - thresh);
  let reach = REACH * (0.62 + 0.38 * size);
  if (d >= reach) { return vec4f(0.0); }
  let f = rzFalloff(d, reach);
  let core = f * f * f;
  let halo = f * HALO;
  var flare = 0.0;
  if (spikes > 0.0) {
    let rot = h.y * 6.2831853;
    let q = vec2f(local.x * cos(rot) - local.y * sin(rot), local.x * sin(rot) + local.y * cos(rot)) / reach;
    let ax = abs(q);
    flare = (rzFalloff(ax.x, 1.0) * rzFalloff(ax.y, SPIKE_THIN) + rzFalloff(ax.y, 1.0) * rzFalloff(ax.x, SPIKE_THIN)) * spikes * size * size;
  }
  let period = 0.25 + 2.75 * gxHash2(cell + 31.7).y;
  let twinkle = 0.45 + 0.55 * sin(time * speed * period + h.x * 40.0);
  let e = (core + flare + halo) * twinkle * (0.45 + 0.85 * size);
  let tint = mix(vec3f(0.7, 0.83, 1.0), vec3f(1.0, 0.95, 0.88), h.x);
  let colour = mix(tint, vec3f(1.0), clamp(core * 2.2, 0.0, 1.0));
  return vec4f(colour * e, e);
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let d = normalize(ray);
  // The galaxy's band: a great circle, tilted from the horizon and turned.
  let tilt = radians(TILT);
  let turn = radians(params.TURN);
  let axis = vec3f(sin(tilt) * sin(turn), cos(tilt), sin(tilt) * cos(turn));
  let b = dot(d, axis);
  let band = exp(-(b / 0.4) * (b / 0.4));
  let core = exp(-(b / 0.13) * (b / 0.13));

  // Its clouds: swirled once, then three octaves; a ridged octave for the
  // filaments and the mottled grain; one more for the dust lanes.
  let q = d * 2.2 + vec3f(3.1, 1.7, 5.2);
  let w = rzValueNoise(q * 0.9 + 17.0);
  let qw = q + (w - 0.5) * vec3f(2.2, -1.4, 1.6);
  let n = rzValueNoise(qw) * 0.55 + rzValueNoise(qw * 2.02 + 11.7) * 0.28 + rzValueNoise(qw * 4.05 + 23.1) * 0.17;
  let r = 1.0 - abs(2.0 * rzValueNoise(qw * 3.1 + 8.0) - 1.0);
  let dust = smoothstep(0.5, 0.72, rzValueNoise(q * 2.6 + 41.0));
  let fil = r * r * r * r;
  let density = n * (0.5 + 0.5 * band) + 0.15 * core;
  let body = smoothstep(0.32, 0.68, density) * (0.72 + 0.28 * r);
  var neb = params.NEBULA * body * 0.75;
  neb = neb + WISP * smoothstep(0.5, 0.8, density) * (0.35 + 0.9 * fil) * 0.6 * (0.3 + 0.7 * band);
  neb = neb + vec3f(0.8, 0.92, 1.0) * smoothstep(0.7, 0.95, density) * fil * 0.7 * band;
  neb = neb * (1.0 - 0.65 * dust * (0.4 + 0.6 * band));

  // The sky itself, darkened where the dust passes in front of the clouds.
  let sky = mix(LOW, ZENITH, smoothstep(0.0, 0.6, clamp(d.y, 0.0, 1.0)));
  var col = sky * (1.0 - 0.35 * dust * body) + neb;

  // The glow along the horizon, broken up by the same clouds.
  col = col + GLOW * exp(-(d.y * d.y) / 0.006) * (0.35 + 0.65 * n) * 0.21;

  // Stars in three sizes, crowding along the band.
  let sph = vec2f(atan2(d.x, d.z) * 1.2, asin(clamp(d.y, -1.0, 1.0)) * 1.5);
  let latCos = max(0.2, sqrt(max(0.0, 1.0 - d.y * d.y)));
  let s = clamp(params.STARS, 0.0, 1.0);
  var st = gxStars(sph, 22.0, mix(0.975, 0.9, s) - 0.05 * band, time, params.TWINKLE * 1.6, 1.0, latCos) * 1.8;
  st = st + 1.3 * gxStars(sph + 3.7, 60.0, mix(0.94, 0.72, s) - 0.12 * band, time, params.TWINKLE, 0.0, latCos);
  st = st + gxStars(sph + 9.1, 130.0, mix(0.9, 0.66, s) - 0.15 * band, time, params.TWINKLE * 0.6, 0.0, latCos);
  col = col + st.rgb;

  return vec4f(clamp(col * params.BRIGHTNESS, vec3f(0.0), vec3f(1.0)), 1.0);
}

#particles 24000
#blend additive
#bloom
#lights 1

#param float GATHER 1.3 0 3 — >1 crowds them toward the cast; 1 is an even spread
#param float RISE 0 0 0.3 — units a second upward; the game's motes do not rise
#param float WANDER 0.12 0 2 — units a second the noise pushes a mote: X340's is 0.12, X323's 1.6
#param float SIZE_MAX 0.16 0.02 0.4 — the largest mote; most are far smaller
#param float GAIN 7.0 1 14 — HDR brightness: white here is grey after the view transform
#param float LIGHT 0.6 0 3 — the lamp under them, warming the floor

// Ember Motes — warm points of light hanging in the air around the cast.
//
// A PORT OF A PARTICLE, IN FLOATING STARS' VOLUME AND AT ITS GRAIN. Aether
// Gazer's X340 draws this as one ParticleSystem named lizi (粒子): a box over
// the compass rose holding eighty motes, each born one of two warm tints,
// living five to ten seconds, fading in over the first two fifths and out over
// the rest, shrinking to nothing, not rising — start speed ±0.005, gravity 0 —
// and wandering on one octave of noise. Those are a mote's numbers here.
// X323 draws the same particle as lizi_2 — three hundred in a room-sized box,
// finer (1–3 mm), a beige dust rather than orange, wandering ten times as hard,
// each a nine-frame flake that crumbles away over its life. Its drift is the
// top of the WANDER dial.
//
// Everything about the FIELD is Floating Stars': the same cylinder round the
// cast, the same gather inward, the same count and the same sizes — a dust of
// fine points rather than a scatter of balls. The game's sprite is a flat white
// disc that its bloom turns into a glow; drawn as a disc here it read as
// spheres, so the sprite is the stars' instead — a hard core inside a soft
// halo, both reaching exactly zero at the quad's edge — and the glow is real
// rather than borrowed from the bloom.
//
// THE LAMP IS OURS. The game has no Lights module on this system; its floor
// warms only through bloom, which never enters shading. One lamp at the centre
// does what the field would aggregate to, at one slot.

// The volume — Floating Stars' cylinder.
const CENTER = vec3f(0.0, 0.0, 0.0);
const INNER = 1.5;        // clear of the body
const OUTER = 50.0;       // and how far out they reach
const FLOOR = 0.0;
const TOP = 58.0;

const LIFE_MIN = 5.0;
const LIFE_MAX = 10.0;
const SIZE_MIN = 0.03;
const SWIRL = 0.04;              // the noise's frequency, over a stage this size
// Its two tints, linear. startColor is a random blend between them, and the
// colour-over-life gradient holds 0.575 (gamma) across the whole life.
const TINT_A = vec3f(1.0, 0.257, 0.140);
const TINT_B = vec3f(1.0, 0.517, 0.194);
const GRADE = 0.29;              // 0.575 gamma, as light
const FADE_IN = 0.407;           // alpha reaches 1 at 26664 / 65535 of the life
const CORE = 0.17;               // core radius, in quad halves — the stars'
const HALO = 0.28;               // the soft glow round it, steady: an ember burns
const BRIGHT_VAR = 0.8;          // the faint many against the bright few

const LIGHT_COLOR = vec3f(1.0, 0.42, 0.18);
const LIGHT_R = 40.0;

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let a = rzHash13(seed + f32(id) * 0.0193);
  let b = rzHash13(seed * 1.61 + f32(id) * 0.0377);
  // Around the cast, gathered inward — Floating Stars' ring.
  let ang = a.x * 6.2831853;
  let radial = pow(sqrt(a.y), params.GATHER);
  let radius = mix(INNER, OUTER, radial);
  p.pos = CENTER + vec3f(cos(ang) * radius, mix(FLOOR, TOP, a.z), sin(ang) * radius);
  // Squared, so most are small and a few are the size the dial names.
  p.size = mix(SIZE_MIN, params.SIZE_MAX, b.x * b.x);
  p.vel = vec3f(0.0, params.RISE * mix(0.5, 1.5, b.y), 0.0);
  p.stretch = 0.0;
  p.rot = 0.0;
  p.life = mix(LIFE_MIN, LIFE_MAX, b.y);
  // Staggered, so the pool is not born on one frame: the game prewarms, and
  // this is the same thing.
  p.age = p.life * b.z;
  p.seed = seed + f32(id) * 0.0193;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // One octave, in x and y only — the game's strengthZ is 0. Curl so two motes
  // side by side do not trace the same thread.
  let w = rzCurlNoise(q.pos * SWIRL + vec3f(0.0, rzTime() * 0.05, 0.0));
  q.pos = q.pos + (q.vel + vec3f(w.x, w.y, 0.0) * params.WANDER) * dt;
  // Over the top and back to the floor, when the dial makes them climb.
  if (q.pos.y > TOP) { q.pos.y = FLOOR; }
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let r = length(q);
  let t = clamp(p.age / max(p.life, 1e-4), 0.0, 1.0);

  // Every piece reaches EXACTLY zero at the quad's edge — rzFalloff has compact
  // support — so bloom has no square to find. Squared rather than powed: pow is
  // undefined for a negative base.
  let cf = rzFalloff(r, CORE);
  let core = cf * cf;
  let halo = rzFalloff(r, 1.0) * HALO;

  // In over the first two fifths, out over the rest — the gradient's alpha keys.
  let fade = select(1.0 - (t - FADE_IN) / (1.0 - FADE_IN), t / FADE_IN, t < FADE_IN);
  // Shrinking to nothing is the size curve. Done on the profile rather than on
  // p.size, so the quad the engine culls by stays the size it was born at.
  let shrink = 1.0 - t;
  let cs = rzFalloff(r, max(CORE * shrink, 1e-3));
  let e = clamp(cs * cs + halo * shrink, 0.0, 1.0) * fade;
  if (e <= 0.0) { return vec4f(0.0); }

  // SHAPE in alpha, BRIGHTNESS in colour: the fragment is premultiplied, so a
  // profile carried in both would be squared.
  let tint = mix(TINT_A, TINT_B, rzHash11(p.seed * 5.09));
  let bv = rzHash11(p.seed * 11.71);
  let bright = mix(0.4, 1.0 + BRIGHT_VAR, bv * bv * bv);
  return vec4f(tint * GRADE * params.GAIN * bright, e);
}

/**
 * One lamp under the field. The motes together are a faint warm haze round
 * the cast; the lamp is that haze as light, and it breathes a little so it
 * reads as fire rather than as a fixture.
 */
fn lightEmitTuned(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  l.pos = CENTER + vec3f(0.0, 3.2, 0.0);
  l.color = LIGHT_COLOR;
  l.radius = LIGHT_R;
  l.intensity = params.LIGHT * (0.92 + 0.08 * sin(time * 2.3) * sin(time * 3.7));
  return l;
}

// Its light as tuned on the engine's old curve — brightness at the light, zero
// at the radius — carried onto the inverse square every light now falls off by:
// in Unity's units (no π); the bulb (near 2.5) is where that old curve flattened.
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l = lightEmitTuned(i, time);
  l.intensity = l.intensity * 0.64 * max(0.25 * l.radius * l.radius, 6.25);
  l.near = 2.5;
  return l;
}

