#param float INTENSITY 80 0 200 — how far past white the water glows: the game's _Color (9.3, 10.2, 10.9) is HDR, linear to its shader as that to the 2.2 — 134-190 — times its start colour
#param float OPACITY 0.2 0 1 — each splat's cover (the game's 0.31 times its material's 0.65)
#param color COLOR #b3e3ff

// Water Splash (splash bones) — where a fall lands, and a fountain's crown.
//
// A SPLASH IS A BONE whose name starts with "splash", on any model: the Unity
// stage converter writes one on each of the game's splash emitters, pointing
// the way the water leaves and as long as the game's largest splat there. A
// wide emitter comes as a row of them. Add your own in any PMX editor.
//
// WHAT THE GAME DRAWS, from X348's own particle systems: ten or so big splats
// a second on each emitter, tall (3.4-4.3 of the bone's 4 units high, 0.4-4
// wide), turned at random, growing from an eighth of their size to all of it
// and fading from halfway, gone in half a second to a second. They hardly
// move — every system clamps its particles to one unit a second, launch and
// gravity notwithstanding — so a splash is a crown standing on the water,
// not a spray of drops. Each is its colour eighty times over white at a fifth
// of cover — the game's HDR colour, linear — which is what makes even its
// faint fringe glow and bloom a metre wide; the half below the water is hidden
// by the water, as in the game.

// THE SPLAT: the game's picture (sc_light_white_043) drawn rather than sampled,
// since an effect carries no textures — a lumpy body pushed out by noise round
// its rim, a few short spikes, holes, and bright ridges where the water folds.
// q runs -1..1 across the sprite; s picks the splat.
fn splatHash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}

fn splatNoise(x: vec2f) -> f32 {
  let i = floor(x);
  let f = x - i;
  let u = f * f * (3.0 - 2.0 * f);
  let a = splatHash(i);
  let b = splatHash(i + vec2f(1.0, 0.0));
  let c = splatHash(i + vec2f(0.0, 1.0));
  let d = splatHash(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn splat(q: vec2f, s: f32) -> f32 {
  let r = length(q);
  let a = atan2(q.y, q.x);
  let dir = vec2f(cos(a), sin(a));
  let o = vec2f(s * 37.0, s * 91.0);
  let lump = splatNoise(dir * 2.2 + o);
  let fine = splatNoise(dir * 6.0 + o);
  let arms = pow(max(sin(a * 5.0 + s * 31.0), 0.0), 8.0) * 0.3 + pow(max(sin(a * 9.0 + s * 53.0), 0.0), 14.0) * 0.2;
  // a body as full as the game's picture, which fills about 70% of its card
  let rim = min(0.58 + 0.2 * lump + 0.06 * fine + arms * 0.7, 0.98);
  let body = 1.0 - clamp((r - (rim - 0.025)) / 0.025, 0.0, 1.0);
  let holes = clamp((splatNoise(q * 4.5 + o) - 0.78) / 0.04, 0.0, 1.0) * clamp((rim - 0.1 - r) / 0.1, 0.0, 1.0);
  let m = splatNoise(q * 5.0 + o.yx) * 0.65 + splatNoise(q * 9.0 + o) * 0.35;
  let ridge = 1.0 - abs(m * 2.0 - 1.0);
  // THE LIGHT IS IN THE VEINS: the game multiplies its splat by a caustic mask
  // (sc_Square_013), so most of a splat is all but clear and its folds carry the
  // light — at the game's HDR colour a solid body saturated into a white ball
  return body * (1.0 - holes) * (0.06 + 0.94 * pow(ridge, 4.0));
}

// A direction within `spread` radians of `up`.
fn splatCone(up: vec3f, spread: f32, r: vec3f) -> vec3f {
  let side = normalize(select(cross(up, vec3f(0.0, 0.0, 1.0)), cross(up, vec3f(1.0, 0.0, 0.0)), abs(up.z) > 0.9));
  let other = cross(up, side);
  let a = spread * sqrt(r.x);
  let turn = 6.2831853 * r.y;
  return up * cos(a) + (side * cos(turn) + other * sin(turn)) * sin(a);
}

// The splat's width and height in the game's units (the bone is 4.01 of them),
// fixed per particle by its seed so the step and the shade agree.
fn splashDims(seed: f32) -> vec2f {
  let h = rzHash13(seed * 7.13 + 0.5);
  return vec2f(mix(0.36, 4.01, h.x), mix(3.36, 4.34, h.y));
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let n = rzPointCount();
  if (n == 0u) { return p; }
  let pt = rzPoint(id % n);
  let axis = pt.tip - pt.pos;
  let len = length(axis);
  let up = select(vec3f(0.0, 1.0, 0.0), axis / max(len, 1e-5), len > 1e-5);
  let unit = max(len, 0.05) / 4.01;
  let r = rzHash13(seed + f32(id) * 0.371);
  let r2 = rzHash13(seed * 1.93 + f32(id) * 0.113);
  p.pos = pt.pos;
  p.vel = splatCone(up, radians(9.73), r) * mix(0.8, 1.0, r2.x) * unit;
  p.life = mix(0.5, 1.0, r2.y);
  p.seed = r.z;
  let d = splashDims(p.seed) * unit;
  p.size = 0.5 * max(d.x, d.y);
  p.rot = mix(-4.121944, -1.4276794, r2.z);
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  let d = splashDims(p.seed);
  let unit = 2.0 * p.size / max(d.x, d.y);
  // gravity 3-5 pulls it down, and the clamp holds it to a unit a second
  q.vel.y = q.vel.y - 4.0 * 9.81 * unit * dt;
  let v = length(q.vel);
  if (v > unit) { q.vel = q.vel * (unit / v); }
  q.pos = q.pos + q.vel * dt;
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let t = clamp(p.age / max(p.life, 1e-3), 0.0, 1.0);
  // the game's size over life (0.13, 0.40 at 45%, 1) and its fade from 45%
  let grow = select(mix(0.398, 1.0, (t - 0.45) / 0.55), mix(0.128, 0.398, t / 0.45), t < 0.45);
  let fade = select(1.0 - (t - 0.45) / 0.55, 1.0, t < 0.45);
  let d = splashDims(p.seed);
  let q = (uv * 2.0 - 1.0) / (d / max(d.x, d.y)) / grow;
  return vec4f(params.COLOR * params.INTENSITY, splat(q, p.seed) * fade * params.OPACITY);
}

