// Water Spray (spray bones) — the spray round a fountain's basin, the stream
// under its crown, the churn along a fall's foot.
//
// A SPRAY IS A BONE whose name starts with "spray": the Unity stage converter
// writes one on each of the game's lighter splash emitters, pointing the way
// the water leaves and as long as the game's largest splat there. Add your own
// in any PMX editor.
//
// WHAT THE GAME DRAWS, from X348's own particle systems: twenty to fifty small
// splats a second on each, 0.7-0.92 of the bone's length, turned at random and
// standing a little above their emitter (the game's pivot, 0.4 of a splat),
// growing from 0.42 of their size to all of it and gone in under a second.
// Like the splashes they hardly move — clamped to a unit a second — and glow:
// the game's HDR colour, linear, is 122 times over white at a sixth of cover.

// THE SPLAT: the game's picture (sc_light_white_043) drawn rather than sampled,
// since an effect carries no textures — a lumpy body pushed out by noise round
// its rim, a few short spikes, holes, and bright ridges where the water folds.
// q runs -1..1 across the sprite; s picks the splat.
fn splatHash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}

fn splatNoise(x: vec2f) -> f32 {
  let i = floor(x);
  let f = x - i;
  let u = f * f * (3.0 - 2.0 * f);
  let a = splatHash(i);
  let b = splatHash(i + vec2f(1.0, 0.0));
  let c = splatHash(i + vec2f(0.0, 1.0));
  let d = splatHash(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn splat(q: vec2f, s: f32) -> f32 {
  let r = length(q);
  let a = atan2(q.y, q.x);
  let dir = vec2f(cos(a), sin(a));
  let o = vec2f(s * 37.0, s * 91.0);
  let lump = splatNoise(dir * 2.2 + o);
  let fine = splatNoise(dir * 6.0 + o);
  let arms = pow(max(sin(a * 5.0 + s * 31.0), 0.0), 8.0) * 0.3 + pow(max(sin(a * 9.0 + s * 53.0), 0.0), 14.0) * 0.2;
  // a body as full as the game's picture, which fills about 70% of its card
  let rim = min(0.58 + 0.2 * lump + 0.06 * fine + arms * 0.7, 0.98);
  let body = 1.0 - clamp((r - (rim - 0.025)) / 0.025, 0.0, 1.0);
  let holes = clamp((splatNoise(q * 4.5 + o) - 0.78) / 0.04, 0.0, 1.0) * clamp((rim - 0.1 - r) / 0.1, 0.0, 1.0);
  let m = splatNoise(q * 5.0 + o.yx) * 0.65 + splatNoise(q * 9.0 + o) * 0.35;
  let ridge = 1.0 - abs(m * 2.0 - 1.0);
  // THE LIGHT IS IN THE VEINS: the game multiplies its splat by a caustic mask
  // (sc_Square_013), so most of a splat is all but clear and its folds carry the
  // light — at the game's HDR colour a solid body saturated into a white ball
  return body * (1.0 - holes) * (0.06 + 0.94 * pow(ridge, 4.0));
}

// A direction within `spread` radians of `up`.
fn splatCone(up: vec3f, spread: f32, r: vec3f) -> vec3f {
  let side = normalize(select(cross(up, vec3f(0.0, 0.0, 1.0)), cross(up, vec3f(1.0, 0.0, 0.0)), abs(up.z) > 0.9));
  let other = cross(up, side);
  let a = spread * sqrt(r.x);
  let turn = 6.2831853 * r.y;
  return up * cos(a) + (side * cos(turn) + other * sin(turn)) * sin(a);
}

// The splat's size against the bone, fixed per particle by its seed.
fn sprayScale(seed: f32) -> f32 {
  return mix(0.7, 0.92, rzHash13(seed * 7.13 + 0.5).x) / 0.92;
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let n = rzPointCount();
  if (n == 0u) { return p; }
  let pt = rzPoint(id % n);
  let axis = pt.tip - pt.pos;
  let len = length(axis);
  let up = select(vec3f(0.0, 1.0, 0.0), axis / max(len, 1e-5), len > 1e-5);
  let size = max(len, 0.05);
  let r = rzHash13(seed + f32(id) * 0.371);
  let r2 = rzHash13(seed * 1.93 + f32(id) * 0.113);
  p.seed = r.z;
  let full = size * sprayScale(p.seed);
  // the game's pivot stands the splat 0.4 of itself above where it was born
  p.pos = pt.pos + vec3f(0.0, 0.4 * full, 0.0);
  p.vel = splatCone(up, radians(20.0), r) * mix(0.6, 1.0, r2.x) * size;
  p.life = mix(0.4, 0.7, r2.y);
  p.size = 0.5 * full;
  p.rot = mix(-4.121944, -1.4276794, r2.z);
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  let unit = 2.0 * p.size / sprayScale(p.seed);
  q.vel.y = q.vel.y - 0.4 * 9.81 * unit * dt;
  let v = length(q.vel);
  if (v > unit) { q.vel = q.vel * (unit / v); }
  q.pos = q.pos + q.vel * dt;
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let t = clamp(p.age / max(p.life, 1e-3), 0.0, 1.0);
  // the game's size over life (0.42, 0.70 at 20%, 1); its dissolve fades the
  // splat out, here over the last third
  let grow = select(mix(0.696, 1.0, (t - 0.2) / 0.8), mix(0.4216, 0.696, t / 0.2), t < 0.2);
  let fade = 1.0 - smoothstep(0.67, 1.0, t);
  let q = (uv * 2.0 - 1.0) / grow;
  return vec4f(params.COLOR * params.INTENSITY, splat(q, p.seed) * fade * params.OPACITY);
}

#param float SIZE 1.0 0.4 1.4 — how tall the windows stand in the frame
#param float GAP 0.14 0 0.3 — the stone between one window and the next, in frame heights. Close them up for a vertical frame
#param float PIECES 46 8 120 — how many pieces of glass stand in the frame's height
#param float FIGURE 0.75 0 1 — how much she is glass: the lead across her and the colour of each piece. At 0 she is one painted piece
#param float JUMP 6 0 20 — seconds between her jumps from one window to another. At 0 she keeps the middle one
#param float LIGHT 1.0 0 2 — the light on the stone, and the shafts falling from the windows
#param float FOG 0.7 0 1.5 — the cloud at the foot

// Stained Glass — the shot, leaded into the windows of a church.
//
// THREE LANCETS AND TWO ROSES. The same tall light three times on one sill,
// each a little over twice as high as it is wide under an equilateral head,
// with stone between them. Up in the stone between the heads, a small rose
// each side: the crown that makes one front of three openings.
//
// GAP IS THAT STONE. Closed up, the three stand almost as one window, which
// is what a vertical frame wants; the roses keep their size and rise into the
// stone above the heads, where the spandrel is still wide enough to hold them.
//
// THEY DO NOT STAY PUT. Every JUMP seconds the figures are dealt to the
// lights again, at random. The windows do not change for it: the middle is
// always the niche with its glory, the left the Emperor's, the right the
// tree, and whoever lands in one stands before what is there.
//
// A FIGURE TO A LIGHT. The first of the cast has the middle one, the second
// the left, the third the right. A light with nobody in it carries ornament,
// never a second copy of someone: a window draws its force from the figure
// in it, and one dancer three times is a video wall.
//
// THE SHOT RUNS BEHIND THE WALL. A light with a figure holds the shot centred
// on that character's hips, so it follows them as they move. The others hold
// the shot as the middle light has it, so an arm thrown wide passes into the
// next light.
//
// THE GLASS IS CHARTRES, AND GRAVE. Deep cobalt and deep ruby, and most of
// the window dark: the light comes through as small jewels, not as a lit
// sheet. Green, pale blue, murrey and gold are there by the piece, a few in
// a hundred. The lead beside a piece takes the least trace of its colour,
// and now and then one catches the light. The grounds answer each
// other from light to light — cobalt behind one figure, ruby behind the next.
//
// A FIGURE'S LIGHT is a base at the foot, a band of its second ground; the
// niche, where she stands; and an arch of white fillet over it
// with the second ground above, painted with a fine diaper.
//
// THE MIDDLE LIGHT HOLDS A GLORY, and it is a window whether or not anybody
// stands in it. A mandorla, the almond a figure in majesty is given: a
// field of night in the window's own cut, sown with gold stars, with a sun
// high in it that comes behind a figure's head; round it a fillet, and a
// rim of short rays, gold and amber by turns. The field is dark, so a pale
// figure stands off it.
//
// THE TWO SIDE LIGHTS ARE TWO KINDS OF WINDOW, as neighbours in a nave are,
// and each has its subject. Nobody is drawn in them: the old glass names a
// person by what they carry, and so do these.
//
// ON THE LEFT, THE EMPEROR AND THE EMPRESS, as the tarot has them, in a
// medallion window built at three scales the way the thirteenth century
// built them, and in the card's colours: imperial purple and crimson, and
// everything picked out in gold. The ground is the window's own cut in
// crimson and purple, painted with a fine diaper. On it stand compound
// medallions, a canted square with a lobe on each side, and half medallions
// break in from the border between them, a gold fillet round every one.
// In the squares, up the light, their cards' numbers and what crowns them
// both: IV, III, and the laurel. Round IV, the Emperor's: the crown, the
// orb, the sword, the sceptre. Round III, the Empress's: her stars, the
// mirror of Venus, the rose, the heart. Round the laurel: the sun and the
// moon, the harp, the shield.
//
// ON THE RIGHT, THE FATHER AND THE SON, in a Tree of Jesse after the
// twelfth-century ones at Saint-Denis and in the west front of Chartres. A
// pale stem climbs the whole light. Up it stand almonds of ruby with what a
// king of the tree would be: the Chi-Rho, the chalice, the cross, the key,
// the mitre. Either side between them a scroll of white vine curls round an
// emblem of its own — the fish and the anchor, the knot of the Trinity and
// the daisy, the crozier and the star, the sun and the moon. The ground is
// open cobalt, no lattice: the two lights are told apart from across the
// church.
//
// NO EMBLEM STANDS TWICE IN A LIGHT.
//
// AN EMBLEM IS BRUSHED, NOT RULED. Its outline is drawn off true and wavers
// as a hand does; its yellow is silver stain, pale in one and amber in the
// next; and a matting wash darkens it toward its outline and its lower
// right, which is all the modelling old glass has and all it needs.
//
// AN EMBLEM IS DRAWN THREE TIMES OVER, as the glazier made it: cut to its
// outline in gold, a second glass set into it where it is jewelled or red,
// and then painted — the groove down a blade and the wire on its grip, the
// scales and gill of the fish, the bands of the crown and the orb, a line
// down every ray of the star.
//
// ONE LIGHT MODEL FOR EVERY PIECE. A mosaic piece, a square of the diaper, a
// petal, a border block, its bead, a length of fillet: each is described by
// its pot, its own random pair and this point's distance to its lead, and
// all of them are lit by the same few lines. NO PIECE IS FLAT: each is
// brightest in its middle and dark toward the lead, streaked one way, its
// own, and seeded with small bubbles; each cobalt leans to violet or to cyan
// and each ruby to crimson or to orange; and the day behind is brighter up
// the light and drifts across it. THE LEAD IS HEAVY, a real bar of metal.
//
// THE MOSAIC is the butterfly window's on Shadertoy (a fork of Yrai's
// "Flourescent butterfly", CC BY-NC-SA 3.0): a Voronoi cut, the lead its
// distance to the piece's border. The stage does not show through the
// glass: what is behind it is the sky.
//
// SHE IS PAINTED ON THE GLASS, AND SHE DANCES. Not a figure behind a window:
// the figure in it. rzCastDistance is her silhouette, and the band of dark
// just outside it is the came that sets her into the ground.
//
// What makes her the window's is the cut and the light. The same mosaic
// runs through her, in a figure's lead, finer than the ground's, each line
// with its soft shadow; the came round her throws one on the ground. And
// the window's light falls on her as on the glass beside her — the day
// behind, the sheen, the sun — but only what varies smoothly across her.
// Nothing is decided piece by piece, so no piece of her is grey beside a
// white one.
//
// SHE IS LEADED ALONG HER OWN FORMS. The outline round her is what sets her
// in the window, and the same line is drawn inside her wherever one part
// of her stands in front of another — an arm over her body, hair over a
// shoulder. Those are found from her depth and are hers, moving with her.
// And every line of the mosaic across her has a soft shadow several pixels
// wide, the same in every piece, which is what gives the cut its weight.
//
// HER DRAWING IS PAINTED BACK IN, AND ONLY HER DRAWING. The lead across her
// is a random cut and knows nothing of her; the lines that say who she is —
// an eye, a strand of hair, the edge of a sleeve — the scene draws a pixel
// or two wide. So a stroke that is plainly darker than what is round it is
// laid on again in dark paint, as a glazier traces a figure. Shading is not
// a line and is left alone: a figure inked at every change of tone is a
// scribble.
//
// What stays hers is the drawing. Each piece is a little deeper in colour
// than the scene drew it and leans its own way in hue, then is set back to
// the brightness the scene gave it; the picture is a little sharper than it
// came; nothing is blended across a piece and nothing is moved.
//
// IT IS GLASS, NOT PAINT, BY TWO THINGS. It is seen through: behind it is a
// sky, warm at the horizon and blue above with cloud drifting over, coloured
// by each piece and bent by each a little differently, so a cloud's edge
// carries from piece to piece and breaks at the lead. And it has a surface:
// a pale highlight crosses it that is the room in the glass, not the glass's
// own colour.
//
// IT IS A WINDOW BECAUSE THE LIGHT COMES THROUGH IT. There is a sun behind
// the wall, a bright place that drifts slowly across: the pieces in front
// of it flare in their own colours and whiten at its heart, and go down
// again as it passes. Round a bright piece the lead takes its colour. Each
// light throws its colour on the stone about it, and under each the cloud
// holds a pool of it, wider the further it has fallen.
//
// NOTHING IN IT IS RULED. An old window is cut by hand and mended for seven
// hundred years. The ornament is drawn on a wall that wanders a few pixels,
// so no line of it is straight; the lead is thicker in one place than the
// next; the squares of the diaper are not one size, and here and there one
// is a mend in a pot that does not belong; the border's blocks are uneven
// lengths, its beads uneven, and its inner edge wavers.
//
// NOTHING IN IT IS STILL, AND NOTHING HURRIES. The two roses turn, each the
// other way, glass and lead together under a day that stays where it is, so
// a piece changes as it passes through the light. The day itself drifts as
// cloud would move it. A sheen crosses the windows a few times a minute and
// every piece answers it by its own amount. The glory breathes outward
// along its rays, and the light on the reveals swells and falls.
//
// THE WALL IS AN OLD CHURCH'S, AND IT IS DARK. The inside of a church by a
// lit window is black stone that the window's own light finds: it shows
// only within reach of an opening and goes out beyond it. Nothing is drawn
// on it, no course and no joint — a face of stone, quietly mottled and
// stained in runs.
//
// A WINDOW IS SET INTO IT, NOT DRAWN ON IT. Each opening has a splay, the
// wall's thickness cut back at a slope to the glass: dark in the corner
// against the lead, a little lit down the side that faces the light, which
// is what says the wall is deep.
//
// Shafts fall from the windows through the air in front, and cloud lies at
// the foot.
//
// THAT LIGHT HAS COME THROUGH THE GLASS, so it is the glass's colours and
// not one pale blue: cobalt, violet, rose and gold, a shaft of each, the
// reveal turning from one to the next along the wall, and the cloud glowing
// where it catches them. It lies on the stone and the air beside the
// windows; over the glass itself it is held back, so the leading stays
// sharp.

// EACH POINT DOES ONLY ITS OWN WORK. The glass is worked out inside the
// openings and the stone outside them; the four extra readings of the frame
// that sharpen her are taken only where she is; the cloud only below the
// line it can rise to, and the shafts only where they fall.

// Everything below is in frame heights at SIZE 1, y DOWN, the origin at the
// frame's centre.
const SILL: f32 = 0.46;
// A light: half its width, the height of its straight sides, and the pitch
// from one to the next. The head is the equilateral arch, struck from the
// opposite springer at twice the half width, so a light stands its sides
// plus 1.732 half widths: 0.92.
const HW: f32 = 0.20;
const HB: f32 = 0.5736;
// The pitch is a dial: two half widths and the GAP between, 0.54 at its default.
// The roses: how high they sit and their radius. Each is midway between two
// lights.
// ROSE_Y is where it sits at the default GAP; closer lights lift it (sgRoseY).
const ROSE_Y: f32 = -0.36;
const ROSE_R: f32 = 0.085;
const ROSE_TURN: f32 = 0.06;    // radians a second
// The panels of a light: the base's height.
const BASE_H: f32 = 0.115;
const STRIP: f32 = 0.009;       // a white fillet
// The border inside the stone: its width, the white fillet beside it, the
// length of one block along it and the radius of the bead in the block.
const BAND: f32 = 0.020;
const FILLET: f32 = 0.007;
const BLOCK: f32 = 0.031;
const BEAD: f32 = 0.0052;
const DIAPER: f32 = 0.0095;     // the painted lattice's pitch
const MED_PITCH: f32 = 0.40;
const MED_FOOT: f32 = 0.215;
const DIAMOND: f32 = 0.090;
const LOBE_R: f32 = 0.064;
const LOBE_AT: f32 = 0.108;
const HALF_R: f32 = 0.066;
// The radius an emblem is drawn to in a lobe, and in the square.
const EMBLEM: f32 = 0.046;
// How much an emblem's outline is fattened, in its own units, so a blade or
// a rod is wide enough to carry gold between its leads; how much narrower
// the lead is inside an emblem; and how much brighter its glass.
const BOLD: f32 = 0.030;
const FINE_LEAD: f32 = 2.0;
const EMBLEM_LIFT: f32 = 1.12;
// Silver stain, the glazier's yellow: from pale lemon to deep amber, and no
// two emblems quite the same.
const STAIN_PALE = vec3f(0.92, 0.78, 0.30);
const STAIN_DEEP = vec3f(0.74, 0.42, 0.06);
const CHARGE: f32 = 0.057;
// The tree: the pitch from one almond to the next and the height of the
// lowest one's centre above the base; an almond's half height and half
// width; where a scroll's centre stands out from the stem, its radius, and
// half the vine's width; and the radius an emblem is drawn to in a scroll
// and in an almond.
const TREE_PITCH: f32 = 0.22;
const TREE_FOOT: f32 = 0.135;
const ALMOND_H: f32 = 0.098;
const ALMOND_W: f32 = 0.064;
const SCROLL_AT: f32 = 0.118;
const SCROLL_R: f32 = 0.049;
const VINE: f32 = 0.0075;
const SCROLL_EMBLEM: f32 = 0.029;
const TREE_EMBLEM: f32 = 0.043;
// The mandorla: the height of its middle above the sill, and its half
// height and half width.
const GLORY_Y: f32 = 0.50;
const GLORY_H: f32 = 0.36;
const GLORY_W: f32 = 0.150;
// In it: the width of its sunburst rim; how far above its middle the sun
// stands and the sun's radius; the pitch of the stars and a star's radius.
const GLORY_RIM: f32 = 0.030;
const SUN_UP: f32 = 0.17;
const SUN_R: f32 = 0.062;
const STAR_PITCH: f32 = 0.058;
const STAR_R: f32 = 0.0125;
const REACH: f32 = 0.24;        // how far the light spills onto the stone
const LEAD = vec3f(0.020, 0.016, 0.020);   // the lead
const COBALT = vec3f(0.035, 0.14, 0.70);
const RUBY = vec3f(0.66, 0.025, 0.06);
const GOLD = vec3f(0.86, 0.56, 0.09);
const GREEN = vec3f(0.04, 0.42, 0.20);
const SKY = vec3f(0.42, 0.66, 0.92);
const MURREY = vec3f(0.42, 0.10, 0.30);
const NIGHT = vec3f(0.035, 0.05, 0.34);     // the field of the glory
const VIOLET = vec3f(0.30, 0.07, 0.52);    // the imperial purple
const CRIMSON = vec3f(0.50, 0.02, 0.07);   // and the red it is set in
const PEARL = vec3f(0.92, 0.93, 0.86);
const GLORY = vec3f(0.62, 0.22, 0.05);     // the deep amber ray of the mandorla
// The wall's stone.
const STONE_WARM = vec3f(0.150, 0.136, 0.118);
const STONE_COOL = vec3f(0.132, 0.134, 0.138);
// How wide an opening's splay is, out from the glass.
const SPLAY: f32 = 0.0045;
// The soft darkening outside an opening's edge: how deep at the edge, and
// the distance over which it falls to about a third.
const EDGE_SHADE: f32 = 0.34;
const EDGE_REACH: f32 = 0.0075;
const CLOUD = vec3f(0.50, 0.56, 0.72);     // cloud in no light
const EXPOSURE: f32 = 1.9;      // the light through a piece at its brightest
const CAME: f32 = 0.0019;       // the came round her and along her forms: the width of the mosaic's lead
const WANDER: f32 = 0.011;      // how far the hand strays, edge to edge
// Her drawing: how much darker than its surroundings a point must be to
// begin to be inked, and to be inked in full; and the paint.
const TRACE_FROM: f32 = 0.030;
const TRACE_FULL: f32 = 0.170;
const TRACE_PAINT = vec3f(0.085, 0.055, 0.045);
// How far into a piece of her the lead's shadow reaches, in pieces.
const LEAD_SHADOW: f32 = 0.22;
// The lead everywhere, on the ground and on her: where a piece's edge is
// all lead, and where it is all glass, in pieces. Close together, so the
// line is thin and its edge clean.
const LEAD_IN: f32 = 0.017;
const LEAD_OUT: f32 = 0.036;
// The came inside her: how large a step in her depth, as a part of her
// distance from the eye, begins a line, and makes a whole one.
const INNER_FROM: f32 = 0.012;
const INNER_FULL: f32 = 0.030;
const HER_LIFT: f32 = 1.28;     // how much brighter she is drawn, to match the glass
const SHARPEN: f32 = 0.20;      // how hard her picture's edges are drawn back in
// How far a piece's point may sit from its cell's edge. Kept in from the
// corners so the nearest border is always one of the eight cells around.
const JITTER_MIN: f32 = 0.15;
const JITTER_SPAN: f32 = 0.7;
const TAU: f32 = 6.2831853;

struct SgCell {
  rnd: vec2f,   // the piece's own random pair
  edge: f32,    // distance to the piece's border, in cells
  to: vec2f,    // from this point toward the piece's own point, in cells
}

fn sgHash2(p: vec2f) -> vec2f {
  return fract(sin(vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)))) * 43758.5453);
}

/** The demo's voro(): nearest point, then the true distance to its border. */
fn sgVoro(at: vec2f) -> SgCell {
  let id = floor(at);
  let f = fract(at);
  var best = 10.0;
  var mDiff = vec2f(0.0);
  var mNear = vec2f(0.0);
  var mRnd = vec2f(0.0);
  for (var j = -1; j <= 1; j = j + 1) {
    for (var i = -1; i <= 1; i = i + 1) {
      let g = vec2f(f32(i), f32(j));
      let h = sgHash2(id + g);
      let diff = g + vec2f(JITTER_MIN) + JITTER_SPAN * h - f;
      let d = dot(diff, diff);
      if (d < best) { best = d; mDiff = diff; mNear = g; mRnd = h; }
    }
  }
  var edge = 10.0;
  for (var j = -1; j <= 1; j = j + 1) {
    for (var i = -1; i <= 1; i = i + 1) {
      if (i == 0 && j == 0) { continue; }
      let g = mNear + vec2f(f32(i), f32(j));
      let diff = g + vec2f(JITTER_MIN) + JITTER_SPAN * sgHash2(id + g) - f;
      let across = diff - mDiff;
      edge = min(edge, dot(0.5 * (mDiff + diff), across / max(length(across), 1.0e-5)));
    }
  }
  return SgCell(mRnd, edge, mDiff);
}

/** Value noise, 0..1. */
fn sgNoise(p: vec2f) -> f32 {
  let i = floor(p);
  var f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(sgHash2(i).x, sgHash2(i + vec2f(1.0, 0.0)).x, f.x),
             mix(sgHash2(i + vec2f(0.0, 1.0)).x, sgHash2(i + vec2f(1.0, 1.0)).x, f.x), f.y);
}

/** Two value noises for the price of one, each 0..1. */
fn sgNoise2(p: vec2f) -> vec2f {
  let i = floor(p);
  var f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(sgHash2(i), sgHash2(i + vec2f(1.0, 0.0)), f.x),
             mix(sgHash2(i + vec2f(0.0, 1.0)), sgHash2(i + vec2f(1.0, 1.0)), f.x), f.y);
}

/** Value noise along a line, 0..1. */
fn sgNoise1(x: f32) -> f32 {
  let i = floor(x);
  var f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(fract(sin(i * 127.1) * 43758.5453), fract(sin((i + 1.0) * 127.1) * 43758.5453), f);
}

/** The light the windows throw: cobalt, violet, rose, gold, and round again. */
fn sgSpectrum(x: f32) -> vec3f {
  let t = fract(x) * 4.0;
  let cobalt = vec3f(0.30, 0.50, 1.00);
  let violet = vec3f(0.70, 0.40, 1.00);
  let rose = vec3f(1.00, 0.38, 0.55);
  let gold = vec3f(1.00, 0.78, 0.35);
  if (t < 1.0) { return mix(cobalt, violet, t); }
  if (t < 2.0) { return mix(violet, rose, t - 1.0); }
  if (t < 3.0) { return mix(rose, gold, t - 2.0); }
  return mix(gold, cobalt, t - 3.0);
}

/** A colour's brightest channel: how light it is whatever its hue. */
fn sgValue(c: vec3f) -> f32 { return max(c.r, max(c.g, c.b)); }

fn sgLuma(c: vec3f) -> f32 { return dot(c, vec3f(0.299, 0.587, 0.114)); }

/** A turn about the grey axis, in whole turns. */
fn sgHue(c: vec3f, turns: f32) -> vec3f {
  let axis = vec3f(0.57735);
  let p = axis * dot(axis, c);
  let u = c - p;
  let a = turns * TAU;
  return u * cos(a) + cross(axis, u) * sin(a) + p;
}

/** Signed distance to a lancet, negative inside. The origin is the middle of its sill. */
fn sgLancet(p: vec2f, hw: f32, hb: f32) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  // The true distance, so that outside a foot of the light it runs round the
  // corner and anything drawn at a distance from it does too.
  let d = vec2f(q.x - hw, q.y);
  let body = length(max(d, vec2f(0.0))) + min(max(d.x, d.y), 0.0);
  let head = length(vec2f(q.x + hw, q.y + hb)) - 2.0 * hw;
  return select(body, head, q.y < -hb);
}

/** From one light's middle to the next's: two half widths and the stone between. */
fn sgPitch() -> f32 { return 2.0 * HW + clamp(params.GAP, 0.0, 1.0); }

/**
 * How high a rose sits. At the default GAP, ROSE_Y; as the lights close it
 * rises, just far enough to keep the clearance it has there from the heads
 * either side. A head's near side is an arc struck from the far springer,
 * radius 2 HW, so that clearance is a distance from the arc's centre, and
 * the rose rides up the circle round it at that distance.
 */
fn sgRoseY() -> f32 {
  let arc = vec2f(-HW, SILL - HB);
  let keep = length(vec2f(0.54 * 0.5, ROSE_Y) - arc);
  let dx = sgPitch() * 0.5 - arc.x;
  return min(ROSE_Y, arc.y - sqrt(max(keep * keep - dx * dx, 0.0)));
}

/** Signed distance to the nearest opening, a light or a rose, negative inside. */
fn sgOpening(g: vec2f) -> f32 {
  let k = clamp(round(g.x / sgPitch()), -1.0, 1.0);
  let lancet = sgLancet(vec2f(g.x - k * sgPitch(), g.y - SILL), HW, HB);
  let rose = length(vec2f(abs(g.x) - sgPitch() * 0.5, g.y - sgRoseY())) - ROSE_R;
  return min(lancet, rose);
}

/** A drawn lead line about a distance's zero: 0 on the line, 1 off it. */
fn sgLine(d: f32) -> f32 {
  return smoothstep(0.0015, 0.0030, abs(d));
}

/**
 * A ground: mostly its first pot, about one piece in ten the second, and
 * the rest of the palette a few in a hundred.
 */
fn sgGround(first: vec3f, second: vec3f, pick: f32) -> vec3f {
  var c = first;
  if (pick > 0.78) { c = second; }
  if (pick > 0.88) { c = GREEN; }
  if (pick > 0.93) { c = SKY; }
  if (pick > 0.96) { c = MURREY; }
  if (pick > 0.985) { c = GOLD; }
  return c;
}

/** A round-ended taper from a (radius ra) to b (radius rb). */
fn sgTaper(p: vec2f, a: vec2f, b: vec2f, ra: f32, rb: f32) -> f32 {
  let ab = b - a;
  let t = clamp(dot(p - a, ab) / dot(ab, ab), 0.0, 1.0);
  return length(p - a - t * ab) - mix(ra, rb, t);
}

fn sgBox(p: vec2f, c: vec2f, h: vec2f) -> f32 {
  let d = abs(p - c) - h;
  return length(max(d, vec2f(0.0))) + min(max(d.x, d.y), 0.0);
}

/**
 * Petals round a centre: n of them, each a taper along its own radius.
 * p is in units of the flower's radius.
 */
fn sgPetals(p: vec2f, n: f32, a0: f32, a1: f32, r0: f32, r1: f32) -> f32 {
  let sector = TAU / n;
  let ang = atan2(p.y, p.x);
  let fold = ang - sector * round(ang / sector);
  return sgTaper(vec2f(cos(fold), sin(fold)) * length(p), vec2f(a0, 0.0), vec2f(a1, 0.0), r0, r1);
}

/**
 * A fleur-de-lis about one unit tall, y up: the middle petal a pointed lens,
 * a petal each side that rises and hooks over, the band, and the feet.
 */
fn sgFleur(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  // The lens is where two circles of radius r overlap: half height 0.52,
  // half width 0.165.
  let r = (0.52 * 0.52 + 0.165 * 0.165) / (2.0 * 0.165);
  let middle = length(q - vec2f(0.165 - r, 0.10)) - r;
  let petal = min(sgTaper(q, vec2f(0.07, -0.10), vec2f(0.34, 0.30), 0.07, 0.085),
                  sgTaper(q, vec2f(0.34, 0.30), vec2f(0.47, 0.06), 0.085, 0.04));
  let band = sgBox(q, vec2f(0.0, -0.17), vec2f(0.23, 0.042));
  let foot = sgTaper(q, vec2f(0.07, -0.24), vec2f(0.21, -0.44), 0.05, 0.025);
  return min(min(middle, petal), min(band, foot));
}

// The emblems, each drawn to a radius of about one, y up.

/** A crown: a band, three points and a pearl on each. */
fn sgCrown(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let band = sgBox(q, vec2f(0.0, -0.36), vec2f(0.56, 0.13));
  let middle = sgTaper(q, vec2f(0.0, -0.25), vec2f(0.0, 0.42), 0.17, 0.04);
  let side = sgTaper(q, vec2f(0.40, -0.25), vec2f(0.52, 0.24), 0.14, 0.04);
  let pearls = min(length(q - vec2f(0.0, 0.56)) - 0.10, length(q - vec2f(0.55, 0.38)) - 0.09);
  return min(min(band, middle), min(side, pearls));
}

/** The sun: a disc and sixteen rays. */
fn sgSun(p: vec2f) -> f32 {
  return min(length(p) - 0.38, sgPetals(p, 16.0, 0.48, 0.92, 0.075, 0.0));
}

/** The moon: a crescent, open to the right. */
fn sgMoon(p: vec2f) -> f32 {
  return max(length(p) - 0.66, 0.56 - length(p - vec2f(0.30, 0.08)));
}

/** A star of eight points. */
fn sgStar(p: vec2f) -> f32 {
  return min(sgPetals(p, 8.0, 0.0, 0.92, 0.19, 0.0), length(p) - 0.24);
}

/** A rose: six petals round an eye. */
fn sgRose(p: vec2f) -> f32 {
  return min(sgPetals(p, 6.0, 0.34, 0.70, 0.11, 0.25), length(p) - 0.16);
}

/** A cross pattee: four arms that widen to the rim. */
fn sgCross(p: vec2f) -> f32 {
  return max(sgPetals(p, 4.0, 0.0, 0.70, 0.11, 0.30), length(p) - 0.86);
}

/** A daisy: sixteen narrow petals round a wide eye. */
fn sgDaisy(p: vec2f) -> f32 {
  return min(sgPetals(p, 16.0, 0.34, 0.84, 0.055, 0.09), length(p) - 0.24);
}

/** A sword, point up: a blade tapering to its point, a guard that droops to a knob each end, grip and pommel. */
fn sgSword(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let blade = sgTaper(q, vec2f(0.0, -0.20), vec2f(0.0, 0.96), 0.095, 0.0);
  let guard = min(sgTaper(q, vec2f(0.0, -0.24), vec2f(0.40, -0.31), 0.055, 0.04), length(q - vec2f(0.43, -0.32)) - 0.07);
  return min(min(blade, guard), min(sgBox(q, vec2f(0.0, -0.50), vec2f(0.05, 0.20)), length(q - vec2f(0.0, -0.80)) - 0.13));
}

/** A heater shield. Its cross is set in. */
fn sgShield(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  return max(q.y - 0.72, length(q - vec2f(-0.55, 0.45)) - 1.30);
}

/** A chalice: bowl, stem with its knop, and foot. */
fn sgChalice(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let bowl = max(length(q - vec2f(0.0, 0.58)) - 0.46, q.y - 0.64);
  let stem = min(sgBox(q, vec2f(0.0, -0.12), vec2f(0.055, 0.30)), length(q - vec2f(0.0, -0.04)) - 0.13);
  let foot = min(sgTaper(q, vec2f(0.0, -0.40), vec2f(0.0, -0.66), 0.06, 0.30), sgBox(q, vec2f(0.0, -0.70), vec2f(0.36, 0.05)));
  return min(min(bowl, stem), foot);
}

/** A key: a trefoil bow, a collared shaft, and wards cut like a comb. */
fn sgKey(p: vec2f) -> f32 {
  let bow = min(min(abs(length(p - vec2f(0.0, 0.74)) - 0.14) - 0.055, abs(length(p - vec2f(-0.19, 0.50)) - 0.14) - 0.055),
                min(abs(length(p - vec2f(0.19, 0.50)) - 0.14) - 0.055, length(p - vec2f(0.0, 0.58)) - 0.07));
  let shaft = min(sgBox(p, vec2f(0.0, -0.22), vec2f(0.055, 0.56)), min(length(p - vec2f(0.0, 0.26)) - 0.10, length(p - vec2f(0.0, 0.10)) - 0.08));
  let wards = min(sgBox(p, vec2f(0.17, -0.66), vec2f(0.13, 0.06)), min(sgBox(p, vec2f(0.15, -0.44), vec2f(0.11, 0.05)), sgBox(p, vec2f(0.25, -0.55), vec2f(0.045, 0.13))));
  return min(min(bow, shaft), wards);
}

/** The numeral III, the Empress's card: three strokes between two bars. */
fn sgThree(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let strokes = min(sgBox(q, vec2f(0.0, 0.0), vec2f(0.075, 0.50)), sgBox(q, vec2f(0.34, 0.0), vec2f(0.075, 0.50)));
  return min(strokes, sgBox(vec2f(q.x, abs(q.y)), vec2f(0.0, 0.56), vec2f(0.56, 0.065)));
}

/** The numeral IV, the Emperor's: a stroke and a V between two bars. */
fn sgFour(p: vec2f) -> f32 {
  let vee = min(sgTaper(p, vec2f(-0.06, 0.50), vec2f(0.24, -0.50), 0.075, 0.06), sgTaper(p, vec2f(0.54, 0.50), vec2f(0.24, -0.50), 0.06, 0.06));
  let bars = sgBox(vec2f(p.x, abs(p.y)), vec2f(0.0, 0.56), vec2f(0.66, 0.065));
  return min(min(sgBox(p, vec2f(-0.42, 0.0), vec2f(0.075, 0.50)), vee), bars);
}

/** A laurel wreath: two sprays of leaves up a ring, open at the top, tied at the foot. */
fn sgLaurel(p: vec2f) -> f32 {
  let r = length(p);
  // Round from the foot, the same both sides: nine leaf places, the last
  // left empty for the opening.
  let a = abs(atan2(p.x, -p.y));
  let sec = 3.1416 / 9.0;
  let mid = (clamp(floor(a / sec), 0.0, 7.0) + 0.5) * sec;
  // Each leaf is an ellipse lying along the ring, tilted outward.
  let lp = vec2f((a - mid) * 0.62, r - 0.62);
  let lq = vec2f(lp.x * 0.8776 + lp.y * 0.4794, lp.y * 0.8776 - lp.x * 0.4794);
  let leaf = select((length(lq / vec2f(0.17, 0.075)) - 1.0) * 0.075, 1.0, a > 8.0 * sec);
  let stem = max(abs(r - 0.60) - 0.022, a - 8.0 * sec);
  return min(min(leaf, stem), sgBox(p, vec2f(0.0, -0.62), vec2f(0.10, 0.07)));
}

/** The mirror of Venus: a ring on a cross. */
fn sgVenus(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  return min(abs(length(q - vec2f(0.0, 0.34)) - 0.30) - 0.065, min(sgBox(q, vec2f(0.0, -0.42), vec2f(0.065, 0.40)), sgBox(q, vec2f(0.0, -0.46), vec2f(0.27, 0.065))));
}

/** A ring of radius r about c, t either side of it. */
fn sgRing(p: vec2f, c: vec2f, r: f32, t: f32) -> f32 {
  return abs(length(p - c) - r) - t;
}

/** The orb: a globe with a cross on it. Its bands are painted. */
fn sgOrb(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  return min(length(p - vec2f(0.0, -0.22)) - 0.44, min(sgBox(q, vec2f(0.0, 0.50), vec2f(0.05, 0.30)), sgBox(q, vec2f(0.0, 0.56), vec2f(0.19, 0.05))));
}

/** A sceptre: a rod with a knop, a fleur-de-lis at its head. */
fn sgSceptre(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let rod = min(sgBox(q, vec2f(0.0, -0.22), vec2f(0.04, 0.62)), length(q - vec2f(0.0, -0.88)) - 0.08);
  return min(min(rod, length(q - vec2f(0.0, 0.36)) - 0.09), sgFleur((p - vec2f(0.0, 0.66)) / 0.62) * 0.62);
}

/** A bishop's mitre: the pointed cap, its band and its two lappets. */
fn sgMitre(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  var cap = max(length(q - vec2f(-0.83, -0.33)) - 1.25, -(q.y + 0.33));
  cap = max(cap, -sgBox(q, vec2f(0.0, 0.08), vec2f(0.04, 0.30)));
  return min(cap, min(sgBox(q, vec2f(0.0, -0.42), vec2f(0.44, 0.07)), sgTaper(q, vec2f(0.20, -0.52), vec2f(0.27, -0.90), 0.075, 0.06)));
}

/** A crozier: the staff, and the crook curling over to the left. */
fn sgCrozier(p: vec2f) -> f32 {
  let crook = max(sgRing(p, vec2f(-0.10, 0.42), 0.26, 0.05), min(-(p.x + 0.10), 0.42 - p.y));
  let staff = sgBox(p, vec2f(0.16, -0.25), vec2f(0.045, 0.68));
  return min(min(crook, staff), min(length(p - vec2f(-0.36, 0.42)) - 0.07, length(p - vec2f(0.16, 0.44)) - 0.07));
}

/** The Chi-Rho. */
fn sgChiRho(p: vec2f) -> f32 {
  let chi = min(sgTaper(p, vec2f(-0.42, -0.50), vec2f(0.42, 0.36), 0.055, 0.055), sgTaper(p, vec2f(0.42, -0.50), vec2f(-0.42, 0.36), 0.055, 0.055));
  let rho = min(sgTaper(p, vec2f(0.0, -0.85), vec2f(0.0, 0.78), 0.055, 0.055), max(sgRing(p, vec2f(0.20, 0.56), 0.21, 0.05), -p.x));
  return min(chi, rho);
}

/** The fish, swimming left: a body of two arcs, a crescent tail, a fin above and two below. */
fn sgFish(p: vec2f) -> f32 {
  let q = vec2f(p.x, abs(p.y));
  let hull = length(q - vec2f(-0.10, -0.60)) - 0.90;
  let tail = max(length(p - vec2f(0.84, 0.0)) - 0.42, 0.38 - length(p - vec2f(1.06, 0.0)));
  let fins = min(sgTaper(p, vec2f(-0.08, 0.24), vec2f(0.14, 0.54), 0.12, 0.0),
                 min(sgTaper(p, vec2f(-0.18, -0.24), vec2f(-0.02, -0.48), 0.08, 0.0), sgTaper(p, vec2f(0.26, -0.20), vec2f(0.38, -0.40), 0.06, 0.0)));
  return min(min(hull, tail), fins);
}

/** The knot of the Trinity: three rings through one another. */
fn sgTrinity(p: vec2f) -> f32 {
  let rings = min(sgRing(p, vec2f(0.0, 0.30), 0.50, 0.05),
                  min(sgRing(p, vec2f(-0.2598, -0.15), 0.50, 0.05), sgRing(p, vec2f(0.2598, -0.15), 0.50, 0.05)));
  return max(rings, length(p) - 0.80);
}

/** An anchor: ring, stock, shank, and the arms with their flukes. */
fn sgAnchor(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let shank = min(sgBox(q, vec2f(0.0, 0.02), vec2f(0.045, 0.60)), min(sgRing(q, vec2f(0.0, 0.74), 0.12, 0.04), sgBox(q, vec2f(0.0, 0.44), vec2f(0.30, 0.04))));
  let arms = min(max(sgRing(q, vec2f(0.0, -0.12), 0.52, 0.05), q.y + 0.12), sgTaper(q, vec2f(0.52, -0.14), vec2f(0.52, 0.12), 0.10, 0.0));
  return min(shank, arms);
}

/** The heart, a flame at its cleft and a cross standing on it. */
fn sgHeart(p: vec2f) -> f32 {
  let q = vec2f(abs(p.x), p.y);
  let body = min(sgTaper(q, vec2f(0.25, 0.10), vec2f(0.0, -0.72), 0.30, 0.0), sgTaper(q, vec2f(0.0, 0.36), vec2f(0.10, 0.50), 0.09, 0.0));
  return min(body, min(sgBox(q, vec2f(0.0, 0.62), vec2f(0.035, 0.22)), sgBox(q, vec2f(0.0, 0.68), vec2f(0.13, 0.035))));
}

/** A harp: pillar, neck and soundbox, and four strings. */
fn sgHarp(p: vec2f) -> f32 {
  let body = min(sgTaper(p, vec2f(0.38, -0.72), vec2f(0.38, 0.62), 0.055, 0.055),
                 min(sgTaper(p, vec2f(0.38, 0.62), vec2f(-0.46, 0.40), 0.06, 0.06), sgTaper(p, vec2f(-0.46, 0.40), vec2f(0.38, -0.72), 0.07, 0.07)));
  let strings = min(min(sgTaper(p, vec2f(-0.24, 0.44), vec2f(-0.24, 0.10), 0.013, 0.013), sgTaper(p, vec2f(-0.06, 0.48), vec2f(-0.06, -0.14), 0.013, 0.013)),
                    min(sgTaper(p, vec2f(0.12, 0.54), vec2f(0.12, -0.38), 0.013, 0.013), sgTaper(p, vec2f(0.27, 0.58), vec2f(0.27, -0.56), 0.013, 0.013)));
  return min(body, strings);
}

/**
 * An emblem by number: 0 crown, 1 sun, 2 moon, 3 star, 4 rose, 5 daisy,
 * 6 sword, 7 shield, 8 chalice, 9 key, 10 orb, 11 sceptre, 12 mitre,
 * 13 crozier, 14 Chi-Rho, 15 fish, 16 Trinity knot, 17 anchor, 18 heart,
 * 19 harp, 20 cross, 21 mirror of Venus.
 */
fn sgEmblem(kind: i32, p: vec2f) -> f32 {
  if (kind == 0) { return sgCrown(p); }
  if (kind == 1) { return sgSun(p); }
  if (kind == 2) { return sgMoon(p); }
  if (kind == 3) { return sgStar(p); }
  if (kind == 4) { return sgRose(p); }
  if (kind == 5) { return sgDaisy(p); }
  if (kind == 6) { return sgSword(p); }
  if (kind == 7) { return sgShield(p); }
  if (kind == 8) { return sgChalice(p); }
  if (kind == 9) { return sgKey(p); }
  if (kind == 10) { return sgOrb(p); }
  if (kind == 11) { return sgSceptre(p); }
  if (kind == 12) { return sgMitre(p); }
  if (kind == 13) { return sgCrozier(p); }
  if (kind == 14) { return sgChiRho(p); }
  if (kind == 15) { return sgFish(p); }
  if (kind == 16) { return sgTrinity(p); }
  if (kind == 17) { return sgAnchor(p); }
  if (kind == 18) { return sgHeart(p); }
  if (kind == 19) { return sgHarp(p); }
  if (kind == 21) { return sgVenus(p); }
  return sgCross(p);
}

/**
 * Where the brush actually went: a point of an emblem, moved off true by
 * the hand's wander and a slow sway of its own, so nothing drawn is quite
 * symmetric.
 */
fn sgByHand(p: vec2f, hand: vec2f) -> vec2f {
  return p + hand * 0.10 + 0.022 * vec2f(sin(p.y * 4.3 + 1.0), sin(p.x * 3.7 + 2.0));
}

/** How far a brushed outline strays from the drawn one at a point, in an emblem's units. */
fn sgWaver(p: vec2f) -> f32 {
  return 0.016 * sin(p.x * 17.0 + p.y * 11.0) * sin(p.y * 13.0 - p.x * 7.0);
}

/**
 * The matting wash on an emblem: darker toward its outline and toward the
 * lower right, the way a glass painter gives a flat piece its form. inset is
 * how far inside the outline this point is, in the emblem's units.
 */
fn sgWash(p: vec2f, inset: f32) -> f32 {
  return (0.58 + 0.42 * smoothstep(0.0, 0.11, inset)) * clamp(0.90 + 0.17 * dot(p, vec2f(-0.6, 0.6)), 0.70, 1.08);
}

/** Distance to the stroke from a to b. */
fn sgStroke(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  return sgTaper(p, a, b, 0.0, 0.0);
}

/**
 * What a glass painter adds inside an emblem's gold. x is the distance to
 * the lines painted on it — the groove of a blade, the scales of a fish,
 * the bands of a crown — and y the signed distance to what is set into it
 * in ruby: a jewel, a heart, the cross of a shield. Nine where there is
 * none.
 */
fn sgDetail(kind: i32, p: vec2f) -> vec2f {
  let q = vec2f(abs(p.x), p.y);
  let absent = 9.0;
  if (kind == 0) {
    // Crown: two lines on the band, a ruby in it and one each side, one on the middle point.
    let lines = min(sgStroke(p, vec2f(-0.56, -0.25), vec2f(0.56, -0.25)), sgStroke(p, vec2f(-0.56, -0.47), vec2f(0.56, -0.47)));
    return vec2f(lines, min(min(length(q - vec2f(0.0, -0.36)) - 0.075, length(q - vec2f(0.32, -0.36)) - 0.065), length(q - vec2f(0.0, 0.56)) - 0.06));
  }
  if (kind == 1) {
    // Sun: two rings on the disc.
    return vec2f(min(abs(length(p) - 0.27), abs(length(p) - 0.12)), absent);
  }
  if (kind == 2) {
    // Moon: a line following its inner curve, and a ruby.
    let inMoon = max(length(p) - 0.66, 0.56 - length(p - vec2f(0.30, 0.08))) < -0.03;
    return vec2f(select(absent, abs(length(p - vec2f(0.07, 0.02)) - 0.56), inMoon), length(p - vec2f(-0.40, -0.05)) - 0.06);
  }
  if (kind == 3) {
    // Star: a line down the middle of every ray, so each has two faces.
    let sector = TAU / 8.0;
    let ang = atan2(p.y, p.x);
    let r = length(p);
    return vec2f(select(absent, abs(sin(ang - sector * round(ang / sector))) * r, r < 0.86), r - 0.085);
  }
  if (kind == 6) {
    // Sword: the fuller down the blade, three turns of wire on the grip, a
    // ruby in the pommel and one in the guard.
    let wraps = min(min(sgStroke(p, vec2f(-0.05, -0.40), vec2f(0.05, -0.40)), sgStroke(p, vec2f(-0.05, -0.50), vec2f(0.05, -0.50))), sgStroke(p, vec2f(-0.05, -0.60), vec2f(0.05, -0.60)));
    return vec2f(min(sgStroke(p, vec2f(0.0, -0.12), vec2f(0.0, 0.60)), wraps), min(length(p - vec2f(0.0, -0.80)) - 0.075, length(p - vec2f(0.0, -0.25)) - 0.06));
  }
  if (kind == 7) {
    // Shield: a line inside its edge, and its cross in ruby.
    let field = max(q.y - 0.72, length(q - vec2f(-0.55, 0.45)) - 1.30);
    let bars = min(sgBox(q, vec2f(0.0, 0.10), vec2f(0.085, 0.56)), sgBox(q, vec2f(0.0, 0.28), vec2f(0.50, 0.085)));
    return vec2f(abs(field + 0.07), max(bars, field + 0.10));
  }
  if (kind == 8) {
    // Chalice: the wine's line in the bowl, the rim, the foot, a ruby in the knop.
    let wine = max(abs(length(q - vec2f(0.0, 0.58)) - 0.34), q.y - 0.50);
    let rims = min(sgStroke(p, vec2f(-0.34, -0.66), vec2f(0.34, -0.66)), sgStroke(p, vec2f(-0.40, 0.57), vec2f(0.40, 0.57)));
    return vec2f(min(wine, rims), length(p - vec2f(0.0, -0.04)) - 0.08);
  }
  if (kind == 9) {
    // Key: a line at the collar and along the ward, a ruby in the bow.
    return vec2f(min(sgStroke(p, vec2f(-0.07, 0.18), vec2f(0.07, 0.18)), sgStroke(p, vec2f(0.06, -0.74), vec2f(0.28, -0.74))), length(p - vec2f(0.0, 0.58)) - 0.045);
  }
  if (kind == 10) {
    // Orb: its bands, painted double, and a ruby on the globe and the cross.
    let onGlobe = length(p - vec2f(0.0, -0.22)) < 0.44;
    let girdle = min(sgStroke(p, vec2f(-0.44, -0.18), vec2f(0.44, -0.18)), sgStroke(p, vec2f(-0.44, -0.26), vec2f(0.44, -0.26)));
    let upright = min(sgStroke(p, vec2f(-0.04, -0.18), vec2f(-0.04, 0.22)), sgStroke(p, vec2f(0.04, -0.18), vec2f(0.04, 0.22)));
    return vec2f(select(absent, min(girdle, upright), onGlobe), min(length(p - vec2f(0.0, 0.56)) - 0.06, length(p - vec2f(0.0, -0.22)) - 0.07));
  }
  if (kind == 12) {
    // Mitre: a line above the band and one inside its edge, rubies on the band.
    let edgeLine = select(absent, abs(length(q - vec2f(-0.83, -0.33)) - 1.19), q.y > -0.33);
    return vec2f(min(sgStroke(p, vec2f(-0.44, -0.34), vec2f(0.44, -0.34)), edgeLine), min(length(q - vec2f(0.0, -0.42)) - 0.05, length(q - vec2f(0.26, -0.42)) - 0.045));
  }
  if (kind == 15) {
    // Fish: the gill, rows of scales behind it, the eye, the rays of the fin.
    let hull = length(vec2f(p.x, abs(p.y)) - vec2f(-0.10, -0.60)) - 0.90;
    let gill = max(abs(length(p - vec2f(-0.56, 0.0)) - 0.24), -(p.x + 0.44));
    let v = p.y / 0.115;
    let rowN = floor(v);
    let u = (p.x + 0.30) / 0.135 + 0.5 * (rowN - 2.0 * floor(rowN * 0.5));
    let sp = vec2f(fract(u) - 0.5, v - rowN - 0.5);
    let scales = select(absent, abs(length(sp + vec2f(0.5, 0.0)) - 0.52) * 0.125, p.x > -0.30 && p.x < 0.50 && hull < -0.03);
    let eye = abs(length(p - vec2f(-0.56, 0.09)) - 0.07);
    let finRays = min(sgStroke(p, vec2f(-0.04, 0.28), vec2f(0.12, 0.50)), sgStroke(p, vec2f(0.04, 0.28), vec2f(0.16, 0.44)));
    return vec2f(min(min(gill, scales), min(eye, finRays)), length(p - vec2f(-0.56, 0.09)) - 0.035);
  }
  if (kind == 18) {
    // Heart: it is ruby inside a gold rim, and a line of thorns crosses it.
    let body = sgTaper(q, vec2f(0.25, 0.10), vec2f(0.0, -0.72), 0.30, 0.0);
    return vec2f(select(absent, abs(p.y - 0.02 - 0.045 * sin(p.x * 26.0)), body < -0.05), body + 0.065);
  }
  return vec2f(absent, absent);
}

/**
 * Which emblem stands in a lobe of the Emperor and Empress's light. place is
 * 0 above, 1 right, 2 below, 3 left; third is the medallion's place up the
 * light, by threes: the Emperor's, the Empress's, the laurel's.
 */
fn sgKind(third: i32, place: i32) -> i32 {
  var four = vec4i(0, 10, 6, 11);                    // crown, orb, sword, sceptre
  if (third == 1) { four = vec4i(3, 21, 4, 18); }    // star, mirror of Venus, rose, heart
  if (third == 2) { four = vec4i(1, 19, 7, 2); }     // sun, harp, shield, moon
  return four[clamp(place, 0, 3)];
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = max(rzResolution(), vec2f(1.0));
  let aspect = res.x / res.y;
  let size = max(params.SIZE, 1.0e-3);

  let light = max(params.LIGHT, 0.0);

  // This pixel on the wall. The frame's uv runs up; the wall's y runs down.
  let g = (uv - vec2f(0.5)) * vec2f(aspect, -1.0) / size;

  // ── The openings ──
  // Which light this pixel belongs to, counted from the middle, and where it
  // is in that light.
  let k = clamp(round(g.x / sgPitch()), -1.0, 1.0);
  let lx = g.x - k * sgPitch();
  let gy = g.y - SILL;
  let lancet = sgLancet(vec2f(lx, gy), HW, HB);
  // The rose each side, midway between two lights.
  let rp = vec2f(abs(g.x) - sgPitch() * 0.5, g.y - sgRoseY());
  let rlen = length(rp);
  // Turned: the rose's own frame. rp is mirrored across the middle light,
  // so the two turn opposite ways.
  let spin = time * ROSE_TURN;
  let rr = vec2f(rp.x * cos(spin) - rp.y * sin(spin), rp.x * sin(spin) + rp.y * cos(spin));
  let rose = rlen - ROSE_R;
  let inRose = rose < lancet;
  let sd = min(lancet, rose);
  // Which way is out from the nearest opening, and how that meets the light,
  // which is from the upper left: 1 where the edge faces it, -1 where it
  // faces away.
  let out2 = vec2f(sgOpening(g + vec2f(0.002, 0.0)) - sd, sgOpening(g + vec2f(0.0, 0.002)) - sd);
  let outward = out2 / max(length(out2), 1.0e-5);
  let sunward = dot(outward, vec2f(-0.7071, -0.7071));
  // THE SUN IS BEHIND THE GLASS. A bright place in the sky that drifts slowly
  // across behind the wall; what stands in front of it is lit through.
  let sunAt = vec2f(0.46 * sin(time * 0.045), -0.16 + 0.11 * cos(time * 0.031));
  let sunGlow = exp(-dot(g - sunAt, g - sunAt) / (0.30 * 0.30)) * light;
  // The colour a window throws: purple from the Emperor's, blue from the
  // other two.
  let thrown = select(vec3f(0.35, 0.50, 1.00), vec3f(0.62, 0.28, 0.95), k < 0.0);
  // The hand: a slow wander, each way about a half.
  let hand = sgNoise2(g * 11.0) - vec2f(0.5);
  // 0 the middle, 1 the left, 2 the right.
  let seat = i32(abs(k)) * 2 - select(0, 1, k < 0.0);
  // THE CAST JUMPS FROM LIGHT TO LIGHT. Every JUMP seconds the three lights
  // are dealt again: a turn of nought, one or two places, drawn for that
  // stretch of time, so the first of the cast lands in a light at random
  // and the others move round with her. It is a function of the clock
  // alone, so an export jumps where the preview did.
  var dealt = 0;
  if (params.JUMP > 0.0) {
    let nth = floor(time / params.JUMP);
    // The first stretch is always the middle light: she starts there.
    dealt = select(i32(floor(sgHash2(vec2f(nth, 17.0)).x * 2.999)), 0, nth < 0.5);
  }
  let slot = (seat + dealt) % 3;
  // Which light the first of the cast is in: the one whose seat the dealt
  // brings round to nought.
  let home = (3 - dealt) % 3;
  let homeK = select(select(1.0, -1.0, home == 1), 0.0, home == 0);

  // ── The shot behind the wall ──
  // Unsqueezed, a frame height of wall to a frame height of shot, centred on
  // the first of the cast. A light with a figure of its own holds the shot
  // with that figure's hips at its middle.
  var across = 0.5;
  // A light with nobody in it holds the shot as the first one's light has it.
  var anchorX = homeK * sgPitch();
  let one = rzSubject(0);
  if (one.valid) {
    let hip = rzProject(one.center);
    if (hip.z > 0.0) { across = clamp(hip.x, 0.0, 1.0); }
  }
  if (slot < rzSubjectCount()) {
    let who = rzSubject(slot);
    if (who.valid) {
      let hip = rzProject(who.center);
      if (hip.z > 0.0) { across = clamp(hip.x, 0.0, 1.0); anchorX = k * sgPitch(); }
    }
  }
  let fit = vec2f(1.0 / max(aspect, 1.0e-3), 1.0);
  let sceneUv = clamp(vec2f(across, 0.5) + vec2f(g.x - anchorX, -g.y) * fit, vec2f(0.001), vec2f(0.999));

  // Everything a piece of glass is, worked out only where there is glass:
  // inside an opening, and the feather of its edge.
  var lit = vec3f(0.0);
  var onFigure = false;
  if (sd < 0.006) {
    // ── The cut ──
    let pieces = clamp(params.PIECES, 1.0, 200.0);
    // A rose is cut in its own turning frame, so its pieces turn with it.
    let cut = select(g, rr + vec2f(3.0, 0.0), inRose) * pieces;
    let cell = sgVoro(cut);
    let pick = fract(cell.rnd.x * 7.31 + cell.rnd.y * 3.17);

    // The two grounds of this light. They change places from one light to the
    // next: cobalt first in the middle, ruby first either side of it.
    let odd = k != 0.0;
    let firstGround = sgGround(select(COBALT, RUBY, odd), select(RUBY, COBALT, odd), pick);
    let secondGround = sgGround(select(RUBY, COBALT, odd), select(COBALT, RUBY, odd), pick);
    // Paint: a fine diaper, a lattice of lines with a dot at each crossing.
    let dq = vec2f(g.x + g.y, g.x - g.y) / DIAPER;
    let df = abs(fract(dq) - vec2f(0.5));
    let diaper = 0.40 + 0.60 * min(smoothstep(0.03, 0.09, min(df.x, df.y)), smoothstep(0.10, 0.17, length(df - vec2f(0.5))));

    // ── The piece of glass at this point ──
    // Its pot, its own random pair, and how far this point is from its lead,
    // counted in pieces of the mosaic. It starts as a piece of the first
    // ground and each panel below says otherwise where it must. seam is the
    // lead a panel draws between its own parts.
    var pot = firstGround;
    var rnd = cell.rnd;
    var edge = cell.edge;
    var paint = 1.0;
    var gilt = false;
    var seam = 1.0;
    // How much more of the day this piece lets through than its pot would.
    var lift = 1.0;

    // The base is decided piece by piece, by where each piece's own point
    // lies, so its top is the ragged run of the mosaic's leads and no line
    // is ruled across the light for a figure's feet to break.
    let inBase = gy + cell.to.y / pieces > -BASE_H && !inRose;
    let inHead = gy < -HB + 0.01;
    let canopyR = HW - BAND - FILLET - 0.016;
    let can = length(vec2f(lx, gy + HB - 0.01)) - canopyR;

    if (inRose) {
      // A rose: eight petals of cobalt on a painted ruby ground, a gold boss.
      let innerR = ROSE_R - BAND - FILLET;
      let petal = sgPetals(vec2f(rr.x, -rr.y) / innerR, 8.0, 0.34, 0.68, 0.07, 0.22) * innerR;
      let boss = rlen - 0.19 * innerR;
      if (boss < 0.0) {
        pot = GOLD;
        gilt = true;
        rnd = sgHash2(vec2f(sign(g.x), 4.0));
        edge = -boss * pieces;
      } else if (petal < 0.0) {
        pot = sgGround(COBALT, SKY, pick);
        edge = min(edge, min(-petal, boss) * pieces);
      } else {
        pot = sgGround(RUBY, MURREY, pick);
        paint = diaper;
        edge = min(edge, min(petal, boss) * pieces);
      }
    } else if (inBase) {
      // The base: a band of the light's second ground across its foot, in
      // the window's own cut, painted with the diaper.
      pot = secondGround;
      paint = diaper;
    } else if (k == 0.0) {
      // A figure's light: the niche, the fillet arched over it, and above the
      // arch the second ground, painted.
      if (inHead && can > STRIP) {
        pot = secondGround;
        paint = diaper;
      } else if (inHead && can > 0.0) {
        // The mosaic's own cut divides the fillet into lengths.
        pot = PEARL * 0.62;
        edge = min(edge, min(can, STRIP - can) * pieces);
      }
      seam = select(1.0, sgLine(can) * sgLine(can - STRIP), inHead);

      // The glory behind her: a vesica, where two circles of radius gr overlap.
      let gp = vec2f(lx, gy + GLORY_Y);
      let gr = (GLORY_H * GLORY_H + GLORY_W * GLORY_W) / (2.0 * GLORY_W);
      let glory = length(vec2f(abs(gp.x) + gr - GLORY_W, gp.y)) - gr;
      // How far inside the rim and its fillet this point is.
      let within = -glory - GLORY_RIM - STRIP;
      if (within > 0.0) {
        // The field: night, in the window's own cut, sown with stars, and a
        // sun high in it where a figure's head comes.
        pot = select(NIGHT, VIOLET * 0.8, pick > 0.80);
        paint = 1.0;
        edge = min(cell.edge, within * pieces);
        let sunP = sgByHand(vec2f(gp.x, -(gp.y + SUN_UP)) / SUN_R, hand);
        let sun = (sgSun(sunP) - BOLD + sgWaver(sunP)) * SUN_R;
        // The stars: one to a cell of a lattice, every other row set over
        // by half. A star is drawn only where the whole of it lies in the
        // field and clear of the sun.
        let sq = gp / STAR_PITCH;
        let rowN = floor(sq.y);
        let nudge = 0.5 * (rowN - 2.0 * floor(rowN * 0.5));
        let colN = floor(sq.x + nudge);
        // No two alike and none on a rule: each strays from the middle of
        // its cell, each is its own size, one in three has four points and
        // not eight, and one cell in four has no star at all.
        let stray = sgHash2(vec2f(colN, rowN) + vec2f(31.0, 7.0));
        let starSeed = sgHash2(vec2f(colN, rowN) + vec2f(3.0, 19.0));
        let starAt = vec2f((colN + 0.5 - nudge) * STAR_PITCH, (rowN + 0.5) * STAR_PITCH) + (stray - vec2f(0.5)) * STAR_PITCH * 0.40;
        let starR = STAR_R * (0.55 + 0.80 * starSeed.x);
        let entire = fract(starSeed.x * 7.3 + starSeed.y * 3.1) > 0.25
                  && length(vec2f(abs(starAt.x) + gr - GLORY_W, starAt.y)) - gr < -GLORY_RIM - STRIP - starR * 1.3
                  && length(starAt - vec2f(0.0, -SUN_UP)) > SUN_R * 1.7;
        let starP = vec2f(gp.x - starAt.x, starAt.y - gp.y) / starR;
        let fourPoint = min(sgPetals(starP, 4.0, 0.0, 0.98, 0.20, 0.0), length(starP) - 0.22);
        let star = select(1.0, select(sgStar(starP), fourPoint, starSeed.y > 0.66) * starR, entire);
        if (sun < 0.0) {
          let inlay = sgDetail(1, sunP) * SUN_R;
          rnd = sgHash2(vec2f(5.0, 1.0));
          pot = mix(STAIN_PALE, STAIN_DEEP, 0.30);
          gilt = true;
          edge = -sun * pieces * FINE_LEAD;
          lift = EMBLEM_LIFT;
          paint = (0.25 + 0.75 * smoothstep(0.0005, 0.0012, inlay.x)) * sgWash(sunP, -sun / SUN_R);
        } else if (star < 0.0) {
          rnd = sgHash2(vec2f(colN, rowN));
          pot = mix(STAIN_PALE, STAIN_DEEP, rnd.x * 0.6);
          gilt = true;
          edge = -star * pieces * FINE_LEAD;
          lift = EMBLEM_LIFT;
        } else {
          edge = min(edge, min(sun, star) * pieces);
        }
      } else if (glory < -GLORY_RIM) {
        // The fillet inside the rim.
        pot = PEARL * 0.62;
        paint = 1.0;
        edge = min(cell.edge, min(-glory - GLORY_RIM, GLORY_RIM + STRIP + glory) * pieces);
      } else if (glory < 0.0) {
        // The rim: a sunburst, short rays of gold and amber by turns all the
        // way round, each one piece.
        let sector = TAU / 56.0;
        let ang = atan2(gp.x, -gp.y);
        let ri = round(ang / sector);
        pot = select(GLORY, GOLD, ri - 2.0 * floor(ri * 0.5) < 0.5);
        gilt = true;
        paint = 1.0;
        rnd = sgHash2(vec2f(ri, 3.0));
        edge = min((0.5 - abs(ang / sector - ri)) * sector * length(gp), min(-glory, glory + GLORY_RIM)) * pieces;
        lift = 0.95;
      } else if (glory < STRIP) {
        pot = PEARL * 0.62;
        paint = 1.0;
        rnd = cell.rnd;
        edge = min(cell.edge, min(glory, STRIP - glory) * pieces);
      }
      // The arch stops at the glory; the glory's own fillet takes over.
      seam = select(seam, 1.0, glory < STRIP) * sgLine(glory) * sgLine(glory - STRIP) * sgLine(glory + GLORY_RIM) * sgLine(glory + GLORY_RIM + STRIP);
    } else {
      // Nobody's light: a medallion window. This point up the field from the
      // base, and whose arms it carries.
      let wx = lx + hand.x * WANDER;
      let wy = gy + hand.y * WANDER;
      let yu = -(wy + BASE_H);
      let france = k < 0.0;

      if (france) {
        // The ground underneath everything is the same cut as the rest of
        // the window — crimson with purple in it — and the diaper is painted
        // on it, a fine lattice with a dot at each crossing. A ground of
        // ruled squares with no cut in it is not the same glass as the
        // light beside it.
        pot = sgGround(CRIMSON, VIOLET, pick);
        paint = diaper;

        // The compound medallion nearest this point: a canted square with a
        // lobe on each side. my runs up from its centre.
        let cy = yu - MED_FOOT;
        let row = round(cy / MED_PITCH);
        let my = cy - MED_PITCH * row;
        let a = vec2f(abs(wx), abs(my));
        let diamond = (a.x + a.y - DIAMOND) * 0.7071;
        let lobe = min(length(a - vec2f(LOBE_AT, 0.0)), length(a - vec2f(0.0, LOBE_AT))) - LOBE_R;
        let compound = min(diamond, lobe);
        // The half medallions that break in from the border, between compounds.
        let hy = cy - MED_PITCH * (floor(cy / MED_PITCH) + 0.5);
        let halfMed = length(vec2f(abs(wx) - (HW - BAND - FILLET), hy)) - HALF_R;
        let shape = min(compound, halfMed);

        let third = row - 3.0 * floor(row / 3.0);
        if (diamond < 0.0) {
          // The square, and the charge in it: IV, III, the laurel, up the
          // light.
          let at = vec2f(wx, my) / CHARGE;
          var charge = sgFour(at) * CHARGE;
          if (third > 0.5) { charge = sgThree(at) * CHARGE; }
          if (third > 1.5) { charge = sgLaurel(at) * CHARGE; }
          if (charge < 0.0) {
            pot = GOLD;
            gilt = true;
            rnd = sgHash2(vec2f(row, k * 5.0 + 1.0));
            edge = -charge * pieces * FINE_LEAD;
          lift = EMBLEM_LIFT;
          } else {
            pot = sgGround(CRIMSON, VIOLET, pick);
            gilt = false;
            rnd = cell.rnd;
            edge = min(cell.edge, min(-diamond, charge) * pieces);
          }
        } else if (lobe < 0.0) {
          // A lobe, and its emblem. Which lobe this is: 0 above, 1 right, 2
          // below, 3 left — and what stands there on this medallion.
          let sideways = a.x > a.y;
          let centre = select(vec2f(0.0, sign(my) * (LOBE_AT + 0.006)), vec2f(sign(wx) * (LOBE_AT + 0.006), 0.0), sideways);
          let place = select(select(2, 0, my > 0.0), select(3, 1, wx > 0.0), sideways);
          let kind = sgKind(i32(third), place);
          let brushed = sgByHand((vec2f(wx, my) - centre) / EMBLEM, hand);
          let emblem = (sgEmblem(kind, brushed) - BOLD + sgWaver(brushed)) * EMBLEM;
          if (emblem < 0.0) {
            let inlay = sgDetail(kind, brushed) * EMBLEM;
            gilt = true;
            rnd = sgHash2(vec2f(row * 7.0 + f32(place), k * 3.0 + 2.0));
            pot = select(mix(STAIN_PALE, STAIN_DEEP, rnd.x), RUBY, inlay.y < 0.0);
            edge = min(-emblem, abs(inlay.y)) * pieces * FINE_LEAD;
            lift = EMBLEM_LIFT;
            paint = (0.25 + 0.75 * smoothstep(0.0005, 0.0012, inlay.x)) * sgWash(brushed, -emblem / EMBLEM);
          } else {
            pot = sgGround(VIOLET, MURREY, pick);
            gilt = false;
            rnd = cell.rnd;
            edge = min(cell.edge, min(min(-lobe, diamond), emblem) * pieces);
          }
        } else if (halfMed < 0.0) {
          pot = sgGround(MURREY, VIOLET, pick);
          gilt = false;
          rnd = cell.rnd;
          edge = min(cell.edge, -halfMed * pieces);
        } else if (shape < STRIP) {
          // The white fillet round every figure, in lengths cut by the mosaic.
          pot = GOLD * 0.85;
          gilt = false;
          rnd = cell.rnd;
          edge = min(cell.edge, min(shape, STRIP - shape) * pieces);
        }
        seam = sgLine(shape) * sgLine(shape - STRIP) * select(1.0, sgLine(diamond), compound < 0.0);
      } else {
        // A Tree of Jesse on open cobalt. t0 runs up from the lowest almond.
        pot = sgGround(COBALT, MURREY, pick);
        let t0 = yu - TREE_FOOT;
        let tier = round(t0 / TREE_PITCH);
        let ty = t0 - TREE_PITCH * tier;
        // The almond on the stem: a vesica, where two circles overlap.
        let ar = (ALMOND_H * ALMOND_H + ALMOND_W * ALMOND_W) / (2.0 * ALMOND_W);
        let almond = length(vec2f(abs(wx) + ar - ALMOND_W, ty)) - ar;
        // The scroll each side, between one almond and the next: a ring of
        // vine, and the branch that carries it off the stem.
        let gap = floor(t0 / TREE_PITCH);
        let hy = t0 - TREE_PITCH * (gap + 0.5);
        let sc = vec2f(abs(wx) - SCROLL_AT, hy);
        let sl = length(sc);
        let ring = abs(sl - SCROLL_R) - VINE;
        let branch = sgTaper(vec2f(abs(wx), hy), vec2f(0.0, -0.075), vec2f(SCROLL_AT - SCROLL_R * 0.72, -0.034), VINE * 0.85, VINE * 0.85);
        let stem = select(1.0, abs(wx) - VINE * 1.3, almond > STRIP);
        let vine = min(min(ring, branch), stem);

        if (almond < 0.0) {
          // Ruby, and the emblem where a king would sit: the Chi-Rho, the
          // chalice, the cross, the key, the mitre, up the tree and round again.
          let turn5 = tier - 5.0 * floor(tier / 5.0);
          var kind = 14;
          if (turn5 > 0.5) { kind = 8; }
          if (turn5 > 1.5) { kind = 20; }
          if (turn5 > 2.5) { kind = 9; }
          if (turn5 > 3.5) { kind = 12; }
          let brushed = sgByHand(vec2f(wx, ty) / TREE_EMBLEM, hand);
          let emblem = (sgEmblem(kind, brushed) - BOLD + sgWaver(brushed)) * TREE_EMBLEM;
          if (emblem < 0.0) {
            let inlay = sgDetail(kind, brushed) * TREE_EMBLEM;
            gilt = true;
            rnd = sgHash2(vec2f(tier, 9.0));
            pot = select(mix(STAIN_PALE, STAIN_DEEP, rnd.x), RUBY, inlay.y < 0.0);
            edge = min(-emblem, abs(inlay.y)) * pieces * FINE_LEAD;
            lift = EMBLEM_LIFT;
            paint = (0.25 + 0.75 * smoothstep(0.0005, 0.0012, inlay.x)) * sgWash(brushed, -emblem / TREE_EMBLEM);
          } else {
            pot = sgGround(RUBY, MURREY, pick);
            edge = min(cell.edge, min(-almond, emblem) * pieces);
          }
        } else if (almond < STRIP) {
          pot = PEARL * 0.44;
          edge = min(cell.edge, min(almond, STRIP - almond) * pieces);
        } else if (vine < 0.0) {
          // The vine itself, white, in lengths cut by the mosaic.
          pot = PEARL * 0.42;
          gilt = true;
          edge = min(cell.edge, -vine * pieces * 1.6);
        } else if (sl < SCROLL_R) {
          // Inside a scroll: ruby, and its emblem. This point from the
          // scroll's own centre, unmirrored, so a moon faces one way in both.
          let sp = vec2f(wx - sign(wx) * SCROLL_AT, hy);
          let rightSide = wx > 0.0;
          let pair = gap - 4.0 * floor(gap / 4.0);
          // The fish and the anchor; the knot and the daisy; the crozier and
          // the star; the sun and the moon.
          var which = select(15, 17, rightSide);
          if (pair > 0.5) { which = select(16, 5, rightSide); }
          if (pair > 1.5) { which = select(13, 3, rightSide); }
          if (pair > 2.5) { which = select(1, 2, rightSide); }
          let brushed = sgByHand(sp / SCROLL_EMBLEM, hand);
          let mark = (sgEmblem(which, brushed) - BOLD + sgWaver(brushed)) * SCROLL_EMBLEM;
          if (mark < 0.0) {
            let inlay = sgDetail(which, brushed) * SCROLL_EMBLEM;
            gilt = true;
            rnd = sgHash2(vec2f(gap, sign(wx) + 4.0));
            pot = select(mix(STAIN_PALE, STAIN_DEEP, rnd.x), RUBY, inlay.y < 0.0);
            edge = min(-mark, abs(inlay.y)) * pieces * FINE_LEAD;
            lift = EMBLEM_LIFT;
            paint = (0.25 + 0.75 * smoothstep(0.0005, 0.0012, inlay.x)) * sgWash(brushed, -mark / SCROLL_EMBLEM);
          } else {
            pot = sgGround(RUBY, MURREY, pick);
            edge = min(cell.edge, min(SCROLL_R - VINE - sl, mark) * pieces);
          }
        } else {
          // The open ground, leaded against the vine and the almonds.
          edge = min(cell.edge, min(vine, almond - STRIP) * pieces);
        }
        seam = sgLine(almond) * sgLine(almond - STRIP);
      }
    }

    // ── The border ──
    // Over all of the above, inside the stone. How far along the edge this
    // point is: up a light's straight side, round the arc of its head from the
    // springer, and along the sill; or round a rose.
    // Its width wavers with the hand.
    let band = BAND + hand.x * 0.007;
    if (sd > -band) {
      let q0 = abs(lx);
      var run = select(gy, -HB - 2.0 * HW * atan2(-(gy + HB), q0 + HW), gy < -HB);
      run = select(run, lx, gy > -BAND && q0 < HW - BAND);
      run = select(run, atan2(rr.x, -rr.y) * ROSE_R, inRose);
      // Blocks of uneven length: the count along the edge slips back and forth.
      run = run + hand.y * 0.016 + 0.006 * sin(run * 41.0 + k * 2.0);
      let bi = floor(run / BLOCK);
      let bf = run / BLOCK - bi - 0.5;
      rnd = sgHash2(vec2f(bi, k * 13.0 + 7.0));
      paint = 1.0;
      // Small bright pieces, all middle: held down to the level of the field
      // they frame.
      lift = 0.72;
      // The bead sits in the middle of its block, halfway across the band.
      let beadAt = length(vec2f(bf * BLOCK, -sd - band * 0.5));
      let bead = BEAD * (0.75 + 0.55 * rnd.x);
      if (beadAt < bead) {
        pot = GOLD;
        gilt = true;
        edge = (bead - beadAt) * pieces;
      } else {
        pot = select(COBALT, RUBY, bi - 2.0 * floor(bi * 0.5) < 0.5);
        gilt = false;
        edge = min(min((0.5 - abs(bf)) * BLOCK, min(-sd, sd + band)), beadAt - bead) * pieces;
      }
    } else if (sd > -band - FILLET) {
      // The white fillet, in lengths cut by the mosaic.
      pot = PEARL * 0.55;
      rnd = cell.rnd;
      paint = 1.0;
      lift = 1.0;
      gilt = false;
      edge = min(cell.edge, min(-sd - band, sd + band + FILLET) * pieces);
    }

    // No pot is one hue: a cobalt leans to violet or to cyan, a ruby to
    // crimson or to orange.
    let lean = rnd.x - 0.5;
    if (pot.b > 0.5 && pot.r < 0.3) {
      pot = pot + lean * vec3f(0.16, -0.08, 0.0);
    } else if (pot.r > 0.5 && pot.g < 0.2) {
      pot = pot + lean * vec3f(0.0, 0.10, 0.05);
    }
    pot = clamp(pot, vec3f(0.0), vec3f(1.0));

    // ── What the light does in a piece ──
    // The lead: heavy, and thicker in one place than the next.
    let leadW = 0.70 + 1.0 * (hand.y + 0.5);
    let glass = smoothstep(LEAD_IN * leadW, LEAD_OUT * leadW, edge);
    // Nor one depth: most pieces are deep, a few let the day through. Gold and
    // pearl are kept from going out altogether.
    let shade = select(0.34 + 0.86 * pow(rnd.y, 1.5), 0.40 + 0.45 * rnd.y, gilt) * lift;
    // Dark at the lead and clear a short way in: a rim, narrow enough that a
    // square of the diaper or a petal still has a middle.
    let body = 0.30 + 0.70 * smoothstep(0.0, 0.12, edge);
    // Streaks, one way per piece: noise drawn out seven to one along the
    // piece's own direction.
    let turn = rnd.x * 3.1416;
    let tc = cos(turn);
    let ts = sin(turn);
    let streak = 0.66 + 0.68 * sgNoise(vec2f((cut.x * tc + cut.y * ts) * 1.3, (cut.y * tc - cut.x * ts) * 9.0));
    // Seeds: small bubbles that catch the light.
    let seed = smoothstep(0.82, 0.93, sgNoise(cut * 9.0)) * 0.30;
    // THE SKY IS BEHIND THE GLASS, and the glass is seen through. Warm and
    // pale at the horizon, blue above, with cloud drifting across it. Each
    // piece is a pane at its own tilt and bends the sky by its own small
    // amount, so a cloud's edge runs on from one piece into the next and
    // breaks at the lead between them: what a painted panel cannot do.
    let skyAt = g + (rnd - vec2f(0.5)) * 0.045;
    let sq = vec2f(skyAt.x * 1.9 + time * 0.010, skyAt.y * 3.0);
    let cloud = smoothstep(0.40, 0.62, 0.5 * sgNoise(sq) + 0.25 * sgNoise(sq * 2.03 + vec2f(3.1)) + 0.125 * sgNoise(sq * 4.01 + vec2f(7.7)));
    let clearSky = mix(vec3f(0.98, 0.90, 0.78), vec3f(0.42, 0.62, 1.00), smoothstep(0.0, 0.85, 0.5 - skyAt.y));
    let sky = mix(clearSky, vec3f(1.30, 1.29, 1.25), cloud);
    let skyLum = sgLuma(sky);
    // How much day comes through: more under cloud, which is the brightest
    // thing in a sky, less under clear blue.
    let day = 0.40 + 0.80 * skyLum;
    // And what is seen. The glass colours the sky, and lets a little of the
    // sky itself through as it is — more where the glass is pale.
    let clear = 0.12 + 0.26 * smoothstep(0.35, 0.80, min(pot.r, min(pot.g, pot.b)));
    let seen = pot * mix(vec3f(1.0), sky / max(skyLum, 1.0e-3), 0.45) * (1.0 - clear) + sky * 0.80 * clear;
    // A sheen crossing the wall on a slant, about every twenty seconds. Each
    // piece takes it by its own amount.
    let sheenWave = pow(max(sin((g.x * 0.9 + g.y * 0.5) * 2.4 - time * 0.55), 0.0), 8.0) * 0.42;
    let sheen = sheenWave * (0.35 + 0.65 * rnd.y);

    // Pieces catch the light at random: about six in ten take part, each at
    // its own moment and its own pace, and the whole piece lights. It comes
    // up over a few seconds, holds and goes down as slowly — a swell every
    // fifteen to forty seconds, never a flash.
    let glint = pow(max(sin(time * (0.60 + 0.90 * rnd.y) + rnd.x * 50.0), 0.0), 3.0) * step(0.40, fract(rnd.x * 13.7 + rnd.y * 5.3)) * smoothstep(0.03, 0.14, edge);

    // Lit from behind: a piece in front of the sun lets far more of it
    // through, in its own colour, and whitens at the heart of it.
    let backlit = 1.0 + 1.25 * sunGlow;
    var ground = (seen * shade * body * streak * day * backlit * (1.0 + sheen) * paint * EXPOSURE + pot * seed) * glass;
    // THE GLASS HAS A SURFACE. On the room's side it is glossy, and what it
    // throws back is pale, not the colour of the piece: a thin highlight
    // that crosses the wall and lands on each piece a little early or late,
    // since no two lie at one angle.
    let gloss = pow(max(sin((g.x * 0.9 + g.y * 0.5) * 2.4 - time * 0.55 + (rnd.x - 0.5) * 1.1), 0.0), 16.0);
    ground = ground + vec3f(0.85, 0.92, 1.00) * gloss * (0.30 + 0.70 * rnd.y) * 0.50 * glass * paint * light;
    ground = ground + (pot * 0.55 + vec3f(0.45)) * sunGlow * sunGlow * 0.20 * glass * paint;
    // Through the paint and the lead as the rest of the light is: a piece
    // that shines keeps what is drawn on it.
    ground = ground + (pot * 1.25 + vec3f(0.12)) * glint * 1.15 * light * paint * glass;
    // Halation: the lead beside a piece takes a little of that piece's colour.
    ground = ground + pot * shade * day * (0.07 + 0.34 * sunGlow) * (1.0 - glass);

    // ── The lead between panels ──
    // Where one panel meets another the cut of neither knows about it: the
    // border's inner edge, a panel's own seams, the top of the base.
    ground = ground * seam * sgLine(sd + band + FILLET);

    // ── Her ──
    // Screen pixels to the cast at the point of the shot this piece shows: zero
    // on her, positive outside. A rose shows none of the shot.
    let dist = rzCastDistance(sceneUv);
    let onHer = dist <= 0.0 && !inRose;
    let figure = clamp(params.FIGURE, 0.0, 1.0);

    // The came round her: the band just outside the silhouette goes to lead,
    // and it is the same lead as the lines drawn in the window beside her.
    // The distance comes in pixels of the shot, and a frame height of shot is
    // a frame height of wall, so this is that distance in the wall's own
    // measure, the one the window's lines are drawn in.
    let onWallD = dist / res.y;
    let soft = 1.5 / (res.y * size);
    let came = select(clamp(onWallD / soft, 0.0, 1.0) * (1.0 - clamp((onWallD - CAME) / soft, 0.0, 1.0)), 0.0, inRose);

    // ── The ground's pane ──
    // The came round her is raised too: a soft shadow on the ground beside it.
    let cameShadow = select(1.0 - 0.18 * (1.0 - smoothstep(CAME, CAME + 0.0035, onWallD)), 1.0, inRose);
    let pane = clamp(LEAD + ground * (1.0 - came) * cameShadow, vec3f(0.0), vec3f(1.0));

    // What this point of the glass shows: the ground's pane, or her. Her
    // work is done only where she is — it reads the frame four more times.
    lit = pane;
    onFigure = onHer;
    if (onHer) {
      // Her. She is read exactly where the scene put her: nothing of the
      // glass moves her picture, at the lead or anywhere else. A picture
      // shifted near a line shimmers the moment she moves under it.
      let at = sceneUv;
      let through0 = rzSceneFrame(at);
      // HER DRAWING, FOUND AND PAINTED BACK IN. A glazier traces a figure in
      // bold dark paint — the eye, the strand of hair, the edge of a sleeve —
      // and it is that line, not the lead, that says who she is. The scene
      // draws those lines a pixel or two wide, so they are found here and
      // laid on heavier.
      //
      // A line is where the picture is darker than the ring of it round
      // about. Dark is judged by a colour's brightest channel, so a line
      // drawn in dark red or dark blue is a line as a black one is. The ring
      // is eight points, so it is found whichever way it runs; and the
      // middle is this point averaged with the four close beside it, which
      // takes the speckle out of it — a single dark pixel is not a line —
      // and keeps a line whole along its length.
      let px = vec2f(1.0) / res;
      let near1 = rzSceneDisplay(at + vec2f(px.x, 0.0) * 1.2);
      let near2 = rzSceneDisplay(at - vec2f(px.x, 0.0) * 1.2);
      let near3 = rzSceneDisplay(at + vec2f(0.0, px.y) * 1.2);
      let near4 = rzSceneDisplay(at - vec2f(0.0, px.y) * 1.2);
      let middle = (sgValue(through0) * 2.0 + sgValue(near1) + sgValue(near2) + sgValue(near3) + sgValue(near4)) / 6.0;
      var ringV = 0.0;
      for (var n = 0; n < 8; n = n + 1) {
        let a = f32(n) * 0.7853982;
        ringV = ringV + sgValue(rzSceneDisplay(at + vec2f(cos(a), sin(a)) * px * 2.8));
      }
      // It comes in by degrees as the line is stronger, so nothing flicks on
      // and off as she moves; the soft turn of a shadow stays below it.
      let trace = smoothstep(TRACE_FROM, TRACE_FULL, ringV * 0.125 - middle) * figure;
      // The same four near points sharpen the picture a little.
      let crisp = max(through0 * (1.0 + 4.0 * SHARPEN) - (near1 + near2 + near3 + near4) * SHARPEN, vec3f(0.0));
      // A shade deeper in colour, the same in every piece, and set back to
      // the brightness it had. Her colours are the scene's.
      let lum = sgLuma(crisp);
      var jewel = max(vec3f(lum) + (crisp - vec3f(lum)) * (1.0 + 0.08 * figure), vec3f(0.0));
      jewel = jewel * lum / max(sgLuma(jewel), 1.0e-4);
      // THE WINDOW'S LIGHT FALLS ON HER TOO, OR SHE IS NOT IN IT — but only
      // the light that varies smoothly from place to place, never anything
      // chosen piece by piece. Two pieces side by side get all but the same,
      // so none is grey beside a white one. The day behind, read smooth
      // here and not bent by any piece; the sheen as it crosses; the sun.
      let herSky = smoothstep(0.35, 0.70, sgNoise(vec2f(g.x * 1.9 + time * 0.010, g.y * 3.0)));
      let herDay = mix(1.0, 0.92 + 0.26 * herSky, 0.80 * figure) * (1.0 + 0.26 * sunGlow * figure);
      // Lifted a little, to make up what the lead's shadow takes from her and
      // stand her level with the lit glass beside her.
      var hers = jewel * mix(1.0, HER_LIFT, figure) * herDay * (1.0 + sheenWave * 0.75 * figure);
      // And the lead's shadow on her glass, the same in every piece: a faint
      // darkening that hugs the line on both sides, a little more below and
      // right of it, where the light from the upper left does not reach.
      // Shaded after she is brought inside white, or on a white dress it is
      // spent on brightness nobody sees.
      let away = cell.to / max(length(cell.to), 1.0e-4);
      let nearLead = 1.0 - smoothstep(0.0, LEAD_SHADOW, cell.edge);
      hers = clamp(hers, vec3f(0.0), vec3f(1.0)) * (1.0 - (0.13 + 0.17 * max(dot(away, vec2f(0.7071, 0.7071)), 0.0)) * nearLead * figure)
           * mix(1.0, 0.70 + 0.30 * smoothstep(0.0, 0.12, cell.edge), figure);

      // The lead through her is the window's lead exactly: the same width,
      // wandering as it does, and the glass darkening into it the same way,
      // so its edge is as soft as the lines in the lights beside her.
      let herLead = smoothstep(LEAD_IN * leadW, LEAD_OUT * leadW, cell.edge);
      // Her drawing, in the glass painter's brown-black, over all of it.
      hers = mix(clamp(hers, vec3f(0.0), vec3f(1.0)), TRACE_PAINT, trace * 0.70);
      // THE CAME INSIDE HER. Round her outside she has a bold black line, and
      // it is that line which sets her into the window. Inside she had
      // none: an arm across her body, hair over a shoulder, a sleeve over a
      // skirt met white on white. A glazier leads those — the great forms of
      // a figure are where the glass is cut. They are found by depth: where
      // one part of her stands in front of another, how far she is from the
      // eye steps, and a step is not a slope, so a limb turning away from
      // the light draws nothing. The line is the outline's own weight, and
      // it is hers, so it moves with her and does not shimmer.
      let reach = vec2f(CAME * 0.75) * fit;
      let deep = rzSceneDepth(at);
      let stepX = abs(rzSceneDepth(at + vec2f(reach.x, 0.0)) + rzSceneDepth(at - vec2f(reach.x, 0.0)) - 2.0 * deep);
      let stepY = abs(rzSceneDepth(at + vec2f(0.0, reach.y)) + rzSceneDepth(at - vec2f(0.0, reach.y)) - 2.0 * deep);
      let innerCame = smoothstep(INNER_FROM, INNER_FULL, max(stepX, stepY) / max(deep, 1.0e-3)) * figure;
      lit = clamp(hers, vec3f(0.0), vec3f(1.0)) * mix(LEAD, vec3f(1.0), mix(1.0, herLead, figure) * (1.0 - innerCame));
    }
  }

  // ── The wall ──
  let fall = clamp(1.0 - sd / REACH, 0.0, 1.0);
  let reveal = exp(-max(sd, 0.0) / 0.004) * (0.85 + 0.15 * sin(time * 0.5 + g.x * 3.0));
  // The light the windows throw on it is warm, the colour stone takes: ivory
  // going to gold, with only a trace of the glass in it.
  let wash = mix(vec3f(1.00, 0.84, 0.58), sgSpectrum(g.x * 0.9 + g.y * 0.6 + 0.2 + time * 0.01), 0.22);
  var wall = vec3f(0.0);
  if (sd > -0.004) {

    // The splay slopes in to the glass, so it faces the middle of the
    // opening: a little lit on the side away from the light's corner, dark
    // on the near one, and darkest where it meets the lead.
    let splay = clamp(0.62 - sunward * 0.34, 0.25, 1.0) * (0.30 + 0.70 * smoothstep(0.0, SPLAY, sd));
    let face = mix(splay, 1.0, smoothstep(SPLAY - 0.0008, SPLAY + 0.0008, sd));
    // The stone's face: quietly mottled, and stained in runs down it.
    let blotch = sgNoise2(g * 17.0);
    let runs = sgNoise2(vec2f(g.x * 55.0, g.y * 6.0));
    let surface = (0.80 + 0.40 * blotch.x) * (1.0 - 0.30 * smoothstep(0.50, 0.92, runs.x) * smoothstep(0.2, 0.8, blotch.y)) * (0.92 + 0.16 * runs.y);
    let masonry = mix(STONE_WARM, STONE_COOL, blotch.y) * surface * face;
    // The window's light is the only light: the stone shows as it nears an
    // opening and is gone beyond its reach. Warm at the lead, with a trace
    // of the glass.
    let corner = 1.0 - 0.45 * smoothstep(0.35, 0.95, length(g * vec2f(0.62, 1.0)));
    wall = (masonry * (0.05 + 0.95 * fall * fall * light) + (wash * 0.16 * reveal + thrown * (0.10 + 0.30 * sunGlow) * fall * fall * fall) * light) * corner;
  }
  // A pixel and a half of feather at the cut.
  let aa = 1.5 / (res.y * size);
  let inside = 1.0 - clamp(sd / aa + 0.5, 0.0, 1.0);
  var col = mix(wall, lit, inside);

  // ── The air in front ──
  // Shafts falling from the roses, fanning a little from a point far above.
  // They sway together and slide past one another, and each swells and
  // fades at its own pace.
  let fell = smoothstep(sgRoseY(), sgRoseY() + 0.25, g.y) * (1.0 - smoothstep(0.30, 0.85, abs(g.x))) * (1.0 - 0.55 * smoothstep(0.0, 0.5, g.y));
  if (fell * light > 0.002) {
    let fan = atan2(g.x, g.y + 1.6) + 0.012 * sin(time * 0.23);
    let shaft = 0.55 * sgNoise1(fan * 60.0 + time * 0.20) + 0.45 * sgNoise1(fan * 147.0 + 5.0 - time * 0.13);
    let swell = 0.75 + 0.25 * sin(time * 0.40 + fan * 35.0);
    let shaftHue = sgSpectrum(sgNoise1(fan * 23.0 + 2.0 + time * 0.04) * 1.6 + time * 0.015);
    let rays = shaftHue * shaft * shaft * swell * fell * 0.50 * light * (1.0 - 0.70 * inside);
    col = col + rays * (vec3f(1.0) - col);
  }
  // Cloud at the foot: three octaves, rising toward the sill and the sides.
  // It lies on the stone; over the glass there is barely any, and over her
  // none.
  // It drifts across and billows — each octave on its own heading — and its
  // top edge rises and falls.
  // Only below the line it can rise to: the noise can lift it 0.12 at most.
  if (params.FOG > 0.0 && g.y + 0.10 * abs(g.x) + 0.12 > 0.18) {
    let cp = vec2f(g.x * 2.2 + 0.3, g.y * 3.4);
    let cl = 0.5 * sgNoise(cp + vec2f(time * 0.060, -time * 0.018))
           + 0.25 * sgNoise(cp * 2.03 + vec2f(3.1 - time * 0.085, time * 0.030))
           + 0.125 * sgNoise(cp * 4.01 + vec2f(7.7 + time * 0.150, -time * 0.060));
    let risen = smoothstep(0.18, 0.52, g.y + 0.22 * (cl - 0.5) + 0.10 * abs(g.x) + 0.03 * sin(time * 0.17 + g.x * 2.0));
    let dens = clamp(risen * (0.35 + 1.1 * cl) * max(params.FOG, 0.0), 0.0, 0.94) * (1.0 - 0.85 * inside) * select(1.0, 0.0, onFigure && inside > 0.5);
    let cloudHue = sgSpectrum(cl * 1.7 + g.x * 0.35 + time * 0.02);
    // Under each light the cloud takes what comes through it: a pool of the
    // window's colour, wider the further it has fallen, and mottled.
    let fallen = max(g.y - SILL, 0.0);
    let poolW = HW * (0.9 + 5.0 * fallen);
    let pool = smoothstep(-0.03, 0.08, g.y - SILL) * (1.0 - smoothstep(poolW * 0.6, poolW * 1.3, abs(lx))) * (0.45 + 0.9 * cl);
    let cloud = (CLOUD * 0.45 + cloudHue * 0.75 * light) * (0.55 + 0.7 * cl) + thrown * pool * (0.70 + 0.60 * sunGlow) * light;
    col = mix(col, cloud, dens) + cloud * dens * 0.25 * light;
  }

  // Where a window meets the wall or the cloud in front of it, a soft
  // darkening hugs its edge and is gone within a few pixels, a little
  // deeper below and to the right. It falls off as a curve with no edge of
  // its own, so there is nothing to see but the window sitting in.
  col = col * (1.0 - EDGE_SHADE * exp(-max(sd, 0.0) / EDGE_REACH) * step(0.0, sd) * (0.70 + 0.45 * max(-sunward, 0.0)));

  // Opaque: this replaces the picture rather than laying over it.
  return vec4f(clamp(col, vec3f(0.0), vec3f(1.0)), 1.0);
}
